--
-- Name: _bodyshop_ensure_settlement(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bodyshop_ensure_settlement(p_repair_card_id integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_id bigint;
  v_jc text;
  v_actor text;
BEGIN
  SELECT id, job_card_no INTO v_id, v_jc
    FROM public.bodyshop_settlements
   WHERE repair_card_id = p_repair_card_id;

  IF v_id IS NULL THEN
    SELECT job_card_no INTO v_jc FROM public.bodyshop_repair_cards WHERE id = p_repair_card_id;
    IF v_jc IS NULL THEN
      RAISE EXCEPTION 'repair card % not found', p_repair_card_id USING ERRCODE = 'P0002';
    END IF;

    SELECT a.actor_email INTO v_actor FROM public._bodyshop_settlement_actor() a;

    INSERT INTO public.bodyshop_settlements (repair_card_id, job_card_no, created_by, updated_by)
    VALUES (p_repair_card_id, v_jc, v_actor, v_actor)
    RETURNING id INTO v_id;
  END IF;

  PERFORM public.sync_bodyshop_invoice_account_from_dms(ARRAY[v_jc]);
  RETURN v_id;
END;
$$;


--
-- Name: _bodyshop_settlement_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bodyshop_settlement_actor() RETURNS TABLE(actor_id uuid, actor_email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
BEGIN
  RETURN QUERY
  SELECT auth.uid(),
         COALESCE(auth.jwt() ->> 'email', auth.uid()::text);
END;
$$;


--
-- Name: _bodyshop_settlement_mark_line_reversed(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bodyshop_settlement_mark_line_reversed(p_line_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  ALTER TABLE public.bodyshop_settlement_lines DISABLE TRIGGER trg_prevent_bodyshop_settlement_line_mutation;
  UPDATE public.bodyshop_settlement_lines
     SET is_reversed = true
   WHERE id = p_line_id;
  ALTER TABLE public.bodyshop_settlement_lines ENABLE TRIGGER trg_prevent_bodyshop_settlement_line_mutation;
END;
$$;


--
-- Name: _parts_request_caller_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._parts_request_caller_name() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_name text;
  v_employee_code text;
begin
  select uel.employee_code into v_employee_code
  from public.user_employee_links uel
  where uel.user_id = auth.uid() and uel.is_active = true
  order by uel.is_primary desc, uel.updated_at desc
  limit 1;

  if v_employee_code is not null then
    select em.employee_name into v_name
    from public.employee_master em
    where em.employee_code = v_employee_code;
  end if;

  if v_name is null then
    select coalesce(u.full_name, auth.jwt()->>'email') into v_name
    from public.users u where u.id = auth.uid();
  end if;

  return coalesce(v_name, 'Unknown');
end;
$$;


--
-- Name: accounts_bodyshop_assign_eligible_null_vouchers(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_bodyshop_assign_eligible_null_vouchers(p_repair_card_id integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  r record;
  v_assigned text;
  v_count integer := 0;
BEGIN
  FOR r IN
    SELECT
      l.id,
      l.payment_mode,
      public.accounts_bodyshop_effective_invoice_date(l.repair_card_id) AS eff_date
      FROM public.bodyshop_settlement_lines l
     WHERE l.voucher_no IS NULL
       AND l.is_reversed = false
       AND l.party = 'customer'
       AND l.line_type = 'receipt'
       AND l.component = 'CUSTOMER'
       AND l.payment_mode IN ('cash', 'upi', 'card')
       AND (p_repair_card_id IS NULL OR l.repair_card_id = p_repair_card_id)
       AND public.accounts_bodyshop_effective_invoice_date(l.repair_card_id) >= DATE '2026-09-02'
     ORDER BY
       public.accounts_bodyshop_effective_invoice_date(l.repair_card_id) ASC,
       l.txn_date ASC,
       l.id ASC
  LOOP
    UPDATE public.bodyshop_settlement_lines
       SET voucher_no = public.accounts_mechanical_next_voucher_no(r.payment_mode, r.eff_date)
     WHERE id = r.id
       AND voucher_no IS NULL
    RETURNING voucher_no INTO v_assigned;

    IF v_assigned IS NOT NULL THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION accounts_bodyshop_assign_eligible_null_vouchers(p_repair_card_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounts_bodyshop_assign_eligible_null_vouchers(p_repair_card_id integer) IS 'ACCOUNTS-001 / DBL-0080: Assign RApp/JApp to voucher_no IS NULL Bodyshop customer cash/upi/card receipts now eligible via accounts_bodyshop_effective_invoice_date >= 2026-09-02. Reuses Mechanical nextval. Never updates a non-null voucher_no. Does not assign NULL/unsupported modes.';


--
-- Name: accounts_bodyshop_effective_invoice_date(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_bodyshop_effective_invoice_date(p_repair_card_id integer) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_date date;
  v_jc text;
BEGIN
  IF p_repair_card_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT s.invoice_date, NULLIF(btrim(COALESCE(s.job_card_no, '')), '')
    INTO v_date, v_jc
    FROM public.bodyshop_settlements s
   WHERE s.repair_card_id = p_repair_card_id;

  IF v_date IS NOT NULL THEN
    RETURN v_date;
  END IF;

  IF v_jc IS NULL THEN
    SELECT NULLIF(btrim(COALESCE(c.job_card_no, '')), '')
      INTO v_jc
      FROM public.bodyshop_repair_cards c
     WHERE c.id = p_repair_card_id;
  END IF;

  RETURN public.accounts_mechanical_unique_dms_invoice_date(v_jc);
END;
$$;


--
-- Name: FUNCTION accounts_bodyshop_effective_invoice_date(p_repair_card_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounts_bodyshop_effective_invoice_date(p_repair_card_id integer) IS 'ACCOUNTS-001 / DBL-0080: Bodyshop voucher eligibility date. Settlement invoice_date when present, else unique DMS labour invoice_date for the JC. Reuses DBL-0060 uniqueness. Cutoff remains 2026-09-02 via accounts_mechanical_next_voucher_no.';


