--
-- Name: accounts_mechanical_actor_label(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_actor_label() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
  SELECT COALESCE(
    (
      SELECT NULLIF(btrim(em.employee_name), '')
      FROM public.user_employee_links uel
      JOIN public.employee_master em ON em.employee_code = uel.employee_code
      WHERE uel.user_id = auth.uid()
        AND uel.is_active = true
      ORDER BY COALESCE(em.is_active, true) DESC, em.employee_code
      LIMIT 1
    ),
    (
      SELECT NULLIF(btrim(u.full_name), '')
      FROM public.users u
      WHERE u.id = auth.uid()
    ),
    NULLIF(auth.jwt() ->> 'email', ''),
    NULLIF(auth.uid()::text, ''),
    'system'
  );
$$;


--
-- Name: accounts_mechanical_assign_eligible_null_vouchers(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_assign_eligible_null_vouchers(p_reception_entry_id bigint DEFAULT NULL::bigint, p_jc_number text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  r record;
  v_assigned text;
  v_count integer := 0;
  v_jc text;
BEGIN
  v_jc := NULLIF(upper(btrim(COALESCE(p_jc_number, ''))), '');

  FOR r IN
    SELECT
      l.id,
      l.payment_mode,
      public.accounts_mechanical_effective_invoice_date(l.reception_entry_id) AS eff_date
      FROM public.accounts_mechanical_payment_lines l
      JOIN public.accounts_mechanical_invoices inv ON inv.id = l.mechanical_invoice_id
      JOIN public.service_reception_entries e ON e.id = l.reception_entry_id
     WHERE l.voucher_no IS NULL
       AND l.payment_mode IN ('cash', 'upi', 'card')
       AND (p_reception_entry_id IS NULL OR l.reception_entry_id = p_reception_entry_id)
       AND (
         v_jc IS NULL
         OR upper(btrim(COALESCE(NULLIF(btrim(inv.jc_number), ''), e.jc_number))) = v_jc
       )
       AND public.accounts_mechanical_effective_invoice_date(l.reception_entry_id) >= DATE '2026-09-02'
     ORDER BY
       public.accounts_mechanical_effective_invoice_date(l.reception_entry_id) ASC,
       l.payment_received_date ASC,
       l.posted_at ASC,
       l.id ASC
  LOOP
    UPDATE public.accounts_mechanical_payment_lines
       SET voucher_no = public.accounts_mechanical_next_voucher_no(r.payment_mode, r.eff_date)
     WHERE id = r.id
       AND voucher_no IS NULL
    RETURNING voucher_no INTO v_assigned;

    IF v_assigned IS NOT NULL THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION accounts_mechanical_assign_eligible_null_vouchers(p_reception_entry_id bigint, p_jc_number text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounts_mechanical_assign_eligible_null_vouchers(p_reception_entry_id bigint, p_jc_number text) IS 'ACCOUNTS-001 / DBL-0074: Assign RApp/JApp to voucher_no IS NULL cash/upi/card lines now eligible via accounts_mechanical_effective_invoice_date >= 2026-09-02. Optional reception or JC scope. Never updates a non-null voucher_no.';


