--
-- Name: accounts_mechanical_case_json(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_case_json(p_reception_entry_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_row jsonb;
BEGIN
  SELECT to_jsonb(x) INTO v_row
    FROM (
      SELECT
        e.id AS reception_entry_id,
        e.jc_number,
        e.reg_number,
        e.model,
        e.service_type,
        e.sa_name,
        e.sa_display_name,
        e.sa_employee_code,
        e.branch,
        e.owner_name,
        e.owner_phone,
        e.invoice_done_at,
        e.invoice_done_by,
        e.created_at,
        e.invoice_storage_path,
        e.invoice_file_name,
        e.invoice_drive_url,
        e.expected_invoice_amount,
        inv.invoice_number,
        inv.invoice_date,
        inv.billed_amount,
        inv.payment_status,
        inv.amount_received,
        public.accounts_mechanical_remaining_amount(inv.billed_amount, inv.amount_received) AS remaining_amount,
        inv.payment_notes,
        inv.captured_by,
        inv.captured_at,
        inv.updated_at AS invoice_updated_at,
        COALESCE(inv.keep_on_credit, false) AS keep_on_credit,
        inv.keep_on_credit_reason,
        inv.keep_on_credit_approved_by,
        inv.keep_on_credit_approved_at,
        inv.keep_on_credit_revoked_by,
        inv.keep_on_credit_revoked_at,
        public.accounts_mechanical_invoice_gatepass_reason(
          inv.billed_amount,
          inv.amount_received,
          COALESCE(inv.keep_on_credit, false),
          inv.keep_on_credit_reason,
          inv.keep_on_credit_approved_by,
          inv.keep_on_credit_approved_at
        ) AS gatepass_reason
      FROM public.service_reception_entries e
      LEFT JOIN public.accounts_mechanical_invoices inv
        ON inv.reception_entry_id = e.id
      WHERE e.id = p_reception_entry_id
    ) x;
  RETURN v_row;
END;
$$;


--
-- Name: accounts_mechanical_effective_invoice_date(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_effective_invoice_date(p_reception_entry_id bigint) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_inv public.accounts_mechanical_invoices%ROWTYPE;
  v_jc text;
BEGIN
  IF p_reception_entry_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_inv
    FROM public.accounts_mechanical_invoices
   WHERE reception_entry_id = p_reception_entry_id;

  IF FOUND AND v_inv.invoice_date IS NOT NULL THEN
    RETURN v_inv.invoice_date;
  END IF;

  v_jc := NULLIF(btrim(COALESCE(v_inv.jc_number, '')), '');
  IF v_jc IS NULL THEN
    SELECT NULLIF(btrim(e.jc_number), '')
      INTO v_jc
      FROM public.service_reception_entries e
     WHERE e.id = p_reception_entry_id;
  END IF;

  RETURN public.accounts_mechanical_unique_dms_invoice_date(v_jc);
END;
$$;


--
-- Name: FUNCTION accounts_mechanical_effective_invoice_date(p_reception_entry_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounts_mechanical_effective_invoice_date(p_reception_entry_id bigint) IS 'ACCOUNTS-001 / DBL-0060: Voucher eligibility date. Accounts invoice_date when present, else unique DMS labour invoice_date for the JC. Null when unresolved. Does not use payment_received_date, posted_at, or invoice_done_at.';


--
-- Name: accounts_mechanical_gatepass_eligible(numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_gatepass_eligible(p_billed numeric, p_received numeric, p_keep_on_credit boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT public.accounts_mechanical_gatepass_reason(p_billed, p_received, p_keep_on_credit) IS NOT NULL;
$$;


--
-- Name: accounts_mechanical_gatepass_reason(numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_gatepass_reason(p_billed numeric, p_received numeric, p_keep_on_credit boolean) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_remaining numeric;
  v_allowance numeric;
BEGIN
  IF p_billed IS NULL THEN
    RETURN NULL;
  END IF;
  v_remaining := public.accounts_mechanical_remaining_amount(p_billed, p_received);
  IF v_remaining IS NULL THEN
    RETURN NULL;
  END IF;
  IF v_remaining <= 0 THEN
    RETURN 'paid';
  END IF;
  v_allowance := public.accounts_mechanical_short_payment_allowance(p_billed);
  IF v_allowance IS NOT NULL AND v_remaining <= v_allowance THEN
    RETURN 'short_payment';
  END IF;
  IF COALESCE(p_keep_on_credit, false) THEN
    RETURN 'keep_on_credit';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: accounts_mechanical_gatepass_reason_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_gatepass_reason_label(p_reason text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_reason
    WHEN 'paid' THEN 'Paid'
    WHEN 'short_payment' THEN 'Short payment allowed'
    WHEN 'keep_on_credit' THEN 'Released on credit'
    ELSE NULL
  END;
$$;


--
-- Name: accounts_mechanical_invoice_gatepass_reason(numeric, numeric, boolean, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_invoice_gatepass_reason(p_billed numeric, p_received numeric, p_keep_on_credit boolean, p_reason text, p_approved_by text, p_approved_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT public.accounts_mechanical_gatepass_reason(
    p_billed,
    p_received,
    public.accounts_mechanical_keep_on_credit_valid(
      p_keep_on_credit, p_reason, p_approved_by, p_approved_at
    )
  );
$$;


--
-- Name: accounts_mechanical_keep_on_credit_valid(boolean, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_keep_on_credit_valid(p_keep_on_credit boolean, p_reason text, p_approved_by text, p_approved_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(p_keep_on_credit, false)
    AND NULLIF(btrim(COALESCE(p_reason, '')), '') IS NOT NULL
    AND NULLIF(btrim(COALESCE(p_approved_by, '')), '') IS NOT NULL
    AND p_approved_at IS NOT NULL;
$$;


--
-- Name: FUNCTION accounts_mechanical_keep_on_credit_valid(p_keep_on_credit boolean, p_reason text, p_approved_by text, p_approved_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounts_mechanical_keep_on_credit_valid(p_keep_on_credit boolean, p_reason text, p_approved_by text, p_approved_at timestamp with time zone) IS 'DBL-0065: Valid Keep on Credit = flag true AND non-blank reason AND approved_by AND approved_at. A checkbox or keep_on_credit=true alone is not enough.';


--
-- Name: accounts_mechanical_next_voucher_no(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_next_voucher_no(p_payment_mode text, p_invoice_date date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_mode text;
  v_n bigint;
BEGIN
  IF p_invoice_date IS NULL OR p_invoice_date < DATE '2026-09-02' THEN
    RETURN NULL;
  END IF;

  v_mode := lower(btrim(COALESCE(p_payment_mode, '')));

  IF v_mode = 'cash' THEN
    v_n := nextval('public.accounts_mechanical_voucher_rapp_2627_seq');
    RETURN 'RApp/26-27/' || lpad(v_n::text, 4, '0');
  END IF;

  IF v_mode IN ('upi', 'card') THEN
    v_n := nextval('public.accounts_mechanical_voucher_japp_2627_seq');
    RETURN 'JApp/26-27/' || lpad(v_n::text, 4, '0');
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION accounts_mechanical_next_voucher_no(p_payment_mode text, p_invoice_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounts_mechanical_next_voucher_no(p_payment_mode text, p_invoice_date date) IS 'ACCOUNTS-001 / DBL-0058: nextval RApp (cash) or JApp (upi/card) when mechanical invoice_date >= 2026-09-02. Null otherwise. payment_received_date / posted_at / invoice_done_at do not control eligibility.';


--
-- Name: accounts_mechanical_payment_lines_protect_voucher(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_payment_lines_protect_voucher() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.voucher_no IS NOT NULL AND NEW.voucher_no IS DISTINCT FROM OLD.voucher_no THEN
    RAISE EXCEPTION 'voucher_no is immutable once assigned'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: accounts_mechanical_recalc(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_recalc(p_reception_entry_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_billed numeric;
  v_received numeric;
  v_status text;
BEGIN
  SELECT billed_amount INTO v_billed
    FROM public.accounts_mechanical_invoices
   WHERE reception_entry_id = p_reception_entry_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT COALESCE(sum(l.amount), 0) INTO v_received
    FROM public.accounts_mechanical_payment_lines l
   WHERE l.reception_entry_id = p_reception_entry_id;

  IF v_billed IS NULL THEN
    v_status := 'pending';
  ELSIF v_billed = 0 THEN
    v_status := 'received';
  ELSIF v_received <= 0 THEN
    v_status := 'pending';
  ELSIF v_received < v_billed THEN
    v_status := 'partial';
  ELSE
    v_status := 'received';
  END IF;

  UPDATE public.accounts_mechanical_invoices
     SET amount_received = CASE WHEN v_received = 0 THEN NULL ELSE round(v_received, 2) END,
         payment_status = v_status,
         updated_at = now()
   WHERE reception_entry_id = p_reception_entry_id;
END;
$$;


--
-- Name: accounts_mechanical_reconcile_japp_sequence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_reconcile_japp_sequence() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $_$
DECLARE
  v_max bigint := 0;
  v_seq bigint := 0;
  v_target bigint;
BEGIN
  SELECT COALESCE(max(substring(voucher_no from '([0-9]{4})$')::bigint), 0)
    INTO v_max
    FROM public.accounts_mechanical_payment_lines
   WHERE voucher_no ~ '^JApp/26-27/[0-9]{4}$';

  SELECT last_value INTO v_seq
    FROM public.accounts_mechanical_voucher_japp_2627_seq;

  v_target := GREATEST(v_max, COALESCE(v_seq, 0));
  IF v_target > 0 THEN
    PERFORM setval('public.accounts_mechanical_voucher_japp_2627_seq', v_target, true);
  END IF;

  RETURN v_target;
END;
$_$;


--
-- Name: FUNCTION accounts_mechanical_reconcile_japp_sequence(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounts_mechanical_reconcile_japp_sequence() IS 'ACCOUNTS-001 / DBL-0074: Raise JApp sequence to max(persisted JApp nnnn, last_value). Does not rewind. Does not rewrite voucher_no.';


--
-- Name: accounts_mechanical_remaining_amount(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_remaining_amount(p_billed numeric, p_received numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_billed IS NULL THEN NULL
    ELSE GREATEST(0, round(p_billed - COALESCE(p_received, 0), 2))
  END;
$$;


--
-- Name: accounts_mechanical_short_payment_allowance(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_short_payment_allowance(p_billed numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_billed IS NULL THEN NULL
    ELSE round(p_billed * 0.02, 2)
  END;
$$;


--
-- Name: accounts_mechanical_unique_dms_invoice_date(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_unique_dms_invoice_date(p_jc_number text) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_jc text;
  v_count integer := 0;
  v_date date;
BEGIN
  v_jc := upper(btrim(COALESCE(p_jc_number, '')));
  IF v_jc = '' THEN
    RETURN NULL;
  END IF;

  SELECT COUNT(*)
    INTO v_count
    FROM public.psf_revenue_dms d
   WHERE upper(btrim(d.job_card_number)) = v_jc
     AND COALESCE(d.invoice_status, '') <> 'Cancelled'
     AND NULLIF(btrim(d.invoice_number), '') IS NOT NULL
     AND d.total_invoice_amount IS NOT NULL
     AND d.invoice_date IS NOT NULL;

  IF v_count <> 1 THEN
    RETURN NULL;
  END IF;

  SELECT d.invoice_date
    INTO v_date
    FROM public.psf_revenue_dms d
   WHERE upper(btrim(d.job_card_number)) = v_jc
     AND COALESCE(d.invoice_status, '') <> 'Cancelled'
     AND NULLIF(btrim(d.invoice_number), '') IS NOT NULL
     AND d.total_invoice_amount IS NOT NULL
     AND d.invoice_date IS NOT NULL;

  RETURN v_date;
END;
$$;


--
-- Name: FUNCTION accounts_mechanical_unique_dms_invoice_date(p_jc_number text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounts_mechanical_unique_dms_invoice_date(p_jc_number text) IS 'ACCOUNTS-001 / DBL-0060: Unique live psf_revenue_dms invoice_date for a JC. Null when 0 or 2+ live invoices. Same uniqueness as lookup_accounts_mechanical_dms_invoice. Does not write Accounts invoices.';


--
-- Name: accounts_mechanical_user_is_gm(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounts_mechanical_user_is_gm() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_employee_links uel
    JOIN public.employee_master em ON em.employee_code = uel.employee_code
    WHERE uel.user_id = auth.uid()
      AND uel.is_active = true
      AND COALESCE(em.is_active, true) = true
      AND public.employee_has_business_role(em.role, 'GM')
  );
$$;


--
-- Name: acknowledge(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge(p_complaint_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_is_admin boolean := public.is_admin();
  v_dealer_code text := public.my_dealer_code();
BEGIN
  IF NOT (v_is_admin OR public.has_module_modify('complaints')) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  IF v_is_admin THEN
    UPDATE public.complaint_tickets
    SET status = 'acknowledged'
    WHERE id = p_complaint_id;
  ELSE
    UPDATE public.complaint_tickets
    SET status = 'acknowledged'
    WHERE id = p_complaint_id
      AND dealer_code = v_dealer_code;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Complaint not found or not accessible';
  END IF;

  RETURN jsonb_build_object('status', 'acknowledged');
END;
$$;


--
-- Name: add_accounts_mechanical_payment(bigint, numeric, text, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_accounts_mechanical_payment(p_reception_entry_id bigint, p_amount numeric, p_payment_mode text, p_reference text DEFAULT NULL::text, p_payment_received_date date DEFAULT NULL::date, p_remark text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_inv public.accounts_mechanical_invoices%ROWTYPE;
  v_mode text;
  v_amount numeric;
  v_actor text;
  v_received_date date;
  v_voucher text;
  v_eff date;
BEGIN
  IF NOT public.accounts_can_access() THEN
    RAISE EXCEPTION 'permission denied: requires accounts view'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_inv
    FROM public.accounts_mechanical_invoices
   WHERE reception_entry_id = p_reception_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'capture invoice number and billed amount first'
      USING ERRCODE = '23514';
  END IF;
  IF v_inv.billed_amount IS NULL THEN
    RAISE EXCEPTION 'billed amount is required before posting a receipt'
      USING ERRCODE = '23514';
  END IF;

  v_amount := round(COALESCE(p_amount, 0), 2);
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'receipt amount must be greater than 0'
      USING ERRCODE = '23514';
  END IF;

  v_mode := lower(btrim(COALESCE(p_payment_mode, '')));
  IF v_mode NOT IN ('cash', 'upi', 'card', 'cheque', 'bank', 'other') THEN
    RAISE EXCEPTION 'invalid payment_mode'
      USING ERRCODE = '23514';
  END IF;

  v_received_date := p_payment_received_date;
  IF v_received_date IS NULL THEN
    RAISE EXCEPTION 'payment received date is required'
      USING ERRCODE = '23514';
  END IF;

  v_actor := COALESCE(
    NULLIF(auth.jwt() ->> 'email', ''),
    NULLIF(auth.uid()::text, ''),
    'system'
  );

  v_eff := public.accounts_mechanical_effective_invoice_date(p_reception_entry_id);
  v_voucher := public.accounts_mechanical_next_voucher_no(v_mode, v_eff);

  INSERT INTO public.accounts_mechanical_payment_lines (
    reception_entry_id, mechanical_invoice_id, amount, payment_mode, reference,
    posted_by, posted_at, payment_received_date, voucher_no, remark
  ) VALUES (
    p_reception_entry_id,
    v_inv.id,
    v_amount,
    v_mode,
    NULLIF(btrim(p_reference), ''),
    v_actor,
    now(),
    v_received_date,
    v_voucher,
    NULLIF(btrim(p_remark), '')
  );

  PERFORM public.accounts_mechanical_recalc(p_reception_entry_id);
  RETURN public.accounts_mechanical_case_json(p_reception_entry_id);
END;
$$;


--
-- Name: FUNCTION add_accounts_mechanical_payment(p_reception_entry_id bigint, p_amount numeric, p_payment_mode text, p_reference text, p_payment_received_date date, p_remark text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.add_accounts_mechanical_payment(p_reception_entry_id bigint, p_amount numeric, p_payment_mode text, p_reference text, p_payment_received_date date, p_remark text) IS 'ACCOUNTS-001 / DBL-0069: Append a mechanical receipt at the entered amount. Optional p_remark is trimmed; blank stores NULL. Overpayment is stored as-is. Remaining display floors at 0. Recalc still derives payment_status from billed vs sum(lines). Voucher from effective invoice_date (DBL-0060).';


--
-- Name: add_bodyshop_settlement_line(integer, text, text, text, numeric, date, text, text, numeric, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_bodyshop_settlement_line(p_repair_card_id integer, p_party text DEFAULT NULL::text, p_line_type text DEFAULT NULL::text, p_component text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric, p_txn_date date DEFAULT NULL::date, p_reference text DEFAULT NULL::text, p_remarks text DEFAULT NULL::text, p_main_amount numeric DEFAULT NULL::numeric, p_gst_amount numeric DEFAULT NULL::numeric, p_tds_amount numeric DEFAULT NULL::numeric, p_import_row_token text DEFAULT NULL::text, p_payment_mode text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_id bigint;
  v_h public.bodyshop_settlements%ROWTYPE;
  v_actor_id uuid;
  v_actor_email text;
  v_date date;
  v_main numeric;
  v_gst numeric;
  v_tds numeric;
  v_token text;
  v_mode text;
  v_voucher text;
  v_eff date;
BEGIN
  v_token := NULLIF(btrim(p_import_row_token), '');
  v_main := CASE WHEN COALESCE(p_main_amount, 0) > 0 THEN round(p_main_amount, 2) ELSE 0 END;
  v_gst := CASE WHEN COALESCE(p_gst_amount, 0) > 0 THEN round(p_gst_amount, 2) ELSE 0 END;
  v_tds := CASE WHEN COALESCE(p_tds_amount, 0) > 0 THEN round(p_tds_amount, 2) ELSE 0 END;

  IF v_main > 0 OR v_gst > 0 OR v_tds > 0 THEN
    IF NOT public.bodyshop_settlement_can_post_do(p_repair_card_id) THEN
      RAISE EXCEPTION 'permission denied: requires bodyshop_recovery view or bodyshop_repair modify'
        USING ERRCODE = '42501';
    END IF;

    v_id := public._bodyshop_ensure_settlement(p_repair_card_id);
    SELECT * INTO v_h FROM public.bodyshop_settlements WHERE id = v_id;
    SELECT a.actor_id, a.actor_email INTO v_actor_id, v_actor_email
      FROM public._bodyshop_settlement_actor() a;
    v_date := COALESCE(p_txn_date, CURRENT_DATE);

    IF v_h.do_amount IS NULL THEN
      RAISE EXCEPTION 'DO amount must be captured before posting DO payment'
        USING ERRCODE = '23514';
    END IF;

    IF v_main > 0 THEN
      INSERT INTO public.bodyshop_settlement_lines (
        settlement_id, repair_card_id, party, line_type, component, amount,
        txn_date, reference, remarks, actor_id, actor_email, import_row_token
      ) VALUES (
        v_id, p_repair_card_id, 'insurance', 'do_component', 'MAIN', v_main,
        v_date, p_reference, p_remarks, v_actor_id, v_actor_email, v_token
      );
    END IF;
    IF v_gst > 0 THEN
      INSERT INTO public.bodyshop_settlement_lines (
        settlement_id, repair_card_id, party, line_type, component, amount,
        txn_date, reference, remarks, actor_id, actor_email, import_row_token
      ) VALUES (
        v_id, p_repair_card_id, 'insurance', 'do_component', 'GST', v_gst,
        v_date, p_reference, p_remarks, v_actor_id, v_actor_email, v_token
      );
    END IF;
    IF v_tds > 0 THEN
      INSERT INTO public.bodyshop_settlement_lines (
        settlement_id, repair_card_id, party, line_type, component, amount,
        txn_date, reference, remarks, actor_id, actor_email, import_row_token
      ) VALUES (
        v_id, p_repair_card_id, 'insurance', 'do_component', 'TDS', v_tds,
        v_date, p_reference, p_remarks, v_actor_id, v_actor_email, v_token
      );
    END IF;
    UPDATE public.bodyshop_settlements SET do_not_received = false, updated_by = v_actor_email WHERE id = v_id;
    PERFORM public.recalc_bodyshop_settlement(v_id);
    RETURN public.get_bodyshop_settlement(p_repair_card_id);
  END IF;

  v_mode := lower(btrim(COALESCE(p_payment_mode, '')));
  IF v_mode = '' THEN
    v_mode := NULL;
  ELSIF v_mode NOT IN ('cash', 'upi', 'card', 'cheque', 'bank', 'other') THEN
    RAISE EXCEPTION 'invalid payment_mode'
      USING ERRCODE = '23514';
  END IF;

  IF NOT public.bodyshop_settlement_can_post_customer(p_repair_card_id) THEN
    RAISE EXCEPTION 'permission denied: requires accounts view or bodyshop_repair modify'
      USING ERRCODE = '42501';
  END IF;

  v_id := public._bodyshop_ensure_settlement(p_repair_card_id);
  SELECT * INTO v_h FROM public.bodyshop_settlements WHERE id = v_id;
  SELECT a.actor_id, a.actor_email INTO v_actor_id, v_actor_email
    FROM public._bodyshop_settlement_actor() a;
  v_date := COALESCE(p_txn_date, CURRENT_DATE);

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be greater than 0' USING ERRCODE = '23514';
  END IF;

  IF upper(btrim(COALESCE(p_component, ''))) IN ('CUSTOMER', 'CUSTOMER_REFUND')
     OR lower(btrim(COALESCE(p_party, ''))) = 'customer' THEN
    PERFORM public.recalc_bodyshop_settlement(v_id);
    SELECT * INTO v_h FROM public.bodyshop_settlements WHERE id = v_id;
    IF v_h.customer_settlement_kind IS NULL OR v_h.customer_settlement_kind = 'none' THEN
      RAISE EXCEPTION 'no customer due or refund to post against'
        USING ERRCODE = '23514';
    END IF;
    IF v_h.customer_settlement_kind = 'due' THEN
      IF upper(btrim(COALESCE(p_component, 'CUSTOMER'))) = 'CUSTOMER_REFUND'
         OR lower(btrim(COALESCE(p_line_type, 'receipt'))) = 'refund' THEN
        RAISE EXCEPTION 'refunds are not allowed when customer diff is recoverable'
          USING ERRCODE = '23514';
      END IF;
      IF round(p_amount, 2) > round(COALESCE(v_h.customer_remaining_amount, 0), 2) THEN
        RAISE EXCEPTION 'customer receipt cannot exceed remaining recoverable'
          USING ERRCODE = '23514';
      END IF;
      v_eff := public.accounts_bodyshop_effective_invoice_date(p_repair_card_id);
      v_voucher := public.accounts_mechanical_next_voucher_no(v_mode, v_eff);
      INSERT INTO public.bodyshop_settlement_lines (
        settlement_id, repair_card_id, party, line_type, component, amount,
        txn_date, reference, remarks, actor_id, actor_email, import_row_token, payment_mode, voucher_no
      ) VALUES (
        v_id, p_repair_card_id, 'customer', 'receipt', 'CUSTOMER', round(p_amount, 2),
        v_date, p_reference, p_remarks, v_actor_id, v_actor_email, v_token, v_mode, v_voucher
      );
    ELSE
      IF upper(btrim(COALESCE(p_component, 'CUSTOMER_REFUND'))) = 'CUSTOMER'
         OR lower(btrim(COALESCE(p_line_type, 'refund'))) = 'receipt' THEN
        RAISE EXCEPTION 'receipts are not allowed when customer diff is a refund'
          USING ERRCODE = '23514';
      END IF;
      IF round(p_amount, 2) > round(COALESCE(v_h.customer_remaining_amount, 0), 2) THEN
        RAISE EXCEPTION 'customer refund cannot exceed remaining refund'
          USING ERRCODE = '23514';
      END IF;
      INSERT INTO public.bodyshop_settlement_lines (
        settlement_id, repair_card_id, party, line_type, component, amount,
        txn_date, reference, remarks, actor_id, actor_email, import_row_token, payment_mode
      ) VALUES (
        v_id, p_repair_card_id, 'customer', 'refund', 'CUSTOMER_REFUND', round(p_amount, 2),
        v_date, p_reference, p_remarks, v_actor_id, v_actor_email, v_token, v_mode
      );
    END IF;
    UPDATE public.bodyshop_settlements SET customer_not_received = false, updated_by = v_actor_email WHERE id = v_id;
    PERFORM public.recalc_bodyshop_settlement(v_id);
    RETURN public.get_bodyshop_settlement(p_repair_card_id);
  END IF;

  RAISE EXCEPTION 'unsupported settlement line; use Main/GST/TDS batch or customer amount'
    USING ERRCODE = '23514';
END;
$$;


--
-- Name: FUNCTION add_bodyshop_settlement_line(p_repair_card_id integer, p_party text, p_line_type text, p_component text, p_amount numeric, p_txn_date date, p_reference text, p_remarks text, p_main_amount numeric, p_gst_amount numeric, p_tds_amount numeric, p_import_row_token text, p_payment_mode text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.add_bodyshop_settlement_line(p_repair_card_id integer, p_party text, p_line_type text, p_component text, p_amount numeric, p_txn_date date, p_reference text, p_remarks text, p_main_amount numeric, p_gst_amount numeric, p_tds_amount numeric, p_import_row_token text, p_payment_mode text) IS 'Post DO Main/GST/TDS or customer receipt/refund. Customer receipts assign RApp/JApp via accounts_mechanical_next_voucher_no when eligible. Optional p_payment_mode applies only to customer receipt/refund. DBL-0080.';


--
-- Name: add_customer_message(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_customer_message(p_token text, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_complaint_id bigint;
  v_customer_name text;
  v_dealer_code text;
BEGIN
  SELECT complaint_id INTO v_complaint_id
  FROM public.complaint_access_links
  WHERE token = p_token AND status = 'consumed';

  IF v_complaint_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or inactive complaint link';
  END IF;

  -- Get customer name and dealer from the ticket
  SELECT customer_name, dealer_code INTO v_customer_name, v_dealer_code
  FROM public.complaint_tickets
  WHERE id = v_complaint_id;

  -- Add customer message (never is_internal)
  INSERT INTO public.complaint_messages (
    dealer_code, complaint_id, author_type, author_name, body, is_internal
  ) VALUES (
    v_dealer_code, v_complaint_id, 'customer', v_customer_name, p_body, false
  );

  -- Return updated view
  RETURN public.get_complaint_by_token(p_token);
END;
$$;


--
-- Name: add_staff_message(bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_staff_message(p_complaint_id bigint, p_body text, p_is_internal boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_dealer_code text;
  v_staff_name text;
BEGIN
  IF NOT (public.is_admin() OR public.has_module_modify('complaints')) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  SELECT dealer_code INTO v_dealer_code
  FROM public.complaint_tickets
  WHERE id = p_complaint_id
    AND dealer_code = public.my_dealer_code();

  IF v_dealer_code IS NULL THEN
    RAISE EXCEPTION 'Complaint not found';
  END IF;

  SELECT full_name INTO v_staff_name FROM public.users WHERE id = auth.uid();

  INSERT INTO public.complaint_messages (
    dealer_code, complaint_id, author_type, author_id, author_name, body, is_internal
  ) VALUES (
    v_dealer_code, p_complaint_id, 'staff', auth.uid(), v_staff_name, p_body, p_is_internal
  );

  RETURN jsonb_build_object('message_added', true);
END;
$$;


--
-- Name: advisor_chat_get(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advisor_chat_get(p_chat_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff record;
  v_chat public.advisor_chats%ROWTYPE;
  v_messages jsonb;
BEGIN
  SELECT * INTO v_staff FROM public.advisor_chat_require_staff() LIMIT 1;

  SELECT * INTO v_chat
  FROM public.advisor_chats
  WHERE id = p_chat_id
    AND dealer_code = v_staff.dealer_code
    AND (
      v_staff.see_all
      OR public.advisor_chat_user_involved(id, v_staff.user_id)
    )
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Chat not found';
  END IF;

  IF v_chat.staff_unread_count > 0 THEN
    UPDATE public.advisor_chats
    SET staff_unread_count = 0, updated_at = now()
    WHERE id = v_chat.id;
    v_chat.staff_unread_count := 0;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.created_at), '[]'::jsonb)
  INTO v_messages
  FROM public.advisor_chat_messages m
  WHERE m.chat_id = v_chat.id;

  RETURN jsonb_build_object('chat', to_jsonb(v_chat), 'messages', v_messages);
END;
$$;


--
-- Name: advisor_chat_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advisor_chat_list() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff record;
  v_rows jsonb;
BEGIN
  SELECT * INTO v_staff FROM public.advisor_chat_require_staff() LIMIT 1;

  SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.last_message_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM public.advisor_chats c
  WHERE c.dealer_code = v_staff.dealer_code
    AND c.last_message_at IS NOT NULL
    AND (
      v_staff.see_all
      OR public.advisor_chat_user_involved(c.id, v_staff.user_id)
    );

  RETURN v_rows;
END;
$$;


--
-- Name: advisor_chat_require_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advisor_chat_require_staff() RETURNS TABLE(user_id uuid, dealer_code text, author_name text, see_all boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_dealer text;
  v_name text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = v_uid AND u.is_active = true) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_dealer := NULLIF(btrim(public.my_dealer_code()), '');
  IF v_dealer IS NULL THEN
    RAISE EXCEPTION 'Dealer code required';
  END IF;

  SELECT COALESCE(NULLIF(btrim(u.full_name), ''), NULLIF(btrim(u.email), ''), 'Staff')
  INTO v_name
  FROM public.users u
  WHERE u.id = v_uid;

  user_id := v_uid;
  dealer_code := v_dealer;
  author_name := COALESCE(v_name, 'Staff');
  see_all := public.is_admin() OR public.has_module_view('chat');
  RETURN NEXT;
END;
$$;


--
-- Name: advisor_chat_send(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advisor_chat_send(p_chat_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff record;
  v_body text := btrim(COALESCE(p_body, ''));
  v_chat public.advisor_chats%ROWTYPE;
  v_message public.advisor_chat_messages%ROWTYPE;
BEGIN
  IF char_length(v_body) < 1 THEN
    RAISE EXCEPTION 'Message should be at least 1 character.';
  END IF;
  IF char_length(v_body) > 2000 THEN
    RAISE EXCEPTION 'Message is too long.';
  END IF;

  SELECT * INTO v_staff FROM public.advisor_chat_require_staff() LIMIT 1;

  SELECT * INTO v_chat
  FROM public.advisor_chats
  WHERE id = p_chat_id
    AND dealer_code = v_staff.dealer_code
    AND (
      v_staff.see_all
      OR public.advisor_chat_user_involved(id, v_staff.user_id)
    )
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Chat not found';
  END IF;

  INSERT INTO public.advisor_chat_messages (chat_id, author_side, author_user_id, author_name, body)
  VALUES (v_chat.id, 'staff', v_staff.user_id, v_staff.author_name, v_body)
  RETURNING * INTO v_message;

  UPDATE public.advisor_chats
  SET last_message_at = v_message.created_at,
      last_message_preview = left(v_body, 160),
      last_author_side = 'staff',
      customer_unread_count = customer_unread_count + 1,
      updated_at = now()
  WHERE id = v_chat.id
  RETURNING * INTO v_chat;

  RETURN jsonb_build_object('chat', to_jsonb(v_chat), 'message', to_jsonb(v_message));
END;
$$;


--
-- Name: advisor_chat_unread_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advisor_chat_unread_count() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff record;
  v_count integer;
BEGIN
  SELECT * INTO v_staff FROM public.advisor_chat_require_staff() LIMIT 1;

  SELECT COUNT(*)::integer
  INTO v_count
  FROM public.advisor_chats c
  WHERE c.dealer_code = v_staff.dealer_code
    AND c.staff_unread_count > 0
    AND (
      v_staff.see_all
      OR public.advisor_chat_user_involved(c.id, v_staff.user_id)
    );

  RETURN COALESCE(v_count, 0);
END;
$$;


--
-- Name: advisor_chat_user_involved(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advisor_chat_user_involved(p_chat_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.advisor_chats c
    WHERE c.id = p_chat_id
      AND EXISTS (
        SELECT 1
        FROM public.user_employee_links uel
        WHERE uel.user_id = p_user_id
          AND uel.is_active = true
          AND uel.dealer_code = c.dealer_code
      )
      AND (
        EXISTS (
          SELECT 1
          FROM public.advisor_chat_messages m
          WHERE m.chat_id = c.id
            AND m.author_side = 'staff'
            AND m.author_user_id = p_user_id
        )
        OR (
          COALESCE(c.contact_key, 'advisor') = 'advisor'
          AND NULLIF(btrim(c.sa_name), '') IS NOT NULL
          AND (
            EXISTS (
              SELECT 1
              FROM public.users u
              WHERE u.id = p_user_id
                AND u.is_active = true
                AND lower(btrim(u.full_name)) = lower(btrim(c.sa_name))
            )
            OR EXISTS (
              SELECT 1
              FROM public.user_employee_links uel
              JOIN public.employee_master em ON upper(btrim(em.employee_code)) = upper(btrim(uel.employee_code))
              WHERE uel.user_id = p_user_id
                AND uel.is_active = true
                AND uel.dealer_code = c.dealer_code
                AND lower(btrim(em.employee_name)) = lower(btrim(c.sa_name))
            )
            OR EXISTS (
              SELECT 1
              FROM public.user_employee_links uel
              WHERE uel.user_id = p_user_id
                AND uel.is_active = true
                AND uel.dealer_code = c.dealer_code
                AND upper(btrim(uel.employee_code)) = (
                  SELECT upper(btrim(s.sa_employee_code))
                  FROM public.service_reception_entries s
                  WHERE s.dealer_code = c.dealer_code
                    AND public.customer_norm_reg(s.reg_number) = c.reg_key
                    AND NULLIF(btrim(s.sa_employee_code), '') IS NOT NULL
                  ORDER BY s.created_at DESC
                  LIMIT 1
                )
            )
          )
        )
        OR (
          COALESCE(c.contact_key, 'advisor') <> 'advisor'
          AND EXISTS (
            SELECT 1
            FROM public.settings_customer_helpdesk_contacts h
            JOIN public.users u ON u.id = p_user_id AND u.is_active = true
            WHERE h.is_active = true
              AND h.chat_contact_key = c.contact_key
              AND (
                lower(btrim(u.full_name)) = lower(btrim(h.contact_name))
                OR (
                  NULLIF(btrim(h.email), '') IS NOT NULL
                  AND lower(btrim(u.email)) = lower(btrim(h.email))
                )
                OR EXISTS (
                  SELECT 1
                  FROM public.user_employee_links uel
                  JOIN public.employee_master em ON upper(btrim(em.employee_code)) = upper(btrim(uel.employee_code))
                  WHERE uel.user_id = p_user_id
                    AND uel.is_active = true
                    AND uel.dealer_code = c.dealer_code
                    AND lower(btrim(em.employee_name)) = lower(btrim(h.contact_name))
                )
              )
          )
        )
      )
  );
$$;


--
-- Name: apply_admin_bypass_policy_on_ddl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_admin_bypass_policy_on_ddl() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  cmd RECORD;
  rel_name text;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.object_type = 'table' AND cmd.schema_name IN ('public', 'storage') THEN
      SELECT c.relname INTO rel_name
      FROM pg_class c
      WHERE c.oid = cmd.objid;

      IF rel_name IS NOT NULL THEN
        PERFORM public.ensure_admin_bypass_policy(cmd.schema_name, rel_name);
      END IF;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: apply_admin_bypass_policy_to_existing_tables(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_admin_bypass_policy_to_existing_tables() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  t RECORD;
BEGIN
  FOR t IN
    SELECT n.nspname AS schema_name, c.relname AS table_name
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relkind IN ('r', 'p')
      AND n.nspname IN ('public', 'storage')
      AND c.relrowsecurity = true
  LOOP
    PERFORM public.ensure_admin_bypass_policy(t.schema_name, t.table_name);
  END LOOP;
END;
$$;


--
-- Name: apply_dms_revenue_to_job_card_closed_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_dms_revenue_to_job_card_closed_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_dms record;
begin
  if coalesce(btrim(NEW.job_card_number), '') = '' then
    NEW.dms_final_labour_amount := null;
    NEW.dms_total_invoice_amount := null;
    return NEW;
  end if;

  select *
    into v_dms
  from public.latest_psf_revenue_dms_for_job_card(
    NEW.job_card_number,
    NEW.location,
    NEW.portal
  );

  if found then
    NEW.dms_final_labour_amount := v_dms.final_labour_amount;
    NEW.dms_total_invoice_amount := v_dms.total_invoice_amount;
  else
    NEW.dms_final_labour_amount := null;
    NEW.dms_total_invoice_amount := null;
  end if;

  return NEW;
end;
$$;


--
-- Name: apply_revisit_context_on_reception(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_revisit_context_on_reception() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_prior record;
BEGIN
  IF NULLIF(btrim(NEW.reg_number), '') IS NULL
     OR NOT public.is_floor_incharge_service_type(NEW.service_type) THEN
    NEW.is_revisit := false;
    NEW.prior_reception_entry_id := NULL;
    NEW.suggested_technician_code := NULL;
    NEW.suggested_technician_name := NULL;
    RETURN NEW;
  END IF;

  SELECT *
  INTO v_prior
  FROM public.lookup_reception_revisit_prior(
    NEW.reg_number,
    NEW.dealer_code,
    NEW.id
  );

  IF NOT FOUND OR v_prior.prior_id IS NULL THEN
    NEW.is_revisit := false;
    NEW.prior_reception_entry_id := NULL;
    NEW.suggested_technician_code := NULL;
    NEW.suggested_technician_name := NULL;
    RETURN NEW;
  END IF;

  NEW.is_revisit := true;
  NEW.prior_reception_entry_id := v_prior.prior_id;
  NEW.suggested_technician_code := NULLIF(btrim(v_prior.suggested_technician_code), '');
  NEW.suggested_technician_name := NULLIF(btrim(v_prior.suggested_technician_name), '');

  RETURN NEW;
END;
$$;


--
-- Name: apply_sa_business_mapping_on_employee_master(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_sa_business_mapping_on_employee_master() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  code_upper text;
BEGIN
  code_upper := upper(btrim(coalesce(NEW.employee_code, '')));

  IF code_upper = '' THEN
    RETURN NEW;
  END IF;

  IF code_upper LIKE '%500A840%' THEN
    NEW.location := 'Sitapura';
    NEW.fuel_type := 'EV';
  ELSIF code_upper LIKE '%3001440%' THEN
    NEW.location := 'Ajmer Road';
    NEW.fuel_type := 'PV';
  ELSIF code_upper LIKE '%3000840%' THEN
    NEW.location := 'Sitapura';
    NEW.fuel_type := 'PV';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: apply_sa_business_mapping_on_reception(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_sa_business_mapping_on_reception() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  code_upper text;
  code_part1 text;
  code_part2 text;
  employee_location text;
  employee_fuel_type text;
  mapped_dealer_code text;
BEGIN
  code_upper := upper(btrim(coalesce(NEW.sa_employee_code, '')));
  code_part1 := upper(btrim(coalesce(split_part(NEW.sa_employee_code, '_', 1), '')));
  code_part2 := upper(btrim(coalesce(split_part(NEW.sa_employee_code, '_', 2), '')));

  IF code_upper = '' THEN
    RETURN NEW;
  END IF;

  SELECT
    NULLIF(btrim(em.location), ''),
    CASE WHEN upper(btrim(coalesce(em.fuel_type, ''))) IN ('EV', 'PV') THEN upper(btrim(em.fuel_type)) ELSE NULL END
  INTO employee_location, employee_fuel_type
  FROM public.employee_master em
  WHERE upper(btrim(coalesce(em.employee_code, ''))) IN (code_upper, code_part1, code_part2)
  ORDER BY
    CASE
      WHEN upper(btrim(coalesce(em.employee_code, ''))) = code_upper THEN 1
      WHEN upper(btrim(coalesce(em.employee_code, ''))) = code_part1 THEN 2
      WHEN upper(btrim(coalesce(em.employee_code, ''))) = code_part2 THEN 3
      ELSE 9
    END
  LIMIT 1;

  IF code_part1 IN ('3000840', '500A840', '3001440') THEN
    mapped_dealer_code := code_part1;
  ELSIF code_part2 IN ('3000840', '500A840', '3001440') THEN
    mapped_dealer_code := code_part2;
  ELSIF code_upper IN ('3000840', '500A840', '3001440') THEN
    mapped_dealer_code := code_upper;
  ELSE
    mapped_dealer_code := NULL;
  END IF;

  -- Preserve existing dealer_code mapping behavior.
  IF mapped_dealer_code IS NOT NULL THEN
    NEW.dealer_code := mapped_dealer_code;
  END IF;

  -- Winning source for location is employee_master.location, fallback to legacy mapping.
  NEW.branch := COALESCE(
    employee_location,
    NEW.branch,
    CASE mapped_dealer_code
      WHEN '500A840' THEN 'Sitapura'
      WHEN '3000840' THEN 'Sitapura'
      WHEN '3001440' THEN 'Ajmer Road'
      ELSE NULL
    END
  );

  NEW.location := COALESCE(
    employee_location,
    NULLIF(btrim(coalesce(NEW.location, '')), ''),
    NULLIF(btrim(regexp_replace(coalesce(NEW.branch, ''), '(?i)\s+(EV|PV)$', '')), ''),
    NULLIF(btrim(coalesce(NEW.branch, '')), '')
  );

  NEW.portal := COALESCE(
    employee_fuel_type,
    CASE mapped_dealer_code
      WHEN '500A840' THEN 'EV'
      WHEN '3000840' THEN 'PV'
      WHEN '3001440' THEN 'PV'
      ELSE NULL
    END,
    CASE
      WHEN upper(btrim(coalesce(NEW.branch, ''))) LIKE '% EV' THEN 'EV'
      WHEN upper(btrim(coalesce(NEW.branch, ''))) LIKE '% PV' THEN 'PV'
      ELSE NULL
    END,
    CASE WHEN upper(btrim(coalesce(NEW.portal, ''))) IN ('EV', 'PV') THEN upper(btrim(NEW.portal)) ELSE NULL END
  );

  NEW.branch_label := COALESCE(
    NULLIF(btrim(coalesce(NEW.branch, '')), ''),
    NEW.location
  );

  RETURN NEW;
END;
$_$;


--
-- Name: apply_updation_available_on_reception(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_updation_available_on_reception() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_match record;
BEGIN
  IF NULLIF(btrim(NEW.reg_number), '') IS NULL THEN
    NEW.has_updation_available := false;
    NEW.updation_code := NULL;
    NEW.updation_name := NULL;
    RETURN NEW;
  END IF;

  SELECT *
  INTO v_match
  FROM public.lookup_updation_for_reg(NEW.reg_number, NEW.portal);

  IF NOT FOUND THEN
    NEW.has_updation_available := false;
    NEW.updation_code := NULL;
    NEW.updation_name := NULL;
    RETURN NEW;
  END IF;

  NEW.has_updation_available := true;
  NEW.updation_code := NULLIF(btrim(v_match.updation_code), '');
  NEW.updation_name := NULLIF(btrim(v_match.updation_name), '');
  RETURN NEW;
END;
$$;


--
-- Name: apply_vehicle_updation_claimed_portal(text, uuid, text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_vehicle_updation_claimed_portal(p_portal text, p_upload_session_id uuid, p_file_name text, p_sheet_name text, p_uploaded_by_email text, p_skipped_blank_rows integer, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_submitted_count integer := 0;
  v_removed_count integer := 0;
  v_not_found_count integer := 0;
  v_refresh jsonb;
BEGIN
  IF NOT (public.is_admin() OR public.has_module_modify('job_cards')) THEN
    RAISE EXCEPTION 'Permission denied for vehicle updation claimed import';
  END IF;

  IF p_portal NOT IN ('EV', 'PV') THEN
    RAISE EXCEPTION 'Invalid portal: %. Expected EV or PV.', p_portal;
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a JSON array';
  END IF;

  v_submitted_count := coalesce(jsonb_array_length(p_rows), 0);

  INSERT INTO public.vehicle_updation_uploads (
    portal,
    upload_kind,
    upload_session_id,
    uploaded_by_email,
    file_name,
    sheet_name,
    row_count,
    skipped_blank_rows
  ) VALUES (
    p_portal,
    'claimed',
    p_upload_session_id,
    nullif(btrim(p_uploaded_by_email), ''),
    nullif(btrim(p_file_name), ''),
    nullif(btrim(p_sheet_name), ''),
    v_submitted_count,
    coalesce(p_skipped_blank_rows, 0)
  );

  IF v_submitted_count > 0 THEN
    WITH claimed AS (
      SELECT DISTINCT upper(btrim(r.chassis_no)) AS chassis_norm
      FROM jsonb_to_recordset(p_rows) AS r(
        chassis_no text,
        source_row_number integer,
        source_file_name text,
        source_row_data jsonb
      )
      WHERE nullif(btrim(r.chassis_no), '') IS NOT NULL
    ),
    deleted AS (
      DELETE FROM public.vehicle_updation_data v
      USING claimed c
      WHERE v.portal = p_portal
        AND upper(btrim(v.chassis_no)) = c.chassis_norm
      RETURNING upper(btrim(v.chassis_no)) AS chassis_norm
    )
    SELECT
      (SELECT COUNT(*) FROM claimed),
      (SELECT COUNT(*) FROM deleted),
      (
        SELECT COUNT(*)
        FROM claimed c
        WHERE NOT EXISTS (
          SELECT 1
          FROM deleted d
          WHERE d.chassis_norm = c.chassis_norm
        )
      )
    INTO v_submitted_count, v_removed_count, v_not_found_count;
  END IF;

  v_refresh := public.refresh_reception_updation_flags();

  RETURN jsonb_build_object(
    'portal', p_portal,
    'submitted_count', v_submitted_count,
    'removed_count', v_removed_count,
    'not_found_count', v_not_found_count,
    'skipped_blank_rows', coalesce(p_skipped_blank_rows, 0),
    'upload_session_id', p_upload_session_id,
    'reception_flags', v_refresh
  );
END;
$$;


--
-- Name: FUNCTION apply_vehicle_updation_claimed_portal(p_portal text, p_upload_session_id uuid, p_file_name text, p_sheet_name text, p_uploaded_by_email text, p_skipped_blank_rows integer, p_rows jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_vehicle_updation_claimed_portal(p_portal text, p_upload_session_id uuid, p_file_name text, p_sheet_name text, p_uploaded_by_email text, p_skipped_blank_rows integer, p_rows jsonb) IS 'Remove claimed updation chassis numbers from pending vehicle_updation_data for one portal and refresh reception flags.';


--
-- Name: auto_close_unverified_help_tickets(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_close_unverified_help_tickets(p_limit integer DEFAULT 200, p_grace_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
  v_grace integer := GREATEST(1, COALESCE(p_grace_days, 7));
  v_closed_count integer := 0;
  r record;
BEGIN
  FOR r IN
    SELECT t.id, t.ticket_number, t.raised_by_user_id, t.status, t.resolved_at
    FROM public.help_tickets t
    WHERE t.status IN ('resolved', 'cannot_reproduce')
      AND t.verification_status = 'pending'
      AND t.resolved_at IS NOT NULL
      AND t.resolved_at < (now() - make_interval(days => v_grace))
    ORDER BY t.resolved_at ASC
    LIMIT v_limit
    FOR UPDATE OF t SKIP LOCKED
  LOOP
    UPDATE public.help_tickets SET
      status = 'closed',
      verification_status = 'auto_closed',
      closed_at = now(),
      closure_reason = COALESCE(closure_reason, 'auto_closed_unverified'),
      updated_at = now()
    WHERE id = r.id;

    PERFORM public.help_ticket_write_audit(
      r.id,
      'closed',
      r.status,
      'closed',
      format('Auto-closed after %s days without raiser verification', v_grace),
      NULL,
      NULL,
      'system'
    );

    PERFORM public.help_ticket_emit_notification(
      r.id,
      'closed',
      'raiser',
      r.raised_by_user_id,
      jsonb_build_object(
        'ticket_number', r.ticket_number,
        'reason', 'auto_closed_unverified',
        'grace_days', v_grace
      )
    );
    PERFORM public.help_ticket_notify_support_holders(
      r.id,
      'closed',
      jsonb_build_object(
        'ticket_number', r.ticket_number,
        'reason', 'auto_closed_unverified',
        'grace_days', v_grace
      )
    );

    v_closed_count := v_closed_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'closed_count', v_closed_count,
    'grace_days', v_grace,
    'checked_at', now()
  );
END;
$$;


