--
-- Name: backfill_job_card_closed_dms_revenue_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_job_card_closed_dms_revenue_batch(p_batch_size integer DEFAULT 1000) RETURNS TABLE(processed_source_rows integer, updated_job_card_rows integer, last_psf_revenue_dms_id bigint, is_complete boolean)
    LANGUAGE plpgsql
    AS $$
declare
  v_start_after bigint := 0;
  v_last_id bigint := 0;
  v_processed integer := 0;
  v_updated integer := 0;
  v_total_updated integer := 0;
  v_batch_size integer := greatest(1, least(coalesce(p_batch_size, 1000), 10000));
  r record;
begin
  select p.last_psf_revenue_dms_id
    into v_start_after
  from public.psf_revenue_dms_backfill_progress p
  where p.id = true
  for update;

  for r in
    select d.id, d.job_card_number, d.location, d.portal
    from public.psf_revenue_dms d
    where d.id > v_start_after
      and coalesce(btrim(d.job_card_number), '') <> ''
    order by d.id
    limit v_batch_size
  loop
    v_processed := v_processed + 1;
    v_last_id := r.id;

    select public.refresh_job_card_closed_dms_revenue(r.job_card_number, r.location, r.portal)
      into v_updated;
    v_total_updated := v_total_updated + coalesce(v_updated, 0);
  end loop;

  update public.psf_revenue_dms_backfill_progress p
     set last_psf_revenue_dms_id = case when v_processed > 0 then v_last_id else p.last_psf_revenue_dms_id end,
         processed_source_rows = p.processed_source_rows + v_processed,
         updated_rows = p.updated_rows + v_total_updated,
         completed_at = case when v_processed = 0 then now() else null end,
         updated_at = now()
   where p.id = true;

  return query
  select
    v_processed,
    v_total_updated,
    case when v_processed > 0 then v_last_id else v_start_after end,
    v_processed = 0;
end;
$$;


--
-- Name: bodyshop_can_read_reception_via_linked_card(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bodyshop_can_read_reception_via_linked_card(p_reception_entry_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    public.is_admin()
    OR (
      (public.has_module_view('service_advisor') OR public.has_module_modify('service_advisor'))
      AND EXISTS (
        SELECT 1
        FROM public.bodyshop_repair_cards brc
        WHERE brc.reception_entry_id = p_reception_entry_id
          AND brc.sa_employee_code IS NOT NULL
          AND public.user_has_employee_code(brc.sa_employee_code)
      )
    );
$$;


--
-- Name: FUNCTION bodyshop_can_read_reception_via_linked_card(p_reception_entry_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bodyshop_can_read_reception_via_linked_card(p_reception_entry_id bigint) IS 'SECURITY DEFINER intake read gate: true when caller is admin or mapped SA on a bodyshop_repair_cards row linked to this reception. Matches bodyshop_save_reception_jc_km write auth without cross-table RLS recursion.';


--
-- Name: bodyshop_insurer_payer_mismatch(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bodyshop_insurer_payer_mismatch(p_policy text, p_bill_to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT
    v.p <> '' AND v.b <> ''
    AND position(split_part(v.p, ' ', 1) in v.b) = 0
    AND position(split_part(v.b, ' ', 1) in v.p) = 0
  FROM (
    SELECT
      regexp_replace(
        regexp_replace(lower(btrim(split_part(lower(COALESCE(p_policy, '')), ' c/o ', 1))), '^m/s\.?\s+', ''),
        '^the\s+',
        ''
      ) AS p,
      regexp_replace(
        regexp_replace(lower(btrim(split_part(lower(COALESCE(p_bill_to, '')), ' c/o ', 1))), '^m/s\.?\s+', ''),
        '^the\s+',
        ''
      ) AS b
  ) v;
$$;


--
-- Name: bodyshop_save_reception_jc_km(bigint, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bodyshop_save_reception_jc_km(p_reception_entry_id bigint, p_jc_number text DEFAULT NULL::text, p_km_reading integer DEFAULT NULL::integer) RETURNS TABLE(id bigint, jc_number text, km_reading integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sa_employee_code text;
  v_card_sa_code     text;
  v_is_admin         boolean;
  v_has_sa_modify    boolean;
BEGIN
  -- ── 1. Authorisation ────────────────────────────────────────────────────
  v_is_admin      := public.is_admin();
  v_has_sa_modify := public.has_module_modify('service_advisor');

  IF NOT (v_is_admin OR v_has_sa_modify) THEN
    RAISE EXCEPTION 'permission denied: requires service_advisor modify or admin'
      USING ERRCODE = '42501';
  END IF;

  SELECT sre.sa_employee_code
    INTO v_sa_employee_code
    FROM public.service_reception_entries sre
   WHERE sre.id = p_reception_entry_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reception entry % not found', p_reception_entry_id
      USING ERRCODE = 'P0002';
  END IF;

  -- Non-admins must map to the SA on the reception row (or linked repair card).
  IF NOT v_is_admin THEN
    SELECT brc.sa_employee_code
      INTO v_card_sa_code
      FROM public.bodyshop_repair_cards brc
     WHERE brc.reception_entry_id = p_reception_entry_id
     ORDER BY brc.updated_at DESC NULLS LAST, brc.id DESC
     LIMIT 1;

    IF NOT (
      (v_sa_employee_code IS NOT NULL AND public.user_has_employee_code(v_sa_employee_code))
      OR (v_card_sa_code IS NOT NULL AND public.user_has_employee_code(v_card_sa_code))
    ) THEN
      RAISE EXCEPTION 'permission denied: caller is not the SA on this reception entry'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- ── 2. Build and execute the UPDATE ─────────────────────────────────────
  RETURN QUERY
  UPDATE public.service_reception_entries sre
     SET jc_number  = COALESCE(p_jc_number,  sre.jc_number),
         km_reading = COALESCE(p_km_reading, sre.km_reading),
         updated_at = now()
   WHERE sre.id = p_reception_entry_id
   RETURNING sre.id, sre.jc_number, sre.km_reading;
END;
$$;


--
-- Name: FUNCTION bodyshop_save_reception_jc_km(p_reception_entry_id bigint, p_jc_number text, p_km_reading integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bodyshop_save_reception_jc_km(p_reception_entry_id bigint, p_jc_number text, p_km_reading integer) IS 'SECURITY DEFINER RPC: updates jc_number and/or km_reading on a single service_reception_entries row. Bypasses expensive authenticated-role RLS policies while enforcing the same authorization rules as service_reception_update_sa (user_has_employee_code on reception or linked bodyshop repair card SA code). Admin bypasses SA ownership check.';


--
-- Name: bodyshop_settlement_can_modify(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bodyshop_settlement_can_modify(p_repair_card_id integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dealer text;
BEGIN
  IF public.is_admin() THEN
    RETURN true;
  END IF;
  IF NOT public.has_module_modify('bodyshop_repair') THEN
    RETURN false;
  END IF;

  SELECT sre.dealer_code
    INTO v_dealer
    FROM public.bodyshop_repair_cards brc
    LEFT JOIN public.service_reception_entries sre ON sre.id = brc.reception_entry_id
   WHERE brc.id = p_repair_card_id;

  IF v_dealer IS NULL THEN
    RETURN false;
  END IF;
  RETURN public.dealer_code_in_scope(v_dealer);
END;
$$;


--
-- Name: bodyshop_settlement_can_post_customer(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bodyshop_settlement_can_post_customer(p_repair_card_id integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.is_admin() THEN
    RETURN true;
  END IF;
  IF public.has_module_view('accounts')
     OR public.has_module_modify('accounts') THEN
    RETURN true;
  END IF;
  RETURN public.bodyshop_settlement_can_modify(p_repair_card_id);
END;
$$;


--
-- Name: bodyshop_settlement_can_post_do(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bodyshop_settlement_can_post_do(p_repair_card_id integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.is_admin() THEN
    RETURN true;
  END IF;
  IF public.has_module_view('accounts')
     OR public.has_module_modify('accounts') THEN
    RETURN true;
  END IF;
  IF public.has_module_view('bodyshop_recovery')
     OR public.has_module_modify('bodyshop_recovery') THEN
    RETURN true;
  END IF;
  RETURN public.bodyshop_settlement_can_modify(p_repair_card_id);
END;
$$;


--
-- Name: FUNCTION bodyshop_settlement_can_post_do(p_repair_card_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bodyshop_settlement_can_post_do(p_repair_card_id integer) IS 'ACCOUNTS-001 / DBL-0055: admin, accounts view/modify, recovery view/modify, or bodyshop_repair modify.';


--
-- Name: bodyshop_settlement_can_view(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bodyshop_settlement_can_view(p_repair_card_id integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dealer text;
BEGIN
  IF public.is_admin() THEN
    RETURN true;
  END IF;

  IF public.has_module_view('accounts')
     OR public.has_module_modify('accounts') THEN
    RETURN true;
  END IF;

  -- Recovery is org-wide. Do not require a mapped dealer or branch.
  IF public.has_module_view('bodyshop_recovery')
     OR public.has_module_modify('bodyshop_recovery') THEN
    RETURN true;
  END IF;

  IF NOT (
    public.has_module_view('bodyshop_repair')
    OR public.has_module_modify('bodyshop_repair')
    OR public.has_module_view('bodyshop_tracker')
    OR public.has_module_view('bodyshop_floor')
  ) THEN
    RETURN false;
  END IF;

  SELECT sre.dealer_code
    INTO v_dealer
    FROM public.bodyshop_repair_cards brc
    LEFT JOIN public.service_reception_entries sre ON sre.id = brc.reception_entry_id
   WHERE brc.id = p_repair_card_id;

  IF v_dealer IS NULL THEN
    RETURN false;
  END IF;
  RETURN public.dealer_code_in_scope(v_dealer);
END;
$$;


--
-- Name: bodyshop_settlement_lines_protect_voucher(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bodyshop_settlement_lines_protect_voucher() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.voucher_no IS NOT NULL AND NEW.voucher_no IS DISTINCT FROM OLD.voucher_no THEN
    RAISE EXCEPTION 'voucher_no is immutable once assigned'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bulk_create_reception_entries(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_create_reception_entries(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dealer_code text;
  v_row         jsonb;
  v_count       integer := 0;
  v_sa_name     text;
BEGIN
  v_dealer_code := public.my_dealer_code();

  IF NOT (
    public.is_admin()
    OR (
      public.has_module_modify('reception')
      AND public.dealer_code_in_scope(v_dealer_code)
    )
  ) THEN
    RAISE EXCEPTION 'permission denied: requires reception modify or admin'
      USING ERRCODE = '42501';
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN 0;
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    SELECT em.employee_name
      INTO v_sa_name
      FROM public.employee_master em
     WHERE em.employee_code = upper(btrim(v_row ->> 'sa_employee_code'));

    IF NOT FOUND OR NULLIF(btrim(coalesce(v_sa_name, '')), '') IS NULL THEN
      CONTINUE;
    END IF;

    INSERT INTO public.service_reception_entries (
      reg_number,
      model,
      service_type,
      sa_employee_code,
      sa_name,
      sa_display_name,
      owner_name,
      owner_phone,
      source,
      km_reading,
      jc_number,
      branch,
      dealer_code
    ) VALUES (
      upper(btrim(coalesce(v_row ->> 'reg_number', ''))),
      NULLIF(btrim(coalesce(v_row ->> 'model', '')), ''),
      NULLIF(btrim(coalesce(v_row ->> 'service_type', '')), ''),
      upper(btrim(coalesce(v_row ->> 'sa_employee_code', ''))),
      v_sa_name,
      v_sa_name,
      NULLIF(btrim(coalesce(v_row ->> 'owner_name', '')), ''),
      btrim(coalesce(v_row ->> 'owner_phone', '')),
      NULLIF(btrim(coalesce(v_row ->> 'source', '')), ''),
      NULLIF(v_row ->> 'km_reading', '')::integer,
      NULLIF(upper(btrim(coalesce(v_row ->> 'jc_number', ''))), ''),
      NULLIF(btrim(coalesce(v_row ->> 'branch', '')), ''),
      v_dealer_code
    );

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION bulk_create_reception_entries(p_rows jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bulk_create_reception_entries(p_rows jsonb) IS 'Bulk reception import bypassing authenticated RLS (57014 on multi-row INSERT).';


--
-- Name: busy_insurance_master_normalize_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.busy_insurance_master_normalize_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
  NEW.company_name := btrim(regexp_replace(coalesce(NEW.company_name, ''), '\s+', ' ', 'g'));
  NEW.busy_group := btrim(regexp_replace(coalesce(NEW.busy_group, ''), '\s+', ' ', 'g'));
  NEW.gstin := upper(regexp_replace(coalesce(NEW.gstin, ''), '[\s-]', '', 'g'));

  IF length(NEW.company_name) = 0 THEN
    RAISE EXCEPTION 'Insurance company name cannot be empty';
  END IF;
  IF length(NEW.busy_group) = 0 THEN
    RAISE EXCEPTION 'BUSY Group of Account cannot be empty';
  END IF;
  IF NEW.gstin !~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][A-Z0-9]Z[A-Z0-9]$' THEN
    RAISE EXCEPTION 'GSTIN is missing or invalid';
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: busy_parts_account_master_normalize_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.busy_parts_account_master_normalize_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_code text;
BEGIN
  v_code := upper(regexp_replace(split_part(btrim(coalesce(NEW.code, '')), '-', 1), '\s+', '', 'g'));
  NEW.code := v_code;
  NEW.party_name := btrim(regexp_replace(coalesce(NEW.party_name, ''), '\s+', ' ', 'g'));
  NEW.busy_group := btrim(regexp_replace(coalesce(NEW.busy_group, ''), '\s+', ' ', 'g'));
  NEW.gstin := upper(regexp_replace(coalesce(NEW.gstin, ''), '[\s-]', '', 'g'));

  IF NEW.code !~ '^[0-9A-Z]+$' THEN
    RAISE EXCEPTION 'Dealer code is missing or invalid';
  END IF;
  IF length(NEW.party_name) = 0 THEN
    RAISE EXCEPTION 'Party Name cannot be empty';
  END IF;
  IF length(NEW.busy_group) = 0 THEN
    RAISE EXCEPTION 'BUSY Group of Account cannot be empty';
  END IF;
  IF NEW.gstin !~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][A-Z0-9]Z[A-Z0-9]$' THEN
    RAISE EXCEPTION 'GSTIN is missing or invalid';
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: calc_all_service_assumed_next_service_date(date, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_all_service_assumed_next_service_date(p_last_service_date date, p_last_service_type text, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS date
    LANGUAGE sql STABLE
    AS $$
  WITH normalized AS (
    SELECT lower(btrim(COALESCE(p_last_service_type, ''))) AS lst
  ), inferred_type AS (
    SELECT public.calc_all_service_assumed_next_service_type(p_last_service_type) AS assumed_type
  )
  SELECT
    CASE
      WHEN it.assumed_type = 'Unknown' THEN NULL
      WHEN p_last_service_date IS NULL THEN NULL
      ELSE p_as_of_date + (
        (
          CASE
            WHEN n.lst = '' OR n.lst = 'new' THEN 60
            WHEN n.lst IN ('first free service', 'tma-first free service') THEN 120
            ELSE 180
          END
        )
        - MOD(GREATEST(0, (p_as_of_date - p_last_service_date)::int), 180)
      )
    END
  FROM normalized n
  CROSS JOIN inferred_type it;
$$;


--
-- Name: FUNCTION calc_all_service_assumed_next_service_date(p_last_service_date date, p_last_service_type text, p_as_of_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calc_all_service_assumed_next_service_date(p_last_service_date date, p_last_service_type text, p_as_of_date date) IS 'Date-typed overload matching all_service_data.last_service_date (converted from timestamptz on 2026-07-07). Same Phase 4 projection rule as the text/timestamptz overloads; no timezone parsing needed since the input is already a plain date.';


--
-- Name: calc_all_service_assumed_next_service_date(text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_all_service_assumed_next_service_date(p_last_service_date text, p_last_service_type text, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS date
    LANGUAGE sql STABLE
    AS $$
  WITH parsed AS (
    SELECT public.parse_all_service_date_text(p_last_service_date) AS last_service_dt
  ), normalized AS (
    SELECT lower(btrim(COALESCE(p_last_service_type, ''))) AS lst
  ), inferred_type AS (
    SELECT public.calc_all_service_assumed_next_service_type(p_last_service_type) AS assumed_type
  )
  SELECT
    CASE
      WHEN it.assumed_type = 'Unknown' THEN NULL
      WHEN p.last_service_dt IS NULL THEN NULL
      ELSE p_as_of_date + (
        (
          CASE
            WHEN n.lst = '' OR n.lst = 'new' THEN 60
            WHEN n.lst IN ('first free service', 'tma-first free service') THEN 120
            ELSE 180
          END
        )
        - MOD(GREATEST(0, (p_as_of_date - p.last_service_dt)::int), 180)
      )
    END
  FROM parsed p
  CROSS JOIN normalized n
  CROSS JOIN inferred_type it;
$$;


--
-- Name: FUNCTION calc_all_service_assumed_next_service_date(p_last_service_date text, p_last_service_type text, p_as_of_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calc_all_service_assumed_next_service_date(p_last_service_date text, p_last_service_type text, p_as_of_date date) IS 'Implements approved Phase 4 rule: assumed_next_service_date = as_of_date + (target_days - MOD(GREATEST(0, as_of_date - parsed_last_service_date), 180)); target_days: 60 for new/null/empty, 120 for first free/tma-first free, else 180. Additional guard: returns NULL when inferred assumed_next_service_type is Unknown.';


--
-- Name: calc_all_service_assumed_next_service_date(timestamp with time zone, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_all_service_assumed_next_service_date(p_last_service_date timestamp with time zone, p_last_service_type text, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS date
    LANGUAGE sql STABLE
    AS $$
  WITH normalized AS (
    SELECT lower(btrim(COALESCE(p_last_service_type, ''))) AS lst
  ), inferred_type AS (
    SELECT public.calc_all_service_assumed_next_service_type(p_last_service_type) AS assumed_type
  ), parsed AS (
    SELECT (p_last_service_date AT TIME ZONE 'Asia/Kolkata')::date AS last_service_dt
  )
  SELECT
    CASE
      WHEN it.assumed_type = 'Unknown' THEN NULL
      WHEN p.last_service_dt IS NULL THEN NULL
      ELSE p_as_of_date + (
        (
          CASE
            WHEN n.lst = '' OR n.lst = 'new' THEN 60
            WHEN n.lst IN ('first free service', 'tma-first free service') THEN 120
            ELSE 180
          END
        )
        - MOD(GREATEST(0, (p_as_of_date - p.last_service_dt)::int), 180)
      )
    END
  FROM parsed p
  CROSS JOIN normalized n
  CROSS JOIN inferred_type it;
$$;


--
-- Name: calc_all_service_assumed_next_service_type(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_all_service_assumed_next_service_type(p_last_service_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  WITH normalized AS (
    SELECT lower(btrim(COALESCE(p_last_service_type, ''))) AS lst
  )
  SELECT
    CASE
      WHEN n.lst = '' THEN NULL
      WHEN n.lst = 'new' THEN 'First Free Service'
      WHEN n.lst = 'first free service' THEN 'Second Free Service'
      WHEN n.lst = 'second free service' THEN 'Third Free Service'
      WHEN n.lst = 'tma-first free service' THEN 'Second Free Service'
      WHEN n.lst = 'tma-second free service' THEN 'Third Free Service'
      WHEN n.lst = 'tma-third free service' THEN 'Paid Service'
      WHEN n.lst = 'third free service' THEN 'Paid Service'
      WHEN n.lst = 'fourth free service' THEN 'Paid Service'
      WHEN n.lst = 'fifth free service' THEN 'Paid Service'
      WHEN n.lst = 'sixth free service' THEN 'Paid Service'
      WHEN n.lst = 'seventh free service' THEN 'Paid Service'
      WHEN n.lst = 'tenth free service' THEN 'Paid Service'
      WHEN n.lst = 'paid service' THEN 'Paid Service'
      WHEN n.lst = 'schedule service' THEN 'Paid Service'
      ELSE 'Unknown'
    END
  FROM normalized n;
$$;


--
-- Name: FUNCTION calc_all_service_assumed_next_service_type(p_last_service_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calc_all_service_assumed_next_service_type(p_last_service_type text) IS 'Maps known last_service_type values to assumed_next_service_type. Any non-blank unmapped value stays Unknown.';


--
-- Name: calc_all_service_dynamic_priority_bucket(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_all_service_dynamic_priority_bucket(p_sold_dealer text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN lower(btrim(COALESCE(p_sold_dealer, ''))) = 'techwheels' THEN 1
    WHEN lower(btrim(COALESCE(p_sold_dealer, ''))) = 'others' THEN 2
    ELSE 3
  END;
$$;


--
-- Name: FUNCTION calc_all_service_dynamic_priority_bucket(p_sold_dealer text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calc_all_service_dynamic_priority_bucket(p_sold_dealer text) IS 'Priority bucket mapping: Techwheels=1, Others=2, NULL/other=3.';


--
-- Name: calc_all_service_dynamic_priority_score(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_all_service_dynamic_priority_score(p_assumed_next_service_date date, p_assumed_next_service_type text) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT public.calc_all_service_dynamic_priority_score(
    p_assumed_next_service_date,
    p_assumed_next_service_type,
    NULL
  );
$$;


--
-- Name: FUNCTION calc_all_service_dynamic_priority_score(p_assumed_next_service_date date, p_assumed_next_service_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calc_all_service_dynamic_priority_score(p_assumed_next_service_date date, p_assumed_next_service_type text) IS 'Compatibility wrapper that routes to the 3-arg scorer with NULL vehicle_sale_date.';


--
-- Name: calc_all_service_dynamic_priority_score(date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_all_service_dynamic_priority_score(p_assumed_next_service_date date, p_assumed_next_service_type text, p_vehicle_sale_date_text text) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    AS $$
  WITH parsed AS (
    SELECT public.parse_all_service_date_text(p_vehicle_sale_date_text) AS vehicle_sale_dt
  ), parts AS (
    SELECT
      -- Higher component = earlier assumed_next_service_date; NULL dates are lowest.
      CASE
        WHEN p_assumed_next_service_date IS NULL THEN 0
        ELSE GREATEST(1, 36500 - LEAST(36499, (p_assumed_next_service_date - DATE '2000-01-01')))
      END AS assumed_date_component,
      CASE
        WHEN lower(btrim(COALESCE(p_assumed_next_service_type, ''))) = 'first free service' THEN 99
        WHEN lower(btrim(COALESCE(p_assumed_next_service_type, ''))) = 'second free service' THEN 98
        WHEN lower(btrim(COALESCE(p_assumed_next_service_type, ''))) = 'third free service' THEN 97
        WHEN lower(btrim(COALESCE(p_assumed_next_service_type, ''))) = 'paid service' THEN 96
        WHEN lower(btrim(COALESCE(p_assumed_next_service_type, ''))) = 'unknown' THEN 95
        WHEN NULLIF(btrim(COALESCE(p_assumed_next_service_type, '')), '') IS NULL THEN 94
        ELSE 93
      END AS type_component,
      -- Newer vehicle_sale_date gets higher component; NULL/unparseable is lowest.
      CASE
        WHEN p.vehicle_sale_dt IS NULL THEN 0
        ELSE LEAST(99999, GREATEST(1, (p.vehicle_sale_dt - DATE '2000-01-01') + 1))
      END AS vehicle_sale_component
    FROM parsed p
  )
  SELECT
    (assumed_date_component::bigint * 10000000)
    + (type_component::bigint * 100000)
    + vehicle_sale_component::bigint
  FROM parts;
$$;


--
-- Name: FUNCTION calc_all_service_dynamic_priority_score(p_assumed_next_service_date date, p_assumed_next_service_type text, p_vehicle_sale_date_text text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calc_all_service_dynamic_priority_score(p_assumed_next_service_date date, p_assumed_next_service_type text, p_vehicle_sale_date_text text) IS 'Higher score = higher priority inside bucket. Encodes assumed_next_service_date asc (NULL last), then assumed_next_service_type rank, then exact vehicle_sale_date desc (new to old; NULL/unparseable last).';


--
-- Name: calc_all_service_powertrain_type(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_all_service_powertrain_type(p_product_line text) RETURNS text
    LANGUAGE sql STABLE
    AS $_$
  WITH normalized AS (
    SELECT upper(btrim(COALESCE(p_product_line, ''))) AS pl
  ), base AS (
    SELECT
      CASE
        WHEN n.pl = '' THEN NULL
        WHEN n.pl LIKE '%EV%' THEN 'EV'
        WHEN n.pl LIKE '%CNG%' THEN 'CNG'
        WHEN (
          n.pl ~ '(^|[^A-Z0-9])QJET([^A-Z0-9]|$)'
          OR n.pl LIKE '%DICOR%'
          OR n.pl ~ '(^|[^A-Z0-9])CR4([^A-Z0-9]|$)'
          OR n.pl LIKE '%(D)%'
          OR n.pl LIKE '%DIESEL%'
          OR n.pl LIKE '%1.05 D%'
          OR n.pl ~ '(^|[^0-9])1\.5([^0-9]|$)'
        ) THEN 'DIESEL'
        WHEN (
          n.pl LIKE '%(P)%'
          OR n.pl LIKE '%PETROL%'
          OR n.pl LIKE '%1.2 P%'
          OR n.pl LIKE '%1.0 P%'
          OR n.pl LIKE '%GDI%'
        ) THEN 'PETROL'
        ELSE NULL
      END AS base_result,
      n.pl
    FROM normalized n
  ), ov AS (
    SELECT o.powertrain_type
    FROM base b
    JOIN public.all_service_data_powertrain_overrides o
      ON o.is_active = true
     AND b.pl LIKE upper(o.match_pattern)
    ORDER BY o.priority ASC, o.id ASC
    LIMIT 1
  )
  SELECT
    CASE
      WHEN b.base_result IS NOT NULL THEN b.base_result
      WHEN EXISTS (SELECT 1 FROM ov) THEN (SELECT powertrain_type FROM ov)
      WHEN b.pl = '' THEN NULL
      ELSE 'UNKNOWN'
    END
  FROM base b;
$_$;


--
-- Name: FUNCTION calc_all_service_powertrain_type(p_product_line text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calc_all_service_powertrain_type(p_product_line text) IS 'Deterministic powertrain mapping from product_line. Ordered rules: EV/CNG/DIESEL/PETROL explicit markers, then active override table match_pattern by priority, else UNKNOWN; blank => NULL.';


--
-- Name: can_access_bodyshop_surveyor_settings(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_bodyshop_surveyor_settings(target_dealer text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_target text := upper(btrim(coalesce(target_dealer, '')));
  v_has_bodyshop_role boolean := false;
  v_has_module_access boolean := false;
BEGIN
  IF v_uid IS NULL OR v_target = '' THEN
    RETURN false;
  END IF;

  IF public.is_admin() THEN
    RETURN true;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.get_my_bodyshop_employee_scope() s
    WHERE public.employee_has_any_business_role(s.role, ARRAY['SA', 'EDP', 'SURVEY'])
  ) INTO v_has_bodyshop_role;

  v_has_module_access := (
    public.has_module_view('settings'::text)
    OR public.has_module_view('bodyshop_repair'::text)
    OR public.has_module_modify('bodyshop_repair'::text)
  );

  RETURN (
    EXISTS (
      SELECT 1
      FROM unnest(public.my_effective_dealer_codes()) AS dc(code)
      WHERE upper(btrim(coalesce(dc.code, ''))) = v_target
    )
    OR EXISTS (
      SELECT 1
      FROM public.user_employee_links uel
      WHERE uel.user_id = v_uid
        AND uel.is_active = true
        AND upper(btrim(coalesce(uel.dealer_code, ''))) = v_target
    )
  )
  AND (v_has_module_access OR v_has_bodyshop_role);
END;
$$;


--
-- Name: FUNCTION can_access_bodyshop_surveyor_settings(target_dealer text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_access_bodyshop_surveyor_settings(target_dealer text) IS 'Checks whether current user can access bodyshop surveyor settings for a dealer via admin, module scope, or mapped bodyshop role.';


