COMMENT ON FUNCTION public.can_manage_fuel_rules() IS 'Fuel RPC guard: true for admin users, service_role API callers, and postgres SQL-editor sessions.';


--
-- Name: can_view_bodyshop_surveyor_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_bodyshop_surveyor_catalog() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_has_bodyshop_role boolean := false;
BEGIN
  IF public.is_admin() THEN
    RETURN true;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.get_my_bodyshop_employee_scope() s
    WHERE public.employee_has_any_business_role(s.role, ARRAY['SA', 'EDP', 'SURVEY'])
  ) INTO v_has_bodyshop_role;

  RETURN (
    public.has_module_view('settings'::text)
    OR public.has_module_view('bodyshop_repair'::text)
    OR public.has_module_modify('bodyshop_repair'::text)
    OR v_has_bodyshop_role
  );
END;
$$;


--
-- Name: capture_bodyshop_customer_group_wa_click(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_bodyshop_customer_group_wa_click() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- First transition from stage <=4 to stage >=5 marks Customer Group completion.
  IF COALESCE(OLD.current_stage, 0) <= 4 AND COALESCE(NEW.current_stage, 0) >= 5 THEN
    IF NEW.customer_group_wa_sent_at IS NULL THEN
      NEW.customer_group_wa_sent_at := COALESCE(NEW.updated_at, now());
    END IF;

    IF COALESCE(BTRIM(NEW.customer_group_wa_sent_by), '') = '' THEN
      NEW.customer_group_wa_sent_by := COALESCE(auth.uid()::text, NEW.customer_group_wa_sent_by);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: check_complaint_sla_breaches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_complaint_sla_breaches() RETURNS TABLE(breached_count integer, escalated_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_breached_count integer := 0;
  v_escalated_count integer := 0;
BEGIN
  -- Mark response breaches
  UPDATE public.complaint_tickets
  SET response_breached = true
  WHERE response_due_at < now()
    AND first_response_at IS NULL
    AND response_breached = false
    AND status IN ('new', 'acknowledged');

  GET DIAGNOSTICS v_breached_count = ROW_COUNT;

  -- Mark resolution breaches
  UPDATE public.complaint_tickets
  SET resolution_breached = true
  WHERE resolution_due_at < now()
    AND status NOT IN ('resolved', 'closed')
    AND resolution_breached = false;

  GET DIAGNOSTICS v_escalated_count = ROW_COUNT;

  -- Auto-escalate breached tickets
  UPDATE public.complaint_tickets
  SET
    is_escalated = true,
    escalated_at = now(),
    escalation_reason = 'SLA breached: auto-escalated'
  WHERE (response_breached = true OR resolution_breached = true)
    AND is_escalated = false;

  RETURN QUERY SELECT v_breached_count::integer, v_escalated_count::integer;
END;
$$;


--
-- Name: check_help_ticket_sla_breaches(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_help_ticket_sla_breaches(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
  v_response_count integer := 0;
  v_resolution_count integer := 0;
  r record;
  v_payload jsonb;
BEGIN
  -- Response SLA: no first support reply yet; not paused; still open work
  FOR r IN
    SELECT t.id, t.ticket_number, t.sla_response_at, t.status, t.priority
    FROM public.help_tickets t
    WHERE t.status NOT IN ('closed', 'resolved', 'cannot_reproduce')
      AND COALESCE(t.sla_paused, false) = false
      AND t.status NOT IN ('on_hold', 'waiting_raiser')
      AND t.first_response_at IS NULL
      AND t.sla_response_at IS NOT NULL
      AND t.sla_response_at < now()
      AND t.sla_response_breached_at IS NULL
    ORDER BY t.sla_response_at ASC
    LIMIT v_limit
    FOR UPDATE OF t SKIP LOCKED
  LOOP
    UPDATE public.help_tickets SET
      sla_response_breached_at = now(),
      tags = CASE
        WHEN 'sla_breached' = ANY(tags) THEN tags
        ELSE array_append(tags, 'sla_breached')
      END,
      updated_at = now()
    WHERE id = r.id;

    PERFORM public.help_ticket_write_audit(
      r.id,
      'sla_breached',
      NULL,
      'response',
      'Response SLA breached',
      NULL,
      NULL,
      'system'
    );

    v_payload := jsonb_build_object(
      'ticket_number', r.ticket_number,
      'breach_type', 'response',
      'sla_at', r.sla_response_at,
      'status', r.status,
      'priority', r.priority
    );
    PERFORM public.help_ticket_notify_support_holders(r.id, 'sla_breached', v_payload);

    v_response_count := v_response_count + 1;
  END LOOP;

  -- Resolution SLA: still not resolved/closed; not paused
  FOR r IN
    SELECT t.id, t.ticket_number, t.sla_resolution_at, t.status, t.priority
    FROM public.help_tickets t
    WHERE t.status NOT IN ('closed', 'resolved', 'cannot_reproduce')
      AND COALESCE(t.sla_paused, false) = false
      AND t.status NOT IN ('on_hold', 'waiting_raiser')
      AND t.sla_resolution_at IS NOT NULL
      AND t.sla_resolution_at < now()
      AND t.sla_resolution_breached_at IS NULL
    ORDER BY t.sla_resolution_at ASC
    LIMIT v_limit
    FOR UPDATE OF t SKIP LOCKED
  LOOP
    UPDATE public.help_tickets SET
      sla_resolution_breached_at = now(),
      tags = CASE
        WHEN 'sla_breached' = ANY(tags) THEN tags
        ELSE array_append(tags, 'sla_breached')
      END,
      updated_at = now()
    WHERE id = r.id;

    PERFORM public.help_ticket_write_audit(
      r.id,
      'sla_breached',
      NULL,
      'resolution',
      'Resolution SLA breached',
      NULL,
      NULL,
      'system'
    );

    v_payload := jsonb_build_object(
      'ticket_number', r.ticket_number,
      'breach_type', 'resolution',
      'sla_at', r.sla_resolution_at,
      'status', r.status,
      'priority', r.priority
    );
    PERFORM public.help_ticket_notify_support_holders(r.id, 'sla_breached', v_payload);

    v_resolution_count := v_resolution_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'response_breaches', v_response_count,
    'resolution_breaches', v_resolution_count,
    'checked_at', now()
  );
END;
$$;


--
-- Name: FUNCTION check_help_ticket_sla_breaches(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_help_ticket_sla_breaches(p_limit integer) IS 'HELP-001 Phase 5: marks pause-aware SLA breaches, audits, and notifies support holders (cron).';


--
-- Name: claim_chat_push_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_chat_push_outbox(p_limit integer DEFAULT 40) RETURNS TABLE(id uuid, token_id uuid, title text, body text, chat_id uuid, data jsonb, device_token text, token_provider text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT o.id
    FROM public.chat_push_outbox o
    WHERE o.status = 'pending'
    ORDER BY o.created_at
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 40), 100))
    FOR UPDATE OF o SKIP LOCKED
  ),
  updated AS (
    UPDATE public.chat_push_outbox o
    SET status = 'sending'
    FROM claimed c
    WHERE o.id = c.id
    RETURNING o.id, o.token_id, o.title, o.body, o.chat_id, o.data
  )
  SELECT u.id, u.token_id, u.title, u.body, u.chat_id, u.data, t.device_token, t.token_provider
  FROM updated u
  JOIN public.device_push_tokens t ON t.id = u.token_id;
END;
$$;


--
-- Name: close(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close(p_complaint_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_is_admin boolean := public.is_admin();
  v_dealer_code text := public.my_dealer_code();
BEGIN
  IF NOT (v_is_admin OR public.has_module_modify('complaints')) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  IF v_is_admin THEN
    UPDATE public.complaint_tickets
    SET status = 'closed'
    WHERE id = p_complaint_id;
  ELSE
    UPDATE public.complaint_tickets
    SET status = 'closed'
    WHERE id = p_complaint_id
      AND dealer_code = v_dealer_code;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Complaint not found or not accessible';
  END IF;

  RETURN jsonb_build_object('status', 'closed');
END;
$$;


--
-- Name: complete_chat_push_outbox(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_chat_push_outbox(p_id uuid, p_status text, p_error_text text DEFAULT NULL::text, p_deactivate_token boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_token uuid;
BEGIN
  IF p_status NOT IN ('sent', 'failed', 'pending') THEN
    RAISE EXCEPTION 'Invalid outbox status';
  END IF;

  UPDATE public.chat_push_outbox
  SET status = p_status,
      error_text = NULLIF(left(COALESCE(p_error_text, ''), 500), ''),
      sent_at = CASE WHEN p_status = 'sent' THEN now() ELSE sent_at END
  WHERE id = p_id
  RETURNING token_id INTO v_token;

  IF p_deactivate_token AND v_token IS NOT NULL THEN
    UPDATE public.device_push_tokens
    SET is_active = false, last_used_at = now()
    WHERE id = v_token;
  END IF;
END;
$$;


--
-- Name: compute_parts_order_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_parts_order_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      begin
        new.order_status := case
          when new.received_quantity >= new.ordered_quantity and new.ordered_quantity > 0
            then 'Received'
          when new.invoice_qty is not null and new.invoice_qty >= new.ordered_quantity and new.ordered_quantity > 0
            then 'Received'
          when new.challan_qty > 0
            then 'In-Transit'
          when new.confirmation_qty > 0
            then 'Confirmed'
          when new.order_date is not null
            then 'Ordered'
          else null
        end;
        return new;
      end;
      $$;


--
-- Name: confirm_user_email_on_activate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_user_email_on_activate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_active = TRUE AND (OLD.is_active = FALSE OR OLD.is_active IS NULL) THEN
    UPDATE auth.users
    SET email_confirmed_at = COALESCE(email_confirmed_at, NOW()), updated_at = NOW()
    WHERE id = NEW.id AND email_confirmed_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: my_dealer_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_dealer_code() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'auth', 'public'
    AS $$
    SELECT COALESCE(
        NULLIF(auth.jwt() -> 'user_metadata' ->> 'dealer_code', ''),
        NULLIF(auth.jwt() -> 'app_metadata'  ->> 'dealer_code', ''),
        (
          SELECT uel.dealer_code
          FROM public.user_employee_links AS uel
          WHERE uel.user_id = auth.uid()
            AND uel.is_active = true
            AND uel.is_primary = true
          ORDER BY uel.updated_at DESC, uel.id DESC
          LIMIT 1
        ),
        (
          SELECT uel.dealer_code
          FROM public.user_employee_links AS uel
          WHERE uel.user_id = auth.uid()
            AND uel.is_active = true
          ORDER BY uel.is_primary DESC, uel.updated_at DESC, uel.id DESC
          LIMIT 1
        )
    )
$$;


--
-- Name: FUNCTION my_dealer_code(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.my_dealer_code() IS 'Returns dealer_code from JWT metadata; falls back to active user_employee_links mapping when metadata is missing.';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: service_reception_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_reception_entries (
    id bigint NOT NULL,
    dealer_code text DEFAULT public.my_dealer_code() NOT NULL,
    reg_number text NOT NULL,
    model text,
    service_type text,
    sa_name text NOT NULL,
    jc_number text,
    owner_name text,
    owner_phone text,
    source text NOT NULL,
    created_by text DEFAULT COALESCE((auth.jwt() ->> 'email'::text), (auth.uid())::text, 'system'::text) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    remark text,
    estimate_storage_path text,
    estimate_file_name text,
    estimate_content_type text,
    estimate_uploaded_at timestamp with time zone,
    estimate_uploaded_by text,
    estimate_drive_url text,
    estimate_drive_file_id text,
    branch text,
    sa_employee_code text,
    sa_display_name text,
    invoice_storage_path text,
    invoice_file_name text,
    invoice_content_type text,
    invoice_uploaded_at timestamp with time zone,
    invoice_uploaded_by text,
    invoice_drive_url text,
    invoice_drive_file_id text,
    invoice_done_at timestamp with time zone,
    invoice_done_by text,
    location text,
    portal text,
    branch_label text,
    km_reading integer,
    is_revisit boolean DEFAULT false NOT NULL,
    prior_reception_entry_id bigint,
    suggested_technician_code text,
    suggested_technician_name text,
    has_updation_available boolean DEFAULT false NOT NULL,
    updation_code text,
    updation_name text,
    expected_invoice_amount numeric(14,2),
    gate_pass_issued boolean DEFAULT false,
    gate_pass_number text,
    CONSTRAINT chk_service_reception_entries_jc_number_min_len CHECK (((NULLIF(btrim(jc_number), ''::text) IS NULL) OR (char_length(btrim(jc_number)) >= char_length('JC-MBTPLT-JP1-2627-003041'::text)))),
    CONSTRAINT service_reception_entries_expected_invoice_amount_check CHECK (((expected_invoice_amount IS NULL) OR (expected_invoice_amount >= (0)::numeric))),
    CONSTRAINT service_reception_entries_km_reading_check CHECK (((km_reading IS NULL) OR (km_reading >= 0))),
    CONSTRAINT service_reception_entries_portal_check CHECK (((portal IS NULL) OR (portal = ANY (ARRAY['EV'::text, 'PV'::text])))),
    CONSTRAINT service_reception_owner_phone_check CHECK (((owner_phone IS NULL) OR (owner_phone ~ '^[0-9]{10}$'::text))),
    CONSTRAINT service_reception_reg_number_not_blank CHECK ((length(btrim(reg_number)) > 0)),
    CONSTRAINT service_reception_sa_name_not_blank CHECK ((length(btrim(sa_name)) > 0)),
    CONSTRAINT service_reception_service_type_check CHECK (((service_type IS NULL) OR (length(btrim(service_type)) > 0))),
    CONSTRAINT service_reception_source_not_blank CHECK ((length(btrim(source)) > 0))
);


