--
-- Name: create_reception_entry(text, text, text, text, text, text, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_reception_entry(p_reg_number text, p_model text, p_service_type text, p_sa_employee_code text, p_owner_name text, p_owner_phone text, p_source text, p_km_reading integer DEFAULT NULL::integer, p_jc_number text DEFAULT NULL::text, p_branch text DEFAULT NULL::text, p_portal text DEFAULT NULL::text) RETURNS SETOF public.service_reception_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_dealer_code  text;
  v_sa_name      text;
  v_reg_number   text;
  v_service_type text;
  v_portal       text;
BEGIN
  v_dealer_code := public.my_dealer_code();

  IF NOT (
    public.is_admin()
    OR (
      public.has_module_modify('reception')
      AND public.dealer_code_in_scope(v_dealer_code)
    )
  ) THEN
    RAISE EXCEPTION 'permission denied: requires reception modify or admin'
      USING ERRCODE = '42501';
  END IF;

  v_reg_number := upper(btrim(coalesce(p_reg_number, '')));
  v_service_type := NULLIF(btrim(coalesce(p_service_type, '')), '');
  v_portal := NULLIF(upper(btrim(coalesce(p_portal, ''))), '');

  IF v_reg_number = '' THEN
    RAISE EXCEPTION 'registration number is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(coalesce(p_model, '')), '') IS NULL THEN
    RAISE EXCEPTION 'model is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(coalesce(p_sa_employee_code, '')), '') IS NULL THEN
    RAISE EXCEPTION 'sa employee code is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(coalesce(p_owner_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'owner name is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(coalesce(p_source, '')), '') IS NULL THEN
    RAISE EXCEPTION 'source is required' USING ERRCODE = '22023';
  END IF;
  IF p_owner_phone IS NULL OR btrim(p_owner_phone) !~ '^[0-9]{10}$' THEN
    RAISE EXCEPTION 'owner phone must be exactly 10 digits' USING ERRCODE = '22023';
  END IF;
  IF v_portal IS NOT NULL AND v_portal NOT IN ('EV', 'PV') THEN
    RAISE EXCEPTION 'portal must be EV or PV' USING ERRCODE = '22023';
  END IF;

  SELECT em.employee_name
    INTO v_sa_name
    FROM public.employee_master em
   WHERE em.employee_code = upper(btrim(p_sa_employee_code));

  IF NOT FOUND OR NULLIF(btrim(coalesce(v_sa_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'employee code % not found', p_sa_employee_code
      USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  INSERT INTO public.service_reception_entries (
    reg_number,
    model,
    service_type,
    sa_employee_code,
    sa_name,
    sa_display_name,
    owner_name,
    owner_phone,
    source,
    km_reading,
    jc_number,
    branch,
    portal,
    dealer_code
  ) VALUES (
    v_reg_number,
    NULLIF(btrim(p_model), ''),
    v_service_type,
    upper(btrim(p_sa_employee_code)),
    v_sa_name,
    v_sa_name,
    NULLIF(btrim(p_owner_name), ''),
    btrim(p_owner_phone),
    NULLIF(btrim(p_source), ''),
    p_km_reading,
    NULLIF(upper(btrim(coalesce(p_jc_number, ''))), ''),
    NULLIF(btrim(coalesce(p_branch, '')), ''),
    v_portal,
    v_dealer_code
  )
  RETURNING *;
END;
$_$;


--
-- Name: customer_advisor_chat_context(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_advisor_chat_context(p_session_token text, p_reg_number text) RETURNS TABLE(phone_10 text, reg_key text, reg_number text, dealer_code text, customer_name text, jc_number text, sa_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess record;
  v_reg text;
BEGIN
  v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  SELECT * INTO v_sess FROM public.customer_require_session(p_session_token);

  RETURN QUERY
  SELECT
    v_sess.phone,
    v_reg,
    s.reg_number,
    s.dealer_code,
    s.owner_name,
    s.jc_number,
    COALESCE(NULLIF(btrim(s.sa_display_name), ''), s.sa_name)
  FROM public.service_reception_entries s
  WHERE public.customer_norm_reg(s.reg_number) = v_reg
    AND public.customer_last10_digits(s.owner_phone) = v_sess.phone
    AND NULLIF(btrim(s.dealer_code), '') IS NOT NULL
  ORDER BY s.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    v_sess.phone,
    v_reg,
    v.reg_number,
    v.dealer_code,
    v.owner_name,
    NULL::text,
    NULL::text
  FROM public.vehicles v
  WHERE public.customer_norm_reg(v.reg_number) = v_reg
    AND public.customer_last10_digits(v.owner_phone) = v_sess.phone
    AND NULLIF(btrim(v.dealer_code), '') IS NOT NULL
  ORDER BY v.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vehicle not found for this session.';
  END IF;
END;
$$;


--
-- Name: customer_assert_reg(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_assert_reg(p_session_token text, p_reg_number text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_sess record;
  v_reg text := public.customer_norm_reg(p_reg_number);
  v_ok boolean := false;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  if v_reg is null then
    raise exception 'Vehicle not found for this session.';
  end if;
  select exists (
    select 1
    from jsonb_array_elements(public.customer_collect_vehicles(v_sess.phone)) v
    where v->>'reg_key' = v_reg
  ) into v_ok;
  if not v_ok then
    raise exception 'Vehicle not found for this session.';
  end if;
  return v_reg;
end;
$$;


