    doc_aadhaar_back boolean DEFAULT false NOT NULL,
    doc_tp_affidavit boolean DEFAULT false NOT NULL,
    CONSTRAINT bodyshop_repair_cards_customer_payment_status_check CHECK (((customer_payment_status IS NULL) OR (customer_payment_status = ANY (ARRAY['pending'::text, 'partial'::text, 'received'::text, 'not_received'::text])))),
    CONSTRAINT bodyshop_repair_cards_customer_settlement_kind_check CHECK (((customer_settlement_kind IS NULL) OR (customer_settlement_kind = ANY (ARRAY['due'::text, 'refund'::text, 'none'::text])))),
    CONSTRAINT bodyshop_repair_cards_customer_type_check CHECK ((customer_type = ANY (ARRAY['individual'::text, 'firm'::text, 'foc'::text, 'cash'::text]))),
    CONSTRAINT bodyshop_repair_cards_delivery_status_check CHECK ((delivery_status = ANY (ARRAY['pending'::text, 'done'::text]))),
    CONSTRAINT bodyshop_repair_cards_do_payment_status_check CHECK (((do_payment_status IS NULL) OR (do_payment_status = ANY (ARRAY['pending'::text, 'partial'::text, 'received'::text, 'not_received'::text])))),
    CONSTRAINT bodyshop_repair_cards_do_status_check CHECK ((do_status = ANY (ARRAY['pending'::text, 'received'::text, 'not_received'::text]))),
    CONSTRAINT bodyshop_repair_cards_estimated_amount_non_negative CHECK (((estimated_amount IS NULL) OR (estimated_amount >= (0)::numeric))),
    CONSTRAINT bodyshop_repair_cards_floor_status_check CHECK ((floor_status = ANY (ARRAY['work_inprocess'::text, 'hold'::text, 'completed'::text]))),
    CONSTRAINT bodyshop_repair_cards_insurance_type_check CHECK (((insurance_type IS NULL) OR (insurance_type = ANY (ARRAY['TMI'::text, 'Non-TMI'::text])))),
    CONSTRAINT bodyshop_repair_cards_overall_status_check CHECK ((overall_status = ANY (ARRAY['active'::text, 'delivered'::text, 'cancelled'::text]))),
    CONSTRAINT bodyshop_repair_cards_parts_entry_status_check CHECK ((parts_entry_status = ANY (ARRAY['pending'::text, 'entered'::text, 'billed'::text]))),
    CONSTRAINT bodyshop_repair_cards_payment_status_check CHECK ((payment_status = ANY (ARRAY['pending'::text, 'partial'::text, 'received'::text, 'not_received'::text]))),
    CONSTRAINT bodyshop_repair_cards_portal_check CHECK (((portal IS NULL) OR (portal = ANY (ARRAY['EV'::text, 'PV'::text])))),
    CONSTRAINT bodyshop_repair_cards_qc_pass_fields_check CHECK ((((qc_status = 'pass'::text) AND (qc_passed_by IS NOT NULL) AND (qc_passed_at IS NOT NULL)) OR (qc_status <> 'pass'::text))),
    CONSTRAINT bodyshop_repair_cards_qc_status_check CHECK ((qc_status = ANY (ARRAY['pending'::text, 'pass'::text, 'fail'::text]))),
    CONSTRAINT bodyshop_repair_cards_reinspection_status_check CHECK ((reinspection_status = ANY (ARRAY['pending'::text, 'completed'::text]))),
    CONSTRAINT bodyshop_repair_cards_reinspection_type_check CHECK (((reinspection_type IS NULL) OR (reinspection_type = ANY (ARRAY['floor_incharge'::text, 'surveyor'::text, 'other'::text])))),
    CONSTRAINT bodyshop_repair_cards_survey_status_check CHECK ((survey_status = ANY (ARRAY['pending'::text, 'hold'::text, 'approved'::text])))
);


