--
-- Name: customer_bodyshop_effective_stage(public.bodyshop_repair_cards); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_bodyshop_effective_stage(p_card public.bodyshop_repair_cards) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
begin
  return greatest(1, least(18, coalesce(p_card.current_stage, 1)));
end;
$$;


--
-- Name: customer_bodyshop_stage_label(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_bodyshop_stage_label(p_stage integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_stage
    when 1 then 'Vehicle Receiving'
    when 2 then 'Receiving Photos'
    when 3 then 'Job Card'
    when 4 then 'Customer Group'
    when 5 then 'Documentation'
    when 6 then 'Estimation'
    when 7 then 'Estimation Approval'
    when 8 then 'Claim Intimation'
    when 9 then 'Survey'
    when 10 then 'Parts Status'
    when 11 then 'Floor Assignment'
    when 12 then 'Additional Approval'
    when 13 then 'Quality Check'
    when 14 then 'Re-Inspection'
    when 15 then 'Billing'
    when 16 then 'DO Status'
    when 17 then 'Delivery'
    when 18 then 'Payment'
    else 'In progress'
  end;
$$;


--
-- Name: customer_collect_vehicles(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_collect_vehicles(p_phone text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_phone text := public.customer_last10_digits(p_phone);
  v_rows jsonb := '[]'::jsonb;
begin
  if v_phone is null then
    return '[]'::jsonb;
  end if;

  with rec as (
    select
      1 as src_rank,
      s.id::text as source_id,
      'reception'::text as source,
      public.customer_norm_reg(s.reg_number) as reg_key,
      s.reg_number,
      s.model,
      null::text as vin,
      s.owner_name,
      s.owner_phone,
      s.service_type,
      s.sa_name,
      s.sa_display_name,
      s.jc_number,
      s.branch,
      s.created_at,
      s.invoice_done_at,
      s.km_reading::numeric as km_reading,
      s.remark,
      s.estimate_storage_path,
      s.estimate_drive_url,
      s.invoice_storage_path,
      s.invoice_drive_url
    from public.service_reception_entries s
    where public.customer_last10_digits(s.owner_phone) = v_phone
      and public.customer_norm_reg(s.reg_number) is not null
  ),
  veh as (
    select
      2 as src_rank,
      public.customer_norm_reg(v.reg_number) as source_id,
      'vehicles'::text as source,
      public.customer_norm_reg(v.reg_number) as reg_key,
      v.reg_number,
      v.model,
      v.vin,
      v.owner_name,
      v.owner_phone,
      null::text as service_type,
      null::text as sa_name,
      null::text as sa_display_name,
      null::text as jc_number,
      null::text as branch,
      v.created_at,
      null::timestamptz as invoice_done_at,
      null::numeric as km_reading,
      null::text as remark,
      null::text as estimate_storage_path,
      null::text as estimate_drive_url,
      null::text as invoice_storage_path,
      null::text as invoice_drive_url
    from public.vehicles v
    where public.customer_last10_digits(v.owner_phone) = v_phone
      and public.customer_norm_reg(v.reg_number) is not null
  ),
  bs as (
    select
      3 as src_rank,
      b.id::text as source_id,
      'bodyshop'::text as source,
      public.customer_norm_reg(b.reg_number) as reg_key,
      b.reg_number,
      null::text as model,
      null::text as vin,
      b.customer_name as owner_name,
      b.customer_phone as owner_phone,
      'Body & Paint'::text as service_type,
      b.sa_name,
      b.sa_name as sa_display_name,
      b.job_card_no as jc_number,
      b.branch,
      b.created_at,
      b.delivered_at as invoice_done_at,
      null::numeric as km_reading,
      b.overall_status as remark,
      null::text as estimate_storage_path,
      null::text as estimate_drive_url,
      null::text as invoice_storage_path,
      null::text as invoice_drive_url
    from public.bodyshop_repair_cards b
    where public.customer_last10_digits(b.customer_phone) = v_phone
      and public.customer_norm_reg(b.reg_number) is not null
  ),
  asd as (
    select
      4 as src_rank,
      a.id::text as source_id,
      'all_service_data'::text as source,
      public.customer_norm_reg(a.vehicle_registration_number) as reg_key,
      a.vehicle_registration_number as reg_number,
      a.model,
      a.chassis_no as vin,
      nullif(btrim(concat_ws(' ', a.first_name, a.last_name)), '') as owner_name,
      coalesce(
        public.customer_last10_digits(a.last_service_customer_mobile_no),
        v_phone
      ) as owner_phone,
      a.last_service_type as service_type,
      a.last_service_dealer as sa_name,
      a.last_service_dealer as sa_display_name,
      a.extended_warranty_order_no as jc_number,
      a.sold_dealer as branch,
      coalesce(a.last_service_date::timestamptz, a.created_at) as created_at,
      a.last_service_date::timestamptz as invoice_done_at,
      nullif(regexp_replace(coalesce(a.last_service_km, ''), '[^0-9]', '', 'g'), '')::numeric as km_reading,
      a.product_line as remark,
      null::text as estimate_storage_path,
      null::text as estimate_drive_url,
      null::text as invoice_storage_path,
      null::text as invoice_drive_url
    from public.all_service_data a
    where public.customer_norm_reg(a.vehicle_registration_number) is not null
      and (
        public.customer_last10_digits(a.last_service_customer_mobile_no) = v_phone
        or exists (
          select 1
          from unnest(regexp_split_to_array(coalesce(a.contact_phones, ''), '[,;/|]+')) as part
          where public.customer_last10_digits(part) = v_phone
        )
      )
  ),
  united as (
    select * from rec
    union all
    select * from veh
    union all
    select * from bs
    union all
    select * from asd
  ),
  picked as (
    select distinct on (reg_key)
      source_id,
      source,
      reg_key,
      reg_number,
      model,
      vin,
      owner_name,
      owner_phone,
      service_type,
      sa_name,
      sa_display_name,
      jc_number,
      branch,
      created_at,
      invoice_done_at,
      km_reading,
      remark,
      estimate_storage_path,
      estimate_drive_url,
      invoice_storage_path,
      invoice_drive_url
    from united
    where reg_key is not null
    order by reg_key, src_rank, created_at desc nulls last
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', source_id,
        'source', source,
        'reg_number', reg_number,
        'reg_key', reg_key,
        'model', model,
        'vin', vin,
        'owner_name', owner_name,
        'owner_phone', owner_phone,
        'service_type', service_type,
        'sa_name', sa_name,
        'sa_display_name', sa_display_name,
        'jc_number', jc_number,
        'branch', branch,
        'created_at', created_at,
        'invoice_done_at', invoice_done_at,
        'km_reading', km_reading,
        'remark', remark,
        'estimate_storage_path', estimate_storage_path,
        'estimate_drive_url', estimate_drive_url,
        'invoice_storage_path', invoice_storage_path,
        'invoice_drive_url', invoice_drive_url
      )
      order by reg_number
    ),
    '[]'::jsonb
  )
  into v_rows
  from picked;

  return v_rows;
end;
$$;


--
-- Name: customer_deactivate_device_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_deactivate_device_token(p_session_token text, p_device_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session record;
BEGIN
  SELECT * INTO v_session FROM public.customer_require_session(p_session_token);
  UPDATE public.device_push_tokens
  SET is_active = false, last_used_at = now()
  WHERE device_token = btrim(COALESCE(p_device_token, ''))
    AND audience = 'customer'
    AND phone_10 = v_session.phone;
END;
$$;


--
-- Name: customer_end_session(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_end_session(p_session_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  perform public.customer_reject_staff_jwt();
  if p_session_token is null or btrim(p_session_token) = '' then
    return;
  end if;
  update public.customer_sessions
  set revoked_at = now()
  where token_hash = public.customer_hash_token(btrim(p_session_token))
    and revoked_at is null;
end;
$$;


--
-- Name: customer_get_active_job(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_active_job(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_sess record;
  v_reg text;
  v_regs text[];
  v_job jsonb;
  v_vehicle jsonb;
BEGIN
  SELECT * INTO v_sess FROM public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);

  IF p_reg_number IS NOT NULL AND btrim(p_reg_number) <> '' THEN
    v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  END IF;

  SELECT jsonb_build_object(
    'id', s.id,
    'source', 'reception',
    'reg_number', s.reg_number,
    'reg_key', public.customer_norm_reg(s.reg_number),
    'model', s.model,
    'owner_name', s.owner_name,
    'owner_phone', s.owner_phone,
    'service_type', s.service_type,
    'sa_name', s.sa_name,
    'sa_display_name', s.sa_display_name,
    'jc_number', s.jc_number,
    'branch', s.branch,
    'created_at', s.created_at,
    'invoice_done_at', s.invoice_done_at,
    'km_reading', s.km_reading,
    'remark', s.remark,
    'estimate_storage_path', s.estimate_storage_path,
    'estimate_drive_url', s.estimate_drive_url,
    'invoice_storage_path', s.invoice_storage_path,
    'invoice_drive_url', s.invoice_drive_url,
    'status', CASE WHEN s.invoice_done_at IS NULL THEN 'in_service' ELSE 'delivered' END
  )
  INTO v_job
  FROM public.service_reception_entries s
  WHERE public.customer_norm_reg(s.reg_number) = ANY (v_regs)
    AND (v_reg IS NULL OR public.customer_norm_reg(s.reg_number) = v_reg)
  ORDER BY (s.invoice_done_at IS NULL) DESC, s.created_at DESC
  LIMIT 1;

  IF v_job IS NULL THEN
    SELECT jsonb_build_object(
      'id', b.id,
      'source', 'bodyshop',
      'reg_number', b.reg_number,
      'reg_key', public.customer_norm_reg(b.reg_number),
      'model', NULL,
      'owner_name', b.customer_name,
      'owner_phone', b.customer_phone,
      'service_type', 'Body & Paint',
      'sa_name', b.sa_name,
      'sa_display_name', b.sa_name,
      'jc_number', b.job_card_no,
      'branch', b.branch,
      'created_at', b.created_at,
      'invoice_done_at', b.delivered_at,
      'km_reading', NULL,
      'remark', b.overall_status,
      'status', CASE
        WHEN COALESCE(b.overall_status, '') IN ('delivered', 'closed') OR b.delivered_at IS NOT NULL
          THEN 'delivered'
        ELSE 'in_service'
      END
    )
    INTO v_job
    FROM public.bodyshop_repair_cards b
    WHERE public.customer_norm_reg(b.reg_number) = ANY (v_regs)
      AND (v_reg IS NULL OR public.customer_norm_reg(b.reg_number) = v_reg)
    ORDER BY b.created_at DESC
    LIMIT 1;
  END IF;

  SELECT v
  INTO v_vehicle
  FROM jsonb_array_elements(public.customer_collect_vehicles(v_sess.phone)) v
  WHERE v_reg IS NULL OR v->>'reg_key' = v_reg
  LIMIT 1;

  RETURN jsonb_build_object(
    'phone', v_sess.phone,
    'vehicle', v_vehicle,
    'job', v_job,
    'visit_kind', public.customer_resolve_visit_kind(v_job)
  );
END;
$$;


--
-- Name: customer_get_bodyshop_document(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_bodyshop_document(p_session_token text, p_reg_number text, p_doc_key text DEFAULT 'doc_estimate'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET row_security TO 'off'
    AS $$
declare
  v_sess record;
  v_reg text;
  v_regs text[];
  v_card_id integer;
  v_doc jsonb;
  v_doc_key text;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);
  v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  v_doc_key := nullif(btrim(coalesce(p_doc_key, 'doc_estimate')), '');

  if v_doc_key is null then
    raise exception 'doc_key is required';
  end if;

  select b.id
  into v_card_id
  from public.bodyshop_repair_cards b
  where public.customer_norm_reg(b.reg_number) = any(v_regs)
    and public.customer_norm_reg(b.reg_number) = v_reg
  order by b.created_at desc
  limit 1;

  if v_card_id is null then
    return null;
  end if;

  select jsonb_build_object(
    'doc_key', d.doc_key,
    'file_name', d.file_name,
    'content_type', d.content_type,
    'drive_url', nullif(btrim(coalesce(d.drive_url, '')), ''),
    'drive_file_id', nullif(btrim(coalesce(d.drive_file_id, '')), ''),
    'storage_bucket', coalesce(nullif(btrim(d.storage_bucket), ''), 'autodoc'),
    'storage_path', d.storage_path,
    'uploaded_at', d.uploaded_at,
    'uploaded_by', d.uploaded_by
  )
  into v_doc
  from public.bodyshop_repair_card_documents d
  where d.repair_card_id = v_card_id
    and d.doc_key = v_doc_key
  order by d.uploaded_at desc nulls last, d.id desc
  limit 1;

  return v_doc;
end;
$$;


--
-- Name: customer_get_gate_pass(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_gate_pass(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_sess record;
  v_reg text;
  v_regs text[];
  v_text text;
  v_payload jsonb;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);
  if p_reg_number is not null and btrim(p_reg_number) <> '' then
    v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  end if;

  select b.feedback_text
  into v_text
  from public.post_feedback_bot_data b
  where b.mode = 'customer_gatepass_payload'
    and (
      public.customer_last10_digits(b.mobile_number) = v_sess.phone
      or public.customer_norm_reg(b.vehicle_registration_number) = any(v_regs)
    )
    and (v_reg is null or public.customer_norm_reg(b.vehicle_registration_number) = v_reg)
  order by b.created_at desc
  limit 1;

  if v_text is not null then
    begin
      v_payload := v_text::jsonb;
    exception when others then
      v_payload := null;
    end;
    if v_payload is not null and nullif(btrim(coalesce(v_payload->>'gate_pass_no', '')), '') is not null then
      return v_payload;
    end if;
  end if;

  return null;
end;
$$;


--
-- Name: customer_get_mechanical_case(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_mechanical_case(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_sess record;
  v_reg text;
  v_regs text[];
  v_entry public.service_reception_entries%ROWTYPE;
  v_inv public.accounts_mechanical_invoices%ROWTYPE;
  v_has_inv boolean := false;
  v_gate jsonb;
  v_has_gate boolean := false;
  v_floor jsonb := 'null'::jsonb;
  v_payments jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_sess FROM public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);

  IF p_reg_number IS NOT NULL AND btrim(p_reg_number) <> '' THEN
    v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  END IF;

  SELECT s.*
  INTO v_entry
  FROM public.service_reception_entries s
  WHERE public.customer_norm_reg(s.reg_number) = ANY (v_regs)
    AND (v_reg IS NULL OR public.customer_norm_reg(s.reg_number) = v_reg)
  ORDER BY (s.invoice_done_at IS NULL) DESC, s.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF NOT public.is_floor_incharge_service_type(v_entry.service_type) THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'technician_name', ta.technician_name,
    'technician_code', ta.technician_code,
    'bay_no', ta.bay_no,
    'work_status', ta.work_status,
    'assigned_at', ta.assigned_at,
    'out_ts', ta.out_ts
  )
  INTO v_floor
  FROM public.technician_assignments ta
  WHERE NULLIF(btrim(v_entry.jc_number), '') IS NOT NULL
    AND upper(btrim(ta.job_card_number)) = upper(btrim(v_entry.jc_number))
  ORDER BY ta.id DESC
  LIMIT 1;

  SELECT * INTO v_inv
  FROM public.accounts_mechanical_invoices inv
  WHERE inv.reception_entry_id = v_entry.id;

  v_has_inv := FOUND;

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', p.id,
        'amount', p.amount,
        'payment_mode', p.payment_mode,
        'reference', p.reference,
        'payment_received_date', p.payment_received_date,
        'posted_at', p.posted_at
      )
      ORDER BY p.posted_at DESC NULLS LAST, p.id DESC
    ),
    '[]'::jsonb
  )
  INTO v_payments
  FROM public.accounts_mechanical_payment_lines p
  WHERE p.reception_entry_id = v_entry.id;

  v_gate := public.customer_get_gate_pass(p_session_token, v_entry.reg_number);
  v_has_gate := v_gate IS NOT NULL
    AND nullif(btrim(coalesce(v_gate->>'gate_pass_no', '')), '') IS NOT NULL;

  RETURN jsonb_build_object(
    'reception_entry_id', v_entry.id,
    'reg_number', v_entry.reg_number,
    'model', v_entry.model,
    'service_type', v_entry.service_type,
    'jc_number', v_entry.jc_number,
    'km_reading', v_entry.km_reading,
    'sa_name', v_entry.sa_name,
    'sa_display_name', v_entry.sa_display_name,
    'branch', v_entry.branch,
    'created_at', v_entry.created_at,
    'invoice_done_at', v_entry.invoice_done_at,
    'expected_invoice_amount', v_entry.expected_invoice_amount,
    'estimate_storage_path', v_entry.estimate_storage_path,
    'estimate_drive_url', v_entry.estimate_drive_url,
    'invoice_storage_path', v_entry.invoice_storage_path,
    'invoice_drive_url', v_entry.invoice_drive_url,
    'gate_pass_issued', coalesce(v_entry.gate_pass_issued, false) OR v_has_gate,
    'gate_pass_number', coalesce(v_entry.gate_pass_number, v_gate->>'gate_pass_no'),
    'floor', coalesce(v_floor, 'null'::jsonb),
    'invoice', CASE
      WHEN v_has_inv THEN jsonb_build_object(
        'invoice_number', v_inv.invoice_number,
        'invoice_date', v_inv.invoice_date,
        'billed_amount', v_inv.billed_amount,
        'amount_received', coalesce(v_inv.amount_received, 0),
        'remaining_amount', public.accounts_mechanical_remaining_amount(v_inv.billed_amount, v_inv.amount_received),
        'payment_status', v_inv.payment_status
      )
      ELSE NULL
    END,
    'payments', coalesce(v_payments, '[]'::jsonb)
  );
END;
$$;


--
-- Name: FUNCTION customer_get_mechanical_case(p_session_token text, p_reg_number text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_mechanical_case(p_session_token text, p_reg_number text) IS 'MOBILE-015: Customer read model for Floor Incharge visits (mechanical desk). Null when active reception row is not a floor service type.';


--
-- Name: customer_get_repair_card(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_repair_card(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET row_security TO 'off'
    AS $$
declare
  v_sess record;
  v_reg text;
  v_regs text[];
  v_row jsonb;
  v_card public.bodyshop_repair_cards%rowtype;
  v_effective integer;
  v_display integer;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);
  if p_reg_number is not null and btrim(p_reg_number) <> '' then
    v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  end if;

  select b.*
  into v_card
  from public.bodyshop_repair_cards b
  where public.customer_norm_reg(b.reg_number) = any(v_regs)
    and (v_reg is null or public.customer_norm_reg(b.reg_number) = v_reg)
  order by b.created_at desc
  limit 1;

  if not found then
    return null;
  end if;

  v_effective := public.customer_bodyshop_effective_stage(v_card);

  select coalesce(max(p.stage_no), v_effective)
  into v_display
  from public.bodyshop_stage_worklist_projection p
  where p.repair_card_id = v_card.id
    and p.is_pending = true;

  select
    (to_jsonb(b) - 'sa_employee_code' - 'created_by')
    || jsonb_build_object(
      'customer_effective_stage', v_effective,
      'customer_effective_stage_name', public.customer_bodyshop_stage_label(v_effective),
      'customer_display_stage', v_display,
      'customer_display_stage_name', public.customer_bodyshop_stage_label(v_display),
      'pending_worklist_stages',
      coalesce(
        (
          select jsonb_agg(p.stage_no order by p.stage_no)
          from public.bodyshop_stage_worklist_projection p
          where p.repair_card_id = b.id
            and p.is_pending = true
        ),
        '[]'::jsonb
      ),
      'worklist_stages',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'stage_no', p.stage_no,
              'is_done', p.is_done,
              'is_pending', p.is_pending,
              'is_ready', p.is_ready
            )
            order by p.stage_no
          )
          from public.bodyshop_stage_worklist_projection p
          where p.repair_card_id = b.id
        ),
        '[]'::jsonb
      ),
      'estimate_document',
      (
        select jsonb_build_object(
          'doc_key', d.doc_key,
          'file_name', d.file_name,
          'content_type', d.content_type,
          'drive_url', nullif(btrim(coalesce(d.drive_url, '')), ''),
          'drive_file_id', nullif(btrim(coalesce(d.drive_file_id, '')), ''),
          'storage_bucket', coalesce(nullif(btrim(d.storage_bucket), ''), 'autodoc'),
          'storage_path', d.storage_path,
          'uploaded_at', d.uploaded_at,
          'uploaded_by', d.uploaded_by
        )
        from public.bodyshop_repair_card_documents d
        where d.repair_card_id = b.id
          and d.doc_key = 'doc_estimate'
        order by d.uploaded_at desc nulls last, d.id desc
        limit 1
      ),
      'uploaded_documents',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'doc_key', doc.doc_key,
              'file_name', doc.file_name,
              'uploaded_at', doc.uploaded_at
            )
            order by doc.doc_key
          )
          from public.bodyshop_repair_card_documents doc
          where doc.repair_card_id = b.id
        ),
        '[]'::jsonb
      ),
      'intake_photo_count',
      (
        select count(*)::int
        from public.bodyshop_intake_vehicle_photos p
        where p.repair_card_id = b.id
           or (b.reception_entry_id is not null and p.reception_entry_id = b.reception_entry_id)
      ),
      'settlement',
      (
        select jsonb_build_object(
          'invoice_number', s.invoice_number,
          'invoice_date', s.invoice_date,
          'invoice_amount', s.invoice_amount,
          'do_amount', s.do_amount,
          'insurance_due_amount', s.insurance_due_amount,
          'customer_diff_amount', s.customer_diff_amount,
          'customer_remaining_amount', s.customer_remaining_amount,
          'do_payment_status', s.do_payment_status,
          'derived_payment_status', s.derived_payment_status
        )
        from public.bodyshop_settlements s
        where s.repair_card_id = b.id
        limit 1
      )
    )
  into v_row
  from public.bodyshop_repair_cards b
  where b.id = v_card.id;

  return v_row;
end;
$$;


--
-- Name: customer_get_service_history(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_service_history(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_sess record;
  v_reg text;
  v_regs text[];
  v_rows jsonb := '[]'::jsonb;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);
  if p_reg_number is not null and btrim(p_reg_number) <> '' then
    v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  end if;

  select coalesce(jsonb_agg(item order by (item->>'service_date') desc nulls last), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'id', 'rec-' || s.id::text,
      'source', 'reception',
      'reg_number', s.reg_number,
      'service_date', coalesce(s.invoice_done_at, s.created_at),
      'jc_number', s.jc_number,
      'service_type', s.service_type,
      'km_reading', s.km_reading,
      'service_advisor', coalesce(s.sa_display_name, s.sa_name),
      'total_amount', s.expected_invoice_amount,
      'status', case when s.invoice_done_at is null then 'In service' else 'Delivered' end,
      'invoice_storage_path', s.invoice_storage_path,
      'invoice_drive_url', s.invoice_drive_url
    ) as item
    from public.service_reception_entries s
    where public.customer_norm_reg(s.reg_number) = any(v_regs)
      and (v_reg is null or public.customer_norm_reg(s.reg_number) = v_reg)

    union all

    select jsonb_build_object(
      'id', 'asd-' || a.id::text,
      'source', 'all_service_data',
      'reg_number', a.vehicle_registration_number,
      'service_date', a.last_service_date,
      'jc_number', a.extended_warranty_order_no,
      'service_type', a.last_service_type,
      'km_reading', nullif(regexp_replace(coalesce(a.last_service_km, ''), '[^0-9]', '', 'g'), '')::numeric,
      'service_advisor', a.last_service_dealer,
      'total_amount', null,
      'status', 'Delivered'
    )
    from public.all_service_data a
    where public.customer_norm_reg(a.vehicle_registration_number) = any(v_regs)
      and (v_reg is null or public.customer_norm_reg(a.vehicle_registration_number) = v_reg)
      and a.last_service_date is not null
  ) hist;

  return v_rows;
end;
$$;


--
-- Name: customer_get_settlement(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_settlement(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET row_security TO 'off'
    AS $_$
declare
  v_sess record;
  v_reg text;
  v_regs text[];
  v_text text;
  v_payload jsonb;
  v_row jsonb;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);
  if p_reg_number is not null and btrim(p_reg_number) <> '' then
    v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  end if;

  select jsonb_build_object(
    'source', 'bodyshop_settlements',
    'is_bodyshop', true,
    'is_insurance_claim',
      coalesce(s.do_amount, 0) > 0
      or nullif(btrim(coalesce(b.insurance_company, '')), '') is not null
      or nullif(btrim(coalesce(b.claim_intimation_no, '')), '') is not null,
    'repair_card_id', b.id,
    'reception_entry_id', b.reception_entry_id,
    'reg_number', b.reg_number,
    'jc_number', coalesce(s.job_card_no, b.job_card_no),
    'owner_name', b.customer_name,
    'branch', b.branch,
    'service_type', 'Accidental / Bodyshop Repair',
    'insurance_company', nullif(btrim(coalesce(b.insurance_company, s.invoice_account, '')), ''),
    'insurance_policy_no', b.insurance_policy_no,
    'claim_intimation_no', b.claim_intimation_no,
    'invoice_no', s.invoice_number,
    'invoice_date', s.invoice_date,
    'total_billed', coalesce(s.invoice_amount, 0),
    'billed_amount', coalesce(s.invoice_amount, 0),
    'do_amount', coalesce(s.do_amount, 0),
    'do_remaining', coalesce(s.insurance_due_amount, 0),
    'customer_diff_amount', coalesce(s.customer_diff_amount, 0),
    'customer_posted_amount', coalesce(s.customer_posted_amount, 0),
    'customer_remaining_amount', coalesce(s.customer_remaining_amount, 0),
    'customer_settlement_kind', s.customer_settlement_kind,
    'outstanding_amount', coalesce(s.outstanding_amount, 0),
    'amount_received', coalesce(s.customer_posted_amount, 0),
    'remaining_amount', coalesce(s.customer_remaining_amount, 0),
    'remaining_due', coalesce(s.customer_remaining_amount, 0),
    'status', coalesce(s.derived_payment_status, s.customer_payment_status, 'pending'),
    'do_payment_status', s.do_payment_status,
    'customer_payment_status', s.customer_payment_status,
    'updated_at', coalesce(s.updated_at, s.created_at),
    'payments', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', l.id,
          'amount', l.amount,
          'payment_mode', coalesce(nullif(btrim(l.payment_mode), ''), 'Accounts Cleared'),
          'reference', l.reference,
          'posted_at', coalesce(l.created_at, l.txn_date::timestamptz),
          'payment_received_date', to_char(l.txn_date, 'DD Mon YYYY'),
          'voucher_no', l.voucher_no
        )
        order by l.txn_date desc nulls last, l.id desc
      )
      from public.bodyshop_settlement_lines l
      where l.repair_card_id = b.id
        and l.party = 'customer'
        and coalesce(l.is_reversed, false) = false
        and l.line_type = 'receipt'
    ), '[]'::jsonb)
  )
  into v_row
  from public.bodyshop_settlements s
  join public.bodyshop_repair_cards b on b.id = s.repair_card_id
  where public.customer_norm_reg(b.reg_number) = any(v_regs)
    and (v_reg is null or public.customer_norm_reg(b.reg_number) = v_reg)
    and (
      s.invoice_amount is not null
      or nullif(btrim(coalesce(s.invoice_number, '')), '') is not null
    )
  order by coalesce(s.updated_at, s.created_at) desc nulls last
  limit 1;

  if v_row is not null then
    return v_row;
  end if;

  select b.feedback_text
  into v_text
  from public.post_feedback_bot_data b
  where b.mode = 'customer_payment_payload'
    and (
      public.customer_last10_digits(b.mobile_number) = v_sess.phone
      or public.customer_norm_reg(b.vehicle_registration_number) = any(v_regs)
    )
    and (v_reg is null or public.customer_norm_reg(b.vehicle_registration_number) = v_reg)
  order by b.created_at desc
  limit 1;

  if v_text is not null then
    begin
      v_payload := v_text::jsonb;
    exception when others then
      v_payload := null;
    end;
    if v_payload is not null
      and coalesce((v_payload->>'total_billed')::numeric, (v_payload->>'billed_amount')::numeric, 0) > 0
    then
      return v_payload || jsonb_build_object('source', 'customer_payment_payload');
    end if;
  end if;

  if to_regclass('public.accounts_mechanical_invoices') is not null then
    execute
      $q$
      select jsonb_build_object(
        'source', 'accounts_mechanical_invoices',
        'is_bodyshop', false,
        'reception_entry_id', s.id,
        'reg_number', s.reg_number,
        'jc_number', coalesce(inv.jc_number, s.jc_number),
        'owner_name', s.owner_name,
        'branch', s.branch,
        'service_type', s.service_type,
        'invoice_no', inv.invoice_number,
        'invoice_date', inv.invoice_date,
        'total_billed', inv.billed_amount,
        'billed_amount', inv.billed_amount,
        'amount_received', coalesce(inv.amount_received, 0),
        'remaining_amount', public.accounts_mechanical_remaining_amount(inv.billed_amount, inv.amount_received),
        'remaining_due', public.accounts_mechanical_remaining_amount(inv.billed_amount, inv.amount_received),
        'status', inv.payment_status,
        'keep_on_credit', coalesce(inv.keep_on_credit, false),
        'keep_on_credit_reason', inv.keep_on_credit_reason,
        'invoice_drive_url', s.invoice_drive_url,
        'invoice_storage_path', s.invoice_storage_path,
        'updated_at', coalesce(inv.updated_at, inv.captured_at, s.created_at),
        'payments', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', p.id, 'amount', p.amount, 'payment_mode', p.payment_mode,
            'reference', p.reference, 'remark', p.remark, 'posted_at', p.posted_at,
            'payment_received_date', p.payment_received_date, 'voucher_no', p.voucher_no
          ) order by p.posted_at desc)
          from public.accounts_mechanical_payment_lines p
          where p.reception_entry_id = s.id
        ), '[]'::jsonb)
      )
      from public.accounts_mechanical_invoices inv
      join public.service_reception_entries s on s.id = inv.reception_entry_id
      where public.customer_norm_reg(s.reg_number) = any($1)
        and ($2::text is null or public.customer_norm_reg(s.reg_number) = $2)
        and inv.billed_amount is not null
      order by coalesce(inv.updated_at, inv.captured_at, s.created_at) desc nulls last
      limit 1
      $q$
    into v_row
    using v_regs, v_reg;
    if v_row is not null then
      return v_row;
    end if;
  end if;

  select jsonb_build_object(
    'source', 'reception_expected',
    'reception_entry_id', s.id,
    'reg_number', s.reg_number,
    'jc_number', s.jc_number,
    'owner_name', s.owner_name,
    'branch', s.branch,
    'service_type', s.service_type,
    'total_billed', s.expected_invoice_amount,
    'billed_amount', s.expected_invoice_amount,
    'amount_received', 0,
    'remaining_amount', s.expected_invoice_amount,
    'remaining_due', s.expected_invoice_amount,
    'status', case when s.invoice_done_at is null then 'pending' else 'invoiced' end,
    'invoice_drive_url', s.invoice_drive_url,
    'invoice_storage_path', s.invoice_storage_path,
    'payments', '[]'::jsonb,
    'updated_at', coalesce(s.invoice_done_at, s.created_at)
  )
  into v_row
  from public.service_reception_entries s
  where public.customer_norm_reg(s.reg_number) = any(v_regs)
    and (v_reg is null or public.customer_norm_reg(s.reg_number) = v_reg)
    and s.expected_invoice_amount is not null
    and s.expected_invoice_amount > 0
  order by (s.invoice_done_at is null) desc, s.created_at desc
  limit 1;

  return v_row;
end;
$_$;


--
-- Name: FUNCTION customer_get_settlement(p_session_token text, p_reg_number text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_settlement(p_session_token text, p_reg_number text) IS 'Customer payments. Priority: bodyshop_settlements (Accounts desk) > payment payload > mechanical invoice > reception expected.';


--
-- Name: customer_get_visit_context(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_visit_context(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_base jsonb;
  v_kind text;
BEGIN
  IF p_reg_number IS NULL OR btrim(p_reg_number) = '' THEN
    RAISE EXCEPTION 'reg_number required';
  END IF;

  v_base := public.customer_get_active_job(p_session_token, p_reg_number);
  v_kind := COALESCE(v_base->>'visit_kind', public.customer_resolve_visit_kind(v_base->'job'));

  IF v_kind = 'mechanical' THEN
    RETURN v_base
      || jsonb_build_object(
        'visit_kind', v_kind,
        'mechanical_case', public.customer_get_mechanical_case(p_session_token, p_reg_number),
        'repair_card', NULL
      );
  ELSIF v_kind = 'bodyshop' THEN
    RETURN v_base
      || jsonb_build_object(
        'visit_kind', v_kind,
        'mechanical_case', NULL,
        'repair_card', public.customer_get_repair_card(p_session_token, p_reg_number)
      );
  END IF;

  RETURN v_base
    || jsonb_build_object(
      'visit_kind', v_kind,
      'mechanical_case', NULL,
      'repair_card', NULL
    );
END;
$$;


--
-- Name: FUNCTION customer_get_visit_context(p_session_token text, p_reg_number text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_visit_context(p_session_token text, p_reg_number text) IS 'Single customer portal payload: active job, visit_kind, and type-specific case (mechanical or bodyshop).';


--
-- Name: customer_hash_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_hash_token(p_token text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select encode(extensions.digest(convert_to(p_token, 'UTF8'), 'sha256'), 'hex');
$$;


--
-- Name: customer_helpdesk_peer_name(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_helpdesk_peer_name(p_contact_key text, p_default_sa text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT c.contact_name
      FROM public.settings_customer_helpdesk_contacts c
      WHERE c.is_active = true
        AND c.chat_contact_key = btrim(COALESCE(p_contact_key, ''))
      LIMIT 1
    ),
    CASE btrim(COALESCE(p_contact_key, 'advisor'))
      WHEN 'payal' THEN 'Payal Makhija'
      WHEN 'govind' THEN 'Govind Singh'
      WHEN 'rajesh' THEN 'Mr Rajesh Panday'
      WHEN 'tata_akshay' THEN 'Mr Akshay Jethalia'
      WHEN 'tata_gurmeet' THEN 'Mr Gurmeet Singh'
      ELSE COALESCE(NULLIF(btrim(p_default_sa), ''), 'Service advisor')
    END
  );
$$;


--
-- Name: customer_last10_digits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_last10_digits(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when length(regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g')) >= 10
      then right(regexp_replace(p, '[^0-9]', '', 'g'), 10)
    else null
  end;
$$;


--
-- Name: customer_list_advisor_messages(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_advisor_messages(p_session_token text, p_reg_number text, p_contact_key text DEFAULT 'advisor'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ctx record;
  v_chat public.advisor_chats%ROWTYPE;
  v_messages jsonb;
  v_contact text := COALESCE(NULLIF(btrim(p_contact_key), ''), 'advisor');
BEGIN
  IF v_contact <> 'advisor' AND NOT EXISTS (
    SELECT 1
    FROM public.settings_customer_helpdesk_contacts c
    WHERE c.is_active = true
      AND c.chat_contact_key = v_contact
  ) THEN
    RAISE EXCEPTION 'Not allowed.';
  END IF;

  SELECT * INTO v_ctx
  FROM public.customer_advisor_chat_context(p_session_token, p_reg_number)
  LIMIT 1;

  SELECT * INTO v_chat
  FROM public.advisor_chats c
  WHERE c.dealer_code = v_ctx.dealer_code
    AND c.reg_key = v_ctx.reg_key
    AND c.phone_10 = v_ctx.phone_10
    AND c.contact_key = v_contact
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'chat', NULL,
      'messages', '[]'::jsonb
    );
  END IF;

  IF v_chat.customer_unread_count > 0 THEN
    UPDATE public.advisor_chats
    SET customer_unread_count = 0,
        updated_at = now()
    WHERE id = v_chat.id;
    v_chat.customer_unread_count := 0;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.created_at), '[]'::jsonb)
  INTO v_messages
  FROM public.advisor_chat_messages m
  WHERE m.chat_id = v_chat.id;

  RETURN jsonb_build_object(
    'chat', to_jsonb(v_chat),
    'messages', v_messages
  );
END;
$$;


--
-- Name: customer_list_estimates(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_estimates(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_sess record;
  v_reg text;
  v_regs text[];
  v_rows jsonb := '[]'::jsonb;
  v_extra jsonb := '[]'::jsonb;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);
  if p_reg_number is not null and btrim(p_reg_number) <> '' then
    v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  end if;

  select coalesce(jsonb_agg(item), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'estimate_id', 'reception-' || s.id::text,
      'source', 'reception',
      'reg_number', s.reg_number,
      'estimate_storage_path', s.estimate_storage_path,
      'estimate_drive_url', s.estimate_drive_url,
      'status', 'issued',
      'created_at', s.estimate_uploaded_at
    ) as item
    from public.service_reception_entries s
    where public.customer_norm_reg(s.reg_number) = any(v_regs)
      and (v_reg is null or public.customer_norm_reg(s.reg_number) = v_reg)
      and (
        nullif(btrim(coalesce(s.estimate_storage_path, '')), '') is not null
        or nullif(btrim(coalesce(s.estimate_drive_url, '')), '') is not null
      )

    union all

    select case
      when (b.feedback_text)::jsonb ? 'estimate_no'
        then (b.feedback_text)::jsonb
          || jsonb_build_object(
            'estimate_id', coalesce((b.feedback_text)::jsonb->>'estimate_no', 'bot-' || b.id::text),
            'source', 'customer_estimate_payload',
            'reg_number', b.vehicle_registration_number
          )
      else jsonb_build_object(
        'estimate_id', 'bot-' || b.id::text,
        'source', 'customer_estimate_payload',
        'reg_number', b.vehicle_registration_number,
        'status', 'issued'
      )
    end
    from public.post_feedback_bot_data b
    where b.mode = 'customer_estimate_payload'
      and b.feedback_text ~ '^\s*\{'
      and (
        public.customer_last10_digits(b.mobile_number) = v_sess.phone
        or public.customer_norm_reg(b.vehicle_registration_number) = any(v_regs)
      )
      and (v_reg is null or public.customer_norm_reg(b.vehicle_registration_number) = v_reg)
  ) est;

  if to_regclass('public.customer_estimates') is not null then
    execute
      $q$
      select coalesce(jsonb_agg(to_jsonb(c) || jsonb_build_object(
        'estimate_id', c.estimate_no,
        'source', 'customer_estimates',
        'reg_number', c.vehicle_registration_number
      )), '[]'::jsonb)
      from public.customer_estimates c
      where public.customer_norm_reg(c.vehicle_registration_number) = any($1)
        and ($2::text is null or public.customer_norm_reg(c.vehicle_registration_number) = $2)
      $q$
    into v_extra
    using v_regs, v_reg;
    v_rows := coalesce(v_rows, '[]'::jsonb) || coalesce(v_extra, '[]'::jsonb);
  end if;

  return coalesce(v_rows, '[]'::jsonb);
end;
$_$;


--
-- Name: customer_list_helpdesk_contacts(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_helpdesk_contacts(p_session_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.customer_require_session(p_session_token);

  RETURN COALESCE(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', c.id,
          'group_key', c.group_key,
          'sort_order', c.sort_order,
          'level_label', c.level_label,
          'contact_name', c.contact_name,
          'role_title', c.role_title,
          'description', c.description,
          'phone', c.phone,
          'email', c.email,
          'icon_emoji', c.icon_emoji,
          'badge_variant', c.badge_variant,
          'chat_contact_key', c.chat_contact_key
        )
        ORDER BY c.group_key, c.sort_order, c.id
      )
      FROM public.settings_customer_helpdesk_contacts c
      WHERE c.is_active = true
    ),
    '[]'::jsonb
  );
END;
$$;


--
-- Name: customer_list_my_bookings(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_my_bookings(p_session_token text, p_reg_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_sess record;
  v_reg text;
  v_regs text[];
  v_rows jsonb;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);

  if p_reg_number is not null and btrim(p_reg_number) <> '' then
    v_reg := public.customer_assert_reg(p_session_token, p_reg_number);
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', s.id,
        'lead_number', s.lead_number,
        'booking_date', s.booking_date,
        'appointment_date', s.appointment_date,
        'booking_time', s.booking_time,
        'booking_source', s.booking_source,
        'reg_number', s.reg_number,
        'model', s.model,
        'variant', s.variant,
        'customer_name', s.customer_name,
        'customer_phone', s.customer_phone,
        'service_type', s.service_type,
        'complaint_description', s.complaint_description,
        'pickup_required', s.pickup_required,
        'pickup_address', s.pickup_address,
        'branch', s.branch,
        'status', s.status,
        'assigned_sa_name', s.assigned_sa_name,
        'created_at', s.created_at
      )
      order by s.created_at desc
    ),
    '[]'::jsonb
  )
  into v_rows
  from (
    select *
    from public.service_bookings b
    where (
      public.customer_norm_reg(b.reg_number) = any(v_regs)
      or public.customer_last10_digits(b.customer_phone) = public.customer_last10_digits(v_sess.phone)
    )
    and (
      v_reg is null
      or public.customer_norm_reg(b.reg_number) = v_reg
    )
    order by b.created_at desc
    limit 20
  ) s;

  return v_rows;
end;
$$;


--
-- Name: FUNCTION customer_list_my_bookings(p_session_token text, p_reg_number text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_list_my_bookings(p_session_token text, p_reg_number text) IS 'Customer portal booking list. Returns live service_bookings status for the session phone and vehicles, including Cancelled.';


--
-- Name: customer_list_my_vehicles(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_my_vehicles(p_session_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_sess record;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  return public.customer_collect_vehicles(v_sess.phone);
end;
$$;


--
-- Name: customer_my_reg_keys(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_my_reg_keys(p_phone text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(array_agg(v->>'reg_key'), '{}'::text[])
  from jsonb_array_elements(public.customer_collect_vehicles(p_phone)) v;
$$;


--
-- Name: customer_norm_reg(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_norm_reg(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select nullif(upper(regexp_replace(coalesce(p, ''), '\s+', '', 'g')), '');
$$;


--
-- Name: customer_register_device_token(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_register_device_token(p_session_token text, p_device_token text, p_token_provider text, p_token_platform text, p_app_version text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session record;
  v_token text := btrim(COALESCE(p_device_token, ''));
  v_provider text := lower(btrim(COALESCE(p_token_provider, '')));
  v_platform text := lower(btrim(COALESCE(p_token_platform, '')));
  v_id uuid;
BEGIN
  SELECT * INTO v_session FROM public.customer_require_session(p_session_token);
  IF char_length(v_token) < 10 OR char_length(v_token) > 4096 THEN
    RAISE EXCEPTION 'Invalid device token';
  END IF;
  IF v_provider NOT IN ('fcm', 'expo') OR v_platform NOT IN ('ios', 'android') THEN
    RAISE EXCEPTION 'Invalid token metadata';
  END IF;

  INSERT INTO public.device_push_tokens (
    audience, user_id, phone_10, device_token, token_provider, token_platform, app_version, is_active, last_used_at
  ) VALUES (
    'customer', NULL, v_session.phone, v_token, v_provider, v_platform, NULLIF(btrim(COALESCE(p_app_version, '')), ''), true, now()
  )
  ON CONFLICT (device_token) DO UPDATE SET
    audience = 'customer',
    user_id = NULL,
    phone_10 = EXCLUDED.phone_10,
    token_provider = EXCLUDED.token_provider,
    token_platform = EXCLUDED.token_platform,
    app_version = EXCLUDED.app_version,
    is_active = true,
    last_used_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: customer_reject_staff_jwt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_reject_staff_jwt() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is not null
     and exists (select 1 from public.users u where u.id = auth.uid()) then
    raise exception 'forbidden';
  end if;
end;
$$;


--
-- Name: customer_require_session(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_require_session(p_session_token text) RETURNS TABLE(profile_id uuid, phone text, session_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_hash text;
begin
  perform public.customer_reject_staff_jwt();

  if p_session_token is null or btrim(p_session_token) = '' then
    raise exception 'Session expired.';
  end if;

  v_hash := public.customer_hash_token(btrim(p_session_token));

  return query
  select p.id, p.phone, s.id
  from public.customer_sessions s
  join public.customer_profiles p on p.id = s.profile_id
  where s.token_hash = v_hash
    and s.revoked_at is null
    and s.expires_at > now()
  limit 1;

  if not found then
    raise exception 'Session expired.';
  end if;
end;
$$;


--
-- Name: customer_resolve_visit_kind(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_resolve_visit_kind(p_job jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_job IS NULL THEN 'other'
    WHEN public.is_floor_incharge_service_type(p_job->>'service_type') THEN 'mechanical'
    WHEN COALESCE(p_job->>'source', '') = 'bodyshop' THEN 'bodyshop'
    WHEN COALESCE(p_job->>'service_type', '') = 'Accident' THEN 'bodyshop'
    WHEN lower(COALESCE(p_job->>'service_type', '')) LIKE '%accident%' THEN 'bodyshop'
    ELSE 'other'
  END;
$$;


--
-- Name: FUNCTION customer_resolve_visit_kind(p_job jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_resolve_visit_kind(p_job jsonb) IS 'Customer mobile visit classification from active job row (reception wins over bodyshop card).';


--
-- Name: customer_send_advisor_message(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_send_advisor_message(p_session_token text, p_reg_number text, p_body text, p_contact_key text DEFAULT 'advisor'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ctx record;
  v_body text := btrim(COALESCE(p_body, ''));
  v_chat public.advisor_chats%ROWTYPE;
  v_message public.advisor_chat_messages%ROWTYPE;
  v_name text;
  v_contact text := COALESCE(NULLIF(btrim(p_contact_key), ''), 'advisor');
  v_peer text;
BEGIN
  IF v_contact <> 'advisor' AND NOT EXISTS (
    SELECT 1
    FROM public.settings_customer_helpdesk_contacts c
    WHERE c.is_active = true
      AND c.chat_contact_key = v_contact
  ) THEN
    RAISE EXCEPTION 'Not allowed.';
  END IF;

  IF char_length(v_body) < 1 THEN
    RAISE EXCEPTION 'Message should be at least 1 character.';
  END IF;
  IF char_length(v_body) > 2000 THEN
    RAISE EXCEPTION 'Message is too long.';
  END IF;

  SELECT * INTO v_ctx
  FROM public.customer_advisor_chat_context(p_session_token, p_reg_number)
  LIMIT 1;

  v_name := COALESCE(NULLIF(btrim(v_ctx.customer_name), ''), 'Customer');
  v_peer := public.customer_helpdesk_peer_name(v_contact, v_ctx.sa_name);

  INSERT INTO public.advisor_chats (
    dealer_code, reg_number, reg_key, phone_10, customer_name, jc_number, sa_name, contact_key
  )
  VALUES (
    v_ctx.dealer_code, v_ctx.reg_number, v_ctx.reg_key, v_ctx.phone_10,
    v_ctx.customer_name, v_ctx.jc_number, v_peer, v_contact
  )
  ON CONFLICT (dealer_code, reg_key, phone_10, contact_key) DO UPDATE
  SET reg_number = EXCLUDED.reg_number,
      customer_name = COALESCE(EXCLUDED.customer_name, public.advisor_chats.customer_name),
      jc_number = COALESCE(EXCLUDED.jc_number, public.advisor_chats.jc_number),
      sa_name = COALESCE(EXCLUDED.sa_name, public.advisor_chats.sa_name),
      updated_at = now()
  RETURNING * INTO v_chat;

  SELECT * INTO v_chat
  FROM public.advisor_chats
  WHERE id = v_chat.id
  FOR UPDATE;

  INSERT INTO public.advisor_chat_messages (chat_id, author_side, author_user_id, author_name, body)
  VALUES (v_chat.id, 'customer', NULL, v_name, v_body)
  RETURNING * INTO v_message;

  UPDATE public.advisor_chats
  SET last_message_at = v_message.created_at,
      last_message_preview = left(v_body, 160),
      last_author_side = 'customer',
      staff_unread_count = staff_unread_count + 1,
      customer_unread_count = 0,
      updated_at = now()
  WHERE id = v_chat.id
  RETURNING * INTO v_chat;

  RETURN jsonb_build_object(
    'chat', to_jsonb(v_chat),
    'message', to_jsonb(v_message)
  );
END;
$$;


--
-- Name: customer_set_estimate_decision(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_estimate_decision(p_session_token text, p_estimate_id text, p_decision text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_sess record;
  v_regs text[];
  v_decision text := lower(btrim(coalesce(p_decision, '')));
  v_est_reg text;
  v_mode text;
  v_id bigint;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_regs := public.customer_my_reg_keys(v_sess.phone);

  if v_decision not in ('approve', 'approved', 'reject', 'rejected') then
    raise exception 'Invalid estimate decision.';
  end if;
  if v_decision in ('reject', 'rejected') and nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'Rejection reason is required.';
  end if;

  if to_regclass('public.customer_estimates') is not null then
    execute
      $q$
      select public.customer_norm_reg(c.vehicle_registration_number)
      from public.customer_estimates c
      where c.estimate_no = $1
         or c.id::text = $1
      limit 1
      $q$
    into v_est_reg
    using btrim(p_estimate_id);
  end if;

  if v_est_reg is null then
    select public.customer_norm_reg(b.vehicle_registration_number)
    into v_est_reg
    from public.post_feedback_bot_data b
    where b.mode = 'customer_estimate_payload'
      and (
        b.id::text = btrim(p_estimate_id)
        or (b.feedback_text)::jsonb->>'estimate_no' = btrim(p_estimate_id)
      )
    limit 1;
  end if;

  if v_est_reg is null then
    select public.customer_norm_reg(s.reg_number)
    into v_est_reg
    from public.service_reception_entries s
    where ('reception-' || s.id::text) = btrim(p_estimate_id)
    limit 1;
  end if;

  if v_est_reg is null or not (v_est_reg = any(v_regs)) then
    raise exception 'Vehicle not found for this session.';
  end if;

  if to_regclass('public.customer_estimates') is not null then
    execute
      $q$
      update public.customer_estimates
      set status = $2,
          rejection_reason = $3,
          approved_at = case when $2 = 'Approved' then now() else approved_at end,
          updated_at = now()
      where estimate_no = $1 or id::text = $1
      $q$
    using btrim(p_estimate_id),
          case when v_decision in ('approve', 'approved') then 'Approved' else 'Rejected' end,
          nullif(btrim(coalesce(p_reason, '')), '');
  end if;

  v_mode := case
    when v_decision in ('approve', 'approved') then 'customer_estimate_approval'
    else 'customer_estimate_rejection'
  end;

  insert into public.post_feedback_bot_data (
    vehicle_registration_number,
    mobile_number,
    feedback_text,
    service_type,
    mode,
    complaint_date_time
  ) values (
    v_est_reg,
    v_sess.phone,
    case
      when v_mode = 'customer_estimate_approval'
        then '[Estimate Approved] Customer approved Estimate #' || btrim(p_estimate_id) || ' via app.'
      else '[Estimate Rejected] Estimate #' || btrim(p_estimate_id) || ' rejected. Reason: ' || btrim(coalesce(p_reason, ''))
    end,
    'Estimate decision',
    v_mode,
    now()::text
  )
  returning id into v_id;

  return jsonb_build_object(
    'id', v_id,
    'estimate_id', btrim(p_estimate_id),
    'decision', v_decision,
    'reg_number', v_est_reg
  );
end;
$_$;


--
-- Name: customer_start_session(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_start_session(p_username text, p_password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user text := public.customer_last10_digits(p_username);
  v_pass text := public.customer_last10_digits(p_password);
  v_phone_key text := coalesce(v_user, v_pass, 'invalid');
  v_attempt_count int;
  v_vehicles jsonb;
  v_profile_id uuid;
  v_token text;
  v_expires timestamptz := now() + interval '12 hours';
begin
  perform public.customer_reject_staff_jwt();

  insert into public.customer_auth_attempts (phone_key) values (v_phone_key);
  select count(*) into v_attempt_count
  from public.customer_auth_attempts
  where phone_key = v_phone_key
    and attempted_at > now() - interval '15 minutes';
  if v_attempt_count > 10 then
    raise exception 'Invalid mobile number.';
  end if;

  if v_user is null or v_pass is null or v_user <> v_pass then
    raise exception 'Invalid mobile number.';
  end if;

  v_vehicles := public.customer_collect_vehicles(v_user);
  if v_vehicles is null or jsonb_array_length(v_vehicles) = 0 then
    raise exception 'No vehicle found for this mobile number.';
  end if;

  insert into public.customer_profiles (phone, last_login_at, updated_at)
  values (v_user, now(), now())
  on conflict (phone) do update
    set last_login_at = now(),
        updated_at = now()
  returning id into v_profile_id;

  v_token := encode(extensions.gen_random_bytes(32), 'hex');

  insert into public.customer_sessions (profile_id, token_hash, expires_at)
  values (v_profile_id, public.customer_hash_token(v_token), v_expires);

  return jsonb_build_object(
    'session_token', v_token,
    'expires_at', v_expires,
    'phone', v_user,
    'vehicles', v_vehicles
  );
end;
$$;


--
-- Name: FUNCTION customer_start_session(p_username text, p_password text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_start_session(p_username text, p_password text) IS 'MOBILE-011: username and password must be the same 10-digit mobile. Returns session_token + that phone''s vehicles.';


--
-- Name: customer_submit_complaint(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_submit_complaint(p_session_token text, p_reg_number text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_sess record;
  v_reg text;
  v_id bigint;
  v_text text;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_reg := public.customer_assert_reg(p_session_token, p_reg_number);

  v_text := nullif(btrim(coalesce(p_payload->>'text', p_payload->>'feedback_text', '')), '');
  if v_text is null and jsonb_typeof(p_payload->'problems') = 'array' then
    select string_agg('Point ' || ord::text || ': ' || btrim(elem), E'\n')
    into v_text
    from jsonb_array_elements_text(p_payload->'problems') with ordinality as t(elem, ord)
    where btrim(elem) <> '';
    if coalesce(btrim(p_payload->>'notes'), '') <> '' then
      v_text := trim(both E'\n' from coalesce(v_text, '') || E'\nAdditional Notes: ' || btrim(p_payload->>'notes'));
    end if;
  end if;

  if v_text is null or btrim(v_text) = '' then
    raise exception 'Complaint text is required.';
  end if;

  insert into public.post_feedback_bot_data (
    vehicle_registration_number,
    customer_name,
    mobile_number,
    rating,
    feedback_text,
    service_type,
    service_advisor_name,
    branch,
    model,
    mode,
    complaint_date_time
  ) values (
    v_reg,
    nullif(btrim(coalesce(p_payload->>'owner_name', '')), ''),
    v_sess.phone,
    null,
    v_text,
    coalesce(nullif(btrim(p_payload->>'service_type'), ''), 'Customer Reported Issues'),
    nullif(btrim(coalesce(p_payload->>'sa_name', '')), ''),
    nullif(btrim(coalesce(p_payload->>'branch', '')), ''),
    nullif(btrim(coalesce(p_payload->>'model', '')), ''),
    'customer_portal_concern',
    now()::text
  )
  returning id into v_id;

  return jsonb_build_object('id', v_id, 'mode', 'customer_portal_concern');
end;
$$;


--
-- Name: customer_submit_feedback(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_submit_feedback(p_session_token text, p_reg_number text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_sess record;
  v_reg text;
  v_id bigint;
  v_text text;
  v_rating smallint;
begin
  select * into v_sess from public.customer_require_session(p_session_token);
  v_reg := public.customer_assert_reg(p_session_token, p_reg_number);

  v_text := nullif(btrim(coalesce(p_payload->>'text', p_payload->>'feedback_text', '')), '');
  if v_text is null then
    raise exception 'Feedback text is required.';
  end if;

  begin
    v_rating := nullif(p_payload->>'rating', '')::smallint;
  exception when others then
    v_rating := null;
  end;

  insert into public.post_feedback_bot_data (
    vehicle_registration_number,
    customer_name,
    mobile_number,
    rating,
    feedback_text,
    service_type,
    service_advisor_name,
    branch,
    model,
    mode,
    complaint_date_time
  ) values (
    v_reg,
    nullif(btrim(coalesce(p_payload->>'owner_name', '')), ''),
    v_sess.phone,
    v_rating,
    v_text,
    coalesce(nullif(btrim(p_payload->>'service_type'), ''), 'General Service'),
    nullif(btrim(coalesce(p_payload->>'sa_name', '')), ''),
    nullif(btrim(coalesce(p_payload->>'branch', '')), ''),
    nullif(btrim(coalesce(p_payload->>'model', '')), ''),
    'customer_portal_feedback',
    now()::text
  )
  returning id into v_id;

  return jsonb_build_object('id', v_id, 'mode', 'customer_portal_feedback');
end;
$$;


--
-- Name: deactivate_staff_device_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deactivate_staff_device_token(p_device_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  UPDATE public.device_push_tokens
  SET is_active = false, last_used_at = now()
  WHERE device_token = btrim(COALESCE(p_device_token, ''))
    AND audience = 'staff'
    AND user_id = v_uid;
END;
$$;


--
-- Name: dealer_code_in_scope(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dealer_code_in_scope(p_dealer_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM unnest(public.my_effective_dealer_codes()) AS dc(code)
    WHERE upper(btrim(coalesce(dc.code, ''))) = upper(btrim(coalesce(p_dealer_code, '')))
  );
$$;


--
-- Name: FUNCTION dealer_code_in_scope(p_dealer_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dealer_code_in_scope(p_dealer_code text) IS 'Returns true if provided dealer code is within current user effective dealer scope.';


--
-- Name: delete_reception_entry_cascade(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_reception_entry_cascade(p_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_jc_number              text;
  v_reg_number             text;
  v_estimate_storage_path  text;
  v_invoice_storage_path   text;
  v_dealer_code            text;
  v_repair_card_id         integer;
  v_repair_card_job_card_no text;
  v_repair_card_reg_number  text;
  v_repair_card_status      text;
  v_intake_photo_paths     text[];
BEGIN
  SELECT
    jc_number,
    reg_number,
    estimate_storage_path,
    invoice_storage_path,
    dealer_code
  INTO
    v_jc_number,
    v_reg_number,
    v_estimate_storage_path,
    v_invoice_storage_path,
    v_dealer_code
  FROM public.service_reception_entries
  WHERE id = p_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reception entry % not found', p_id;
  END IF;

  IF NOT (
    public.is_admin()
    OR (
      public.has_module_delete('reception')
      AND public.dealer_code_in_scope(v_dealer_code)
    )
  ) THEN
    RAISE EXCEPTION 'permission denied: requires reception delete or admin'
      USING ERRCODE = '42501';
  END IF;

  SELECT id, job_card_no, reg_number, overall_status
  INTO v_repair_card_id, v_repair_card_job_card_no, v_repair_card_reg_number, v_repair_card_status
  FROM public.bodyshop_repair_cards
  WHERE reception_entry_id = p_id
  LIMIT 1;

  IF FOUND THEN
    IF lower(btrim(COALESCE(v_repair_card_status, ''))) = 'cancelled' THEN
      NULL;
    ELSIF upper(btrim(v_repair_card_job_card_no)) IS DISTINCT FROM
          upper(btrim(COALESCE(v_repair_card_reg_number, '')))
          AND btrim(v_repair_card_job_card_no) <> ''
    THEN
      RAISE EXCEPTION
        'Cannot delete: bodyshop repair card has a real DMS job card assigned (%). Cancel the bodyshop repair first, then delete this entry.',
        v_repair_card_job_card_no;
    END IF;

    SELECT array_agg(storage_path)
    INTO v_intake_photo_paths
    FROM public.bodyshop_intake_vehicle_photos
    WHERE repair_card_id = v_repair_card_id;

    DELETE FROM public.bodyshop_repair_cards WHERE id = v_repair_card_id;
  END IF;

  IF v_jc_number IS NOT NULL AND btrim(v_jc_number) <> '' THEN
    DELETE FROM public.technician_assignments
    WHERE job_card_number = v_jc_number;

    DELETE FROM public.job_card_support_assignments
    WHERE job_card_number = v_jc_number;

    DELETE FROM public.bodyshop_floor_support_assignments
    WHERE job_card_number = v_jc_number;
  END IF;

  DELETE FROM public.service_reception_entries WHERE id = p_id;

  RETURN jsonb_build_object(
    'deleted_id',             p_id,
    'estimate_storage_path',  v_estimate_storage_path,
    'invoice_storage_path',   v_invoice_storage_path,
    'intake_photo_paths',     COALESCE(to_jsonb(v_intake_photo_paths), '[]'::jsonb)
  );
END;
$$;


--
-- Name: FUNCTION delete_reception_entry_cascade(p_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_reception_entry_cascade(p_id bigint) IS 'Deletes a service_reception_entries row and dependents. Requires admin or reception delete in dealer scope. Blocks if a bodyshop repair card has a real DMS JC unless that card is cancelled.';


--
-- Name: employee_business_roles(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_business_roles(p_role text) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    array_agg(DISTINCT normalized ORDER BY normalized),
    ARRAY[]::text[]
  )
  FROM (
    SELECT public.normalize_business_role_token(token) AS normalized
    FROM unnest(string_to_array(coalesce(p_role, ''), ',')) AS token
  ) parsed
  WHERE normalized IS NOT NULL;
$$;


--
-- Name: FUNCTION employee_business_roles(p_role text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employee_business_roles(p_role text) IS 'RBAC-003: split comma-separated employee_master.role into canonical role codes.';


--
-- Name: employee_has_any_business_role(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_has_any_business_role(p_role text, p_targets text[]) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM unnest(public.employee_business_roles(p_role)) AS role_code
    WHERE role_code = ANY (
      SELECT public.normalize_business_role_token(t)
      FROM unnest(coalesce(p_targets, ARRAY[]::text[])) AS t
    )
  );
$$;


--
-- Name: FUNCTION employee_has_any_business_role(p_role text, p_targets text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employee_has_any_business_role(p_role text, p_targets text[]) IS 'RBAC-003: true when any parsed role matches any normalized target.';


--
-- Name: employee_has_business_role(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_has_business_role(p_role text, p_target text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT public.normalize_business_role_token(p_target) = ANY(public.employee_business_roles(p_role));
$$;


--
-- Name: FUNCTION employee_has_business_role(p_role text, p_target text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.employee_has_business_role(p_role text, p_target text) IS 'RBAC-003: true when any parsed role on employee_master.role matches target.';


--
-- Name: enforce_all_service_data_robot_flag_freshness_for_plus2_due(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_all_service_data_robot_flag_freshness_for_plus2_due() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_today_ist date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_is_stale_robot_mark boolean;
BEGIN
  v_is_stale_robot_mark :=
    COALESCE(NEW.updated_by_robot, false) = true
    AND (
      NEW.updated_by_robot_at IS NULL
      OR ((NEW.updated_by_robot_at AT TIME ZONE 'Asia/Kolkata')::date <> v_today_ist)
    );

  IF NEW.chassis_no IS NOT NULL
     AND v_is_stale_robot_mark
     AND (
       NEW.assumed_next_service_date = (current_date + 2)
       OR (
         NEW.assumed_next_service_date IS NULL
         AND lower(btrim(COALESCE(NEW.assumed_next_service_type, ''))) = 'first free service'
       )
     )
  THEN
    NEW.updated_by_robot := false;
    NEW.updated_by_robot_at := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_all_service_data_robot_flag_freshness_for_plus2_due(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_all_service_data_robot_flag_freshness_for_plus2_due() IS 'Before-write guard: stale/non-today robot timestamp forces updated_by_robot=false and updated_by_robot_at=NULL for +2 due rows and First Free Service rows with no assumed due date.';


--
-- Name: enforce_bodyshop_intake_photo_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_bodyshop_intake_photo_limit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  existing_count integer;
begin
  select count(*)
    into existing_count
  from public.bodyshop_intake_vehicle_photos p
  where p.reception_entry_id = new.reception_entry_id
    and (tg_op = 'INSERT' or p.id <> new.id);

  if existing_count >= 20 then
    raise exception 'Maximum 20 bodyshop intake photos allowed per reception entry.'
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_bodyshop_reception_link_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_bodyshop_reception_link_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.reception_entry_id IS NULL THEN
    RAISE EXCEPTION
      'reception_entry_id is required when creating bodyshop_repair_cards (id=%).',
      COALESCE(NEW.id, -1);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_bodyshop_stage_pointer_s9_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_bodyshop_stage_pointer_s9_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_survey_status text;
	v_survey_hold_reason text;
	v_floor_assigned boolean;
	v_stage9_done boolean;
BEGIN
	IF COALESCE(NEW.overall_status, 'active') <> 'active' THEN
		RETURN NEW;
	END IF;

	v_survey_status := lower(btrim(COALESCE(NEW.survey_status, '')));
	v_survey_hold_reason := btrim(COALESCE(NEW.survey_hold_reason, ''));
	v_floor_assigned := lower(btrim(COALESCE(NEW.bodyshop_floor, ''))) IN ('floor 2', 'floor 3');

	v_stage9_done := (
		NEW.survey_date IS NOT NULL
		AND (v_survey_status IN ('hold', 'approved'))
		AND (v_survey_status <> 'hold' OR v_survey_hold_reason <> '')
		AND v_floor_assigned
	);

	IF COALESCE(NEW.current_stage, 1) > 9 AND NOT v_stage9_done THEN
		NEW.current_stage := 9;
		NEW.current_stage_name := 'Survey';
	END IF;

	RETURN NEW;
END;
$$;


--
-- Name: enforce_service_reception_sa_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_service_reception_sa_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF public.is_admin() OR public.has_module_view('reception') THEN
    RETURN NEW;
  END IF;

  IF public.has_module_modify('service_advisor') THEN
    -- Ownership gate: SA can only update rows mapped to their employee code(s).
    IF OLD.sa_employee_code IS NULL OR NOT public.user_has_employee_code(OLD.sa_employee_code) THEN
      RAISE EXCEPTION 'You can update only your own assigned rows | code: P0001';
    END IF;

    -- SA may edit only these fields: service_type, jc_number, remark, estimate_* and updated_at.
    IF NEW.dealer_code IS DISTINCT FROM OLD.dealer_code
      OR NEW.reg_number IS DISTINCT FROM OLD.reg_number
      OR NEW.model IS DISTINCT FROM OLD.model
      OR NEW.sa_name IS DISTINCT FROM OLD.sa_name
      OR NEW.sa_employee_code IS DISTINCT FROM OLD.sa_employee_code
      OR NEW.sa_display_name IS DISTINCT FROM OLD.sa_display_name
      OR NEW.owner_name IS DISTINCT FROM OLD.owner_name
      OR NEW.owner_phone IS DISTINCT FROM OLD.owner_phone
      OR NEW.source IS DISTINCT FROM OLD.source
      OR NEW.created_by IS DISTINCT FROM OLD.created_by
      OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'Service Advisor can edit only Service Type, Job Card Number, Remark, and Estimate fields';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enqueue_advisor_chat_push(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_advisor_chat_push() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_chat public.advisor_chats%ROWTYPE;
  v_title text;
  v_body text;
  v_data jsonb;
BEGIN
  SELECT * INTO v_chat FROM public.advisor_chats WHERE id = NEW.chat_id;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  v_title := left(btrim(v_chat.reg_number), 80);
  IF COALESCE(v_chat.contact_key, 'advisor') <> 'advisor' AND NULLIF(btrim(v_chat.sa_name), '') IS NOT NULL THEN
    v_title := left(btrim(v_chat.reg_number) || ' · ' || btrim(v_chat.sa_name), 80);
  END IF;
  v_body := left(btrim(NEW.body), 160);
  v_data := jsonb_build_object(
    'chat_id', v_chat.id::text,
    'reg_number', v_chat.reg_number,
    'audience', CASE WHEN NEW.author_side = 'customer' THEN 'staff' ELSE 'customer' END,
    'contact_key', COALESCE(v_chat.contact_key, 'advisor')
  );

  IF NEW.author_side = 'customer' THEN
    INSERT INTO public.chat_push_outbox (message_id, token_id, title, body, chat_id, data)
    SELECT NEW.id, t.id, v_title, v_body, v_chat.id, v_data
    FROM public.device_push_tokens t
    JOIN public.users u ON u.id = t.user_id AND u.is_active = true
    WHERE t.audience = 'staff'
      AND t.is_active
      AND (NEW.author_user_id IS NULL OR t.user_id IS DISTINCT FROM NEW.author_user_id)
      AND EXISTS (
        SELECT 1
        FROM public.user_employee_links uel
        WHERE uel.user_id = u.id
          AND uel.is_active = true
          AND uel.dealer_code = v_chat.dealer_code
      )
      AND (
        u.role = ANY (ARRAY['admin'::text, 'super_admin'::text])
        OR EXISTS (
          SELECT 1
          FROM public.user_module_permissions p
          JOIN public.modules m ON m.id = p.module_id
          WHERE p.user_id = u.id
            AND m.name = 'chat'
            AND m.is_active = true
            AND p.can_view = true
        )
        OR public.advisor_chat_user_involved(v_chat.id, u.id)
      )
    ON CONFLICT (message_id, token_id) DO NOTHING;
  ELSIF NEW.author_side = 'staff' THEN
    INSERT INTO public.chat_push_outbox (message_id, token_id, title, body, chat_id, data)
    SELECT NEW.id, t.id, v_title, v_body, v_chat.id, v_data
    FROM public.device_push_tokens t
    WHERE t.audience = 'customer'
      AND t.is_active
      AND t.phone_10 = v_chat.phone_10
      AND (NEW.author_user_id IS NULL OR t.user_id IS DISTINCT FROM NEW.author_user_id)
    ON CONFLICT (message_id, token_id) DO NOTHING;
  END IF;

  BEGIN
    PERFORM public.invoke_send_chat_push();
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: enqueue_all_service_history_sync(text, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_all_service_history_sync(p_chassis_no text, p_delay interval DEFAULT '00:00:45'::interval) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_key text;
  v_delay interval;
BEGIN
  v_key := nullif(upper(btrim(coalesce(p_chassis_no, ''))), '');
  v_delay := COALESCE(p_delay, interval '45 seconds');

  IF v_key IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.all_service_history_sync_queue (
    chassis_key,
    last_event_at,
    not_before,
    enqueue_count,
    source_tag
  )
  VALUES (
    v_key,
    now(),
    now() + v_delay,
    1,
    'trigger'
  )
  ON CONFLICT (chassis_key) DO UPDATE
  SET
    last_event_at = EXCLUDED.last_event_at,
    not_before = GREATEST(public.all_service_history_sync_queue.not_before, EXCLUDED.not_before),
    enqueue_count = public.all_service_history_sync_queue.enqueue_count + 1,
    source_tag = EXCLUDED.source_tag;
END;
$$;


--
-- Name: FUNCTION enqueue_all_service_history_sync(p_chassis_no text, p_delay interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_all_service_history_sync(p_chassis_no text, p_delay interval) IS 'Enqueues or extends delayed chassis-level refresh requests for all_service_data history sync.';


--
-- Name: enqueue_psf_import_run(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_psf_import_run(p_branch_slot text, p_source_file_name text, p_rows jsonb) RETURNS TABLE(import_run_id bigint, status text, total_rows integer, staged_rows integer, error_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id bigint;
  v_total_rows integer := 0;
  v_staged_rows integer := 0;
begin
  v_total_rows := coalesce(jsonb_array_length(coalesce(p_rows, '[]'::jsonb)), 0);

  insert into public.psf_import_runs (
    status,
    branch_slot,
    source_file_name,
    total_rows,
    started_at,
    completed_at,
    error_message
  )
  values (
    'queued',
    p_branch_slot,
    p_source_file_name,
    v_total_rows,
    null,
    null,
    null
  )
  returning id into v_run_id;

  if v_total_rows > 0 then
    insert into public.psf_import_staging (
      import_run_id,
      row_number,
      branch,
      branch_label,
      location,
      portal,
      invoice_date,
      job_card_number,
      sr_type,
      chassis_number,
      final_labour_amount,
      final_spares_amount,
      total_invoice_amount,
      parent_product_line,
      product_line,
      created_date_time,
      closed_date_time,
      first_name,
      last_name,
      sr_assigned_to,
      employee_code,
      vehicle_registration_number,
      vehicle_sale_date,
      account_phone_number,
      lubs_revenue,
      kms_run,
      last_service_km,
      last_service_date,
      source_row
    )
    select
      v_run_id,
      src.ordinality::integer,
      nullif(btrim(src.row ->> 'branch'), ''),
      nullif(btrim(src.row ->> 'branch_label'), ''),
      nullif(btrim(src.row ->> 'location'), ''),
      public.psf_normalize_portal(src.row ->> 'portal'),
      public.psf_try_date(src.row ->> 'invoice_date'),
      nullif(upper(btrim(src.row ->> 'job_card_number')), ''),
      nullif(btrim(src.row ->> 'sr_type'), ''),
      nullif(upper(btrim(src.row ->> 'chassis_number')), ''),
      public.psf_try_numeric(src.row ->> 'final_labour_amount'),
      public.psf_try_numeric(src.row ->> 'final_spares_amount'),
      public.psf_try_numeric(src.row ->> 'total_invoice_amount'),
      nullif(btrim(src.row ->> 'parent_product_line'), ''),
      nullif(btrim(src.row ->> 'product_line'), ''),
      public.psf_try_timestamptz(src.row ->> 'created_date_time'),
      public.psf_try_timestamptz(src.row ->> 'closed_date_time'),
      nullif(btrim(src.row ->> 'first_name'), ''),
      nullif(btrim(src.row ->> 'last_name'), ''),
      nullif(btrim(src.row ->> 'sr_assigned_to'), ''),
      nullif(upper(btrim(src.row ->> 'employee_code')), ''),
      nullif(upper(btrim(src.row ->> 'vehicle_registration_number')), ''),
      public.psf_try_date(src.row ->> 'vehicle_sale_date'),
      nullif(btrim(src.row ->> 'account_phone_number'), ''),
      public.psf_try_numeric(src.row ->> 'lubs_revenue'),
      public.psf_try_numeric(src.row ->> 'kms_run'),
      public.psf_try_numeric(src.row ->> 'last_service_km'),
      public.psf_try_date(src.row ->> 'last_service_date'),
      src.row
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) with ordinality as src(row, ordinality);
  end if;

  select count(*) into v_staged_rows
  from public.psf_import_staging s
  where s.import_run_id = v_run_id;

  update public.psf_import_runs
  set staged_rows = v_staged_rows
  where id = v_run_id;

  return query
  select
    v_run_id,
    'queued'::text,
    v_total_rows,
    v_staged_rows,
    null::text;
exception
  when others then
    if v_run_id is not null then
      update public.psf_import_runs
      set
        status = 'failed',
        error_message = sqlerrm,
        completed_at = now()
      where id = v_run_id;
    end if;

    return query
    select
      coalesce(v_run_id, 0),
      'failed'::text,
      coalesce(v_total_rows, 0),
      coalesce(v_staged_rows, 0),
      sqlerrm;
end;
$$;


--
-- Name: ensure_admin_bypass_policy(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_admin_bypass_policy(target_schema text, target_table text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  fq_table text;
  has_rls boolean;
  owner_name text;
BEGIN
  IF target_schema IS NULL OR target_table IS NULL THEN
    RETURN;
  END IF;

  -- Restrict automation to app tables only.
  IF target_schema NOT IN ('public', 'storage') THEN
    RETURN;
  END IF;

  fq_table := format('%I.%I', target_schema, target_table);

  SELECT c.relrowsecurity, pg_get_userbyid(c.relowner)
  INTO has_rls, owner_name
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = target_schema
    AND c.relname = target_table
    AND c.relkind IN ('r', 'p');

  -- Do not alter baseline behavior for tables that are not already RLS-protected.
  IF COALESCE(has_rls, false) = false THEN
    RETURN;
  END IF;

  -- CREATE POLICY requires table ownership; skip tables owned by managed platform roles.
  IF owner_name IS DISTINCT FROM current_user THEN
    RAISE NOTICE 'Skipping %.%: owner is %, executor is %', target_schema, target_table, owner_name, current_user;
    RETURN;
  END IF;

  BEGIN
    EXECUTE format(
      'DROP POLICY IF EXISTS admin_unrestricted_all_ops_v1 ON %s',
      fq_table
    );

    EXECUTE format(
      'CREATE POLICY admin_unrestricted_all_ops_v1 ON %s FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin())',
      fq_table
    );
  EXCEPTION
    WHEN insufficient_privilege THEN
      RAISE NOTICE 'Skipping %.% due to insufficient privilege while creating policy', target_schema, target_table;
      RETURN;
  END;
END;
$$;


--
-- Name: escalate(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate(p_complaint_id bigint, p_escalation_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_is_admin boolean := public.is_admin();
  v_dealer_code text := public.my_dealer_code();
BEGIN
  IF NOT (v_is_admin OR public.has_module_modify('complaints')) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  IF v_is_admin THEN
    UPDATE public.complaint_tickets
    SET
      is_escalated = true,
      escalated_at = now(),
      escalation_reason = p_escalation_reason
    WHERE id = p_complaint_id;
  ELSE
    UPDATE public.complaint_tickets
    SET
      is_escalated = true,
      escalated_at = now(),
      escalation_reason = p_escalation_reason
    WHERE id = p_complaint_id
      AND dealer_code = v_dealer_code;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Complaint not found or not accessible';
  END IF;

  RETURN jsonb_build_object('is_escalated', true);
END;
$$;


--
-- Name: export_bodyshop_do_recovery(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_bodyshop_do_recovery(p_repair_card_ids integer[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_ids integer[];
  v_cases jsonb;
  v_lines jsonb;
  v_docs jsonb;
BEGIN
  IF NOT (
    public.is_admin()
    OR public.has_module_view('bodyshop_recovery')
    OR public.has_module_modify('bodyshop_recovery')
  ) THEN
    RAISE EXCEPTION 'permission denied: requires bodyshop_recovery view'
      USING ERRCODE = '42501';
  END IF;

  v_ids := COALESCE((
    SELECT ARRAY_AGG(DISTINCT x)
    FROM unnest(COALESCE(p_repair_card_ids, ARRAY[]::integer[])) AS x
    WHERE x IS NOT NULL
  ), ARRAY[]::integer[]);

  SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.insurance_due_amount DESC NULLS LAST, c.repair_card_id), '[]'::jsonb)
    INTO v_cases
    FROM (
      SELECT
        brc.id AS repair_card_id,
        brc.job_card_no,
        brc.reg_number,
        brc.customer_name,
        brc.customer_phone,
        brc.branch,
        brc.sa_name,
        brc.insurance_company,
        brc.insurance_policy_no,
        brc.claim_intimation_no,
        s.invoice_number,
        s.invoice_date,
        s.invoice_amount,
        s.invoice_account,
        s.do_amount,
        s.do_released_amount,
        s.insurance_due_amount,
        s.do_payment_status,
        public.bodyshop_insurer_payer_mismatch(brc.insurance_company, s.invoice_account) AS insurer_mismatch
      FROM public.bodyshop_repair_cards brc
      LEFT JOIN public.bodyshop_settlements s ON s.repair_card_id = brc.id
      WHERE brc.id = ANY (v_ids)
    ) c;

  SELECT COALESCE(jsonb_agg(to_jsonb(l) ORDER BY l.repair_card_id, l.created_at, l.id), '[]'::jsonb)
    INTO v_lines
    FROM (
      SELECT
        sl.id,
        sl.repair_card_id,
        brc.job_card_no,
        brc.reg_number,
        sl.component,
        sl.line_type,
        sl.amount,
        sl.reference,
        sl.remarks,
        sl.actor_email,
        sl.created_at,
        sl.is_reversed
      FROM public.bodyshop_settlement_lines sl
      JOIN public.bodyshop_repair_cards brc ON brc.id = sl.repair_card_id
      WHERE sl.repair_card_id = ANY (v_ids)
    ) l;

  SELECT COALESCE(jsonb_agg(to_jsonb(d) ORDER BY d.repair_card_id, d.doc_key), '[]'::jsonb)
    INTO v_docs
    FROM (
      SELECT
        doc.repair_card_id,
        brc.job_card_no,
        brc.reg_number,
        doc.doc_key,
        doc.file_name,
        NULLIF(btrim(COALESCE(doc.drive_url, '')), '') AS drive_url,
        doc.storage_bucket,
        doc.storage_path
      FROM public.bodyshop_repair_card_documents doc
      JOIN public.bodyshop_repair_cards brc ON brc.id = doc.repair_card_id
      WHERE doc.repair_card_id = ANY (v_ids)
    ) d;

  RETURN jsonb_build_object(
    'cases', v_cases,
    'lines', v_lines,
    'documents', v_docs
  );
END;
$$;


--
-- Name: generate_complaint_link(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_complaint_link(p_reception_entry_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dealer_code text;
  v_token text;
  v_link_id bigint;
  v_sa_employee_code text;
BEGIN
  SELECT dealer_code, sa_employee_code
    INTO v_dealer_code, v_sa_employee_code
  FROM public.service_reception_entries
  WHERE id = p_reception_entry_id;

  IF v_dealer_code IS NULL THEN
    RAISE EXCEPTION 'Reception entry not found';
  END IF;

  IF NOT (
    public.is_admin()
    OR public.has_module_modify('complaints')
    OR (
      public.has_module_modify('service_advisor')
      AND v_sa_employee_code IS NOT NULL
      AND (
        public.user_has_employee_code(v_sa_employee_code)
        OR public.user_is_crm_for_dealer_sa(v_sa_employee_code)
        OR EXISTS (
          SELECT 1
          FROM public.user_employee_links uel
          JOIN public.employee_master em
            ON em.employee_code = uel.employee_code
          WHERE uel.user_id = auth.uid()
            AND uel.is_active = true
            AND public.employee_has_any_business_role(em.role, ARRAY['SM', 'GM'])
        )
      )
    )
  ) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  v_token := encode(extensions.gen_random_bytes(16), 'base64')
    || encode(extensions.gen_random_bytes(8), 'base64');
  v_token := REPLACE(REPLACE(REPLACE(v_token, '/', '_'), '+', '-'), '=', '');
  v_token := SUBSTRING(v_token FROM 1 FOR 24);

  INSERT INTO public.complaint_access_links (
    dealer_code, reception_entry_id, token, status
  ) VALUES (
    v_dealer_code, p_reception_entry_id, v_token, 'active'
  )
  ON CONFLICT (reception_entry_id) DO UPDATE
  SET token = v_token, status = 'active', created_at = now()
  RETURNING id INTO v_link_id;

  RETURN jsonb_build_object(
    'link_id', v_link_id,
    'token', v_token,
    'url', 'https://tw.care/c/' || v_token
  );
END;
$$;


--
-- Name: FUNCTION generate_complaint_link(p_reception_entry_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_complaint_link(p_reception_entry_id bigint) IS 'Generate customer complaint access link; uses extensions.gen_random_bytes for token entropy.';


--
-- Name: generate_lead_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_lead_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
  date_part text;
  seq_num   int;
begin
  if new.lead_number is null or new.lead_number = '' then
    date_part := to_char(current_date, 'YYYYMMDD');
    select coalesce(max(
      case when lead_number ~ ('^BKG-' || date_part || '-[0-9]+$')
           then (split_part(lead_number, '-', 3))::int else 0 end
    ), 0) + 1
    into seq_num
    from public.service_bookings;
    new.lead_number := 'BKG-' || date_part || '-' || lpad(seq_num::text, 4, '0');
  end if;
  return new;
end;
$_$;


--
-- Name: get_all_my_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_my_permissions() RETURNS TABLE(module_name text, module_label text, route text, can_view boolean, can_modify boolean, can_delete boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT m.name, m.label, m.route, p.can_view, p.can_modify, p.can_delete
  FROM public.user_module_permissions p
  JOIN public.modules m ON m.id = p.module_id
