--
-- Name: get_bodyshop_recovery_case(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bodyshop_recovery_case(p_repair_card_id integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_card public.bodyshop_repair_cards%ROWTYPE;
  v_header public.bodyshop_settlements%ROWTYPE;
  v_docs jsonb;
BEGIN
  IF NOT (
    public.is_admin()
    OR public.has_module_view('bodyshop_recovery')
    OR public.has_module_modify('bodyshop_recovery')
  ) THEN
    RAISE EXCEPTION 'permission denied: requires bodyshop_recovery view'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_card FROM public.bodyshop_repair_cards WHERE id = p_repair_card_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'repair card % not found', p_repair_card_id USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_header FROM public.bodyshop_settlements WHERE repair_card_id = p_repair_card_id;

  SELECT COALESCE(jsonb_agg(to_jsonb(d) ORDER BY d.uploaded_at DESC, d.id DESC), '[]'::jsonb)
    INTO v_docs
    FROM (
      SELECT
        doc.id,
        doc.doc_key,
        doc.file_name,
        doc.content_type,
        NULLIF(btrim(COALESCE(doc.drive_url, '')), '') AS drive_url,
        NULLIF(btrim(COALESCE(doc.drive_file_id, '')), '') AS drive_file_id,
        doc.storage_bucket,
        doc.storage_path,
        doc.uploaded_at
      FROM public.bodyshop_repair_card_documents doc
      WHERE doc.repair_card_id = p_repair_card_id
    ) d;

  RETURN jsonb_build_object(
    'repair_card_id', v_card.id,
    'job_card_no', v_card.job_card_no,
    'reg_number', v_card.reg_number,
    'customer_name', v_card.customer_name,
    'customer_phone', v_card.customer_phone,
    'customer_type', v_card.customer_type,
    'branch', v_card.branch,
    'sa_name', v_card.sa_name,
    'insurance_company', v_card.insurance_company,
    'insurance_policy_no', v_card.insurance_policy_no,
    'claim_intimation_no', v_card.claim_intimation_no,
    'insurance_type', v_card.insurance_type,
    'insurance_valid_date', v_card.insurance_valid_date,
    'invoice_number', v_header.invoice_number,
    'invoice_date', v_header.invoice_date,
    'invoice_amount', v_header.invoice_amount,
    'invoice_account', v_header.invoice_account,
    'do_amount', v_header.do_amount,
    'do_released_amount', v_header.do_released_amount,
    'insurance_due_amount', v_header.insurance_due_amount,
    'do_payment_status', v_header.do_payment_status,
    'documents', v_docs
  );
END;
$$;


--
-- Name: get_bodyshop_settlement(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bodyshop_settlement(p_repair_card_id integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_card public.bodyshop_repair_cards%ROWTYPE;
  v_header jsonb;
  v_lines jsonb;
  v_suggested jsonb;
  v_mismatch boolean := false;
BEGIN
  IF NOT public.bodyshop_settlement_can_view(p_repair_card_id) THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_card FROM public.bodyshop_repair_cards WHERE id = p_repair_card_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'repair card % not found', p_repair_card_id USING ERRCODE = 'P0002';
  END IF;

  SELECT to_jsonb(s) INTO v_header
    FROM public.bodyshop_settlements s
   WHERE s.repair_card_id = p_repair_card_id;

  SELECT COALESCE(jsonb_agg(to_jsonb(l) ORDER BY l.created_at DESC, l.id DESC), '[]'::jsonb)
    INTO v_lines
    FROM public.bodyshop_settlement_lines l
   WHERE l.repair_card_id = p_repair_card_id;

  SELECT to_jsonb(x) INTO v_suggested
    FROM (
      SELECT invoice_number, invoice_date, total_invoice_amount,
             final_labour_amount, final_spares_amount, account,
             tax_parts, invoice_status
        FROM public.psf_revenue_dms
       WHERE upper(btrim(job_card_number)) = upper(btrim(v_card.job_card_no))
         AND COALESCE(invoice_status, '') <> 'Cancelled'
       ORDER BY invoice_date DESC NULLS LAST, updated_at DESC NULLS LAST
       LIMIT 1
    ) x;

  IF v_suggested IS NOT NULL AND v_card.insurance_company IS NOT NULL THEN
    v_mismatch := position(
      lower(split_part(v_card.insurance_company, ' ', 1))
      IN lower(COALESCE(v_suggested ->> 'account', ''))
    ) = 0
    AND position(
      lower(split_part(COALESCE(v_suggested ->> 'account', ''), ' ', 1))
      IN lower(v_card.insurance_company)
    ) = 0;
  END IF;

  RETURN jsonb_build_object(
    'header', v_header,
    'lines', v_lines,
    'suggested_invoice', v_suggested,
    'payer_mismatch', v_mismatch,
    'card', jsonb_build_object(
      'id', v_card.id,
      'job_card_no', v_card.job_card_no,
      'insurance_company', v_card.insurance_company,
      'parts_entry_status', v_card.parts_entry_status,
      'billed_amount', v_card.billed_amount,
      'do_status', v_card.do_status,
      'do_amount', v_card.do_amount,
      'customer_diff_amount', v_card.customer_diff_amount,
      'payment_status', v_card.payment_status,
      'do_payment_status', v_card.do_payment_status,
      'customer_payment_status', v_card.customer_payment_status,
      'customer_settlement_kind', v_card.customer_settlement_kind
    )
  );
END;
$$;


--
-- Name: get_bodyshop_surveyor_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bodyshop_surveyor_options() RETURNS TABLE(id bigint, surveyor_name text, surveyor_contact_number text, surveyor_email text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.can_view_bodyshop_surveyor_catalog() THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (
      UPPER(BTRIM(COALESCE(s.surveyor_name, ''))),
      UPPER(BTRIM(COALESCE(s.surveyor_contact_number, '')))
    )
    s.id,
    s.surveyor_name,
    s.surveyor_contact_number,
    s.surveyor_email,
    s.created_at,
    s.updated_at
  FROM public.settings_bodyshop_surveyors s
  WHERE BTRIM(COALESCE(s.surveyor_name, '')) <> ''
    AND BTRIM(COALESCE(s.surveyor_contact_number, '')) <> ''
  ORDER BY
    UPPER(BTRIM(COALESCE(s.surveyor_name, ''))),
    UPPER(BTRIM(COALESCE(s.surveyor_contact_number, ''))),
    s.updated_at DESC,
    s.id DESC;
END;
$$;


