--
-- Name: get_complaint_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_complaint_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_link_id bigint;
  v_complaint_id bigint;
  v_entry_id bigint;
  v_status text;
  v_mode text;
  v_ticket jsonb;
  v_messages jsonb;
  v_activity jsonb;
  v_entry_summary jsonb;
BEGIN
  -- Find the link by token
  SELECT id, complaint_id, reception_entry_id, status
  INTO v_link_id, v_complaint_id, v_entry_id, v_status
  FROM public.complaint_access_links
  WHERE token = p_token;

  IF v_link_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired complaint link';
  END IF;

  -- Bump view count and last_viewed_at
  UPDATE public.complaint_access_links
  SET view_count = view_count + 1, last_viewed_at = now()
  WHERE id = v_link_id;

  -- Determine mode: 'raise' if no complaint yet, 'view' if raised
  IF v_complaint_id IS NULL THEN
    v_mode := 'raise';
  ELSE
    v_mode := 'view';
  END IF;

  -- Get entry summary from direct columns (authoritative schema)
  SELECT jsonb_build_object(
    'reception_entry_id', id,
    'reg_number', reg_number,
    'jc_number', jc_number,
    'model', model,
    'customer_name', owner_name,
    'service_type', service_type,
    'branch', branch
  ) INTO v_entry_summary
  FROM public.service_reception_entries
  WHERE id = v_entry_id;

  -- If in view mode, fetch the full ticket + messages + activity
  IF v_mode = 'view' THEN
    SELECT jsonb_build_object(
      'id', id,
      'ticket_number', ticket_number,
      'status', status,
      'priority', priority,
      'category', category,
      'title', title,
      'description', description,
      'severity_self', severity_self,
      'created_at', created_at,
      'response_due_at', response_due_at,
      'resolution_due_at', resolution_due_at,
      'first_response_at', first_response_at,
      'resolved_at', resolved_at,
      'csat_rating', csat_rating,
      'assigned_to_name', (SELECT full_name FROM public.users WHERE id = complaint_tickets.assigned_to),
      'sla_status', CASE
        WHEN now() > resolution_due_at AND status NOT IN ('resolved','closed') THEN 'breached'
        WHEN now() > response_due_at AND first_response_at IS NULL THEN 'warning'
        ELSE 'ok'
      END
    ) INTO v_ticket
    FROM public.complaint_tickets
    WHERE id = v_complaint_id;

    SELECT jsonb_agg(jsonb_build_object(
      'id', id,
      'author_type', author_type,
      'author_name', author_name,
      'body', body,
      'created_at', created_at
    ) ORDER BY created_at)
    INTO v_messages
    FROM public.complaint_messages
    WHERE complaint_id = v_complaint_id
      AND is_internal = false;

    SELECT jsonb_agg(jsonb_build_object(
      'event_type', event_type,
      'from_value', from_value,
      'to_value', to_value,
      'actor_name', actor_name,
      'created_at', created_at
    ) ORDER BY created_at)
    INTO v_activity
    FROM public.complaint_activity
    WHERE complaint_id = v_complaint_id;
  ELSE
    v_ticket := NULL;
    v_messages := NULL;
    v_activity := NULL;
  END IF;

  RETURN jsonb_build_object(
    'mode', v_mode,
    'link_token', p_token,
    'entry_summary', v_entry_summary,
    'ticket', v_ticket,
    'messages', v_messages,
    'activity', v_activity
  );
END;
$$;


--
-- Name: get_distinct_dealers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_distinct_dealers() RETURNS TABLE(sold_dealers text[], service_dealers text[])
    LANGUAGE sql SECURITY DEFINER
    AS $$
  SELECT
    array_remove(ARRAY(
      SELECT DISTINCT sold_dealer
      FROM all_service_data
      WHERE sold_dealer IS NOT NULL AND sold_dealer != ''
      ORDER BY sold_dealer
    ), NULL),
    array_remove(ARRAY(
      SELECT DISTINCT last_service_dealer
      FROM all_service_data
      WHERE last_service_dealer IS NOT NULL AND last_service_dealer != ''
      ORDER BY last_service_dealer
    ), NULL)
  ;
$$;


