    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    uel.employee_code,
    em.department,
    em.role,
    em.location,
    em.fuel_type
  FROM public.user_employee_links uel
