--

CREATE FUNCTION public.get_my_permissions(p_module text) RETURNS TABLE(can_view boolean, can_modify boolean, can_delete boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT p.can_view, p.can_modify, p.can_delete
  FROM public.user_module_permissions p
