-- Name: get_reception_by_jc_case_insensitive(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_reception_by_jc_case_insensitive(p_jc_numbers text[]) RETURNS TABLE(jc_number text, reg_number text)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.jc_number,
    s.reg_number
  FROM public.service_reception_entries s
  WHERE UPPER(BTRIM(COALESCE(s.jc_number, ''))) = ANY(
    SELECT UPPER(BTRIM(v)) FROM UNNEST(p_jc_numbers) AS t(v)
  );
END;
$$;


--
-- Name: get_reception_entries_by_ids(bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_reception_entries_by_ids(p_ids bigint[]) RETURNS TABLE(id bigint, model text, km_reading integer, dealer_code text, jc_number text, reg_number text, owner_name text, owner_phone text, branch text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    r.id,
    r.model,
    r.km_reading,
    r.dealer_code,
    r.jc_number,
    r.reg_number,
    r.owner_name,
    r.owner_phone,
    r.branch,
    r.created_at
    FROM public.service_reception_entries r
   WHERE r.id = ANY (p_ids)
     AND (
       public.is_admin()
       OR public.service_reception_entry_in_summary_scope(
         r.dealer_code,
         r.sa_employee_code,
         r.service_type
       )
     )
   ORDER BY r.id;
END;
$$;


