-- Name: get_unread_help_ticket_notification_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_help_ticket_notification_count() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::integer
  FROM public.help_ticket_notifications n
  WHERE n.channel = 'in_app'
    AND n.recipient_user_id = auth.uid()
    AND n.dismissed_at IS NULL
    AND n.read_at IS NULL;
$$;


--
-- Name: ggn_stock_status_for_part(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ggn_stock_status_for_part(p_part_number text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pn text := upper(replace(btrim(coalesce(p_part_number, '')), ' ', ''));
  v_qty numeric;
begin
  if v_pn = '' then
    return null;
  end if;

  select free_stock into v_qty
  from public.ggn_stock_data
  where part_number = v_pn;

  if not found then
    return null;
  end if;

  if v_qty > 0 then
    return 'Available';
  end if;

  return 'Not Available';
end;
$$;


--
-- Name: grant_active_module_to_admins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_active_module_to_admins() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_active = true THEN
    INSERT INTO public.user_module_permissions (
      user_id,
      module_id,
      can_view,
      can_modify,
      can_delete,
      granted_by,
      granted_at
    )
    SELECT
      u.id,
      NEW.id,
      true,
      true,
      true,
      NULL::uuid,
      now()
    FROM public.users u
    WHERE u.role = 'admin'
      AND u.is_active = true
    ON CONFLICT (user_id, module_id)
    DO UPDATE SET
      can_view = true,
      can_modify = true,
      can_delete = true,
      granted_at = now();
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: grant_admin_all_active_modules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_admin_all_active_modules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.role = 'admin' AND NEW.is_active = true THEN
    INSERT INTO public.user_module_permissions (
      user_id,
      module_id,
      can_view,
      can_modify,
      can_delete,
      granted_by,
      granted_at
    )
    SELECT
      NEW.id,
      m.id,
      true,
      true,
      true,
      NULL::uuid,
      now()
    FROM public.modules m
    WHERE m.is_active = true
    ON CONFLICT (user_id, module_id)
    DO UPDATE SET
      can_view = true,
      can_modify = true,
      can_delete = true,
      granted_at = now();
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO public.users (id, email, full_name)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email)
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: has_module_action(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_module_action(p_module text, p_action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE LOWER(p_action)
    WHEN 'view' THEN public.has_module_view(p_module)
    WHEN 'modify' THEN public.has_module_modify(p_module)
    WHEN 'delete' THEN public.has_module_delete(p_module)
    ELSE false
  END;
$$;


--
-- Name: FUNCTION has_module_action(p_module text, p_action text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_module_action(p_module text, p_action text) IS 'Unified action-based permission check.
   p_action: ''view'' | ''modify'' | ''delete''.
   Maps to corresponding has_module_view/modify/delete checks.';


--
-- Name: has_module_delete(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_module_delete(p_module text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT
    public.is_admin()
    OR EXISTS (
      SELECT 1
      FROM public.get_my_permissions(p_module) p
      WHERE COALESCE(p.can_delete, false) = true
    );
$$;


--
-- Name: has_module_modify(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_module_modify(p_module text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT
    public.is_admin()
    OR EXISTS (
      SELECT 1
      FROM public.get_my_permissions(p_module) p
      WHERE COALESCE(p.can_modify, false) = true
    );
$$;


--
-- Name: has_module_view(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_module_view(p_module text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT
    public.is_admin()
    OR EXISTS (
      SELECT 1
      FROM public.get_my_permissions(p_module) p
      WHERE COALESCE(p.can_view, false) = true
    );
$$;


