$$;


--
-- Name: help_ticket_assign(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_assign(p_ticket_id uuid, p_assignee_employee_code text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_ticket public.help_tickets%ROWTYPE;
  v_assignee record;
BEGIN
  PERFORM public.help_ticket_require_support_modify();
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;
  SELECT * INTO v_ticket FROM public.help_tickets WHERE id = p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  SELECT * INTO v_assignee
  FROM public.help_ticket_resolve_assignee(p_assignee_employee_code)
  LIMIT 1;

  UPDATE public.help_tickets SET
    assigned_to_employee_code = v_assignee.employee_code,
    assigned_to_name = v_assignee.employee_name,
    assigned_at = now(),
    assigned_by_employee_code = v_emp.employee_code,
    status = CASE WHEN status = 'new' THEN 'open' ELSE status END,
    updated_at = now()
  WHERE id = p_ticket_id;

  PERFORM public.help_ticket_write_audit(
    p_ticket_id, 'assigned', v_ticket.assigned_to_employee_code, v_assignee.employee_code, p_reason,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );

  PERFORM public.help_ticket_emit_notification(
    p_ticket_id, 'assigned', 'assignee', v_assignee.notify_user_id,
    jsonb_build_object('ticket_number', v_ticket.ticket_number, 'assigned_to_name', v_assignee.employee_name)
  );
  PERFORM public.help_ticket_emit_notification(
    p_ticket_id, 'assigned', 'raiser', v_ticket.raised_by_user_id,
    jsonb_build_object('ticket_number', v_ticket.ticket_number, 'assigned_to_name', v_assignee.employee_name)
  );

  RETURN jsonb_build_object('success', true, 'assigned_to_employee_code', v_assignee.employee_code);
END;
$$;


--
-- Name: help_ticket_attachment_create(uuid, text, integer, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_attachment_create(p_ticket_id uuid, p_original_filename text, p_file_size_bytes integer, p_file_type text DEFAULT NULL::text, p_message_id uuid DEFAULT NULL::uuid, p_storage_staging_path text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_id uuid;
BEGIN
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;

  IF NOT public.help_ticket_can_see(p_ticket_id) THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;
  IF NULLIF(btrim(p_original_filename), '') IS NULL THEN
    RAISE EXCEPTION 'Filename is required';
  END IF;
  IF p_file_size_bytes IS NULL OR p_file_size_bytes <= 0 OR p_file_size_bytes > 26214400 THEN
    RAISE EXCEPTION 'Invalid file size';
  END IF;

  INSERT INTO public.help_ticket_attachments (
    ticket_id, message_id,
    uploaded_by_user_id, uploaded_by_employee_code, uploaded_by_name,
    original_filename, file_size_bytes, file_type, storage_staging_path, status
  ) VALUES (
    p_ticket_id, p_message_id,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name,
    btrim(p_original_filename), p_file_size_bytes, p_file_type, p_storage_staging_path, 'uploading'
  )
  RETURNING id INTO v_id;

  PERFORM public.help_ticket_write_audit(
    p_ticket_id, 'attachment_added', NULL, v_id::text, NULL,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );

  RETURN jsonb_build_object('id', v_id, 'status', 'uploading');
END;
$$;


--
-- Name: help_ticket_attachment_mark_failed(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_attachment_mark_failed(p_attachment_id uuid, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_att public.help_ticket_attachments%ROWTYPE;
BEGIN
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;
  SELECT * INTO v_att FROM public.help_ticket_attachments WHERE id = p_attachment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Attachment not found';
  END IF;
  IF v_att.uploaded_by_user_id <> v_emp.user_id
     AND NOT (public.is_admin() OR public.has_module_modify('help_tickets')) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  UPDATE public.help_ticket_attachments SET
    status = 'upload_failed',
    error_message = left(COALESCE(p_error, 'upload failed'), 1000)
  WHERE id = p_attachment_id;

  RETURN jsonb_build_object('id', p_attachment_id, 'status', 'upload_failed');
END;
$$;


--
-- Name: help_ticket_calculate_sla_targets(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_calculate_sla_targets(p_category_id uuid, p_priority text) RETURNS TABLE(response_minutes integer, resolution_minutes integer, response_at timestamp with time zone, resolution_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_resp integer;
  v_res integer;
  v_mult numeric := 1;
BEGIN
  SELECT c.sla_response_minutes, c.sla_resolution_minutes
    INTO v_resp, v_res
  FROM public.help_ticket_categories c
  WHERE c.id = p_category_id;

  v_resp := COALESCE(v_resp, 240);
  v_res := COALESCE(v_res, 1440);

  IF p_priority = 'urgent' THEN
    v_mult := 0.5;
  ELSIF p_priority = 'high' THEN
    v_mult := 0.75;
  ELSIF p_priority = 'low' THEN
    v_mult := 1.5;
  END IF;

  v_resp := GREATEST(15, ceil(v_resp * v_mult)::integer);
  v_res := GREATEST(30, ceil(v_res * v_mult)::integer);

  RETURN QUERY SELECT
    v_resp,
    v_res,
    now() + make_interval(mins => v_resp),
    now() + make_interval(mins => v_res);
END;
$$;


--
-- Name: help_ticket_can_see(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_can_see(p_ticket_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_code text := public.my_employee_code();
  v_raiser text;
  v_assignee text;
BEGIN
  -- Org-wide support view / admin — NO dealer_code check
  IF public.is_admin() OR public.has_module_view('help_tickets') THEN
    RETURN true;
  END IF;

  IF v_code IS NULL THEN
    RETURN false;
  END IF;

  SELECT t.raised_by_employee_code, t.assigned_to_employee_code
    INTO v_raiser, v_assignee
  FROM public.help_tickets t
  WHERE t.id = p_ticket_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  RETURN v_code = v_raiser OR v_code = v_assignee;
END;
$$;


--
-- Name: help_ticket_create(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_create(p_category_key text, p_subject text, p_description text, p_priority text DEFAULT NULL::text, p_severity text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_cat public.help_ticket_categories%ROWTYPE;
  v_priority text;
  v_severity text;
  v_sla record;
  v_id uuid;
  v_number text;
BEGIN
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;

  IF NULLIF(btrim(p_subject), '') IS NULL OR NULLIF(btrim(p_description), '') IS NULL THEN
    RAISE EXCEPTION 'Subject and description are required';
  END IF;

  SELECT * INTO v_cat
  FROM public.help_ticket_categories
  WHERE key = btrim(p_category_key) AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid category';
  END IF;

  v_priority := COALESCE(NULLIF(btrim(p_priority), ''), v_cat.default_priority, 'normal');
  IF v_priority NOT IN ('low','normal','high','urgent') THEN
    RAISE EXCEPTION 'Invalid priority';
  END IF;

  v_severity := COALESCE(NULLIF(btrim(p_severity), ''), 'minor');
  IF v_severity NOT IN ('cosmetic','minor','major','critical') THEN
    RAISE EXCEPTION 'Invalid severity';
  END IF;

  SELECT * INTO v_sla
  FROM public.help_ticket_calculate_sla_targets(v_cat.id, v_priority);

  v_number := public.help_ticket_next_number();

  INSERT INTO public.help_tickets (
    ticket_number, raiser_dealer_code,
    raised_by_user_id, raised_by_employee_code, raised_by_name, raised_by_email, raised_by_department,
    category_id, category_key, subject, description,
    status, priority, severity,
    sla_response_target_minutes, sla_resolution_target_minutes,
    sla_response_at, sla_resolution_at
  ) VALUES (
    v_number, v_emp.raiser_dealer_code,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name, v_emp.email, v_emp.department,
    v_cat.id, v_cat.key, btrim(p_subject), btrim(p_description),
    'new', v_priority, v_severity,
    v_sla.response_minutes, v_sla.resolution_minutes,
    v_sla.response_at, v_sla.resolution_at
  )
  RETURNING id INTO v_id;

  PERFORM public.help_ticket_write_audit(
    v_id, 'created', NULL, 'new', NULL,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );

  PERFORM public.help_ticket_notify_support_holders(
    v_id,
    'raised',
    jsonb_build_object(
      'ticket_number', v_number,
      'subject', btrim(p_subject),
      'category_key', v_cat.key,
      'raised_by_name', v_emp.employee_name
    )
  );

  RETURN jsonb_build_object(
    'id', v_id,
    'ticket_number', v_number,
    'status', 'new'
  );
END;
$$;


--
-- Name: help_ticket_emit_notification(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_emit_notification(p_ticket_id uuid, p_event_type text, p_recipient_type text, p_recipient_user_id uuid, p_payload jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_recipient_user_id IS NULL THEN
    RETURN;
  END IF;
  INSERT INTO public.help_ticket_notifications (
    ticket_id, event_type, recipient_type, recipient_user_id,
    channel, status, payload, sent_at
  ) VALUES (
    p_ticket_id, p_event_type, p_recipient_type, p_recipient_user_id,
    'in_app', 'sent', p_payload, now()
  );
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'help_ticket_notifications outbox write skipped: %', SQLERRM;
END;
$$;


--
-- Name: help_ticket_escalate(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_escalate(p_ticket_id uuid, p_escalate_to_employee_code text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_ticket public.help_tickets%ROWTYPE;
  v_target record;
BEGIN
  PERFORM public.help_ticket_require_support_modify();
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;
  SELECT * INTO v_ticket FROM public.help_tickets WHERE id = p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  SELECT * INTO v_target
  FROM public.help_ticket_resolve_assignee(p_escalate_to_employee_code)
  LIMIT 1;

  UPDATE public.help_tickets SET
    status = 'escalated',
    is_escalated = true,
    escalated_to_employee_code = v_target.employee_code,
    escalated_at = now(),
    escalation_reason = NULLIF(btrim(p_reason), ''),
    assigned_to_employee_code = v_target.employee_code,
    assigned_to_name = v_target.employee_name,
    assigned_at = now(),
    assigned_by_employee_code = v_emp.employee_code,
    updated_at = now()
  WHERE id = p_ticket_id;

  PERFORM public.help_ticket_write_audit(
    p_ticket_id, 'escalated', v_ticket.assigned_to_employee_code, v_target.employee_code, p_reason,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );

  PERFORM public.help_ticket_emit_notification(
    p_ticket_id, 'escalated', 'assignee', v_target.notify_user_id,
    jsonb_build_object('ticket_number', v_ticket.ticket_number)
  );
  PERFORM public.help_ticket_emit_notification(
    p_ticket_id, 'escalated', 'raiser', v_ticket.raised_by_user_id,
    jsonb_build_object('ticket_number', v_ticket.ticket_number)
  );

  RETURN jsonb_build_object('success', true, 'status', 'escalated');
END;
$$;


--
-- Name: help_ticket_audit_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.help_ticket_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    action_type text NOT NULL,
    changed_by_user_id uuid,
    changed_by_employee_code text,
    changed_by_name text,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    old_value text,
    new_value text,
    reason text
);


--
-- Name: help_ticket_get_audit_log(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_get_audit_log(p_ticket_id uuid) RETURNS SETOF public.help_ticket_audit_log
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.help_ticket_require_support_view();
  IF NOT EXISTS (SELECT 1 FROM public.help_tickets WHERE id = p_ticket_id) THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  RETURN QUERY
  SELECT a.*
  FROM public.help_ticket_audit_log a
  WHERE a.ticket_id = p_ticket_id
  ORDER BY a.changed_at DESC;
END;
$$;


--
-- Name: help_ticket_get_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_get_detail(p_ticket_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_ticket public.help_tickets%ROWTYPE;
  v_is_support boolean;
  v_messages jsonb;
  v_attachments jsonb;
BEGIN
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;

  IF NOT public.help_ticket_can_see(p_ticket_id) THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  SELECT * INTO v_ticket FROM public.help_tickets WHERE id = p_ticket_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  v_is_support := public.is_admin() OR public.has_module_view('help_tickets');

  SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.sequence_number ASC), '[]'::jsonb)
    INTO v_messages
  FROM public.help_ticket_messages m
  WHERE m.ticket_id = p_ticket_id
    AND (v_is_support OR m.visibility = 'public');

  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.uploaded_at ASC), '[]'::jsonb)
    INTO v_attachments
  FROM public.help_ticket_attachments a
  WHERE a.ticket_id = p_ticket_id;

  RETURN jsonb_build_object(
    'ticket', to_jsonb(v_ticket),
    'messages', v_messages,
    'attachments', v_attachments,
    'viewer', jsonb_build_object(
      'employee_code', v_emp.employee_code,
      'is_raiser', v_emp.employee_code = v_ticket.raised_by_employee_code,
      'is_support', v_is_support,
      'can_modify', public.is_admin() OR public.has_module_modify('help_tickets')
    )
  );
END;
$$;


--
-- Name: help_ticket_hold(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_hold(p_ticket_id uuid, p_hold_reason text, p_detail text DEFAULT NULL::text, p_expected_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_ticket public.help_tickets%ROWTYPE;
BEGIN
  PERFORM public.help_ticket_require_support_modify();
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;
  SELECT * INTO v_ticket FROM public.help_tickets WHERE id = p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  UPDATE public.help_tickets SET
    status = 'on_hold',
    sla_paused = true,
    hold_reason = NULLIF(btrim(p_hold_reason), ''),
    hold_reason_detail = NULLIF(btrim(p_detail), ''),
    held_at = now(),
    due_date = COALESCE(p_expected_date, due_date),
    updated_at = now()
  WHERE id = p_ticket_id;

  PERFORM public.help_ticket_write_audit(
    p_ticket_id, 'held', v_ticket.status, 'on_hold', p_hold_reason,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );
  PERFORM public.help_ticket_emit_notification(
    p_ticket_id, 'held', 'raiser', v_ticket.raised_by_user_id,
    jsonb_build_object('ticket_number', v_ticket.ticket_number)
  );

  RETURN jsonb_build_object('success', true, 'status', 'on_hold');
END;
$$;


--
-- Name: help_tickets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.help_tickets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_number text NOT NULL,
    raiser_dealer_code text,
    raised_by_user_id uuid NOT NULL,
    raised_by_employee_code text NOT NULL,
    raised_by_name text NOT NULL,
    raised_by_email text,
    raised_by_department text,
    category_id uuid NOT NULL,
    category_key text NOT NULL,
    subject text NOT NULL,
    description text NOT NULL,
    status text DEFAULT 'new'::text NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    severity text DEFAULT 'minor'::text NOT NULL,
    assigned_to_employee_code text,
    assigned_to_name text,
    assigned_at timestamp with time zone,
    assigned_by_employee_code text,
    due_date timestamp with time zone,
    sla_response_target_minutes integer,
    sla_resolution_target_minutes integer,
    sla_response_at timestamp with time zone,
    sla_resolution_at timestamp with time zone,
    sla_paused boolean DEFAULT false NOT NULL,
    first_response_at timestamp with time zone,
    resolved_at timestamp with time zone,
    verification_status text DEFAULT 'pending'::text NOT NULL,
    verified_at timestamp with time zone,
    verified_by_employee_code text,
    closed_at timestamp with time zone,
    closure_reason text,
    is_escalated boolean DEFAULT false NOT NULL,
    escalated_to_employee_code text,
    escalated_at timestamp with time zone,
    escalation_reason text,
    hold_reason text,
    hold_reason_detail text,
    held_at timestamp with time zone,
    reopen_count integer DEFAULT 0 NOT NULL,
    last_reopened_at timestamp with time zone,
    last_reopened_by_employee_code text,
    is_duplicate boolean DEFAULT false NOT NULL,
    duplicate_of_ticket_id uuid,
    tags text[] DEFAULT ARRAY[]::text[] NOT NULL,
    internal_notes text,
    resolution_notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sla_response_breached_at timestamp with time zone,
    sla_resolution_breached_at timestamp with time zone,
    CONSTRAINT help_tickets_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT help_tickets_severity_check CHECK ((severity = ANY (ARRAY['cosmetic'::text, 'minor'::text, 'major'::text, 'critical'::text]))),
    CONSTRAINT help_tickets_status_check CHECK ((status = ANY (ARRAY['new'::text, 'open'::text, 'in_progress'::text, 'waiting_raiser'::text, 'on_hold'::text, 'escalated'::text, 'resolved'::text, 'cannot_reproduce'::text, 'closed'::text, 'reopened'::text]))),
    CONSTRAINT help_tickets_verification_status_check CHECK ((verification_status = ANY (ARRAY['pending'::text, 'verified'::text, 'rejected'::text, 'auto_closed'::text])))
);


--
-- Name: COLUMN help_tickets.raiser_dealer_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.help_tickets.raiser_dealer_code IS 'Optional snapshot of raiser dealer at create time for display/reporting. Not an ACL or visibility predicate.';


--
-- Name: COLUMN help_tickets.sla_response_breached_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.help_tickets.sla_response_breached_at IS 'Set once when response SLA is breached (first support reply overdue).';


--
-- Name: COLUMN help_tickets.sla_resolution_breached_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.help_tickets.sla_resolution_breached_at IS 'Set once when resolution SLA is breached (ticket still open past target).';


--
-- Name: help_ticket_list_admin(text[], text, text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_list_admin(p_status text[] DEFAULT NULL::text[], p_assignee_employee_code text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_category_key text DEFAULT NULL::text, p_raiser_dealer_code text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF public.help_tickets
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
BEGIN
  PERFORM public.help_ticket_require_support_view();
  -- Optional raiser_dealer_code is a DISPLAY filter only, not a security gate.

  RETURN QUERY
  SELECT t.*
  FROM public.help_tickets t
  WHERE (p_status IS NULL OR t.status = ANY (p_status))
    AND (p_assignee_employee_code IS NULL OR t.assigned_to_employee_code = p_assignee_employee_code)
    AND (p_priority IS NULL OR t.priority = p_priority)
    AND (p_category_key IS NULL OR t.category_key = p_category_key)
    AND (p_raiser_dealer_code IS NULL OR t.raiser_dealer_code = p_raiser_dealer_code)
    AND (p_cursor IS NULL OR t.created_at < p_cursor)
  ORDER BY t.created_at DESC
  LIMIT v_limit;
END;
$$;


--
-- Name: help_ticket_list_assigned_to_me(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_list_assigned_to_me(p_limit integer DEFAULT 50) RETURNS SETOF public.help_tickets
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
BEGIN
  PERFORM public.help_ticket_require_support_view();
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;

  RETURN QUERY
  SELECT t.*
  FROM public.help_tickets t
  WHERE t.assigned_to_employee_code = v_emp.employee_code
    AND t.status <> 'closed'
  ORDER BY t.created_at DESC
  LIMIT v_limit;
END;
$$;


--
-- Name: help_ticket_list_assignees(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_list_assignees(p_search text DEFAULT NULL::text) RETURNS TABLE(employee_code text, employee_name text, department text, role text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_q text := NULLIF(btrim(COALESCE(p_search, '')), '');
BEGIN
  PERFORM public.help_ticket_require_support_modify();

  RETURN QUERY
  WITH eligible AS (
    -- Module edit holders (linked employees)
    SELECT DISTINCT
      em.employee_code,
      em.employee_name,
      em.department,
      em.role
    FROM public.employee_master em
    JOIN public.user_employee_links uel
      ON uel.employee_code = em.employee_code
     AND uel.is_active = true
    JOIN public.users u
      ON u.id = uel.user_id
     AND COALESCE(u.is_active, true) = true
    WHERE EXISTS (
      SELECT 1
      FROM public.user_module_permissions ump
      JOIN public.modules m ON m.id = ump.module_id
      WHERE ump.user_id = u.id
        AND m.name = 'help_tickets'
        AND COALESCE(ump.can_modify, false) = true
    )

    UNION

    -- Admins: linked employee code when present, else synthetic ADMIN:{uuid}
    SELECT DISTINCT
      COALESCE(
        (
          SELECT uel.employee_code
          FROM public.user_employee_links uel
          WHERE uel.user_id = u.id
            AND uel.is_active = true
          ORDER BY uel.is_primary DESC NULLS LAST, uel.updated_at DESC NULLS LAST
          LIMIT 1
        ),
        public.help_ticket_admin_identity_code(u.id)
      ) AS employee_code,
      COALESCE(
        (
          SELECT NULLIF(btrim(em.employee_name), '')
          FROM public.user_employee_links uel
          JOIN public.employee_master em ON em.employee_code = uel.employee_code
          WHERE uel.user_id = u.id
            AND uel.is_active = true
          ORDER BY uel.is_primary DESC NULLS LAST, uel.updated_at DESC NULLS LAST
          LIMIT 1
        ),
        NULLIF(btrim(u.full_name), ''),
        NULLIF(btrim(u.email), ''),
        'Admin'
      ) AS employee_name,
      (
        SELECT em.department
        FROM public.user_employee_links uel
        JOIN public.employee_master em ON em.employee_code = uel.employee_code
        WHERE uel.user_id = u.id
          AND uel.is_active = true
        ORDER BY uel.is_primary DESC NULLS LAST, uel.updated_at DESC NULLS LAST
        LIMIT 1
      ) AS department,
      u.role
    FROM public.users u
    WHERE COALESCE(u.is_active, true) = true
      AND u.role = ANY (ARRAY['admin'::text, 'super_admin'::text])
  )
  SELECT e.employee_code, e.employee_name, e.department, e.role
  FROM eligible e
  WHERE v_q IS NULL
     OR e.employee_code ILIKE '%' || v_q || '%'
     OR e.employee_name ILIKE '%' || v_q || '%'
  ORDER BY e.employee_name
  LIMIT 100;
END;
$$;


--
-- Name: FUNCTION help_ticket_list_assignees(p_search text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.help_ticket_list_assignees(p_search text) IS 'Assignee picker: help_tickets can_modify holders (linked) UNION all active admins (synthetic ADMIN: identity when unlinked).';


