--
-- Name: help_ticket_list_mine(text[], integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_list_mine(p_status text[] DEFAULT NULL::text[], p_limit integer DEFAULT 50, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF public.help_tickets
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
BEGIN
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;

  RETURN QUERY
  SELECT t.*
  FROM public.help_tickets t
  WHERE t.raised_by_employee_code = v_emp.employee_code
    AND (p_status IS NULL OR t.status = ANY (p_status))
    AND (p_cursor IS NULL OR t.created_at < p_cursor)
  ORDER BY t.created_at DESC
  LIMIT v_limit;
END;
$$;


--
-- Name: help_ticket_mark_duplicate(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_mark_duplicate(p_ticket_id uuid, p_duplicate_of_ticket_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
BEGIN
  PERFORM public.help_ticket_require_support_modify();
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;

  IF NOT EXISTS (SELECT 1 FROM public.help_tickets WHERE id = p_ticket_id) THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.help_tickets WHERE id = p_duplicate_of_ticket_id) THEN
    RAISE EXCEPTION 'Original ticket not found';
  END IF;
  IF p_ticket_id = p_duplicate_of_ticket_id THEN
    RAISE EXCEPTION 'Cannot mark ticket as duplicate of itself';
  END IF;

  UPDATE public.help_tickets SET
    is_duplicate = true,
    duplicate_of_ticket_id = p_duplicate_of_ticket_id,
    status = 'closed',
    verification_status = 'auto_closed',
    closed_at = now(),
    closure_reason = COALESCE(NULLIF(btrim(p_reason), ''), 'duplicate'),
    updated_at = now()
  WHERE id = p_ticket_id;

  PERFORM public.help_ticket_write_audit(
    p_ticket_id, 'closed', NULL, p_duplicate_of_ticket_id::text, p_reason,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );

  RETURN jsonb_build_object('success', true, 'duplicate_of_ticket_id', p_duplicate_of_ticket_id);
END;
$$;


--
-- Name: help_ticket_next_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_next_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_n bigint;
BEGIN
  v_n := nextval('public.help_ticket_number_seq');
  RETURN 'HT-' || lpad(v_n::text, 6, '0');
END;
$$;


--
-- Name: help_ticket_next_sequence_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_next_sequence_number(p_ticket_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_next bigint;
BEGIN
  PERFORM 1 FROM public.help_tickets WHERE id = p_ticket_id FOR UPDATE;
  SELECT COALESCE(MAX(m.sequence_number), 0) + 1
    INTO v_next
  FROM public.help_ticket_messages m
  WHERE m.ticket_id = p_ticket_id;
  RETURN v_next;
END;
$$;


--
-- Name: help_ticket_notify_support_holders(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_notify_support_holders(p_ticket_id uuid, p_event_type text, p_payload jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  -- Org-wide: all users with help_tickets view or modify (+ admins). No dealer filter.
  FOR r IN
    SELECT DISTINCT u.id AS uid
    FROM public.users u
    WHERE u.is_active = true
      AND (
        u.role = 'admin'
        OR EXISTS (
          SELECT 1
          FROM public.user_module_permissions ump
          JOIN public.modules m ON m.id = ump.module_id
          WHERE ump.user_id = u.id
            AND m.name = 'help_tickets'
            AND (COALESCE(ump.can_view, false) OR COALESCE(ump.can_modify, false))
        )
      )
  LOOP
    PERFORM public.help_ticket_emit_notification(
      p_ticket_id,
      p_event_type,
      CASE WHEN EXISTS (
        SELECT 1 FROM public.users au WHERE au.id = r.uid AND au.role = 'admin'
      ) THEN 'admin' ELSE 'support' END,
      r.uid,
      p_payload
    );
  END LOOP;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'help_ticket_notify_support_holders skipped: %', SQLERRM;
END;
$$;


--
-- Name: help_ticket_require_employee(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_require_employee() RETURNS TABLE(user_id uuid, employee_code text, employee_name text, email text, department text, raiser_dealer_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_code text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_code := public.my_employee_code();

  IF v_code IS NOT NULL AND btrim(v_code) <> '' THEN
    RETURN QUERY
    SELECT
      v_uid,
      v_code,
      COALESCE(NULLIF(btrim(em.employee_name), ''), NULLIF(btrim(u.full_name), ''), v_code),
      u.email,
      em.department,
      uel.dealer_code
    FROM public.users u
    LEFT JOIN public.user_employee_links uel
      ON uel.user_id = u.id
     AND uel.employee_code = v_code
     AND uel.is_active = true
     AND uel.is_primary = true
    LEFT JOIN public.employee_master em
      ON em.employee_code = v_code
    WHERE u.id = v_uid
    LIMIT 1;
    RETURN;
  END IF;

  -- Admins (and super_admin via is_admin) may use Get Help without employee_master link
  IF public.is_admin() THEN
    RETURN QUERY
    SELECT
      v_uid,
      ('ADMIN:' || replace(v_uid::text, '-', '')),
      COALESCE(NULLIF(btrim(u.full_name), ''), NULLIF(btrim(u.email), ''), 'Admin'),
      u.email,
      NULL::text,
      NULL::text
    FROM public.users u
    WHERE u.id = v_uid
    LIMIT 1;
    RETURN;
  END IF;

  RAISE EXCEPTION 'Employee link required';
END;
$$;


--
-- Name: help_ticket_require_support_modify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_require_support_modify() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
