--
-- Name: help_ticket_resolve_assignee(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_resolve_assignee(p_code text) RETURNS TABLE(employee_code text, employee_name text, notify_user_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_code text := btrim(COALESCE(p_code, ''));
  v_admin_uid uuid;
  v_name text;
  v_uid uuid;
BEGIN
  IF v_code = '' THEN
    RAISE EXCEPTION 'Assignee is required';
  END IF;

  -- Synthetic admin identity (no employee_master required)
  IF v_code LIKE 'ADMIN:%' THEN
    v_admin_uid := public.help_ticket_user_id_from_admin_identity(v_code);
    IF v_admin_uid IS NULL THEN
      RAISE EXCEPTION 'Assignee not found';
    END IF;
    SELECT
      COALESCE(NULLIF(btrim(u.full_name), ''), NULLIF(btrim(u.email), ''), 'Admin'),
      u.id
      INTO v_name, v_uid
    FROM public.users u
    WHERE u.id = v_admin_uid
      AND COALESCE(u.is_active, true) = true
      AND u.role = ANY (ARRAY['admin'::text, 'super_admin'::text]);
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'Assignee not found';
    END IF;
    employee_code := v_code;
    employee_name := v_name;
    notify_user_id := v_uid;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT em.employee_name INTO v_name
  FROM public.employee_master em
  WHERE em.employee_code = v_code;

  IF v_name IS NULL THEN
    RAISE EXCEPTION 'Assignee not found';
  END IF;

  v_uid := public.help_ticket_user_id_for_employee(v_code);

  employee_code := v_code;
  employee_name := v_name;
  notify_user_id := v_uid;
  RETURN NEXT;
END;
$$;


--
-- Name: help_ticket_send_message(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_send_message(p_ticket_id uuid, p_message_text text, p_visibility text DEFAULT 'public'::text, p_parent_message_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_ticket public.help_tickets%ROWTYPE;
  v_is_support_modify boolean;
  v_is_raiser boolean;
  v_vis text;
  v_type text;
  v_role text;
  v_seq bigint;
  v_msg_id uuid;
  v_notify_uid uuid;
BEGIN
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;

  IF NOT public.help_ticket_can_see(p_ticket_id) THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  SELECT * INTO v_ticket FROM public.help_tickets WHERE id = p_ticket_id FOR UPDATE;
  IF v_ticket.status = 'closed' THEN
    RAISE EXCEPTION 'Ticket is closed';
  END IF;

  IF NULLIF(btrim(p_message_text), '') IS NULL THEN
    RAISE EXCEPTION 'Message text is required';
  END IF;

  v_is_support_modify := public.is_admin() OR public.has_module_modify('help_tickets');
  v_is_raiser := v_emp.employee_code = v_ticket.raised_by_employee_code;
  v_vis := COALESCE(NULLIF(btrim(p_visibility), ''), 'public');

  IF v_vis = 'internal' THEN
    IF NOT v_is_support_modify THEN
      RAISE EXCEPTION 'Insufficient permissions for internal notes';
    END IF;
    v_type := 'internal_note';
    v_role := 'support';
  ELSE
    IF NOT (v_is_raiser OR v_is_support_modify OR v_emp.employee_code = v_ticket.assigned_to_employee_code) THEN
      RAISE EXCEPTION 'Insufficient permissions';
    END IF;
    v_vis := 'public';
    v_type := 'user_comment';
    v_role := CASE
      WHEN v_is_support_modify THEN 'support'
      WHEN v_is_raiser THEN 'raiser'
      ELSE 'assignee'
    END;
  END IF;

  v_seq := public.help_ticket_next_sequence_number(p_ticket_id);

  INSERT INTO public.help_ticket_messages (
    ticket_id, created_by_user_id, created_by_employee_code, created_by_name,
    created_by_role, message_text, message_type, visibility, parent_message_id, sequence_number
  ) VALUES (
    p_ticket_id, v_emp.user_id, v_emp.employee_code, v_emp.employee_name,
    v_role, btrim(p_message_text), v_type, v_vis, p_parent_message_id, v_seq
  )
  RETURNING id INTO v_msg_id;

  -- First support public message: new → open; waiting_raiser → in_progress
  IF v_is_support_modify AND v_vis = 'public' THEN
    UPDATE public.help_tickets t SET
      status = CASE
        WHEN t.status = 'waiting_raiser' THEN 'in_progress'
        WHEN t.status = 'new' THEN 'open'
        ELSE t.status
      END,
      first_response_at = COALESCE(t.first_response_at, now()),
      sla_paused = CASE WHEN t.status = 'waiting_raiser' THEN false ELSE t.sla_paused END,
      updated_at = now()
    WHERE t.id = p_ticket_id;
  END IF;

  -- Raiser reply while waiting_raiser → in_progress
  IF v_is_raiser AND v_ticket.status = 'waiting_raiser' THEN
    UPDATE public.help_tickets SET
      status = 'in_progress',
      sla_paused = false,
      updated_at = now()
    WHERE id = p_ticket_id;
  END IF;

  UPDATE public.help_tickets SET updated_at = now() WHERE id = p_ticket_id;

  PERFORM public.help_ticket_write_audit(
    p_ticket_id, 'message_added', NULL, v_vis, NULL,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );

  IF v_vis = 'public' THEN
    IF v_is_raiser THEN
      IF v_ticket.assigned_to_employee_code IS NOT NULL THEN
        v_notify_uid := public.help_ticket_user_id_for_employee(v_ticket.assigned_to_employee_code);
        PERFORM public.help_ticket_emit_notification(
          p_ticket_id, 'message_added', 'assignee', v_notify_uid,
          jsonb_build_object('ticket_number', v_ticket.ticket_number)
        );
      ELSE
        PERFORM public.help_ticket_notify_support_holders(
          p_ticket_id, 'message_added',
          jsonb_build_object('ticket_number', v_ticket.ticket_number)
        );
      END IF;
    ELSE
      PERFORM public.help_ticket_emit_notification(
        p_ticket_id, 'message_added', 'raiser', v_ticket.raised_by_user_id,
        jsonb_build_object('ticket_number', v_ticket.ticket_number)
      );
    END IF;
  END IF;

  RETURN jsonb_build_object('message_id', v_msg_id, 'sequence_number', v_seq);
END;
$$;


--
-- Name: help_ticket_update_priority(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_update_priority(p_ticket_id uuid, p_priority text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_ticket public.help_tickets%ROWTYPE;
  v_pri text := btrim(p_priority);
BEGIN
  PERFORM public.help_ticket_require_support_modify();
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;
  SELECT * INTO v_ticket FROM public.help_tickets WHERE id = p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;
  IF v_pri NOT IN ('low','normal','high','urgent') THEN
    RAISE EXCEPTION 'Invalid priority';
  END IF;

  UPDATE public.help_tickets SET priority = v_pri, updated_at = now() WHERE id = p_ticket_id;

  PERFORM public.help_ticket_write_audit(
    p_ticket_id, 'priority_changed', v_ticket.priority, v_pri, p_reason,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );

  RETURN jsonb_build_object('success', true, 'priority', v_pri);
END;
$$;


--
-- Name: help_ticket_update_status(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_update_status(p_ticket_id uuid, p_new_status text, p_reason text DEFAULT NULL::text, p_resolution_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_ticket public.help_tickets%ROWTYPE;
  v_new text := btrim(p_new_status);
BEGIN
  PERFORM public.help_ticket_require_support_modify();
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;
  SELECT * INTO v_ticket FROM public.help_tickets WHERE id = p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  IF v_new NOT IN (
    'open','in_progress','waiting_raiser','on_hold','escalated',
    'resolved','cannot_reproduce','closed','reopened'
  ) THEN
    RAISE EXCEPTION 'Invalid status';
  END IF;

  -- Raiser verification gate: support cannot force closed unless already verified/auto
  IF v_new = 'closed' AND v_ticket.verification_status NOT IN ('verified', 'auto_closed')
     AND v_ticket.status <> 'cannot_reproduce' THEN
    RAISE EXCEPTION 'Cannot close until raiser verifies (or use cannot_reproduce flow)';
  END IF;

  UPDATE public.help_tickets SET
    status = v_new,
    sla_paused = (v_new IN ('waiting_raiser', 'on_hold')),
    resolved_at = CASE WHEN v_new = 'resolved' THEN now()
                       WHEN v_new IN ('reopened', 'in_progress', 'open') THEN NULL
                       ELSE resolved_at END,
    verification_status = CASE
      WHEN v_new = 'resolved' THEN 'pending'
      WHEN v_new = 'closed' AND verification_status = 'pending' THEN verification_status
      ELSE verification_status
    END,
    resolution_notes = COALESCE(NULLIF(btrim(p_resolution_notes), ''), resolution_notes),
    closed_at = CASE WHEN v_new = 'closed' THEN COALESCE(closed_at, now()) ELSE closed_at END,
    updated_at = now()
  WHERE id = p_ticket_id;

  PERFORM public.help_ticket_write_audit(
    p_ticket_id, 'status_changed', v_ticket.status, v_new, p_reason,
    v_emp.user_id, v_emp.employee_code, v_emp.employee_name
  );

  IF v_new = 'resolved' THEN
    PERFORM public.help_ticket_emit_notification(
      p_ticket_id, 'resolved', 'raiser', v_ticket.raised_by_user_id,
      jsonb_build_object('ticket_number', v_ticket.ticket_number)
    );
  ELSE
    PERFORM public.help_ticket_emit_notification(
      p_ticket_id, 'status_changed', 'raiser', v_ticket.raised_by_user_id,
      jsonb_build_object('ticket_number', v_ticket.ticket_number, 'status', v_new)
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'status', v_new);
END;
$$;


--
-- Name: help_ticket_user_id_for_employee(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_user_id_for_employee(p_employee_code text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT uel.user_id
  FROM public.user_employee_links uel
  WHERE uel.employee_code = p_employee_code
    AND uel.is_active = true
  ORDER BY uel.is_primary DESC, uel.updated_at DESC
  LIMIT 1;
$$;


--
-- Name: help_ticket_user_id_from_admin_identity(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_user_id_from_admin_identity(p_code text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  v_hex text;
BEGIN
  IF p_code IS NULL OR p_code NOT LIKE 'ADMIN:%' THEN
    RETURN NULL;
  END IF;
  v_hex := substr(btrim(p_code), 7);
  IF length(v_hex) <> 32 OR v_hex !~ '^[0-9a-fA-F]+$' THEN
    RETURN NULL;
  END IF;
  RETURN (
    substr(v_hex, 1, 8) || '-' ||
    substr(v_hex, 9, 4) || '-' ||
    substr(v_hex, 13, 4) || '-' ||
    substr(v_hex, 17, 4) || '-' ||
    substr(v_hex, 21, 12)
  )::uuid;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$_$;


--
-- Name: help_ticket_verify_resolution(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_verify_resolution(p_ticket_id uuid, p_verified boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp record;
  v_ticket public.help_tickets%ROWTYPE;
  v_new_status text;
BEGIN
  SELECT * INTO v_emp FROM public.help_ticket_require_employee() LIMIT 1;
  SELECT * INTO v_ticket FROM public.help_tickets WHERE id = p_ticket_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;
  IF v_ticket.raised_by_employee_code <> v_emp.employee_code THEN
    RAISE EXCEPTION 'Only ticket raiser can verify resolution';
  END IF;
  IF v_ticket.status NOT IN ('resolved', 'cannot_reproduce') THEN
    RAISE EXCEPTION 'Ticket must be resolved to verify';
  END IF;

  IF p_verified THEN
    v_new_status := 'closed';
    UPDATE public.help_tickets SET
      verification_status = 'verified',
      verified_at = now(),
      verified_by_employee_code = v_emp.employee_code,
      status = 'closed',
      closed_at = now(),
      closure_reason = COALESCE(NULLIF(btrim(p_reason), ''), 'resolved'),
      updated_at = now()
    WHERE id = p_ticket_id;

    PERFORM public.help_ticket_write_audit(
      p_ticket_id, 'verified', v_ticket.status, 'closed', p_reason,
      v_emp.user_id, v_emp.employee_code, v_emp.employee_name
    );
    PERFORM public.help_ticket_notify_support_holders(
      p_ticket_id, 'closed',
      jsonb_build_object('ticket_number', v_ticket.ticket_number)
    );
  ELSE
    v_new_status := 'reopened';
    UPDATE public.help_tickets SET
      verification_status = 'rejected',
      status = 'reopened',
      reopen_count = reopen_count + 1,
      last_reopened_at = now(),
      last_reopened_by_employee_code = v_emp.employee_code,
      resolved_at = NULL,
      sla_paused = false,
      updated_at = now()
    WHERE id = p_ticket_id;

    PERFORM public.help_ticket_write_audit(
      p_ticket_id, 'reopened', v_ticket.status, 'reopened', p_reason,
      v_emp.user_id, v_emp.employee_code, v_emp.employee_name
    );
    PERFORM public.help_ticket_notify_support_holders(
      p_ticket_id, 'reopened',
      jsonb_build_object('ticket_number', v_ticket.ticket_number)
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'status', v_new_status);
END;
$$;


--
-- Name: help_ticket_write_audit(uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.help_ticket_write_audit(p_ticket_id uuid, p_action_type text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_employee_code text DEFAULT NULL::text, p_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.help_ticket_audit_log (
    ticket_id, action_type, changed_by_user_id, changed_by_employee_code,
    changed_by_name, old_value, new_value, reason
  ) VALUES (
    p_ticket_id, p_action_type, p_user_id, p_employee_code,
    p_name, p_old_value, p_new_value, p_reason
  );
END;
$$;


--
-- Name: insert_post_feedback_bot_from_message(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_post_feedback_bot_from_message(p_message_id bigint) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  INSERT INTO public.post_feedback_bot_data (
    source_feedback_message_id,
    chassis_no,
    vehicle_registration_number,
    mobile_number,
    customer_name,
    rating,
    feedback_text,
    service_advisor_name,
    branch,
    service_type
  )
  SELECT
    m.id,
    jc.chassis_number,
    m.vehicle_registration_number,
    m.mobile_number,
    m.customer_name,
    m.rating,
    m.feedback_text,
    COALESCE(em.employee_name, jc.sr_assigned_to),
    jc.branch_label,
    jc.sr_type
  FROM public.post_service_feedback_messages m
  LEFT JOIN public.job_card_closed_data jc
    ON jc.id = m.job_card_closed_data_id
  LEFT JOIN public.employee_master em
    ON em.employee_code = jc.employee_code
  WHERE m.id = p_message_id
    AND m.status = 'responded'
    AND m.rating IS NOT NULL
    AND m.rating <= 3
    AND m.cre_status = 'open'
  ON CONFLICT ON CONSTRAINT post_feedback_bot_data_source_feedback_message_id_key
  DO NOTHING;
$$;


--
-- Name: FUNCTION insert_post_feedback_bot_from_message(p_message_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.insert_post_feedback_bot_from_message(p_message_id bigint) IS 'Idempotent insert of one eligible post_service_feedback_messages row into post_feedback_bot_data. Eligibility: status=responded, rating not null and <=3, cre_status=open. Does not update or delete existing bot rows.';


--
-- Name: insurance_next_due_date(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_next_due_date(p_sale_date date, p_as_of date DEFAULT CURRENT_DATE) RETURNS date
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_candidate date;
BEGIN
  IF p_sale_date IS NULL OR p_as_of IS NULL THEN
    RETURN NULL;
  END IF;

  v_candidate := (p_sale_date + INTERVAL '1 year' - INTERVAL '1 day')::date;

  WHILE v_candidate < p_as_of LOOP
    v_candidate := (v_candidate + INTERVAL '1 year')::date;
  END LOOP;

  RETURN v_candidate;
END;
$$;


--
-- Name: insurance_renewal_campaign_count_snapshot(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_campaign_count_snapshot(p_campaign_id bigint) RETURNS TABLE(total_leads integer, pending_count integer, in_progress_count integer, callback_later_count integer, quote_needed_count integer, policy_requested_count integer, quote_sent_count integer, renewed_count integer, policy_done_count integer, completed_count integer, out_of_window_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE a.status = 'pending')::integer,
    count(*) FILTER (WHERE a.status = 'in_progress')::integer,
    count(*) FILTER (WHERE a.status = 'callback_later')::integer,
    count(*) FILTER (WHERE a.status = 'quote_needed')::integer,
    count(*) FILTER (WHERE a.status = 'policy_requested')::integer,
    count(*) FILTER (WHERE a.status = 'quote_sent')::integer,
    count(*) FILTER (WHERE a.status = 'renewed_via_us')::integer,
    count(*) FILTER (WHERE a.status IN ('policy_done', 'already_renewed_unknown'))::integer,
    count(*) FILTER (WHERE a.status IN (
      'renewed_via_us', 'renewed_elsewhere', 'not_interested', 'wrong_number',
      'not_reachable', 'policy_done', 'already_renewed_unknown'
    ))::integer,
    count(*) FILTER (WHERE a.status = 'out_of_window')::integer
  FROM public.insurance_renewal_assignments a
  WHERE a.campaign_id = p_campaign_id;
$$;


--
-- Name: FUNCTION insurance_renewal_campaign_count_snapshot(p_campaign_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.insurance_renewal_campaign_count_snapshot(p_campaign_id bigint) IS 'True assignment-status counts for one insurance renewal campaign. Not subject to PostgREST max_rows.';


--
-- Name: insurance_renewal_get_next_assignment(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_get_next_assignment(p_campaign_id bigint, p_user_email text) RETURNS TABLE(asgn_id bigint, cust_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_assignment_id BIGINT;
  v_customer_id BIGINT;
BEGIN
  SELECT ra.id, ra.customer_id INTO v_assignment_id, v_customer_id
  FROM insurance_renewal_assignments ra
  JOIN insurance_renewal_leads s ON s.id = ra.customer_id
  WHERE ra.campaign_id = p_campaign_id
    AND ra.status = 'pending'
    AND ra.retry_after IS NOT NULL
    AND ra.retry_after <= CURRENT_DATE
  ORDER BY ra.retry_after ASC, s.effective_due_date ASC NULLS LAST, ra.id ASC
  LIMIT 1
  FOR UPDATE OF ra SKIP LOCKED;

  IF v_assignment_id IS NULL THEN
    SELECT ra.id, ra.customer_id INTO v_assignment_id, v_customer_id
    FROM insurance_renewal_assignments ra
    JOIN insurance_renewal_leads s ON s.id = ra.customer_id
    WHERE ra.campaign_id = p_campaign_id
      AND ra.status = 'pending'
      AND ra.retry_after IS NULL
    ORDER BY s.effective_due_date ASC NULLS LAST, ra.id ASC
    LIMIT 1
    FOR UPDATE OF ra SKIP LOCKED;
  END IF;

  IF v_assignment_id IS NOT NULL THEN
    UPDATE insurance_renewal_assignments
    SET assigned_to = p_user_email, status = 'assigned', assigned_at = NOW(), updated_at = NOW()
    WHERE id = v_assignment_id;
    RETURN QUERY SELECT v_assignment_id, v_customer_id;
  END IF;
END;
$$;


--
-- Name: insurance_renewal_rc_fetch_campaign_status(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_rc_fetch_campaign_status(p_campaign_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_pending_stale bigint;
  v_pending_with_vrn bigint;
  v_pending_missing_vrn bigint;
  v_active_job jsonb;
  v_last_job jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT u.role INTO v_role FROM public.users u WHERE u.id = v_uid;
  IF v_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Admin only';
  END IF;

  SELECT p.pending_stale, p.pending_with_vrn, p.pending_missing_vrn
  INTO v_pending_stale, v_pending_with_vrn, v_pending_missing_vrn
  FROM public.insurance_renewal_rc_fetch_pending_counts(p_campaign_id) p;

  SELECT to_jsonb(j) INTO v_active_job
  FROM public.insurance_renewal_rc_fetch_jobs j
  WHERE j.campaign_id = p_campaign_id
    AND j.status IN ('queued', 'running')
  ORDER BY j.created_at DESC
  LIMIT 1;

  SELECT to_jsonb(j) INTO v_last_job
  FROM public.insurance_renewal_rc_fetch_jobs j
  WHERE j.campaign_id = p_campaign_id
    AND j.status IN ('completed', 'failed', 'cancelled')
  ORDER BY j.completed_at DESC NULLS LAST
  LIMIT 1;

  RETURN jsonb_build_object(
    'pending_stale', coalesce(v_pending_stale, 0),
    'pending_with_vrn', coalesce(v_pending_with_vrn, 0),
    'pending_missing_vrn', coalesce(v_pending_missing_vrn, 0),
    'stale_cutoff_before', (CURRENT_DATE - 365),
    'fetch_enabled', (coalesce(v_pending_with_vrn, 0) > 0 AND v_active_job IS NULL),
    'active_job', v_active_job,
    'last_job', v_last_job
  );
END;
$$;


--
-- Name: FUNCTION insurance_renewal_rc_fetch_campaign_status(p_campaign_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.insurance_renewal_rc_fetch_campaign_status(p_campaign_id bigint) IS 'Admin-only RC fetch UI status (pending counts + active/last job) without Edge.';


--
-- Name: insurance_renewal_rc_fetch_cancel_admin(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_rc_fetch_cancel_admin(p_campaign_id bigint DEFAULT NULL::bigint, p_job_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_cancelled jsonb;
  v_n int;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_campaign_id IS NULL AND p_job_id IS NULL THEN
    RAISE EXCEPTION 'Missing campaign_id or job_id';
  END IF;

  SELECT u.role INTO v_role FROM public.users u WHERE u.id = v_uid;
  IF v_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Admin only';
  END IF;

  WITH u AS (
    UPDATE public.insurance_renewal_rc_fetch_jobs j
    SET status = 'cancelled',
        completed_at = now(),
        updated_at = now(),
        last_error = 'Cancelled by admin'
    WHERE j.status IN ('queued', 'running')
      AND (p_job_id IS NULL OR j.id = p_job_id)
      AND (p_campaign_id IS NULL OR j.campaign_id = p_campaign_id)
    RETURNING j.id, j.campaign_id, j.status
  )
  SELECT coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb), count(*)::int
  INTO v_cancelled, v_n
  FROM u;

  RETURN jsonb_build_object(
    'success', true,
    'message', CASE WHEN v_n > 0
      THEN format('Stopped %s RC fetch job(s). No further paid API calls for those jobs.', v_n)
      ELSE 'No queued or running RC fetch job to stop.'
    END,
    'cancelled', v_cancelled
  );
END;
$$;


--
-- Name: insurance_renewal_rc_fetch_diagnostics(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_rc_fetch_diagnostics(p_campaign_id bigint) RETURNS TABLE(assignment_total bigint, stale_in_campaign bigint, attempted_total bigint, pending_stale bigint, pending_with_vrn bigint, pending_missing_vrn bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    (SELECT count(*)::bigint FROM insurance_renewal_assignments ra WHERE ra.campaign_id = p_campaign_id),
    (SELECT count(*)::bigint
     FROM insurance_renewal_assignments ra
     JOIN all_service_data s ON s.id = ra.customer_id
     WHERE ra.campaign_id = p_campaign_id
       AND (
         s.last_insurance_expiry_date IS NULL
         OR s.last_insurance_expiry_date < (CURRENT_DATE - 365)
       )),
    (SELECT count(*)::bigint FROM insurance_renewal_rc_fetch_attempts a WHERE a.campaign_id = p_campaign_id),
    p.pending_stale,
    p.pending_with_vrn,
    p.pending_missing_vrn
  FROM insurance_renewal_rc_fetch_pending_counts(p_campaign_id) p;
$$;


--
-- Name: insurance_renewal_rc_fetch_enqueue_admin(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_rc_fetch_enqueue_admin(p_campaign_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_email text;
  v_pending_stale bigint;
  v_pending_with_vrn bigint;
  v_pending_missing_vrn bigint;
  v_active_id uuid;
  v_job_id uuid;
  v_job_status text;
  v_job_created timestamptz;
  v_kick bigint;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_campaign_id IS NULL THEN
    RAISE EXCEPTION 'Missing campaign_id';
  END IF;

  SELECT u.role, u.email INTO v_role, v_email FROM public.users u WHERE u.id = v_uid;
  IF v_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Admin only';
  END IF;

  SELECT p.pending_stale, p.pending_with_vrn, p.pending_missing_vrn
  INTO v_pending_stale, v_pending_with_vrn, v_pending_missing_vrn
  FROM public.insurance_renewal_rc_fetch_pending_counts(p_campaign_id) p;

  IF coalesce(v_pending_with_vrn, 0) <= 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'No new stale leads with registration numbers to fetch.',
      'job', null,
      'pending_stale', coalesce(v_pending_stale, 0),
      'pending_with_vrn', coalesce(v_pending_with_vrn, 0),
      'pending_missing_vrn', coalesce(v_pending_missing_vrn, 0)
    );
  END IF;

  SELECT j.id INTO v_active_id
  FROM public.insurance_renewal_rc_fetch_jobs j
  WHERE j.campaign_id = p_campaign_id
    AND j.status IN ('queued', 'running')
  LIMIT 1;

  IF v_active_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'RC fetch job already queued or running.',
      'job', jsonb_build_object('id', v_active_id),
      'pending_stale', v_pending_stale,
      'pending_with_vrn', v_pending_with_vrn,
      'pending_missing_vrn', v_pending_missing_vrn
    );
  END IF;

  INSERT INTO public.insurance_renewal_rc_fetch_jobs (campaign_id, status, created_by, stats)
  VALUES (
    p_campaign_id,
    'queued',
    coalesce(v_email, v_uid::text),
    '{}'::jsonb
  )
  RETURNING id, status, created_at INTO v_job_id, v_job_status, v_job_created;

  BEGIN
    SELECT public.invoke_insurance_renewal_rc_fetch_worker() INTO v_kick;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'message', format(
      'Queued background RC fetch for %s new lead(s). Worker runs every ~2 minutes (or when Edge is healthy).',
      v_pending_with_vrn
    ),
    'job', jsonb_build_object('id', v_job_id, 'status', v_job_status, 'created_at', v_job_created),
    'pending_stale', v_pending_stale,
    'pending_with_vrn', v_pending_with_vrn,
    'pending_missing_vrn', v_pending_missing_vrn,
    'worker_kick_request_id', v_kick
  );
END;
$$;


--
-- Name: insurance_renewal_rc_fetch_next_candidates(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_rc_fetch_next_candidates(p_campaign_id bigint, p_after_customer_id bigint, p_limit integer DEFAULT 50) RETURNS TABLE(customer_id bigint, vehicle_registration_number text, last_insurance_expiry_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    s.id AS customer_id,
    s.vehicle_registration_number,
    s.last_insurance_expiry_date
  FROM public.insurance_renewal_assignments ra
  JOIN public.all_service_data s ON s.id = ra.customer_id
  LEFT JOIN public.insurance_renewal_rc_fetch_attempts a
    ON a.campaign_id = ra.campaign_id AND a.customer_id = ra.customer_id
  WHERE ra.campaign_id = p_campaign_id
    AND ra.customer_id > coalesce(p_after_customer_id, 0)
    AND a.customer_id IS NULL
    AND (
      s.last_insurance_expiry_date IS NULL
      OR s.last_insurance_expiry_date < (CURRENT_DATE - 365)
    )
  ORDER BY ra.customer_id ASC
  LIMIT greatest(coalesce(p_limit, 50), 1);
$$;


--
-- Name: FUNCTION insurance_renewal_rc_fetch_next_candidates(p_campaign_id bigint, p_after_customer_id bigint, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.insurance_renewal_rc_fetch_next_candidates(p_campaign_id bigint, p_after_customer_id bigint, p_limit integer) IS 'Next unscanned stale campaign leads for background RC worker (ordered by customer_id).';


--
-- Name: insurance_renewal_rc_fetch_pending_counts(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_rc_fetch_pending_counts(p_campaign_id bigint) RETURNS TABLE(pending_stale bigint, pending_with_vrn bigint, pending_missing_vrn bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    count(*)::bigint AS pending_stale,
    count(*) FILTER (
      WHERE coalesce(nullif(trim(s.vehicle_registration_number), ''), '') <> ''
    )::bigint AS pending_with_vrn,
    count(*) FILTER (
      WHERE coalesce(nullif(trim(s.vehicle_registration_number), ''), '') = ''
    )::bigint AS pending_missing_vrn
  FROM public.insurance_renewal_assignments ra
  JOIN public.all_service_data s ON s.id = ra.customer_id
  LEFT JOIN public.insurance_renewal_rc_fetch_attempts a
    ON a.campaign_id = ra.campaign_id AND a.customer_id = ra.customer_id
  WHERE ra.campaign_id = p_campaign_id
    AND a.customer_id IS NULL
    AND (
      s.last_insurance_expiry_date IS NULL
      OR s.last_insurance_expiry_date < (CURRENT_DATE - 365)
    );
$$;


--
-- Name: FUNCTION insurance_renewal_rc_fetch_pending_counts(p_campaign_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.insurance_renewal_rc_fetch_pending_counts(p_campaign_id bigint) IS 'Counts campaign leads eligible for first-time RC fetch (stale/null insurance, no prior attempt).';


--
-- Name: insurance_renewal_recount_campaign(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insurance_renewal_recount_campaign(p_campaign_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id bigint;
  v_total integer;
BEGIN
  UPDATE public.insurance_renewal_campaigns
  SET updated_at = now()
  WHERE id = p_campaign_id
  RETURNING id, total_leads INTO v_id, v_total;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'insurance renewal campaign % not found', p_campaign_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'campaign_id', v_id,
    'total_leads', v_total
  );
END;
$$;


--
-- Name: FUNCTION insurance_renewal_recount_campaign(p_campaign_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.insurance_renewal_recount_campaign(p_campaign_id bigint) IS 'Touches a campaign row so trg_insurance_renewal_campaigns_force_true_counts writes COUNT(*) counters.';


