CREATE TABLE public.all_service_data (
    id bigint NOT NULL,
    chassis_no text,
    vehicle_registration_number text,
    first_name text,
    last_name text,
    contact_phones text,
    model text,
    product_line text,
    vehicle_sale_date date,
    vehicle_age_in_years text,
    scheduled_next_service_date date,
    scheduled_next_service_kms text,
    last_service_date date,
    last_service_type text,
    last_service_customer_mobile_no text,
    last_service_dealer text,
    last_service_km text,
    extended_warranty_dealer text,
    extended_warranty_policy_no text,
    extended_warranty_product text,
    extended_warranty_service_product_period text,
    extended_warranty_order_no text,
    extended_warranty_order_status text,
    extended_warranty_start_date date,
    extended_warranty_end_date date,
    extended_warranty_end_kms text,
    extended_warranty_final_price_without_tax text,
    extended_warranty_final_price text,
    created_at timestamp with time zone DEFAULT now(),
    last_updated_at timestamp with time zone,
    ex_showroom_price numeric,
    idv numeric,
    last_insurance_expiry_date date,
    last_insurance_comapny text,
    last_insurance_policy_number text,
    assumed_next_service_date date,
    assumed_next_service_type text,
    powertrain_type text,
    sold_dealer text,
