-- Name: COLUMN all_service_data.updated_by_rtoids_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.all_service_data.updated_by_rtoids_at IS 'Timestamp of last insurance field update from public.rto_idspay sync.';


--
-- Name: is_all_service_dynamic_match(public.all_service_data); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_all_service_dynamic_match(r public.all_service_data) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT
    (
      r.chassis_no IS NOT NULL
      AND COALESCE(
        (
          SELECT bool_and(e.value IS NULL)
          FROM jsonb_each(
            to_jsonb(r) - ARRAY['id','chassis_no','created_at','last_updated_at']
          ) AS e(key, value)
        ),
        true
      )
    )
    OR
    (
      r.chassis_no IS NOT NULL
      AND r.assumed_next_service_date = (current_date + 2)
    )
    OR
    (
      r.chassis_no IS NOT NULL
      AND (
        NULLIF(btrim(r.last_service_type), '') IS NULL
        OR btrim(r.last_service_type) !~* 'service'
      )
    )
    OR
    (
      r.chassis_no IS NOT NULL
      AND COALESCE(
        NULLIF(lower(btrim(r.updated_by_robot::text)), ''),
        'false'
      ) IN ('false', 'f')
    );
$$;


--
-- Name: FUNCTION is_all_service_dynamic_match(r public.all_service_data); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_all_service_dynamic_match(r public.all_service_data) IS 'Active include conditions: (1) chassis_no present and all non-technical columns are NULL OR (2) assumed_next_service_date = current_date + 2 OR (3) last_service_type is NULL/blank or does not contain Service text OR (4) updated_by_robot is NULL/blank/false.';


--
-- Name: is_floor_incharge_service_type(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_floor_incharge_service_type(p_service_type text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(p_service_type, '') IN (
    'Running Repairs',
    'First Free Service',
    'Second Free Service',
    'Third Free Service',
    'Paid Service',
    'Mini Paid Service',
    'Updation',
    'E Breakdown',
    'Campaign'
  );
$$;


--
-- Name: is_income_assignment_eligible(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_income_assignment_eligible(p_module_key text, p_assignment_source text, p_employee_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.employee_master em
    JOIN public.income_role_scope rs ON rs.is_active = true
     AND upper(btrim(rs.module_key)) = upper(btrim(coalesce(p_module_key, '')))
     AND upper(btrim(rs.assignment_source)) = upper(btrim(coalesce(p_assignment_source, '')))
    WHERE upper(btrim(coalesce(em.employee_code, ''))) = upper(btrim(coalesce(p_employee_code, '')))
      AND public.employee_has_business_role(
        em.role,
        public.normalize_business_role_token(rs.employee_role)
      )
  );
$$;


--
-- Name: FUNCTION is_income_assignment_eligible(p_module_key text, p_assignment_source text, p_employee_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_income_assignment_eligible(p_module_key text, p_assignment_source text, p_employee_code text) IS 'Returns true when employee_code is eligible for the income module according to income_role_scope and employee_master.role.';


--
-- Name: issue_accounts_mechanical_gatepass(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_accounts_mechanical_gatepass(p_reception_entry_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_inv public.accounts_mechanical_invoices%ROWTYPE;
  v_entry public.service_reception_entries%ROWTYPE;
  v_remaining numeric;
  v_reason text;
  v_label text;
  v_gp_no text;
  v_norm text;
  v_actor text;
  v_issued_at text;
  v_payload jsonb;
  v_bot_id bigint;
  v_received numeric;
  v_credit_valid boolean;
BEGIN
  IF NOT public.accounts_can_access() THEN
    RAISE EXCEPTION 'permission denied: requires accounts view'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_entry
    FROM public.service_reception_entries
   WHERE id = p_reception_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reception entry % not found', p_reception_entry_id
      USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_inv
    FROM public.accounts_mechanical_invoices
   WHERE reception_entry_id = p_reception_entry_id;
  IF NOT FOUND OR v_inv.billed_amount IS NULL THEN
    RAISE EXCEPTION 'capture invoice number and billed amount first'
      USING ERRCODE = '23514';
  END IF;

  v_received := COALESCE(v_inv.amount_received, 0);
  v_remaining := public.accounts_mechanical_remaining_amount(v_inv.billed_amount, v_inv.amount_received);
  v_credit_valid := public.accounts_mechanical_keep_on_credit_valid(
    v_inv.keep_on_credit,
    v_inv.keep_on_credit_reason,
    v_inv.keep_on_credit_approved_by,
    v_inv.keep_on_credit_approved_at
  );
  v_reason := public.accounts_mechanical_gatepass_reason(
    v_inv.billed_amount,
    v_inv.amount_received,
    v_credit_valid
  );
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'gatepass not eligible: remaining ₹% exceeds 2%% of billed ₹% and Keep on Credit is not approved',
      v_remaining, v_inv.billed_amount
      USING ERRCODE = '23514';
  END IF;

  v_label := public.accounts_mechanical_gatepass_reason_label(v_reason);
  v_norm := upper(btrim(COALESCE(v_entry.reg_number, 'VEHICLE')));
  v_gp_no := 'GP-' || CASE
    WHEN NULLIF(btrim(COALESCE(v_entry.jc_number, '')), '') IS NULL THEN right(extract(epoch FROM now())::bigint::text, 5)
    ELSE right(regexp_replace(v_entry.jc_number, '[^0-9]', '', 'g'), 5)
  END;
  v_actor := public.accounts_mechanical_actor_label();
  v_issued_at := to_char(now() AT TIME ZONE 'Asia/Kolkata', 'DD Mon YYYY, HH:MI AM');

  v_payload := jsonb_build_object(
    'gate_pass_no', v_gp_no,
    'reg_number', v_norm,
    'customer_name', COALESCE(NULLIF(btrim(v_entry.owner_name), ''), 'Customer'),
    'customer_phone', v_entry.owner_phone,
    'job_card_no', v_entry.jc_number,
    'invoice_no', COALESCE(v_inv.invoice_number, 'INV-' || replace(v_gp_no, 'GP-', '')),
    'invoice_date', v_inv.invoice_date,
    'billed_amount', v_inv.billed_amount,
    'amount_received', v_received,
    'remaining_amount', v_remaining,
    'payment_status', v_label,
    'settlement_reason', v_reason,
    'keep_on_credit', v_credit_valid,
    'keep_on_credit_reason', CASE WHEN v_reason = 'keep_on_credit' THEN v_inv.keep_on_credit_reason ELSE NULL END,
    'keep_on_credit_approved_by', CASE WHEN v_reason = 'keep_on_credit' THEN v_inv.keep_on_credit_approved_by ELSE NULL END,
    'keep_on_credit_approved_at', CASE WHEN v_reason = 'keep_on_credit' THEN v_inv.keep_on_credit_approved_at ELSE NULL END,
    'issued_at', v_issued_at,
    'issued_by', v_actor,
    'branch', COALESCE(v_entry.branch, 'Sitapura Workshop'),
    'qr_token', 'GP_AUTH_' || v_gp_no || '_' || v_norm || '_SECURE'
  );

  SELECT id INTO v_bot_id
    FROM public.post_feedback_bot_data
   WHERE vehicle_registration_number = v_norm
     AND mode = 'customer_gatepass_payload'
   ORDER BY complaint_date_time DESC NULLS LAST
   LIMIT 1;

  IF v_bot_id IS NOT NULL THEN
    UPDATE public.post_feedback_bot_data
       SET customer_name = v_payload ->> 'customer_name',
           mobile_number = v_entry.owner_phone,
           rating = 5,
           feedback_text = v_payload::text,
           service_type = 'Gate Pass #' || v_gp_no,
           primary_complaint_area = 'Gate Pass Issued',
           complaint_date_time = now()
     WHERE id = v_bot_id;
  ELSE
    INSERT INTO public.post_feedback_bot_data (
      vehicle_registration_number, customer_name, mobile_number, rating,
      feedback_text, service_type, mode, primary_complaint_area, complaint_date_time
    ) VALUES (
      v_norm,
      v_payload ->> 'customer_name',
      v_entry.owner_phone,
      5,
      v_payload::text,
      'Gate Pass #' || v_gp_no,
      'customer_gatepass_payload',
      'Gate Pass Issued',
      now()
    );
  END IF;

  UPDATE public.service_reception_entries
     SET gate_pass_issued = true,
         gate_pass_number = v_gp_no
   WHERE id = p_reception_entry_id;

  RETURN v_payload;
END;
$$;


--
-- Name: FUNCTION issue_accounts_mechanical_gatepass(p_reception_entry_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.issue_accounts_mechanical_gatepass(p_reception_entry_id bigint) IS 'DBL-0065: Issue Mechanical Gatepass only when remaining <= 0, remaining <= 2% of billed, or valid persisted Keep on Credit (flag+reason+approver+time). Computes eligibility server-side from authoritative invoice columns. Does not accept a client eligible flag. payment_status on the payload is the Gatepass clearance label, not financial payment_status.';


--
-- Name: latest_psf_revenue_dms_for_job_card(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.latest_psf_revenue_dms_for_job_card(p_job_card_number text, p_location text DEFAULT NULL::text, p_portal text DEFAULT NULL::text) RETURNS TABLE(final_labour_amount numeric, total_invoice_amount numeric)
    LANGUAGE sql STABLE
    AS $$
  select
    d.final_labour_amount,
    d.total_invoice_amount
  from public.psf_revenue_dms d
  where upper(btrim(d.job_card_number)) = upper(btrim(p_job_card_number))
    and coalesce(btrim(d.job_card_number), '') <> ''
    and (
      coalesce(btrim(p_location), '') = ''
      or d.location = p_location
    )
    and (
      coalesce(btrim(p_portal), '') = ''
      or d.portal = p_portal
    )
  order by d.invoice_date desc nulls last, d.id desc
  limit 1
$$;


--
-- Name: list_accounts_bodyshop_cases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_accounts_bodyshop_cases() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_rows jsonb;
BEGIN
  IF NOT public.accounts_can_access() THEN
    RAISE EXCEPTION 'permission denied: requires accounts view'
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(
    jsonb_agg(to_jsonb(x) ORDER BY x.invoice_date DESC NULLS LAST, x.repair_card_id DESC),
    '[]'::jsonb
  )
    INTO v_rows
    FROM (
      SELECT
        s.repair_card_id,
        s.job_card_no,
        c.reg_number,
        c.customer_name,
        c.branch,
        c.sa_name,
        c.insurance_company,
        c.insurance_policy_no,
        c.overall_status,
        c.current_stage,
        s.invoice_number,
        s.invoice_date,
        s.invoice_amount,
        c.billed_amount,
        s.invoice_account,
        s.customer_diff_amount,
        s.customer_settlement_kind,
        s.customer_posted_amount,
        s.customer_remaining_amount,
        s.customer_payment_status,
        s.do_amount,
        s.do_status,
        s.do_released_amount,
        s.insurance_due_amount,
        s.do_payment_status,
        s.outstanding_amount,
        s.derived_payment_status
      FROM public.bodyshop_settlements s
      JOIN public.bodyshop_repair_cards c ON c.id = s.repair_card_id
      WHERE NULLIF(btrim(s.invoice_number), '') IS NOT NULL
        AND COALESCE(s.invoice_amount, c.billed_amount) IS NOT NULL
        AND COALESCE(c.overall_status, 'active') <> 'cancelled'
    ) x;

  RETURN v_rows;
END;
$$;


--
-- Name: FUNCTION list_accounts_bodyshop_cases(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_accounts_bodyshop_cases() IS 'ACCOUNTS-001 / DBL-0055: billed Bodyshop cases plus settlement outstanding and overall payment status.';


--
-- Name: list_accounts_mechanical_cases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_accounts_mechanical_cases() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_rows jsonb;
BEGIN
  IF NOT public.accounts_can_access() THEN
    RAISE EXCEPTION 'permission denied: requires accounts view'
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(
    jsonb_agg(to_jsonb(x) ORDER BY x.invoice_done_at DESC NULLS LAST, x.reception_entry_id DESC),
    '[]'::jsonb
  )
    INTO v_rows
    FROM (
      SELECT
        e.id AS reception_entry_id,
        e.jc_number,
        e.reg_number,
        e.model,
        e.service_type,
        e.sa_name,
        e.sa_display_name,
        e.sa_employee_code,
        e.branch,
        e.owner_name,
        e.owner_phone,
        e.invoice_done_at,
        e.invoice_done_by,
        e.created_at,
        e.invoice_storage_path,
        e.invoice_file_name,
        e.invoice_drive_url,
        e.expected_invoice_amount,
        inv.invoice_number,
        inv.invoice_date,
        inv.billed_amount,
        inv.payment_status,
        inv.amount_received,
        public.accounts_mechanical_remaining_amount(inv.billed_amount, inv.amount_received) AS remaining_amount,
        inv.payment_notes,
        inv.captured_by,
        inv.captured_at,
        inv.updated_at AS invoice_updated_at,
        COALESCE(inv.keep_on_credit, false) AS keep_on_credit,
        inv.keep_on_credit_reason,
        inv.keep_on_credit_approved_by,
        inv.keep_on_credit_approved_at,
        inv.keep_on_credit_revoked_by,
        inv.keep_on_credit_revoked_at,
        public.accounts_mechanical_invoice_gatepass_reason(
          inv.billed_amount,
          inv.amount_received,
          COALESCE(inv.keep_on_credit, false),
          inv.keep_on_credit_reason,
          inv.keep_on_credit_approved_by,
          inv.keep_on_credit_approved_at
        ) AS gatepass_reason
      FROM public.service_reception_entries e
      LEFT JOIN public.accounts_mechanical_invoices inv
        ON inv.reception_entry_id = e.id
      WHERE e.invoice_done_at IS NOT NULL
        AND e.invoice_done_at >= TIMESTAMPTZ '2026-09-11 00:00:00+05:30'
        AND NULLIF(btrim(e.jc_number), '') IS NOT NULL
        AND public.is_floor_incharge_service_type(e.service_type)
    ) x;

  RETURN v_rows;
END;
$$;


--
-- Name: FUNCTION list_accounts_mechanical_cases(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_accounts_mechanical_cases() IS 'ACCOUNTS-001 / DBL-0065: Mechanical Mark Done cases from 2026-09-11 00:00 Asia/Kolkata. Gatepass reason requires valid Keep on Credit (flag+reason+approver+time), not the flag alone. Remaining is still GREATEST(0, billed − received).';


