--
-- Name: list_bodyshop_do_recovery(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_bodyshop_do_recovery() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_rows jsonb;
BEGIN
  IF NOT (
    public.is_admin()
    OR public.has_module_view('bodyshop_recovery')
    OR public.has_module_modify('bodyshop_recovery')
  ) THEN
    RAISE EXCEPTION 'permission denied: requires bodyshop_recovery view'
      USING ERRCODE = '42501';
  END IF;

  -- Open (due > 0) plus received / due ₹0 (no recovery needed).
  SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.insurance_due_amount DESC, x.invoice_date DESC NULLS LAST, x.repair_card_id DESC), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT
        s.repair_card_id,
        s.job_card_no,
        c.reg_number,
        c.customer_name,
        c.branch,
        c.sa_name,
        c.insurance_company,
        c.overall_status,
        c.current_stage,
        s.invoice_number,
        s.invoice_date,
        s.invoice_amount,
        s.invoice_account,
        s.do_amount,
        s.do_released_amount,
        s.insurance_due_amount,
        s.do_payment_status,
        s.needs_accounts_review
      FROM public.bodyshop_settlements s
      JOIN public.bodyshop_repair_cards c ON c.id = s.repair_card_id
      WHERE s.do_amount IS NOT NULL
        AND COALESCE(c.overall_status, 'active') <> 'cancelled'
    ) x;

  RETURN v_rows;
END;
$$;


--
-- Name: FUNCTION list_bodyshop_do_recovery(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_bodyshop_do_recovery() IS 'Org-wide DO recovery book: billed non-cancelled cards with a DO. Includes open insurance due and received / due ₹0 (no recovery needed).';


--
-- Name: list_my_complaint_notifications(integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_complaint_notifications(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_include_dismissed boolean DEFAULT false) RETURNS TABLE(id bigint, complaint_id bigint, event_type text, recipient_type text, channel text, status text, payload jsonb, created_at timestamp with time zone, seen_at timestamp with time zone, read_at timestamp with time zone, dismissed_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    n.id,
    n.complaint_id,
    n.event_type,
    n.recipient_type,
    n.channel,
    n.status,
    n.payload,
    n.created_at,
    n.seen_at,
    n.read_at,
    n.dismissed_at
  FROM public.complaint_notifications n
  WHERE n.channel = 'in_app'
    AND (p_include_dismissed OR n.dismissed_at IS NULL)
    AND (
      n.recipient_user_id = auth.uid()
      OR (
        public.is_admin()
        AND n.recipient_user_id IS NULL
        AND public.dealer_code_in_scope(n.dealer_code)
      )
    )
  ORDER BY n.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$$;


--
-- Name: list_my_help_ticket_notifications(integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_help_ticket_notifications(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_include_dismissed boolean DEFAULT false) RETURNS TABLE(id bigint, ticket_id uuid, event_type text, recipient_type text, channel text, status text, payload jsonb, created_at timestamp with time zone, seen_at timestamp with time zone, read_at timestamp with time zone, dismissed_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    n.id, n.ticket_id, n.event_type, n.recipient_type, n.channel, n.status,
    n.payload, n.created_at, n.seen_at, n.read_at, n.dismissed_at
  FROM public.help_ticket_notifications n
  WHERE n.channel = 'in_app'
    AND n.recipient_user_id = auth.uid()
    AND (p_include_dismissed OR n.dismissed_at IS NULL)
  ORDER BY n.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$$;


--
-- Name: list_reception_entries_by_jc_numbers(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_reception_entries_by_jc_numbers(p_jc_numbers text[]) RETURNS SETOF public.service_reception_entries
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_jc_numbers IS NULL OR cardinality(p_jc_numbers) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT r.*
    FROM public.service_reception_entries r
   WHERE upper(btrim(r.jc_number)) = ANY (
           SELECT upper(btrim(jc))
             FROM unnest(p_jc_numbers) AS jc
            WHERE NULLIF(btrim(jc), '') IS NOT NULL
         )
     AND public.user_can_read_service_reception_entry(
           r.dealer_code,
           r.sa_employee_code,
           r.service_type,
           r.id
         )
   ORDER BY r.created_at DESC, r.id DESC;
END;
$$;


--
-- Name: FUNCTION list_reception_entries_by_jc_numbers(p_jc_numbers text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_reception_entries_by_jc_numbers(p_jc_numbers text[]) IS 'JC-scoped reception lookup bypassing authenticated RLS.';


--
-- Name: list_reception_entries_page(timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, bigint, text[], text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_reception_entries_page(p_created_at_from timestamp with time zone, p_created_at_to timestamp with time zone, p_page_size integer DEFAULT 100, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id bigint DEFAULT NULL::bigint, p_service_types text[] DEFAULT NULL::text[], p_search_query text DEFAULT NULL::text, p_require_non_empty_jc boolean DEFAULT false) RETURNS SETOF public.service_reception_entries
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_search text;
  v_page_size integer;
  v_is_admin boolean;
  v_broad_scope boolean;
  v_linked_service_floor_fi_only boolean;
  v_use_advisor_own_codes boolean;
  v_reception_dealer_only boolean;
  v_use_floor_incharge_scope boolean;
  v_dealer_codes text[];
BEGIN
  IF p_created_at_from IS NULL OR p_created_at_to IS NULL THEN
    RAISE EXCEPTION 'created_at range is required'
      USING ERRCODE = '22023';
  END IF;

  v_search := NULLIF(btrim(coalesce(p_search_query, '')), '');
  v_page_size := least(greatest(coalesce(p_page_size, 100), 1), 100);
  v_is_admin := public.is_admin();
  v_broad_scope := public.user_needs_sa_summary_broad_scope();

  SELECT coalesce(
    array_agg(DISTINCT upper(btrim(dc))) FILTER (WHERE btrim(coalesce(dc, '')) <> ''),
    ARRAY[]::text[]
  )
    INTO v_dealer_codes
    FROM unnest(public.my_effective_dealer_codes()) AS dc;

  v_reception_dealer_only :=
    NOT v_is_admin
    AND public.has_module_view('reception'::text)
    AND coalesce(array_length(v_dealer_codes, 1), 0) > 0
    AND NOT public.has_module_view('floor_incharge'::text)
    AND NOT public.has_module_view('bodyshop_floor'::text)
    AND NOT public.has_module_modify('bodyshop_floor'::text);

  v_linked_service_floor_fi_only :=
    EXISTS (
      SELECT 1
      FROM public.user_employee_links uel
      JOIN public.employee_master em ON em.employee_code = uel.employee_code
      WHERE uel.user_id = auth.uid()
        AND uel.is_active = true
        AND public.employee_has_business_role(em.role, 'FLOOR_INCHARGE')
        AND upper(replace(btrim(coalesce(em.department, '')), ' ', '')) = 'SERVICE'
        AND NOT public.employee_has_business_role(em.role, 'SA')
    );

  -- Assigned SA path — not bodyshop_floor; not SERVICE floor incharge-only links.
  v_use_advisor_own_codes :=
    NOT v_is_admin
    AND NOT v_broad_scope
    AND NOT public.has_module_view('bodyshop_floor'::text)
    AND NOT public.has_module_modify('bodyshop_floor'::text)
    AND NOT v_linked_service_floor_fi_only
    AND EXISTS (
      SELECT 1
      FROM public.user_employee_links uel
      WHERE uel.user_id = auth.uid()
        AND uel.is_active = true
    );

  v_use_floor_incharge_scope :=
    NOT v_is_admin
    AND NOT v_broad_scope
    AND NOT v_reception_dealer_only
    AND NOT v_use_advisor_own_codes
    AND public.has_module_view('floor_incharge'::text)
    AND NOT public.has_module_view('bodyshop_floor'::text)
    AND NOT public.has_module_modify('bodyshop_floor'::text);

  IF v_is_admin THEN
    RETURN QUERY
    SELECT r.*
      FROM public.service_reception_entries r
     WHERE r.created_at >= p_created_at_from
       AND r.created_at <= p_created_at_to
       AND (
         p_service_types IS NULL
         OR cardinality(p_service_types) = 0
         OR r.service_type = ANY (p_service_types)
       )
       AND (
         NOT coalesce(p_require_non_empty_jc, false)
         OR NULLIF(btrim(r.jc_number), '') IS NOT NULL
       )
       AND (
         v_search IS NULL
         OR r.reg_number ILIKE ('%' || v_search || '%')
         OR coalesce(r.model, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.jc_number, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.owner_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.owner_phone, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.sa_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.sa_display_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.source, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.created_by, '') ILIKE ('%' || v_search || '%')
       )
       AND (
         p_cursor_created_at IS NULL
         OR p_cursor_id IS NULL
         OR (r.created_at, r.id) < (p_cursor_created_at, p_cursor_id)
       )
     ORDER BY r.created_at DESC, r.id DESC
     LIMIT v_page_size;
    RETURN;
  END IF;

  IF v_use_advisor_own_codes THEN
    RETURN QUERY
    SELECT r.*
      FROM public.service_reception_entries r
      INNER JOIN public.user_employee_links uel
        ON uel.user_id = auth.uid()
        AND uel.is_active = true
        AND uel.employee_code = r.sa_employee_code
     WHERE r.created_at >= p_created_at_from
       AND r.created_at <= p_created_at_to
       AND (
         p_service_types IS NULL
         OR cardinality(p_service_types) = 0
         OR r.service_type = ANY (p_service_types)
       )
       AND (
         NOT coalesce(p_require_non_empty_jc, false)
         OR NULLIF(btrim(r.jc_number), '') IS NOT NULL
       )
       AND (
         v_search IS NULL
         OR r.reg_number ILIKE ('%' || v_search || '%')
         OR coalesce(r.model, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.jc_number, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.owner_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.owner_phone, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.sa_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.sa_display_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.source, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.created_by, '') ILIKE ('%' || v_search || '%')
       )
       AND (
         p_cursor_created_at IS NULL
         OR p_cursor_id IS NULL
         OR (r.created_at, r.id) < (p_cursor_created_at, p_cursor_id)
       )
     ORDER BY r.created_at DESC, r.id DESC
     LIMIT v_page_size;
    RETURN;
  END IF;

  IF v_reception_dealer_only THEN
    RETURN QUERY
    SELECT r.*
      FROM public.service_reception_entries r
     WHERE r.created_at >= p_created_at_from
       AND r.created_at <= p_created_at_to
       AND upper(btrim(r.dealer_code)) = ANY (v_dealer_codes)
       AND (
         p_service_types IS NULL
         OR cardinality(p_service_types) = 0
         OR r.service_type = ANY (p_service_types)
       )
       AND (
         NOT coalesce(p_require_non_empty_jc, false)
         OR NULLIF(btrim(r.jc_number), '') IS NOT NULL
       )
       AND (
         v_search IS NULL
         OR r.reg_number ILIKE ('%' || v_search || '%')
         OR coalesce(r.model, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.jc_number, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.owner_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.owner_phone, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.sa_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.sa_display_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.source, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.created_by, '') ILIKE ('%' || v_search || '%')
       )
       AND (
         p_cursor_created_at IS NULL
         OR p_cursor_id IS NULL
         OR (r.created_at, r.id) < (p_cursor_created_at, p_cursor_id)
       )
     ORDER BY r.created_at DESC, r.id DESC
     LIMIT v_page_size;
    RETURN;
  END IF;

  IF v_use_floor_incharge_scope THEN
    RETURN QUERY
    WITH allowed_sa AS MATERIALIZED (
      SELECT DISTINCT upper(btrim(sa.employee_code)) AS sa_code
        FROM public.employee_master sa
       WHERE btrim(coalesce(sa.employee_code, '')) <> ''
         AND public.service_floor_incharge_sa_in_scope(sa.fuel_type, sa.location)
    )
    SELECT r.*
      FROM public.service_reception_entries r
      INNER JOIN allowed_sa a
        ON upper(btrim(r.sa_employee_code)) = a.sa_code
     WHERE r.created_at >= p_created_at_from
       AND r.created_at <= p_created_at_to
       AND (
         p_service_types IS NULL
         OR cardinality(p_service_types) = 0
         OR r.service_type = ANY (p_service_types)
       )
       AND (
         NOT coalesce(p_require_non_empty_jc, false)
         OR NULLIF(btrim(r.jc_number), '') IS NOT NULL
       )
       AND (
         v_search IS NULL
         OR r.reg_number ILIKE ('%' || v_search || '%')
         OR coalesce(r.model, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.jc_number, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.owner_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.owner_phone, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.sa_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.sa_display_name, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.source, '') ILIKE ('%' || v_search || '%')
         OR coalesce(r.created_by, '') ILIKE ('%' || v_search || '%')
       )
       AND (
         p_cursor_created_at IS NULL
         OR p_cursor_id IS NULL
         OR (r.created_at, r.id) < (p_cursor_created_at, p_cursor_id)
       )
     ORDER BY r.created_at DESC, r.id DESC
     LIMIT v_page_size;
    RETURN;
  END IF;

  RETURN QUERY
  WITH my_dealers AS MATERIALIZED (
    SELECT v_dealer_codes AS codes
  )
  SELECT r.*
    FROM public.service_reception_entries r
    CROSS JOIN my_dealers md
   WHERE r.created_at >= p_created_at_from
     AND r.created_at <= p_created_at_to
     AND (
       coalesce(array_length(md.codes, 1), 0) = 0
       OR upper(btrim(r.dealer_code)) = ANY (md.codes)
     )
     AND public.service_reception_entry_in_summary_scope(
       r.dealer_code,
       r.sa_employee_code,
       r.service_type
     )
     AND (
       p_service_types IS NULL
       OR cardinality(p_service_types) = 0
       OR r.service_type = ANY (p_service_types)
     )
     AND (
       NOT coalesce(p_require_non_empty_jc, false)
       OR NULLIF(btrim(r.jc_number), '') IS NOT NULL
     )
     AND (
       v_search IS NULL
       OR r.reg_number ILIKE ('%' || v_search || '%')
       OR coalesce(r.model, '') ILIKE ('%' || v_search || '%')
       OR coalesce(r.jc_number, '') ILIKE ('%' || v_search || '%')
       OR coalesce(r.owner_name, '') ILIKE ('%' || v_search || '%')
       OR coalesce(r.owner_phone, '') ILIKE ('%' || v_search || '%')
       OR coalesce(r.sa_name, '') ILIKE ('%' || v_search || '%')
       OR coalesce(r.sa_display_name, '') ILIKE ('%' || v_search || '%')
       OR coalesce(r.source, '') ILIKE ('%' || v_search || '%')
       OR coalesce(r.created_by, '') ILIKE ('%' || v_search || '%')
     )
     AND (
       p_cursor_created_at IS NULL
       OR p_cursor_id IS NULL
       OR (r.created_at, r.id) < (p_cursor_created_at, p_cursor_id)
     )
   ORDER BY r.created_at DESC, r.id DESC
   LIMIT v_page_size;
END;
$$;


--
-- Name: FUNCTION list_reception_entries_page(p_created_at_from timestamp with time zone, p_created_at_to timestamp with time zone, p_page_size integer, p_cursor_created_at timestamp with time zone, p_cursor_id bigint, p_service_types text[], p_search_query text, p_require_non_empty_jc boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_reception_entries_page(p_created_at_from timestamp with time zone, p_created_at_to timestamp with time zone, p_page_size integer, p_cursor_created_at timestamp with time zone, p_cursor_id bigint, p_service_types text[], p_search_query text, p_require_non_empty_jc boolean) IS 'Paginated reception list. Advisor JOIN for assigned SA; excludes bodyshop_floor and SERVICE floor-FI-only links. Floor incharge uses Employee Master fuel/location SA JOIN (not JC dealer_code). Bodyshop uses summary_scope Accident path.';


--
-- Name: list_reception_jc_numbers_by_sa(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_reception_jc_numbers_by_sa(p_sa_employee_code text) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT NULLIF(btrim(r.jc_number), '')
    FROM public.service_reception_entries r
   WHERE upper(btrim(r.sa_employee_code)) = upper(btrim(coalesce(p_sa_employee_code, '')))
     AND NULLIF(btrim(r.jc_number), '') IS NOT NULL
     AND (
       public.is_admin()
       OR public.user_has_employee_code(p_sa_employee_code)
       OR public.service_reception_entry_in_summary_scope(
         r.dealer_code,
         r.sa_employee_code,
         r.service_type
       )
     )
   ORDER BY 1;
$$;


--
-- Name: FUNCTION list_reception_jc_numbers_by_sa(p_sa_employee_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_reception_jc_numbers_by_sa(p_sa_employee_code text) IS 'Distinct JC numbers for an SA code; bypasses authenticated RLS.';


--
-- Name: list_reception_reg_created_since(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_reception_reg_created_since(p_since timestamp with time zone) RETURNS TABLE(reg_number text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_admin boolean;
  v_broad_scope boolean;
  v_linked_service_floor_fi_only boolean;
  v_use_advisor_own_codes boolean;
  v_reception_dealer_only boolean;
  v_use_floor_incharge_scope boolean;
  v_dealer_codes text[];
  v_row_limit constant integer := 10000;
BEGIN
  IF p_since IS NULL THEN
    RAISE EXCEPTION 'p_since is required' USING ERRCODE = '22023';
  END IF;

  v_is_admin := public.is_admin();
  v_broad_scope := public.user_needs_sa_summary_broad_scope();

  SELECT coalesce(
    array_agg(DISTINCT upper(btrim(dc))) FILTER (WHERE btrim(coalesce(dc, '')) <> ''),
    ARRAY[]::text[]
  )
    INTO v_dealer_codes
    FROM unnest(public.my_effective_dealer_codes()) AS dc;

  v_reception_dealer_only :=
    NOT v_is_admin
    AND public.has_module_view('reception'::text)
    AND coalesce(array_length(v_dealer_codes, 1), 0) > 0
    AND NOT public.has_module_view('floor_incharge'::text)
    AND NOT public.has_module_view('bodyshop_floor'::text)
    AND NOT public.has_module_modify('bodyshop_floor'::text);

  v_linked_service_floor_fi_only :=
    EXISTS (
      SELECT 1
      FROM public.user_employee_links uel
      JOIN public.employee_master em ON em.employee_code = uel.employee_code
      WHERE uel.user_id = auth.uid()
        AND uel.is_active = true
        AND public.employee_has_business_role(em.role, 'FLOOR_INCHARGE')
        AND upper(replace(btrim(coalesce(em.department, '')), ' ', '')) = 'SERVICE'
        AND NOT public.employee_has_business_role(em.role, 'SA')
    );

  v_use_advisor_own_codes :=
    NOT v_is_admin
    AND NOT v_broad_scope
    AND NOT public.has_module_view('bodyshop_floor'::text)
    AND NOT public.has_module_modify('bodyshop_floor'::text)
    AND NOT v_linked_service_floor_fi_only
    AND EXISTS (
      SELECT 1
      FROM public.user_employee_links uel
      WHERE uel.user_id = auth.uid()
        AND uel.is_active = true
    );

  v_use_floor_incharge_scope :=
    NOT v_is_admin
    AND NOT v_broad_scope
    AND NOT v_reception_dealer_only
    AND NOT v_use_advisor_own_codes
    AND public.has_module_view('floor_incharge'::text)
    AND NOT public.has_module_view('bodyshop_floor'::text)
    AND NOT public.has_module_modify('bodyshop_floor'::text);

  IF v_is_admin THEN
    RETURN QUERY
    SELECT r.reg_number, r.created_at
      FROM public.service_reception_entries r
     WHERE r.created_at >= p_since
     ORDER BY r.created_at DESC
     LIMIT v_row_limit;
    RETURN;
  END IF;

  IF v_use_advisor_own_codes THEN
    RETURN QUERY
    SELECT r.reg_number, r.created_at
      FROM public.service_reception_entries r
      INNER JOIN public.user_employee_links uel
        ON uel.user_id = auth.uid()
        AND uel.is_active = true
        AND uel.employee_code = r.sa_employee_code
     WHERE r.created_at >= p_since
     ORDER BY r.created_at DESC
     LIMIT v_row_limit;
    RETURN;
  END IF;

  IF v_reception_dealer_only THEN
    RETURN QUERY
    SELECT r.reg_number, r.created_at
      FROM public.service_reception_entries r
     WHERE r.created_at >= p_since
       AND upper(btrim(r.dealer_code)) = ANY (v_dealer_codes)
     ORDER BY r.created_at DESC
     LIMIT v_row_limit;
    RETURN;
  END IF;

  IF v_use_floor_incharge_scope THEN
    RETURN QUERY
    WITH allowed_sa AS MATERIALIZED (
      SELECT DISTINCT upper(btrim(sa.employee_code)) AS sa_code
        FROM public.employee_master sa
       WHERE btrim(coalesce(sa.employee_code, '')) <> ''
         AND public.service_floor_incharge_sa_in_scope(sa.fuel_type, sa.location)
    )
    SELECT r.reg_number, r.created_at
      FROM public.service_reception_entries r
      INNER JOIN allowed_sa a
        ON upper(btrim(r.sa_employee_code)) = a.sa_code
     WHERE r.created_at >= p_since
     ORDER BY r.created_at DESC
     LIMIT v_row_limit;
    RETURN;
  END IF;

  RETURN QUERY
  WITH my_dealers AS MATERIALIZED (
    SELECT v_dealer_codes AS codes
  )
  SELECT r.reg_number, r.created_at
    FROM public.service_reception_entries r
    CROSS JOIN my_dealers md
   WHERE r.created_at >= p_since
     AND (
       coalesce(array_length(md.codes, 1), 0) = 0
       OR upper(btrim(r.dealer_code)) = ANY (md.codes)
     )
     AND public.service_reception_entry_in_summary_scope(
       r.dealer_code,
       r.sa_employee_code,
       r.service_type
     )
   ORDER BY r.created_at DESC
   LIMIT v_row_limit;
END;
$$;


--
-- Name: FUNCTION list_reception_reg_created_since(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_reception_reg_created_since(p_since timestamp with time zone) IS 'Reg numbers + created_at since timestamp. SA own-code gate matches summary RPC; max 10000 rows.';


--
-- Name: lookup_accounts_mechanical_dms_invoice(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_accounts_mechanical_dms_invoice(p_jc_number text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_jc text;
  v_count integer := 0;
  v_row public.psf_revenue_dms%ROWTYPE;
BEGIN
  IF NOT public.accounts_can_access() THEN
    RAISE EXCEPTION 'permission denied: requires accounts view'
      USING ERRCODE = '42501';
  END IF;

  v_jc := upper(btrim(COALESCE(p_jc_number, '')));
  IF v_jc = '' THEN
    RETURN jsonb_build_object(
      'jc_number', NULL,
      'match_count', 0,
      'unique', false,
      'invoice_number', NULL,
      'invoice_date', NULL,
      'total_invoice_amount', NULL
    );
  END IF;

  SELECT COUNT(*)
    INTO v_count
    FROM public.psf_revenue_dms d
   WHERE upper(btrim(d.job_card_number)) = v_jc
     AND COALESCE(d.invoice_status, '') <> 'Cancelled'
     AND NULLIF(btrim(d.invoice_number), '') IS NOT NULL
     AND d.total_invoice_amount IS NOT NULL;

  IF v_count = 1 THEN
    SELECT *
      INTO v_row
      FROM public.psf_revenue_dms d
     WHERE upper(btrim(d.job_card_number)) = v_jc
       AND COALESCE(d.invoice_status, '') <> 'Cancelled'
       AND NULLIF(btrim(d.invoice_number), '') IS NOT NULL
       AND d.total_invoice_amount IS NOT NULL;
  END IF;

  RETURN jsonb_build_object(
    'jc_number', NULLIF(v_jc, ''),
    'match_count', v_count,
    'unique', (v_count = 1),
    'invoice_number', CASE WHEN v_count = 1 THEN NULLIF(btrim(v_row.invoice_number), '') ELSE NULL END,
    'invoice_date', CASE WHEN v_count = 1 THEN to_char(v_row.invoice_date, 'YYYY-MM-DD') ELSE NULL END,
    'total_invoice_amount', CASE WHEN v_count = 1 THEN v_row.total_invoice_amount ELSE NULL END
  );
END;
$$;


--
-- Name: FUNCTION lookup_accounts_mechanical_dms_invoice(p_jc_number text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lookup_accounts_mechanical_dms_invoice(p_jc_number text) IS 'ACCOUNTS-001: Unique live psf_revenue_dms invoice for a mechanical JC. Capture form fill only; does not persist remaining.';


--
-- Name: lookup_customer_phone_from_contact_details(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_customer_phone_from_contact_details(p_chassis_key text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT NULLIF(btrim(c.cell_phone_no), '')
  FROM public.contact_details c
  WHERE NULLIF(upper(btrim(c.chassis_no)), '')
        = NULLIF(upper(btrim(COALESCE(p_chassis_key, ''))), '')
    AND lower(btrim(COALESCE(c.contact_status, ''))) = 'customer'
    AND NULLIF(btrim(c.cell_phone_no), '') IS NOT NULL
  ORDER BY c.created_at DESC NULLS LAST, c.id DESC
  LIMIT 1;
$$;


--
-- Name: FUNCTION lookup_customer_phone_from_contact_details(p_chassis_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lookup_customer_phone_from_contact_details(p_chassis_key text) IS 'Latest Customer contact_details.cell_phone_no for a normalized chassis. Returns NULL when no eligible source row exists.';


--
-- Name: lookup_reception_revisit_prior(text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_reception_revisit_prior(p_reg_number text, p_dealer_code text, p_exclude_entry_id bigint DEFAULT NULL::bigint) RETURNS TABLE(prior_id bigint, prior_sa_employee_code text, prior_sa_name text, prior_jc_number text, prior_service_type text, prior_created_at timestamp with time zone, suggested_technician_code text, suggested_technician_name text)
    LANGUAGE sql STABLE
    AS $$
  WITH prior AS (
    SELECT
      sre.id,
      sre.sa_employee_code,
      sre.sa_name,
      sre.jc_number,
      sre.service_type,
      sre.created_at
    FROM public.service_reception_entries sre
    WHERE sre.dealer_code = p_dealer_code
      AND upper(btrim(sre.reg_number)) = upper(btrim(p_reg_number))
      AND sre.created_at >= (now() - interval '30 days')
      AND public.is_floor_incharge_service_type(sre.service_type)
      AND NULLIF(btrim(sre.jc_number), '') IS NOT NULL
      AND (p_exclude_entry_id IS NULL OR sre.id <> p_exclude_entry_id)
    ORDER BY sre.created_at DESC, sre.id DESC
    LIMIT 1
  )
  SELECT
    prior.id,
    prior.sa_employee_code,
    prior.sa_name,
    prior.jc_number,
    prior.service_type,
    prior.created_at,
    ta.technician_code,
    ta.technician_name
  FROM prior
  LEFT JOIN LATERAL (
    SELECT t.technician_code, t.technician_name
    FROM public.technician_assignments t
    WHERE upper(btrim(t.job_card_number)) = upper(btrim(prior.jc_number))
    ORDER BY t.updated_at DESC NULLS LAST, t.assigned_at DESC, t.id DESC
    LIMIT 1
  ) ta ON true;
$$;


--
-- Name: lookup_updation_for_reg(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_updation_for_reg(p_reg_number text, p_portal text DEFAULT NULL::text) RETURNS TABLE(updation_code text, updation_name text, portal text)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    v.updation_code,
    v.updation_name,
    v.portal
  FROM public.vehicle_updation_data v
  WHERE upper(btrim(v.vehicle_number)) = upper(btrim(p_reg_number))
    AND NULLIF(btrim(v.vehicle_number), '') IS NOT NULL
    AND (
      NULLIF(btrim(p_portal), '') IS NULL
      OR v.portal = p_portal
    )
  ORDER BY v.imported_at DESC, v.id DESC
  LIMIT 1;
$$;


--
-- Name: FUNCTION lookup_updation_for_reg(p_reg_number text, p_portal text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lookup_updation_for_reg(p_reg_number text, p_portal text) IS 'Returns the latest pending updation campaign for a registration number (optional portal filter).';


--
-- Name: mark_all_complaint_notifications_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_complaint_notifications_read() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows integer;
BEGIN
  UPDATE public.complaint_notifications
  SET
    seen_at = COALESCE(seen_at, now()),
    read_at = COALESCE(read_at, now())
  WHERE channel = 'in_app'
    AND read_at IS NULL
    AND dismissed_at IS NULL
    AND (
      recipient_user_id = auth.uid()
      OR (
        public.is_admin()
        AND recipient_user_id IS NULL
        AND public.dealer_code_in_scope(dealer_code)
      )
    );

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  RETURN jsonb_build_object(
    'updated_rows', v_rows
  );
END;
$$;


--
-- Name: mark_all_help_ticket_notifications_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_help_ticket_notifications_read() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE public.help_ticket_notifications
  SET read_at = COALESCE(read_at, now()),
      seen_at = COALESCE(seen_at, now())
  WHERE recipient_user_id = auth.uid()
    AND dismissed_at IS NULL
    AND read_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'updated', v_count);
END;
$$;


--
-- Name: mark_bodyshop_settlement_not_received(integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_bodyshop_settlement_not_received(p_repair_card_id integer, p_party text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_id bigint;
  v_actor text;
BEGIN
  IF NOT public.bodyshop_settlement_can_modify(p_repair_card_id) THEN
    RAISE EXCEPTION 'permission denied: requires bodyshop_repair modify'
      USING ERRCODE = '42501';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason is required' USING ERRCODE = '23514';
  END IF;

  v_id := public._bodyshop_ensure_settlement(p_repair_card_id);
  SELECT a.actor_email INTO v_actor FROM public._bodyshop_settlement_actor() a;

  IF lower(btrim(p_party)) = 'insurance' THEN
    UPDATE public.bodyshop_settlements
       SET do_not_received = true, updated_by = v_actor, updated_at = now()
     WHERE id = v_id;
  ELSIF lower(btrim(p_party)) = 'customer' THEN
    UPDATE public.bodyshop_settlements
       SET customer_not_received = true, updated_by = v_actor, updated_at = now()
     WHERE id = v_id;
  ELSE
    RAISE EXCEPTION 'party must be insurance or customer' USING ERRCODE = '23514';
  END IF;

  PERFORM public.recalc_bodyshop_settlement(v_id);
  RETURN public.get_bodyshop_settlement(p_repair_card_id);
END;
$$;


