--
-- Name: my_sa_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_sa_name() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT nullif(
    btrim(
      coalesce(
        auth.jwt() ->> 'full_name',
        (
          SELECT u.full_name
          FROM public.users u
          WHERE u.id = auth.uid()
          LIMIT 1
        ),
        split_part(coalesce(auth.jwt() ->> 'email', ''), '@', 1)
      )
    ),
    ''
  );
$$;


--
-- Name: normalize_business_role_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_business_role_token(p_token text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN btrim(coalesce(p_token, '')) = '' THEN NULL
    WHEN upper(replace(btrim(p_token), ' ', '_')) IN ('SERVICE_ADVISOR') THEN 'SA'
    WHEN upper(btrim(p_token)) = 'SERVICE ADVISOR' THEN 'SA'
    WHEN upper(replace(btrim(p_token), ' ', '_')) IN ('SSA', 'SENIOR_SERVICE_ADVISOR') THEN 'EDP'
    WHEN upper(btrim(p_token)) = 'SENIOR SERVICE ADVISOR' THEN 'EDP'
    WHEN upper(replace(btrim(p_token), ' ', '_')) = 'SURVEYOR' THEN 'SURVEY'
    WHEN upper(btrim(p_token)) = 'FLOOR INCHARGE' THEN 'FLOOR_INCHARGE'
    WHEN upper(replace(btrim(p_token), ' ', '_')) = 'FLOOR_INCHARGE' THEN 'FLOOR_INCHARGE'
    WHEN upper(btrim(p_token)) = 'DENTOR HELPER' THEN 'DENTOR_HELPER'
    WHEN upper(btrim(p_token)) = 'PAINTER HELPER' THEN 'PAINTER_HELPER'
    WHEN upper(btrim(p_token)) = 'PARTS INCHARGE' THEN 'PARTS_INCHARGE'
    WHEN upper(replace(btrim(p_token), ' ', '_')) = 'DENTER' THEN 'DENTOR'
    ELSE upper(replace(btrim(p_token), ' ', '_'))
  END;
$$;


--
-- Name: FUNCTION normalize_business_role_token(p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalize_business_role_token(p_token text) IS 'RBAC-003: normalize one Business Role token to canonical uppercase form (aliases included).';


--
-- Name: normalize_employee_fuel_bucket(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_employee_fuel_bucket(p_fuel text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN v = '' THEN NULL
    WHEN v IN ('EV')
      OR v LIKE '%ELECTRIC%'
      OR v LIKE '%BATTERY%'
      THEN 'EV'
    WHEN v IN ('PV', 'ICE')
      OR v LIKE '%PETROL%'
      OR v LIKE '%DIESEL%'
      OR v LIKE '%CNG%'
      OR v LIKE '%LPG%'
      OR v LIKE '%GAS%'
      OR v LIKE '%HYBRID%'
      THEN 'PV'
    WHEN v LIKE '%EV%' THEN 'EV'
    ELSE NULL
  END
  FROM (SELECT upper(btrim(coalesce(p_fuel, ''))) AS v) s;
$$;


--
-- Name: FUNCTION normalize_employee_fuel_bucket(p_fuel text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalize_employee_fuel_bucket(p_fuel text) IS 'Map employee_master.fuel_type to EV or PV. Used by Floor Incharge SA scope.';


--
-- Name: normalize_employee_location_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_employee_location_key(p_location text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN v = '' THEN NULL
    WHEN v LIKE '%AJMER%' THEN 'AJMER ROAD'
    WHEN v LIKE '%SITAPURA%' THEN 'SITAPURA'
    ELSE v
  END
  FROM (SELECT upper(btrim(coalesce(p_location, ''))) AS v) s;
$$;


--
-- Name: FUNCTION normalize_employee_location_key(p_location text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalize_employee_location_key(p_location text) IS 'Canonical employee location key (Sitapura / Ajmer Road) for Floor Incharge SA scope.';


--
-- Name: normalize_employee_master_department(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_employee_master_department() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  normalized_no_space text;
BEGIN
  NEW.department := NULLIF(BTRIM(COALESCE(NEW.department, '')), '');

  IF NEW.department IS NULL THEN
    RETURN NEW;
  END IF;

  normalized_no_space := UPPER(REPLACE(NEW.department, ' ', ''));
  IF normalized_no_space = 'BODYSHOP' THEN
    NEW.department := 'BODY SHOP';
  END IF;

  RETURN NEW;
END;
$$;


