--
-- Name: parse_all_service_date_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_all_service_date_text(v text) RETURNS date
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT
    CASE
      WHEN nullif(btrim(v), '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        THEN to_date(nullif(btrim(v), ''), 'YYYY-MM-DD')
      WHEN nullif(btrim(v), '') ~ '^[0-9]{4}/[0-9]{2}/[0-9]{2}$'
        THEN to_date(nullif(btrim(v), ''), 'YYYY/MM/DD')
      WHEN nullif(btrim(v), '') ~ '^[0-9]{2}-[0-9]{2}-[0-9]{4}$'
        THEN to_date(nullif(btrim(v), ''), 'DD-MM-YYYY')
      WHEN nullif(btrim(v), '') ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$'
        THEN to_date(nullif(btrim(v), ''), 'DD/MM/YYYY')
      ELSE NULL
    END;
$_$;


--
-- Name: FUNCTION parse_all_service_date_text(v text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.parse_all_service_date_text(v text) IS 'Parses text date into date with support for YYYY-MM-DD, YYYY/MM/DD, DD-MM-YYYY, DD/MM/YYYY.';


--
-- Name: parse_date_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_date_text(p_text text) RETURNS date
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  v text;
BEGIN
  v := nullif(btrim(coalesce(p_text, '')), '');

  IF v IS NULL THEN
    RETURN NULL;
  END IF;

  IF v ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN
    RETURN to_date(v, 'DD/MM/YYYY');
  ELSIF v ~ '^[0-9]{2}/[0-9]{2}/[0-9]{2}$' THEN
    RETURN to_date(v, 'DD/MM/YY');
  ELSIF v ~ '^[0-9]{2}-[A-Za-z]{3}-[0-9]{4}$' THEN
    RETURN to_date(initcap(lower(v)), 'DD-Mon-YYYY');
  ELSIF v ~ '^[0-9]{2}-[A-Za-z]{3}-[0-9]{2}$' THEN
    RETURN to_date(initcap(lower(v)), 'DD-Mon-YY');
  ELSIF v ~ '^[0-9]{2}-[0-9]{2}-[0-9]{4}$' THEN
    RETURN to_date(v, 'DD-MM-YYYY');
  ELSIF v ~ '^[0-9]{2}-[0-9]{2}-[0-9]{2}$' THEN
    RETURN to_date(v, 'DD-MM-YY');
  ELSIF v ~ '^[0-9]{4}/[0-9]{2}/[0-9]{2}$' THEN
    RETURN to_date(v, 'YYYY/MM/DD');
  ELSIF v ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RETURN to_date(v, 'YYYY-MM-DD');
  END IF;

  RETURN NULL;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$_$;


--
-- Name: parse_datetime_ist(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_datetime_ist(p_text text) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  v text;
  m text[];
  dd integer;
  mm integer;
  yy integer;
  hh integer;
  mi integer;
  ampm text;
  hh24 integer;
BEGIN
  v := nullif(upper(btrim(coalesce(p_text, ''))), '');

  IF v IS NULL THEN
    RETURN NULL;
  END IF;

  m := regexp_match(v, '^([0-9]{2})/([0-9]{2})/([0-9]{4})\s+([0-9]{1,2}):([0-9]{2})\s*(AM|PM)$');

  IF m IS NULL THEN
    RETURN NULL;
  END IF;

  dd := m[1]::integer;
  mm := m[2]::integer;
  yy := m[3]::integer;
  hh := m[4]::integer;
  mi := m[5]::integer;
  ampm := m[6];

  IF hh < 1 OR hh > 12 OR mi < 0 OR mi > 59 THEN
    RETURN NULL;
  END IF;

  IF ampm = 'AM' THEN
    hh24 := CASE WHEN hh = 12 THEN 0 ELSE hh END;
  ELSE
    hh24 := CASE WHEN hh = 12 THEN 12 ELSE hh + 12 END;
  END IF;

  RETURN make_timestamptz(yy, mm, dd, hh24, mi, 0, 'Asia/Kolkata');
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$_$;


--
-- Name: parse_service_history_datetime_ist(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_service_history_datetime_ist(p_text text) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  v text;
  m text[];
  dd integer;
  mm integer;
  yy integer;
  hh integer;
  mi integer;
  ampm text;
  hh24 integer;
BEGIN
  v := nullif(upper(btrim(coalesce(p_text, ''))), '');

  IF v IS NULL THEN
    RETURN NULL;
  END IF;

  m := regexp_match(v, '^([0-9]{2})/([0-9]{2})/([0-9]{4})\s+([0-9]{1,2}):([0-9]{2})\s*(AM|PM)$');

  IF m IS NULL THEN
    RETURN NULL;
  END IF;

  dd := m[1]::integer;
  mm := m[2]::integer;
  yy := m[3]::integer;
  hh := m[4]::integer;
  mi := m[5]::integer;
  ampm := m[6];

  IF hh < 1 OR hh > 12 OR mi < 0 OR mi > 59 THEN
    RETURN NULL;
  END IF;

  IF ampm = 'AM' THEN
    hh24 := CASE WHEN hh = 12 THEN 0 ELSE hh END;
  ELSE
    hh24 := CASE WHEN hh = 12 THEN 12 ELSE hh + 12 END;
  END IF;

  RETURN make_timestamptz(yy, mm, dd, hh24, mi, 0, 'Asia/Kolkata');
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$_$;


