  where id = p_id;
end;
$$;


--
-- Name: payroll_assert_security_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_assert_security_code(p_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_hash text;
  v_locked_until timestamptz;
  v_fail_count integer := 0;
  v_match boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT s.locked_until, s.fail_count
    INTO v_locked_until, v_fail_count
  FROM public.payroll_security_attempt_state s
  WHERE s.user_id = v_uid;

  IF v_locked_until IS NOT NULL AND v_locked_until > now() THEN
    RAISE EXCEPTION 'Incorrect security code.';
  END IF;

  SELECT security_code_hash INTO v_hash
  FROM public.payroll_security_settings
  WHERE id = 1;

  IF v_hash IS NOT NULL
     AND trim(coalesce(p_code, '')) <> ''
     AND v_hash = extensions.crypt(p_code, v_hash) THEN
    v_match := true;
  END IF;

  IF NOT v_match THEN
    INSERT INTO public.payroll_security_attempt_state (user_id, fail_count, locked_until)
    VALUES (
      v_uid,
      1,
      CASE WHEN 1 >= 5 THEN now() + interval '5 minutes' ELSE NULL END
    )
    ON CONFLICT (user_id) DO UPDATE
    SET fail_count = public.payroll_security_attempt_state.fail_count + 1,
        locked_until = CASE
          WHEN public.payroll_security_attempt_state.fail_count + 1 >= 5
            THEN now() + interval '5 minutes'
          ELSE public.payroll_security_attempt_state.locked_until
        END;

    INSERT INTO public.audit_logs (actor_id, action, resource_type, resource_id, details)
    VALUES (
      v_uid,
      'payroll_security_code_failed',
      'payroll_security',
      NULL,
      jsonb_build_object('at', now())
    );

    RAISE EXCEPTION 'Incorrect security code.';
  END IF;

  INSERT INTO public.payroll_security_attempt_state (user_id, fail_count, locked_until)
  VALUES (v_uid, 0, NULL)
  ON CONFLICT (user_id) DO UPDATE
  SET fail_count = 0, locked_until = NULL;
END;
$$;


--
-- Name: payroll_calc_earned_base(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_calc_earned_base(p_base_salary numeric, p_payable_days numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_base_salary IS NULL OR p_base_salary <= 0 OR p_payable_days IS NULL OR p_payable_days <= 0 THEN 0
    ELSE round((p_base_salary / 30.0) * p_payable_days, 0)
  END;
$$;


--
-- Name: payroll_can_mutate_payroll(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_can_mutate_payroll() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.is_admin()
    OR (
      public.has_module_modify('payroll')
      AND public.payroll_has_security_grant()
    );
$$;


--
-- Name: payroll_create_salary_type_employee(text, text, text, text, text, text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_create_salary_type_employee(p_employee_code text, p_employee_name text, p_department text, p_location text, p_role text, p_fuel_type text, p_account_number text, p_ifsc text, p_bank_name text, p_base_salary numeric, p_salary_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_code text := upper(btrim(coalesce(p_employee_code, '')));
  v_name text := btrim(coalesce(p_employee_name, ''));
  v_dept text := nullif(btrim(coalesce(p_department, '')), '');
  v_loc text := nullif(btrim(coalesce(p_location, '')), '');
  v_role text := nullif(btrim(coalesce(p_role, '')), '');
  v_fuel text := nullif(btrim(coalesce(p_fuel_type, '')), '');
  v_account text := nullif(btrim(coalesce(p_account_number, '')), '');
  v_ifsc text := nullif(upper(btrim(coalesce(p_ifsc, ''))), '');
  v_bank text := nullif(btrim(coalesce(p_bank_name, '')), '');
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Unauthorized: create employee from payroll requires admin';
  END IF;

  IF v_code = '' THEN
    RAISE EXCEPTION 'Employee code is required';
  END IF;

  IF v_name = '' THEN
    RAISE EXCEPTION 'Employee name is required';
  END IF;

  IF p_base_salary IS NULL OR p_base_salary < 0 THEN
    RAISE EXCEPTION 'Invalid base salary';
  END IF;

  IF p_salary_type IS NULL OR p_salary_type NOT IN ('base', 'variable', 'both') THEN
    RAISE EXCEPTION 'Invalid salary type';
  END IF;

  IF v_ifsc IS NOT NULL AND v_ifsc !~ '^[A-Z]{4}0[A-Z0-9]{6}$' THEN
    RAISE EXCEPTION 'Invalid IFSC';
  END IF;

  IF v_account IS NOT NULL AND (v_account ~* 'e[+\-]' OR v_account ~ '^\d+\.\d+$') THEN
    RAISE EXCEPTION 'Unsafe bank account format';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.employee_master em
    WHERE upper(btrim(em.employee_code)) = v_code
  ) THEN
    RAISE EXCEPTION 'Employee code already exists';
  END IF;

  INSERT INTO public.employee_master (
    employee_code,
    employee_name,
    department,
    location,
    role,
    fuel_type,
    account_number,
    ifsc,
    bank_name
  )
  VALUES (
    v_code,
    v_name,
    v_dept,
    v_loc,
    v_role,
    v_fuel,
    v_account,
    v_ifsc,
    v_bank
  );

  INSERT INTO public.payroll_compensation (employee_code, base_salary, salary_type, updated_at)
  VALUES (v_code, p_base_salary, p_salary_type, now());

  RETURN jsonb_build_object('ok', true, 'employee_code', v_code);
END;
$_$;


--
-- Name: payroll_finalize_month(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_finalize_month(p_month date, p_actor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_month date := date_trunc('month', p_month)::date;
BEGIN
  IF NOT (public.is_admin() OR public.has_module_modify('payroll')) THEN
    RAISE EXCEPTION 'Unauthorized: payroll finalize requires modify permission';
  END IF;

  IF NOT public.is_admin() AND NOT public.payroll_has_security_grant() THEN
    RAISE EXCEPTION 'Unauthorized: payroll finalize requires security verification';
  END IF;

  IF public.payroll_is_month_finalized(v_month) THEN
    RAISE EXCEPTION 'Payroll month % is already finalized', v_month;
  END IF;

  INSERT INTO payroll_months (payroll_month, status, finalized_at, finalized_by, updated_at)
  VALUES (v_month, 'finalized', now(), p_actor, now())
  ON CONFLICT (payroll_month) DO UPDATE
  SET status = 'finalized', finalized_at = now(), finalized_by = p_actor,
      unlock_reason = NULL, unlocked_at = NULL, unlocked_by = NULL, updated_at = now();

  UPDATE payroll_advance_schedules pas
  SET applied_amount = pas.scheduled_amount, status = 'applied', updated_at = now()
  FROM payroll_entries pe
  WHERE pas.payroll_month = v_month
    AND pas.status = 'pending'
    AND pas.scheduled_amount > 0
    AND EXISTS (
      SELECT 1 FROM payroll_advances pa
      WHERE pa.id = pas.advance_id
        AND upper(trim(pa.employee_code)) = upper(trim(pe.employee_code))
        AND pe.payroll_month = v_month
        AND pe.advance_deduction >= pas.scheduled_amount
    );

  UPDATE payroll_advances pa
  SET recovered_amount = sub.total_applied,
      status = CASE WHEN sub.total_applied >= pa.original_amount THEN 'closed' ELSE pa.status END,
      updated_at = now()
  FROM (
    SELECT advance_id, sum(applied_amount) AS total_applied
    FROM payroll_advance_schedules
    WHERE status = 'applied'
    GROUP BY advance_id
  ) sub
  WHERE pa.id = sub.advance_id;

  RETURN jsonb_build_object('payroll_month', v_month, 'status', 'finalized');
END;
$$;


--
-- Name: payroll_has_security_grant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_has_security_grant() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.payroll_security_grants g
    WHERE g.user_id = auth.uid()
      AND g.expires_at > now()
  );
$$;


--
-- Name: payroll_is_month_finalized(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_is_month_finalized(p_month date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT status = 'finalized' FROM payroll_months WHERE payroll_month = date_trunc('month', p_month)::date),
    false
  );
$$;


--
-- Name: payroll_is_variable_disbursement_blocked(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_is_variable_disbursement_blocked(p_employee_code text, p_month date) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_month date := date_trunc('month', p_month)::date;
  v_finalized boolean;
  v_salary_type text;
  v_has_variable_entry boolean;
BEGIN
  IF NOT public.payroll_is_month_finalized(v_month) THEN
    RETURN false;
  END IF;

  SELECT pc.salary_type INTO v_salary_type
  FROM payroll_compensation pc
  WHERE upper(trim(pc.employee_code)) = upper(trim(p_employee_code));

  IF v_salary_type IS NULL OR v_salary_type = 'base' THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM payroll_entries pe
    WHERE upper(trim(pe.employee_code)) = upper(trim(p_employee_code))
      AND pe.payroll_month = v_month
      AND pe.variable_earning_total > 0
  ) INTO v_has_variable_entry;

  RETURN v_has_variable_entry;
END;
$$;


--
-- Name: payroll_save_salary_type_master(text, text, text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_save_salary_type_master(p_employee_code text, p_department text, p_location text, p_account_number text, p_ifsc text, p_bank_name text, p_base_salary numeric, p_salary_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_code text := upper(btrim(coalesce(p_employee_code, '')));
  v_dept text := nullif(btrim(coalesce(p_department, '')), '');
  v_loc text := nullif(btrim(coalesce(p_location, '')), '');
  v_account text := nullif(btrim(coalesce(p_account_number, '')), '');
  v_ifsc text := nullif(upper(btrim(coalesce(p_ifsc, ''))), '');
  v_bank text := nullif(btrim(coalesce(p_bank_name, '')), '');
  v_updated int;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Unauthorized: salary type master save requires admin';
  END IF;

  IF v_code = '' THEN
    RAISE EXCEPTION 'Employee code is required';
  END IF;

  IF p_base_salary IS NULL OR p_base_salary < 0 THEN
    RAISE EXCEPTION 'Invalid base salary';
  END IF;

  IF p_salary_type IS NULL OR p_salary_type NOT IN ('base', 'variable', 'both') THEN
    RAISE EXCEPTION 'Invalid salary type';
  END IF;

  IF v_ifsc IS NOT NULL AND v_ifsc !~ '^[A-Z]{4}0[A-Z0-9]{6}$' THEN
    RAISE EXCEPTION 'Invalid IFSC';
  END IF;

  IF v_account IS NOT NULL AND (v_account ~* 'e[+\-]' OR v_account ~ '^\d+\.\d+$') THEN
    RAISE EXCEPTION 'Unsafe bank account format';
  END IF;

  UPDATE public.employee_master
  SET
    department = v_dept,
    location = v_loc,
    account_number = v_account,
    ifsc = v_ifsc,
    bank_name = v_bank
  WHERE upper(btrim(employee_code)) = v_code;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'Employee not found';
  END IF;

  INSERT INTO public.payroll_compensation (employee_code, base_salary, salary_type, updated_at)
  VALUES (v_code, p_base_salary, p_salary_type, now())
  ON CONFLICT (employee_code) DO UPDATE
  SET
    base_salary = EXCLUDED.base_salary,
    salary_type = EXCLUDED.salary_type,
    updated_at = now();

  RETURN jsonb_build_object('ok', true, 'employee_code', v_code);
END;
$_$;


--
-- Name: payroll_security_grant_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_security_grant_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_expires timestamptz;
BEGIN
  SELECT g.expires_at INTO v_expires
  FROM public.payroll_security_grants g
  WHERE g.user_id = auth.uid()
    AND g.expires_at > now();

  RETURN jsonb_build_object(
    'active', v_expires IS NOT NULL,
    'expires_at', v_expires
  );
END;
$$;


--
-- Name: payroll_set_employee_active(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_set_employee_active(p_employee_code text, p_is_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_code text := upper(btrim(coalesce(p_employee_code, '')));
  v_updated int;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Unauthorized: employee activate/deactivate requires admin';
  END IF;

  IF v_code = '' THEN
    RAISE EXCEPTION 'Employee code is required';
  END IF;

  IF p_is_active IS NULL THEN
    RAISE EXCEPTION 'is_active is required';
  END IF;

  UPDATE public.employee_master
  SET is_active = p_is_active
  WHERE upper(btrim(employee_code)) = v_code;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'Employee not found';
  END IF;

  RETURN jsonb_build_object('ok', true, 'employee_code', v_code, 'is_active', p_is_active);
END;
$$;


--
-- Name: payroll_set_security_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_set_security_code(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_jwt_role text := coalesce(current_setting('request.jwt.claim.role', true), '');
  v_has_jwt boolean := auth.uid() IS NOT NULL
    OR nullif(current_setting('request.jwt.claim.sub', true), '') IS NOT NULL;
BEGIN
  IF NOT (
    public.is_admin()
    OR v_jwt_role = 'service_role'
    OR coalesce(auth.role(), '') = 'service_role'
    OR NOT v_has_jwt
  ) THEN
    RAISE EXCEPTION 'Unauthorized: setting the payroll security code requires admin';
  END IF;

  IF trim(coalesce(p_code, '')) = '' THEN
    RAISE EXCEPTION 'Security code is required';
  END IF;

  INSERT INTO public.payroll_security_settings (id, security_code_hash, updated_at, updated_by)
  VALUES (1, extensions.crypt(p_code, extensions.gen_salt('bf')), now(), auth.uid())
  ON CONFLICT (id) DO UPDATE
  SET security_code_hash = EXCLUDED.security_code_hash,
      updated_at = now(),
      updated_by = auth.uid();

  RETURN jsonb_build_object('ok', true, 'updated_at', now());
END;
$$;


--
-- Name: payroll_unlock_month(date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_unlock_month(p_month date, p_reason text, p_security_code text, p_actor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_month date := date_trunc('month', p_month)::date;
  v_uid uuid := auth.uid();
  v_reason text := trim(coalesce(p_reason, ''));
BEGIN
  IF NOT (public.is_admin() OR public.has_module_delete('payroll')) THEN
    RAISE EXCEPTION 'Unauthorized: payroll unlock requires delete permission';
  END IF;

  IF v_reason = '' THEN
    RAISE EXCEPTION 'Unlock reason is required';
  END IF;

  -- Fresh code for every caller, including admin. Does not issue a draft-edit grant.
  PERFORM public.payroll_assert_security_code(p_security_code);

  IF NOT public.payroll_is_month_finalized(v_month) THEN
    RAISE EXCEPTION 'Payroll month % is not finalized', v_month;
  END IF;

  UPDATE public.payroll_advance_schedules
  SET status = 'pending',
      applied_amount = 0,
      updated_at = now()
  WHERE payroll_month = v_month
    AND status = 'applied';

  UPDATE public.payroll_advances pa
  SET recovered_amount = COALESCE(sub.total_applied, 0),
      status = CASE
        WHEN pa.status = 'cancelled' THEN pa.status
        WHEN COALESCE(sub.total_applied, 0) >= pa.original_amount THEN 'closed'
        WHEN pa.status = 'closed' AND COALESCE(sub.total_applied, 0) < pa.original_amount THEN 'active'
        ELSE pa.status
      END,
      updated_at = now()
  FROM (
    SELECT pas.advance_id,
           COALESCE(sum(pas.applied_amount) FILTER (WHERE pas.status = 'applied'), 0) AS total_applied
    FROM public.payroll_advance_schedules pas
    WHERE pas.advance_id IN (
      SELECT s2.advance_id
      FROM public.payroll_advance_schedules s2
      WHERE s2.payroll_month = v_month
    )
    GROUP BY pas.advance_id
  ) sub
  WHERE pa.id = sub.advance_id;

  UPDATE public.payroll_months
  SET status = 'draft',
      unlock_reason = v_reason,
      unlocked_at = now(),
      unlocked_by = p_actor,
      updated_at = now()
  WHERE payroll_month = v_month
    AND status = 'finalized';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payroll month % is not finalized', v_month;
  END IF;

  INSERT INTO public.audit_logs (actor_id, action, resource_type, resource_id, details)
  VALUES (
    v_uid,
    'payroll_month_unlocked',
    'payroll_month',
    v_month::text,
    jsonb_build_object(
      'payroll_month', v_month,
      'reason', v_reason,
      'actor', p_actor,
      'previous_status', 'finalized',
      'resulting_status', 'draft'
    )
  );

  RETURN jsonb_build_object('payroll_month', v_month, 'status', 'draft');
END;
$$;


--
-- Name: payroll_verify_security_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_verify_security_code(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_expires timestamptz := now() + interval '30 minutes';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF NOT (public.is_admin() OR public.has_module_modify('payroll')) THEN
    RAISE EXCEPTION 'Unauthorized: payroll security verification requires modify permission';
  END IF;

  PERFORM public.payroll_assert_security_code(p_code);

  INSERT INTO public.payroll_security_grants (user_id, issued_at, expires_at)
  VALUES (v_uid, now(), v_expires)
  ON CONFLICT (user_id) DO UPDATE
  SET issued_at = now(), expires_at = EXCLUDED.expires_at;

  RETURN jsonb_build_object('ok', true, 'expires_at', v_expires);
END;
$$;


--
-- Name: prevent_bodyshop_reception_link_drift(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_bodyshop_reception_link_drift() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.reception_entry_id IS NOT NULL THEN
    -- Block unlink of an already linked card.
    IF NEW.reception_entry_id IS NULL THEN
      RAISE EXCEPTION
        'Cannot set reception_entry_id to NULL for bodyshop_repair_cards.id=%; delete/close card with explicit workflow instead.',
        OLD.id;
    END IF;

    -- Block re-link to a different reception row.
    IF NEW.reception_entry_id IS DISTINCT FROM OLD.reception_entry_id THEN
      RAISE EXCEPTION
        'Cannot change reception_entry_id for bodyshop_repair_cards.id=% from % to %.',
        OLD.id, OLD.reception_entry_id, NEW.reception_entry_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_bodyshop_settlement_line_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_bodyshop_settlement_line_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'bodyshop_settlement_lines are append-only; reverse via RPC'
      USING ERRCODE = '25006';
  END IF;

  IF OLD.voucher_no IS NULL
     AND NEW.voucher_no IS NOT NULL
     AND NEW.id IS NOT DISTINCT FROM OLD.id
     AND NEW.settlement_id IS NOT DISTINCT FROM OLD.settlement_id
     AND NEW.repair_card_id IS NOT DISTINCT FROM OLD.repair_card_id
     AND NEW.party IS NOT DISTINCT FROM OLD.party
     AND NEW.line_type IS NOT DISTINCT FROM OLD.line_type
     AND NEW.component IS NOT DISTINCT FROM OLD.component
     AND NEW.amount IS NOT DISTINCT FROM OLD.amount
     AND NEW.txn_date IS NOT DISTINCT FROM OLD.txn_date
     AND NEW.reference IS NOT DISTINCT FROM OLD.reference
     AND NEW.remarks IS NOT DISTINCT FROM OLD.remarks
     AND NEW.reverses_line_id IS NOT DISTINCT FROM OLD.reverses_line_id
     AND NEW.is_reversed IS NOT DISTINCT FROM OLD.is_reversed
     AND NEW.actor_id IS NOT DISTINCT FROM OLD.actor_id
     AND NEW.actor_email IS NOT DISTINCT FROM OLD.actor_email
     AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at
     AND NEW.import_row_token IS NOT DISTINCT FROM OLD.import_row_token
     AND NEW.payment_mode IS NOT DISTINCT FROM OLD.payment_mode
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'bodyshop_settlement_lines are append-only; reverse via RPC'
    USING ERRCODE = '25006';
END;
$$;


--
-- Name: FUNCTION prevent_bodyshop_settlement_line_mutation(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prevent_bodyshop_settlement_line_mutation() IS 'Append-only settlement lines. DELETE and general UPDATE remain blocked. DBL-0080 allows voucher_no NULL→value when no other column changes. Reverse still uses _bodyshop_settlement_mark_line_reversed.';


--
-- Name: process_all_service_history_sync_queue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_all_service_history_sync_queue(p_batch_size integer DEFAULT 50) RETURNS TABLE(processed_count integer, remaining_due_count integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_rec record;
  v_processed integer := 0;
  v_batch integer := greatest(coalesce(p_batch_size, 50), 1);
  v_started timestamptz := clock_timestamp();
  v_max_ms constant integer := 60000;
begin
  for v_rec in
    select q.chassis_key
    from public.all_service_history_sync_queue q
    where q.not_before <= now()
    order by q.not_before asc, q.chassis_key asc
    limit v_batch
    for update skip locked
  loop
    if (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer >= v_max_ms then
      exit;
    end if;

    perform public.refresh_all_service_data_from_service_history(v_rec.chassis_key);
    delete from public.all_service_history_sync_queue
    where chassis_key = v_rec.chassis_key;
    v_processed := v_processed + 1;
  end loop;

  return query
  select
    v_processed,
    (
      select count(*)::integer
      from public.all_service_history_sync_queue q
      where q.not_before <= now()
    ) as remaining_due_count;
end;
$$;


--
-- Name: FUNCTION process_all_service_history_sync_queue(p_batch_size integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.process_all_service_history_sync_queue(p_batch_size integer) IS 'Processes due chassis refresh requests from queue with bounded batch size (default 50) and 60s wall-clock budget per invocation. Internal use only (pg_cron / service_role).';


--
-- Name: process_next_psf_import_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_next_psf_import_run() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id bigint;
begin
  select r.id
  into v_run_id
  from public.psf_import_runs r
  where r.status = 'queued'
  order by r.id asc
  for update skip locked
  limit 1;

  if v_run_id is null then
    return null;
  end if;

  perform public.process_psf_import_run(v_run_id);
  return v_run_id;
end;
$$;


--
-- Name: process_psf_import_run(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_psf_import_run(p_import_run_id bigint) RETURNS TABLE(import_run_id bigint, status text, total_rows integer, staged_rows integer, valid_rows integer, inserted_rows integer, updated_rows integer, skipped_rows integer, rejected_rows integer, error_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id bigint := p_import_run_id;
  v_total_rows integer := 0;
  v_staged_rows integer := 0;
  v_valid_rows integer := 0;
  v_inserted_rows integer := 0;
  v_updated_rows integer := 0;
  v_skipped_rows integer := 0;
  v_rejected_rows integer := 0;
begin
  if v_run_id is null then
    raise exception 'import_run_id is required';
  end if;

  update public.psf_import_runs
  set
    status = 'running',
    started_at = coalesce(started_at, now()),
    completed_at = null,
    error_message = null
  where id = v_run_id
    and public.psf_import_runs.status in ('queued', 'running');

  select r.total_rows
  into v_total_rows
  from public.psf_import_runs r
  where r.id = v_run_id;

  if v_total_rows is null then
    raise exception 'psf_import_runs id % not found', v_run_id;
  end if;

  select count(*) into v_staged_rows
  from public.psf_import_staging s
  where s.import_run_id = v_run_id;

  with staged as (
    select
      s.*,
      nullif(btrim(em.location), '') as em_location,
      public.psf_normalize_portal(em.fuel_type) as em_portal,
      coalesce(
        nullif(btrim(em.location), ''),
        public.psf_fallback_location(s.employee_code),
        nullif(btrim(s.location), '')
      ) as resolved_location,
      coalesce(
        public.psf_normalize_portal(em.fuel_type),
        public.psf_fallback_portal(s.employee_code),
        public.psf_normalize_portal(s.portal)
      ) as resolved_portal
    from public.psf_import_staging s
    left join public.employee_master em
      on upper(btrim(coalesce(em.employee_code, ''))) = upper(btrim(coalesce(s.employee_code, '')))
    where s.import_run_id = v_run_id
  ),
  valid_dedup as (
    select distinct on (
      upper(btrim(coalesce(resolved_location, ''))),
      upper(btrim(coalesce(resolved_portal, ''))),
      upper(btrim(coalesce(job_card_number, ''))),
      invoice_date
    )
      *
    from staged
    where
      resolved_location is not null and btrim(resolved_location) <> ''
      and resolved_portal in ('PV', 'EV')
      and job_card_number is not null and btrim(job_card_number) <> ''
      and invoice_date is not null
    order by
      upper(btrim(coalesce(resolved_location, ''))),
      upper(btrim(coalesce(resolved_portal, ''))),
      upper(btrim(coalesce(job_card_number, ''))),
      invoice_date,
      row_number desc
  ),
  existing as (
    select
      v.id as staging_id,
      t.id as target_id,
      (
        t.branch is distinct from v.resolved_location
        or t.branch_label is distinct from v.resolved_location
        or t.location is distinct from v.resolved_location
        or t.portal is distinct from v.resolved_portal
        or t.sr_type is distinct from v.sr_type
        or t.chassis_number is distinct from v.chassis_number
        or t.final_labour_amount is distinct from v.final_labour_amount
        or t.final_spares_amount is distinct from v.final_spares_amount
        or t.total_invoice_amount is distinct from v.total_invoice_amount
        or t.parent_product_line is distinct from v.parent_product_line
        or t.product_line is distinct from v.product_line
        or t.created_date_time is distinct from v.created_date_time
        or t.closed_date_time is distinct from v.closed_date_time
        or t.first_name is distinct from v.first_name
        or t.last_name is distinct from v.last_name
        or t.sr_assigned_to is distinct from v.sr_assigned_to
        or t.employee_code is distinct from v.employee_code
        or t.vehicle_registration_number is distinct from v.vehicle_registration_number
        or t.vehicle_sale_date is distinct from v.vehicle_sale_date
        or t.account_phone_number is distinct from v.account_phone_number
        or t.lubs_revenue is distinct from v.lubs_revenue
        or t.kms_run is distinct from v.kms_run
        or t.last_service_km is distinct from v.last_service_km
        or t.last_service_date is distinct from v.last_service_date
      ) as needs_update
    from valid_dedup v
    join public.job_card_closed_data t
      on t.location = v.resolved_location
      and t.portal = v.resolved_portal
      and upper(btrim(t.job_card_number)) = upper(btrim(v.job_card_number))
      and t.invoice_date = v.invoice_date
  ),
  do_update as (
    update public.job_card_closed_data t
    set
      branch = v.resolved_location,
      branch_label = v.resolved_location,
      location = v.resolved_location,
      portal = v.resolved_portal,
      job_card_number = v.job_card_number,
      sr_type = v.sr_type,
      chassis_number = v.chassis_number,
      final_labour_amount = v.final_labour_amount,
      final_spares_amount = v.final_spares_amount,
      total_invoice_amount = v.total_invoice_amount,
      parent_product_line = v.parent_product_line,
      product_line = v.product_line,
      created_date_time = v.created_date_time,
      closed_date_time = v.closed_date_time,
      invoice_date = v.invoice_date,
      first_name = v.first_name,
      last_name = v.last_name,
      sr_assigned_to = v.sr_assigned_to,
      employee_code = v.employee_code,
      vehicle_registration_number = v.vehicle_registration_number,
      vehicle_sale_date = v.vehicle_sale_date,
      account_phone_number = v.account_phone_number,
      lubs_revenue = v.lubs_revenue,
      kms_run = v.kms_run,
      last_service_km = v.last_service_km,
      last_service_date = v.last_service_date
    from valid_dedup v
    join existing e
      on e.staging_id = v.id
    where
      e.target_id = t.id
      and e.needs_update
    returning t.id
  ),
  do_insert as (
    insert into public.job_card_closed_data (
      branch,
      branch_label,
      location,
      portal,
      job_card_number,
      sr_type,
      chassis_number,
      final_labour_amount,
      final_spares_amount,
      total_invoice_amount,
      parent_product_line,
      product_line,
      created_date_time,
      closed_date_time,
      invoice_date,
      first_name,
      last_name,
      sr_assigned_to,
      employee_code,
      vehicle_registration_number,
      vehicle_sale_date,
      account_phone_number,
      lubs_revenue,
      kms_run,
      last_service_km,
      last_service_date
    )
    select
      v.resolved_location,
      v.resolved_location,
      v.resolved_location,
      v.resolved_portal,
      v.job_card_number,
      v.sr_type,
      v.chassis_number,
      v.final_labour_amount,
      v.final_spares_amount,
      v.total_invoice_amount,
      v.parent_product_line,
      v.product_line,
      v.created_date_time,
      v.closed_date_time,
      v.invoice_date,
      v.first_name,
      v.last_name,
      v.sr_assigned_to,
      v.employee_code,
      v.vehicle_registration_number,
      v.vehicle_sale_date,
      v.account_phone_number,
      v.lubs_revenue,
      v.kms_run,
      v.last_service_km,
      v.last_service_date
    from valid_dedup v
    left join existing e
      on e.staging_id = v.id
    where e.staging_id is null
    returning id
  )
  select
    (select count(*) from valid_dedup),
    (select count(*) from do_insert),
    (select count(*) from do_update),
    (select count(*) from existing where not needs_update)
  into
    v_valid_rows,
    v_inserted_rows,
    v_updated_rows,
    v_skipped_rows;

  v_rejected_rows := greatest(v_staged_rows - v_valid_rows, 0);

  delete from public.psf_import_staging s
  where s.import_run_id = v_run_id;

  update public.psf_import_runs
  set
    status = 'completed',
    staged_rows = v_staged_rows,
    valid_rows = v_valid_rows,
    inserted_rows = v_inserted_rows,
    updated_rows = v_updated_rows,
    skipped_rows = v_skipped_rows,
    rejected_rows = v_rejected_rows,
    completed_at = now(),
    error_message = null
  where id = v_run_id;

  insert into public.import_metadata (table_name, last_updated_at)
  values ('job_card_closed_data', now())
  on conflict (table_name)
  do update set last_updated_at = excluded.last_updated_at;

  return query
  select
    v_run_id,
    'completed'::text,
    v_total_rows,
    v_staged_rows,
    v_valid_rows,
    v_inserted_rows,
    v_updated_rows,
    v_skipped_rows,
    v_rejected_rows,
    null::text;
exception
  when others then
    if v_run_id is not null then
      update public.psf_import_runs
      set
        status = 'failed',
        error_message = sqlerrm,
        completed_at = now()
      where id = v_run_id;
    end if;

    return query
    select
      coalesce(v_run_id, 0),
      'failed'::text,
      coalesce(v_total_rows, 0),
      coalesce(v_staged_rows, 0),
      coalesce(v_valid_rows, 0),
      coalesce(v_inserted_rows, 0),
      coalesce(v_updated_rows, 0),
      coalesce(v_skipped_rows, 0),
      coalesce(v_rejected_rows, 0),
      sqlerrm;
end;
$$;


--
-- Name: psf_add_remark(bigint, text, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_add_remark(p_feedback_id bigint, p_remark text, p_next_follow_up_date date DEFAULT NULL::date, p_set_next_follow_up_date boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_name text;
begin
  if not (public.is_admin() or public.has_module_modify('post_service_feedback_cre')) then
    raise exception 'Insufficient permissions';
  end if;

  if p_remark is null or btrim(p_remark) = '' then
    raise exception 'Remark cannot be empty';
  end if;

  select coalesce(u.full_name, auth.jwt()->>'email')
  into v_actor_name
  from public.users u
  where u.id = auth.uid();

  if v_actor_name is null then
    v_actor_name := coalesce(auth.jwt()->>'email', 'Unknown');
  end if;

  insert into public.post_service_feedback_remarks
    (feedback_id, remark, created_by_id, created_by_name, is_resolution)
  values
    (p_feedback_id, btrim(p_remark), auth.uid(), v_actor_name, false);

  update public.post_service_feedback_messages
  set cre_status = case when cre_status = 'open' then 'in_progress' else cre_status end,
      next_follow_up_date = case
        when p_set_next_follow_up_date then p_next_follow_up_date
        else next_follow_up_date
      end,
      remarked_at = now(),
      updated_at = now()
  where id = p_feedback_id;

  if not found then
    raise exception 'Feedback row not found: %', p_feedback_id;
  end if;

  return jsonb_build_object('ok', true, 'actor_name', v_actor_name);
end;
$$;


--
-- Name: FUNCTION psf_add_remark(p_feedback_id bigint, p_remark text, p_next_follow_up_date date, p_set_next_follow_up_date boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.psf_add_remark(p_feedback_id bigint, p_remark text, p_next_follow_up_date date, p_set_next_follow_up_date boolean) IS 'Logs a CRE call remark and optionally replaces the case next_follow_up_date. When p_set_next_follow_up_date is false the existing date is left unchanged, including when another remark is added. Actor/timestamp are server-derived.';


--
-- Name: psf_fallback_location(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_fallback_location(p_employee_code text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_employee_code is null then null
    when upper(p_employee_code) like '%500A840%' then 'Sitapura'
    when upper(p_employee_code) like '%3000840%' then 'Sitapura'
    when upper(p_employee_code) like '%3001440%' then 'Ajmer Road'
    else null
  end
$$;


--
-- Name: psf_fallback_portal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_fallback_portal(p_employee_code text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_employee_code is null then null
    when upper(p_employee_code) like '%500A840%' then 'EV'
    when upper(p_employee_code) like '%3000840%' then 'PV'
    when upper(p_employee_code) like '%3001440%' then 'PV'
    else null
  end
$$;


--
-- Name: psf_get_today_productivity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_get_today_productivity() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_today_start timestamptz;
  v_today_end timestamptz;
  v_res jsonb;
begin
  v_today_start := (timezone('Asia/Kolkata', now())::date)::timestamp at time zone 'Asia/Kolkata';
  v_today_end := v_today_start + interval '1 day' - interval '1 microsecond';

  select jsonb_build_object(
    'positive', count(*) filter (where rating_at >= v_today_start and rating_at <= v_today_end and effective_rating >= 4),
    'needsFollowup', count(*) filter (where rating_at >= v_today_start and rating_at <= v_today_end and effective_rating <= 3),
    'inProgress', count(*) filter (where remarked_at >= v_today_start and remarked_at <= v_today_end and cre_status = 'in_progress'),
    'resolved', count(*) filter (where resolved_at >= v_today_start and resolved_at <= v_today_end and cre_status = 'resolved'),
    'total', count(*) filter (where
      (remarked_at >= v_today_start and remarked_at <= v_today_end)
      or (rating_at >= v_today_start and rating_at <= v_today_end)
      or (resolved_at >= v_today_start and resolved_at <= v_today_end)
    )
  ) into v_res
  from public.post_service_feedback_messages;

  return coalesce(v_res, '{"positive": 0, "needsFollowup": 0, "inProgress": 0, "resolved": 0, "total": 0}'::jsonb);
end;
$$;


--
-- Name: psf_mark_resolved(bigint, text, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_mark_resolved(p_feedback_id bigint, p_remark text, p_next_follow_up_date date DEFAULT NULL::date, p_set_next_follow_up_date boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor_name text;
  v_now timestamptz := now();
begin
  if not (public.is_admin() or public.has_module_modify('post_service_feedback_cre')) then
    raise exception 'Insufficient permissions';
  end if;

  if p_remark is null or btrim(p_remark) = '' then
    raise exception 'A closing remark is required to mark this resolved';
  end if;

  select coalesce(u.full_name, auth.jwt()->>'email')
  into v_actor_name
  from public.users u
  where u.id = auth.uid();

  if v_actor_name is null then
    v_actor_name := coalesce(auth.jwt()->>'email', 'Unknown');
  end if;

  insert into public.post_service_feedback_remarks
    (feedback_id, remark, created_by_id, created_by_name, is_resolution)
  values
    (p_feedback_id, btrim(p_remark), auth.uid(), v_actor_name, true);

  -- Resolution does not clear next_follow_up_date. The date stays for history.
  -- Today's Follow-ups excludes cre_status = resolved.
  update public.post_service_feedback_messages
  set cre_status = 'resolved',
      resolved_at = v_now,
      resolved_by_id = auth.uid(),
      resolved_by_name = v_actor_name,
      next_follow_up_date = case
        when p_set_next_follow_up_date then p_next_follow_up_date
        else next_follow_up_date
      end,
      updated_at = v_now
  where id = p_feedback_id;

  if not found then
    raise exception 'Feedback row not found: %', p_feedback_id;
  end if;

  return jsonb_build_object('ok', true, 'resolved_at', v_now, 'resolved_by_name', v_actor_name);
end;
$$;


--
-- Name: FUNCTION psf_mark_resolved(p_feedback_id bigint, p_remark text, p_next_follow_up_date date, p_set_next_follow_up_date boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.psf_mark_resolved(p_feedback_id bigint, p_remark text, p_next_follow_up_date date, p_set_next_follow_up_date boolean) IS 'Marks a post_service_feedback_messages row resolved with a closing remark. Does not clear next_follow_up_date unless the caller explicitly sets a new value. resolved_at/resolved_by_* are server-derived.';


--
-- Name: psf_normalize_portal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_normalize_portal(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_value is null or btrim(p_value) = '' then null
    when upper(btrim(p_value)) in ('PV', 'PETROL', 'ICE') then 'PV'
    when upper(btrim(p_value)) in ('EV', 'ELECTRIC') then 'EV'
    else upper(btrim(p_value))
  end
$$;


--
-- Name: psf_set_cre_rating(bigint, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_set_cre_rating(p_feedback_id bigint, p_cre_rating smallint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rating smallint;
  v_effective smallint;
begin
  if not (public.is_admin() or public.has_module_modify('post_service_feedback_cre')) then
    raise exception 'Insufficient permissions';
  end if;

  if p_cre_rating is null or p_cre_rating < 1 or p_cre_rating > 5 then
    raise exception 'Rating must be between 1 and 5';
  end if;

  update public.post_service_feedback_messages
  set cre_rating = p_cre_rating,
      rating_at = now(),
      updated_at = now()
  where id = p_feedback_id
  returning rating, effective_rating into v_rating, v_effective;

  if not found then
    raise exception 'Feedback row not found: %', p_feedback_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'cre_rating', p_cre_rating,
    'rating', v_rating,
    'effective_rating', v_effective
  );
end;
$$;


--
-- Name: FUNCTION psf_set_cre_rating(p_feedback_id bigint, p_cre_rating smallint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.psf_set_cre_rating(p_feedback_id bigint, p_cre_rating smallint) IS 'Sets cre_rating for workflow classification. Does not change customer rating, feedback_text, follow-up date, remarks, or resolution.';


--
-- Name: psf_try_date(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_try_date(p_value text) RETURNS date
    LANGUAGE plpgsql
    AS $$
begin
  if p_value is null or btrim(p_value) = '' then
    return null;
  end if;

  return btrim(p_value)::date;
exception
  when others then
    return null;
end;
$$;


--
-- Name: psf_try_numeric(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_try_numeric(p_value text) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
begin
  if p_value is null or btrim(p_value) = '' then
    return null;
  end if;

  return replace(replace(replace(upper(btrim(p_value)), 'RS.', ''), ',', ''), '₹', '')::numeric;
exception
  when others then
    return null;
end;
$$;


--
-- Name: psf_try_timestamptz(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.psf_try_timestamptz(p_value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $$
begin
  if p_value is null or btrim(p_value) = '' then
    return null;
  end if;

  return btrim(p_value)::timestamptz;
exception
  when others then
    return null;
end;
$$;


--
-- Name: purge_contact_details_older_than(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_contact_details_older_than(p_retention_days integer DEFAULT 10, p_batch_size integer DEFAULT 1000, p_max_ms integer DEFAULT 55000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days integer := GREATEST(COALESCE(p_retention_days, 10), 1);
  v_batch integer := GREATEST(COALESCE(p_batch_size, 1000), 1);
  v_cutoff timestamptz := now() - make_interval(days => v_days);
  v_started timestamptz := clock_timestamp();
  v_deleted integer := 0;
  v_n integer := 0;
  v_budget_hit boolean := false;
  v_remaining boolean := true;
  v_filled integer := 0;
  v_trigger_disabled boolean := false;
BEGIN
  PERFORM set_config('statement_timeout', '120s', true);

  -- Copy any remaining Customer phones before rows age out.
  v_filled := public.reconcile_all_service_data_from_contact_details_chunked(5000);

  ALTER TABLE public.contact_details
    DISABLE TRIGGER trg_refresh_all_service_data_from_contact_details;
  v_trigger_disabled := true;

  BEGIN
    WHILE v_remaining LOOP
      IF p_max_ms IS NOT NULL
         AND (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer >= p_max_ms
      THEN
        v_budget_hit := true;
        EXIT;
      END IF;

      WITH doomed AS (
        SELECT t.id
        FROM public.contact_details t
        WHERE t.created_at IS NULL
           OR t.created_at < v_cutoff
        ORDER BY t.created_at ASC NULLS FIRST, t.id ASC
        LIMIT v_batch
      )
      DELETE FROM public.contact_details t
      USING doomed d
      WHERE t.id = d.id;

      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_deleted := v_deleted + v_n;
      v_remaining := v_n >= v_batch;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    ALTER TABLE public.contact_details
      ENABLE TRIGGER trg_refresh_all_service_data_from_contact_details;
    v_trigger_disabled := false;
    RAISE;
  END;

  IF v_trigger_disabled THEN
    ALTER TABLE public.contact_details
      ENABLE TRIGGER trg_refresh_all_service_data_from_contact_details;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.contact_details t
    WHERE t.created_at IS NULL
       OR t.created_at < v_cutoff
    LIMIT 1
  )
  INTO v_remaining;

  RETURN jsonb_build_object(
    'ok', true,
    'retention_days', v_days,
    'cutoff', v_cutoff,
    'batch_size', v_batch,
    'filled_phones', v_filled,
    'deleted', v_deleted,
    'remaining', v_remaining,
    'budget_hit', v_budget_hit,
    'elapsed_ms', (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer,
    'ran_at', now()
  );
END;
$$;


--
-- Name: FUNCTION purge_contact_details_older_than(p_retention_days integer, p_batch_size integer, p_max_ms integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_contact_details_older_than(p_retention_days integer, p_batch_size integer, p_max_ms integer) IS 'Deletes contact_details rows older than p_retention_days (created_at; NULL created_at is purged). Fills remaining Customer phones first. Batched with optional wall-clock budget (p_max_ms; NULL = drain until empty). Internal use only (pg_cron / service_role).';


--
-- Name: purge_service_history_test_older_than(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_service_history_test_older_than(p_retention_days integer DEFAULT 30, p_batch_size integer DEFAULT 1000, p_max_ms integer DEFAULT 55000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days integer := greatest(coalesce(p_retention_days, 30), 1);
  v_batch integer := greatest(coalesce(p_batch_size, 1000), 1);
  v_cutoff timestamptz := now() - make_interval(days => v_days);
  v_started timestamptz := clock_timestamp();
  v_ev_deleted integer := 0;
  v_pv_deleted integer := 0;
  v_ev_n integer;
  v_pv_n integer;
  v_budget_hit boolean := false;
  v_ev_remaining boolean := true;
  v_pv_remaining boolean := true;
BEGIN
  -- Raise local timeout above wall budget so the function can exit cleanly.
  PERFORM set_config('statement_timeout', '120s', true);

  -- Interleave EV/PV batches so one table cannot starve the other under a time budget.
  WHILE v_ev_remaining OR v_pv_remaining LOOP
    IF p_max_ms IS NOT NULL
       AND (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer >= p_max_ms
    THEN
      v_budget_hit := true;
      EXIT;
    END IF;

    v_ev_n := 0;
    v_pv_n := 0;

    IF v_ev_remaining THEN
      WITH doomed AS (
        SELECT t.id
        FROM public.ev_service_history_test t
        WHERE t.created_at < v_cutoff
        ORDER BY t.created_at ASC, t.id ASC
        LIMIT v_batch
      )
      DELETE FROM public.ev_service_history_test t
      USING doomed d
      WHERE t.id = d.id;

      GET DIAGNOSTICS v_ev_n = ROW_COUNT;
      v_ev_deleted := v_ev_deleted + v_ev_n;
      v_ev_remaining := v_ev_n >= v_batch;
    END IF;

    IF p_max_ms IS NOT NULL
       AND (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer >= p_max_ms
    THEN
      v_budget_hit := true;
      EXIT;
    END IF;

    IF v_pv_remaining THEN
      WITH doomed AS (
        SELECT t.id
        FROM public.pv_service_history_test t
        WHERE t.created_at < v_cutoff
        ORDER BY t.created_at ASC, t.id ASC
        LIMIT v_batch
      )
      DELETE FROM public.pv_service_history_test t
      USING doomed d
      WHERE t.id = d.id;

      GET DIAGNOSTICS v_pv_n = ROW_COUNT;
      v_pv_deleted := v_pv_deleted + v_pv_n;
      v_pv_remaining := v_pv_n >= v_batch;
    END IF;

    -- Both returned partial/empty batches → nothing left in this run window.
    EXIT WHEN (NOT v_ev_remaining) AND (NOT v_pv_remaining);
  END LOOP;

  -- Re-check remaining after budgeted exit (partial last batch may still leave rows).
  SELECT EXISTS (
    SELECT 1
    FROM public.ev_service_history_test t
    WHERE t.created_at < v_cutoff
    LIMIT 1
  )
  INTO v_ev_remaining;

  SELECT EXISTS (
    SELECT 1
    FROM public.pv_service_history_test t
    WHERE t.created_at < v_cutoff
    LIMIT 1
  )
  INTO v_pv_remaining;

  RETURN jsonb_build_object(
    'ok', true,
    'retention_days', v_days,
    'cutoff', v_cutoff,
    'batch_size', v_batch,
    'ev_deleted', v_ev_deleted,
    'pv_deleted', v_pv_deleted,
    'ev_remaining', v_ev_remaining,
    'pv_remaining', v_pv_remaining,
    'budget_hit', v_budget_hit,
    'elapsed_ms', (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer,
    'ran_at', now()
  );
END;
$$;


--
-- Name: FUNCTION purge_service_history_test_older_than(p_retention_days integer, p_batch_size integer, p_max_ms integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_service_history_test_older_than(p_retention_days integer, p_batch_size integer, p_max_ms integer) IS 'Deletes EV/PV service_history_test rows older than p_retention_days (created_at). Batched with optional wall-clock budget (p_max_ms; NULL = drain until empty). Internal use only (pg_cron / service_role).';


--
-- Name: raise_complaint(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_complaint(p_token text, p_category text, p_title text, p_description text, p_severity_self text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_customer_phone text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_link_id bigint;
  v_entry_id bigint;
  v_dealer_code text;
  v_status text;
  v_ticket_id bigint;
  v_sa_code text;
  v_branch text;
  v_reg_number text;
  v_model text;
  v_jc_number text;
  v_service_type text;
  v_owner_name text;
  v_owner_phone text;
  v_customer_name text;
BEGIN
  -- Find & validate link
  SELECT id, reception_entry_id, dealer_code, status
  INTO v_link_id, v_entry_id, v_dealer_code, v_status
  FROM public.complaint_access_links
  WHERE token = p_token;

  IF v_link_id IS NULL THEN
    RAISE EXCEPTION 'Invalid complaint link';
  END IF;

  IF v_status != 'active' THEN
    RAISE EXCEPTION 'This link has already been used or revoked. Cannot raise another complaint.';
  END IF;

  -- Get entry data from direct columns (authoritative schema)
  SELECT
    sa_employee_code,
    branch,
    reg_number,
    model,
    jc_number,
    service_type,
    owner_name,
    owner_phone
  INTO
    v_sa_code,
    v_branch,
    v_reg_number,
    v_model,
    v_jc_number,
    v_service_type,
    v_owner_name,
    v_owner_phone
  FROM public.service_reception_entries
  WHERE id = v_entry_id;

  v_customer_name := COALESCE(NULLIF(btrim(p_customer_name), ''), NULLIF(btrim(v_owner_name), ''), 'Customer');

  INSERT INTO public.complaint_tickets (
    dealer_code,
    reception_entry_id,
    reg_number,
    model,
    jc_number,
    service_type,
    branch,
    customer_name,
    customer_phone,
    category,
    title,
    description,
    severity_self,
    sa_employee_code
  ) VALUES (
    v_dealer_code,
    v_entry_id,
    v_reg_number,
    v_model,
    v_jc_number,
    v_service_type,
    v_branch,
    v_customer_name,
    COALESCE(NULLIF(btrim(p_customer_phone), ''), v_owner_phone),
    p_category,
    p_title,
    p_description,
    p_severity_self,
    v_sa_code
  )
  RETURNING id INTO v_ticket_id;

  -- Mark link as consumed
  UPDATE public.complaint_access_links
  SET status = 'consumed', complaint_id = v_ticket_id, consumed_at = now()
  WHERE id = v_link_id;

  -- Write opening customer message
  INSERT INTO public.complaint_messages (
    dealer_code, complaint_id, author_type, author_name, body
  ) VALUES (
    v_dealer_code, v_ticket_id, 'customer', v_customer_name, p_description
  );

  -- Write activity: 'raised' event
  INSERT INTO public.complaint_activity (
    dealer_code, complaint_id, event_type, actor_type, actor_name, note
  ) VALUES (
    v_dealer_code, v_ticket_id, 'raised', 'customer', v_customer_name,
    'Complaint raised via secure link'
  );

  RETURN public.get_complaint_by_token(p_token);
END;
$$;


--
-- Name: reassign(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reassign(p_complaint_id bigint, p_assigned_to_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_is_admin boolean := public.is_admin();
  v_dealer_code text := public.my_dealer_code();
BEGIN
  IF NOT (v_is_admin OR public.has_module_modify('complaints')) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  IF v_is_admin THEN
    UPDATE public.complaint_tickets
    SET assigned_to = p_assigned_to_user_id
    WHERE id = p_complaint_id;
  ELSE
    UPDATE public.complaint_tickets
    SET assigned_to = p_assigned_to_user_id
    WHERE id = p_complaint_id
      AND dealer_code = v_dealer_code;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Complaint not found or not accessible';
  END IF;

  RETURN jsonb_build_object('assigned_to', p_assigned_to_user_id);
END;
$$;


--
-- Name: recalc_bodyshop_settlement(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_bodyshop_settlement(p_settlement_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_h public.bodyshop_settlements%ROWTYPE;
  v_released numeric(14,2);
  v_posted numeric(14,2);
  v_diff numeric(14,2);
  v_kind text;
  v_ins_due numeric(14,2);
  v_cust_rem numeric(14,2);
  v_do_pay text;
  v_cust_pay text;
  v_overall text;
  v_actor text;
BEGIN
  SELECT * INTO v_h FROM public.bodyshop_settlements WHERE id = p_settlement_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'settlement % not found', p_settlement_id USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(SUM(amount), 0)
    INTO v_released
    FROM public.bodyshop_settlement_lines
   WHERE settlement_id = p_settlement_id
     AND is_reversed = false
     AND party = 'insurance'
     AND line_type = 'do_component'
     AND component IN ('MAIN', 'GST', 'TDS');

  v_diff := CASE
    WHEN v_h.invoice_amount IS NOT NULL AND v_h.do_amount IS NOT NULL
      THEN v_h.invoice_amount - v_h.do_amount
    ELSE v_h.customer_diff_amount
  END;

  v_kind := CASE
    WHEN v_diff IS NULL THEN NULL
    WHEN v_diff > 0 THEN 'due'
    WHEN v_diff < 0 THEN 'refund'
    ELSE 'none'
  END;

  IF v_kind = 'due' THEN
    SELECT COALESCE(SUM(amount), 0)
      INTO v_posted
      FROM public.bodyshop_settlement_lines
     WHERE settlement_id = p_settlement_id
       AND is_reversed = false
       AND party = 'customer'
       AND line_type = 'receipt'
       AND component = 'CUSTOMER';
  ELSIF v_kind = 'refund' THEN
    SELECT COALESCE(SUM(amount), 0)
      INTO v_posted
      FROM public.bodyshop_settlement_lines
     WHERE settlement_id = p_settlement_id
       AND is_reversed = false
       AND party = 'customer'
       AND line_type = 'refund'
       AND component = 'CUSTOMER_REFUND';
  ELSE
    v_posted := 0;
  END IF;

  -- Extra Main/GST/TDS above DO is allowed; due does not go negative.
  v_ins_due := CASE
    WHEN v_h.do_amount IS NULL THEN NULL
    ELSE GREATEST(round(v_h.do_amount - v_released, 2), 0)
  END;
  v_cust_rem := CASE
    WHEN v_diff IS NULL THEN NULL
    WHEN v_kind = 'none' THEN 0
    ELSE abs(v_diff) - v_posted
  END;

  IF v_h.do_amount IS NULL THEN
    v_do_pay := 'pending';
  ELSIF v_h.do_not_received AND v_released = 0 THEN
    v_do_pay := 'not_received';
  ELSIF v_ins_due = v_h.do_amount THEN
    v_do_pay := 'pending';
  ELSIF v_ins_due > 0 THEN
    v_do_pay := 'partial';
  ELSE
    v_do_pay := 'received';
  END IF;

  IF v_kind IS NULL THEN
    v_cust_pay := 'pending';
  ELSIF v_kind = 'none' THEN
    v_cust_pay := 'received';
  ELSIF v_h.customer_not_received AND v_posted = 0 THEN
    v_cust_pay := 'not_received';
  ELSIF v_cust_rem = abs(v_diff) THEN
    v_cust_pay := 'pending';
  ELSIF v_cust_rem > 0 THEN
    v_cust_pay := 'partial';
  ELSE
    v_cust_pay := 'received';
  END IF;

  IF v_do_pay = 'not_received' AND v_cust_pay = 'not_received' THEN
    v_overall := 'not_received';
  ELSIF v_do_pay = 'received' AND v_cust_pay = 'received' THEN
    v_overall := 'received';
  ELSIF v_do_pay IN ('partial', 'received', 'not_received')
     OR v_cust_pay IN ('partial', 'received', 'not_received') THEN
    IF (v_do_pay IN ('partial', 'received') OR v_cust_pay IN ('partial', 'received'))
       AND NOT (v_do_pay = 'received' AND v_cust_pay = 'received') THEN
      v_overall := 'partial';
    ELSIF v_do_pay = 'pending' AND v_cust_pay = 'pending' THEN
      v_overall := 'pending';
    ELSE
      v_overall := 'partial';
    END IF;
  ELSE
    v_overall := 'pending';
  END IF;

  v_actor := COALESCE(v_h.updated_by, v_h.created_by);

  UPDATE public.bodyshop_settlements
     SET customer_diff_amount = v_diff,
         customer_settlement_kind = v_kind,
         do_released_amount = v_released,
         insurance_due_amount = v_ins_due,
         customer_posted_amount = v_posted,
         customer_remaining_amount = v_cust_rem,
         outstanding_amount = COALESCE(v_ins_due, 0) + COALESCE(v_cust_rem, 0),
         do_payment_status = v_do_pay,
         customer_payment_status = v_cust_pay,
         derived_payment_status = v_overall,
         updated_at = now()
   WHERE id = p_settlement_id;

  UPDATE public.bodyshop_repair_cards
     SET billed_amount = v_h.invoice_amount,
         do_amount = v_h.do_amount,
         do_status = COALESCE(v_h.do_status, do_status),
         customer_diff_amount = v_diff,
         do_payment_status = v_do_pay,
         customer_payment_status = v_cust_pay,
         customer_settlement_kind = v_kind,
         payment_status = v_overall,
         updated_at = now()
   WHERE id = v_h.repair_card_id;
END;
$$;


--
-- Name: recompute_bodyshop_stage_worklist_projection_for_all_cards(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_bodyshop_stage_worklist_projection_for_all_cards() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_card_id integer;
BEGIN
	FOR v_card_id IN
		SELECT id FROM public.bodyshop_repair_cards
	LOOP
		PERFORM public.recompute_bodyshop_stage_worklist_projection_for_card(v_card_id, 1, 18, 'reconcile_full');
	END LOOP;
END;
$$;


--
-- Name: recompute_bodyshop_stage_worklist_projection_for_card(integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_bodyshop_stage_worklist_projection_for_card(p_repair_card_id integer, p_stage_from integer DEFAULT 1, p_stage_to integer DEFAULT 18, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
	v_card public.bodyshop_repair_cards%ROWTYPE;
	v_stage integer;
	v_rule_version text;
	v_is_active boolean;
	v_effective_current_stage integer;
	v_customer_type text;
	v_no_docs_required boolean;
	v_stage1_done boolean;
	v_stage2_done boolean;
	v_stage3_done boolean;
	v_stage4_done boolean;
	v_stage5_done boolean;
	v_stage6_done boolean;
	v_stage7_done boolean;
	v_stage8_done boolean;
	v_survey_status text;
	v_survey_hold_reason text;
	v_survey_approved boolean;
	v_survey_approval_evidence boolean;
	v_floor_assigned boolean;
	v_floor_completed boolean;
	v_stage9_done boolean;
	v_stage10_done boolean;
	v_stage11_done boolean;
	v_stage12_done boolean;
	v_stage10_ready boolean;
	v_stage11_ready boolean;
	v_approved_parts_finalized boolean := false;
	v_approved_parts_payload jsonb;
	v_additional_approval_text text;
	v_additional_approval_payload jsonb;
	v_additional_parse_ok boolean := false;
	v_additional_status text := 'none';
	v_additional_requested boolean := false;
	v_additional_part_states_count integer := 0;
	v_additional_pending_count integer := 0;
	v_additional_approved_count integer := 0;
	v_additional_rejected_count integer := 0;
	v_decision_parts jsonb := '[]'::jsonb;
	v_legacy_decision_status text := 'pending';
	v_request_parts_count integer := 0;
	v_request_fallback_present boolean := false;
	v_idx integer;
	v_part_status text;
	v_done boolean;
	v_pending boolean;
	v_ready boolean;
	v_reason_codes text[];
BEGIN
	SELECT * INTO v_card
	FROM public.bodyshop_repair_cards
	WHERE id = p_repair_card_id;

	IF NOT FOUND THEN
		DELETE FROM public.bodyshop_stage_worklist_projection
		WHERE repair_card_id = p_repair_card_id;
		RETURN;
	END IF;

	SELECT rule_version INTO v_rule_version
	FROM public.bodyshop_stage_rule_versions
	WHERE is_active = true
	ORDER BY created_at DESC
	LIMIT 1;

	IF v_rule_version IS NULL THEN
		v_rule_version := 'BODYSHOP-QUEUE-RULES-v1';
	END IF;

	v_is_active := (COALESCE(v_card.overall_status, 'active') = 'active');
	v_effective_current_stage := COALESCE(v_card.current_stage, 1);
	v_customer_type := lower(btrim(COALESCE(v_card.customer_type, '')));
	v_no_docs_required := v_customer_type IN ('cash', 'foc');

	v_stage1_done := (v_effective_current_stage > 1);
	v_stage2_done := (v_effective_current_stage > 2);
	v_stage3_done := (v_effective_current_stage > 3);
	v_stage4_done := (v_effective_current_stage > 4);

	v_stage5_done := (
		v_no_docs_required
		OR (
			v_customer_type = 'individual'
			AND COALESCE(v_card.doc_claim_form, false)
			AND COALESCE(v_card.doc_rc, false)
			AND COALESCE(v_card.doc_insurance, false)
			AND COALESCE(v_card.doc_dl, false)
			AND COALESCE(v_card.doc_aadhaar, false)
			AND COALESCE(v_card.doc_pan, false)
		)
		OR (
			v_customer_type = 'firm'
			AND COALESCE(v_card.doc_claim_form, false)
			AND COALESCE(v_card.doc_rc, false)
			AND COALESCE(v_card.doc_insurance, false)
			AND COALESCE(v_card.doc_dl, false)
			AND COALESCE(v_card.doc_aadhaar, false)
			AND COALESCE(v_card.doc_pan, false)
			AND COALESCE(v_card.doc_gst, false)
			AND COALESCE(v_card.doc_company_pan, false)
			AND COALESCE(v_card.doc_bank_detail, false)
		)
		OR v_effective_current_stage > 5
	);

	v_stage6_done := (COALESCE(v_card.estimated_amount, 0) > 0 OR v_effective_current_stage > 6);
	v_stage7_done := (btrim(COALESCE(v_card.estimation_approved_by, '')) <> '' OR v_effective_current_stage > 7);
	v_stage8_done := (btrim(COALESCE(v_card.claim_intimation_no, '')) <> '' OR v_effective_current_stage > 8);

	v_survey_status := lower(btrim(COALESCE(v_card.survey_status, '')));
	v_survey_hold_reason := btrim(COALESCE(v_card.survey_hold_reason, ''));
	v_survey_approved := (v_survey_status = 'approved');
	v_floor_assigned := lower(btrim(COALESCE(v_card.bodyshop_floor, ''))) IN ('floor 2', 'floor 3');
	v_floor_completed := (lower(btrim(COALESCE(v_card.floor_status, ''))) = 'completed' OR EXISTS (SELECT 1 FROM public.bodyshop_assignments ba WHERE ba.is_active = true AND ba.bs_floor_completed_at IS NOT NULL AND (ba.repair_card_id = v_card.id OR upper(trim(COALESCE(ba.job_card_number, ''))) = upper(trim(COALESCE(v_card.job_card_no, ''))))));

	SELECT EXISTS (
		SELECT 1
		FROM public.bodyshop_repair_card_documents d
		WHERE d.repair_card_id = v_card.id
			AND d.doc_key = 'doc_survey_approval'
	) INTO v_survey_approval_evidence;
	v_survey_approval_evidence := (v_survey_approval_evidence OR v_effective_current_stage >= 10);

	BEGIN
		IF btrim(COALESCE(v_card.approved_parts, '')) <> '' THEN
			v_approved_parts_payload := v_card.approved_parts::jsonb;
			v_approved_parts_finalized := (btrim(COALESCE(v_approved_parts_payload->>'finalized_at', '')) <> '');
		END IF;
	EXCEPTION WHEN others THEN
		v_approved_parts_finalized := false;
	END;

	v_additional_approval_text := btrim(COALESCE(v_card.additional_approval, ''));
	IF v_additional_approval_text <> '' THEN
		BEGIN
			v_additional_approval_payload := v_additional_approval_text::jsonb;
			v_additional_parse_ok := true;
		EXCEPTION WHEN others THEN
			v_additional_parse_ok := false;
		END;

		IF v_additional_parse_ok THEN
			v_legacy_decision_status := lower(btrim(COALESCE(v_additional_approval_payload #>> '{decision,status}', 'pending')));
			IF v_legacy_decision_status NOT IN ('pending', 'approved', 'rejected') THEN
				v_legacy_decision_status := 'pending';
			END IF;

			IF jsonb_typeof(v_additional_approval_payload #> '{request,parts}') = 'array' THEN
				v_request_parts_count := jsonb_array_length(v_additional_approval_payload #> '{request,parts}');
			END IF;

			v_request_fallback_present := (
				btrim(COALESCE(v_additional_approval_payload #>> '{request,part_no}', '')) <> ''
				OR btrim(COALESCE(v_additional_approval_payload #>> '{request,part_description}', '')) <> ''
				OR btrim(COALESCE(v_additional_approval_payload #>> '{request,reason}', '')) <> ''
				OR btrim(COALESCE(v_additional_approval_payload #>> '{request,part_image_path}', '')) <> ''
			);

			v_additional_part_states_count := CASE
				WHEN v_request_parts_count > 0 THEN v_request_parts_count
				WHEN v_request_fallback_present THEN 1
				ELSE 0
			END;

			IF jsonb_typeof(v_additional_approval_payload #> '{decision,parts}') = 'array' THEN
				v_decision_parts := (v_additional_approval_payload #> '{decision,parts}');
			ELSE
				v_decision_parts := '[]'::jsonb;
			END IF;

			IF v_additional_part_states_count > 0 THEN
				FOR v_idx IN 0..(v_additional_part_states_count - 1) LOOP
					v_part_status := lower(btrim(COALESCE(v_decision_parts -> v_idx ->> 'status', v_legacy_decision_status)));
					IF v_part_status NOT IN ('pending', 'approved', 'rejected') THEN
						v_part_status := 'pending';
					END IF;

					IF v_part_status = 'pending' THEN
						v_additional_pending_count := v_additional_pending_count + 1;
					ELSIF v_part_status = 'approved' THEN
						v_additional_approved_count := v_additional_approved_count + 1;
					ELSIF v_part_status = 'rejected' THEN
						v_additional_rejected_count := v_additional_rejected_count + 1;
					END IF;
				END LOOP;

				IF v_additional_pending_count > 0 THEN
					v_additional_status := 'pending';
				ELSIF v_additional_approved_count > 0 AND v_additional_rejected_count > 0 THEN
					v_additional_status := 'mixed';
				ELSIF v_additional_approved_count = v_additional_part_states_count THEN
					v_additional_status := 'approved';
				ELSIF v_additional_rejected_count = v_additional_part_states_count THEN
					v_additional_status := 'rejected';
				ELSE
					v_additional_status := 'pending';
				END IF;
			ELSE
				v_additional_status := v_legacy_decision_status;
				v_additional_pending_count := CASE WHEN v_additional_status = 'pending' THEN 1 ELSE 0 END;
			END IF;
		ELSE
			v_additional_status := 'pending';
			v_additional_part_states_count := 1;
			v_additional_pending_count := 1;
		END IF;
	END IF;

	v_additional_requested := (v_additional_status <> 'none');

	v_stage9_done := (
		(v_card.survey_date IS NOT NULL)
		AND (v_survey_status IN ('hold', 'approved'))
		AND (v_survey_status <> 'hold' OR v_survey_hold_reason <> '')
		AND v_floor_assigned
	);

	v_stage10_done := (v_survey_approved AND v_survey_approval_evidence AND v_approved_parts_finalized);
	v_stage10_ready := (
		v_stage1_done
		AND v_stage2_done
		AND v_stage3_done
		AND v_stage4_done
		AND v_stage5_done
		AND v_stage6_done
		AND v_stage7_done
		AND v_stage8_done
		AND v_survey_approved
		AND v_survey_approval_evidence
	);
	v_stage11_ready := (v_stage10_ready AND v_stage9_done);

	v_stage12_done := (
		(v_additional_part_states_count > 0 AND v_additional_pending_count = 0)
		OR (v_additional_part_states_count = 0 AND v_additional_status IN ('approved', 'rejected'))
		OR v_effective_current_stage > 12
	);

	v_stage11_done := (v_floor_completed AND (NOT v_additional_requested OR v_stage12_done));

	p_stage_from := GREATEST(1, COALESCE(p_stage_from, 1));
	p_stage_to := LEAST(18, COALESCE(p_stage_to, 18));

	IF p_stage_from > p_stage_to THEN
		p_stage_from := 1;
		p_stage_to := 18;
	END IF;

	FOR v_stage IN p_stage_from..p_stage_to LOOP
		v_ready := v_is_active;
		v_done := false;
		v_pending := false;
		v_reason_codes := ARRAY[]::text[];

		IF p_reason IS NOT NULL THEN
			v_reason_codes := array_append(v_reason_codes, p_reason);
		END IF;

		IF NOT v_is_active THEN
			v_done := false;
			v_pending := false;
		ELSE
			IF v_stage = 1 THEN
				v_done := v_stage1_done;
				v_pending := NOT v_stage1_done;
			ELSIF v_stage = 2 THEN
				v_done := v_stage2_done;
				v_pending := NOT v_stage2_done;
			ELSIF v_stage = 3 THEN
				v_done := v_stage3_done;
				v_pending := NOT v_stage3_done;
			ELSIF v_stage = 4 THEN
				v_done := v_stage4_done;
				v_pending := NOT v_stage4_done;
			ELSIF v_stage = 5 THEN
				v_done := v_stage5_done;
				v_pending := v_stage1_done AND v_stage2_done AND v_stage3_done AND v_stage4_done AND NOT v_stage5_done;
			ELSIF v_stage = 6 THEN
				v_done := v_stage6_done;
				v_pending := v_stage1_done AND v_stage2_done AND v_stage3_done AND v_stage4_done AND v_stage5_done AND NOT v_stage6_done;
			ELSIF v_stage = 7 THEN
				v_done := v_stage7_done;
				v_pending := v_stage1_done AND v_stage2_done AND v_stage3_done AND v_stage4_done AND v_stage5_done AND v_stage6_done AND NOT v_stage7_done;
			ELSIF v_stage = 8 THEN
				v_done := v_stage8_done;
				v_pending := v_stage1_done AND v_stage2_done AND v_stage3_done AND v_stage4_done AND v_stage5_done AND v_stage6_done AND v_stage7_done AND NOT v_stage8_done;
			ELSIF v_stage = 9 THEN
				v_done := v_stage9_done;
				v_pending := v_stage1_done AND v_stage2_done AND v_stage3_done AND v_stage4_done AND v_stage5_done AND v_stage6_done AND v_stage7_done AND v_stage8_done AND NOT v_stage9_done;

				IF v_pending AND v_card.survey_date IS NULL THEN
					v_reason_codes := array_append(v_reason_codes, 'survey_date_missing');
				END IF;
				IF v_pending AND v_survey_status NOT IN ('hold', 'approved') THEN
					v_reason_codes := array_append(v_reason_codes, 'survey_status_invalid');
				END IF;
				IF v_pending AND v_survey_status = 'hold' AND v_survey_hold_reason = '' THEN
					v_reason_codes := array_append(v_reason_codes, 'survey_hold_reason_missing');
				END IF;
				IF v_pending AND NOT v_floor_assigned THEN
					v_reason_codes := array_append(v_reason_codes, 'survey_floor_not_assigned');
				END IF;
			ELSIF v_stage = 10 THEN
				v_done := v_stage10_done;
				v_pending := v_stage10_ready AND NOT v_stage10_done;

				IF v_pending AND NOT v_survey_approved THEN
					v_reason_codes := array_append(v_reason_codes, 'survey_not_approved');
				END IF;
				IF v_pending AND NOT v_survey_approval_evidence THEN
					v_reason_codes := array_append(v_reason_codes, 'survey_approval_evidence_missing');
				END IF;
				IF v_pending AND NOT v_approved_parts_finalized THEN
					v_reason_codes := array_append(v_reason_codes, 'approved_parts_not_finalized');
				END IF;
			ELSIF v_stage = 11 THEN
				v_done := v_stage11_done;
				v_pending := NOT v_stage11_done;

				IF v_pending AND NOT v_stage10_done THEN
					v_reason_codes := array_append(v_reason_codes, 'stage10_not_done');
				END IF;
				IF v_pending AND NOT v_floor_completed THEN
					v_reason_codes := array_append(v_reason_codes, 'floor_not_completed');
				END IF;
				IF v_pending AND v_additional_requested AND NOT v_stage12_done THEN
					v_reason_codes := array_append(v_reason_codes, 'additional_approval_pending');
				END IF;
			ELSIF v_stage = 12 THEN
				v_done := v_stage12_done;
				v_pending := v_stage11_ready AND v_additional_requested AND NOT v_stage12_done;

				IF v_pending AND v_additional_part_states_count > 0 AND v_additional_pending_count > 0 THEN
					v_reason_codes := array_append(v_reason_codes, 'additional_approval_part_pending');
				END IF;
				IF v_pending AND v_additional_part_states_count = 0 AND v_additional_status NOT IN ('approved', 'rejected') THEN
					v_reason_codes := array_append(v_reason_codes, 'additional_approval_decision_missing');
				END IF;
			ELSIF v_stage BETWEEN 13 AND 18 THEN
				v_done := (v_effective_current_stage > v_stage);
				v_pending := (v_effective_current_stage = v_stage);
			ELSE
				v_done := (v_stage < v_effective_current_stage);
				v_pending := (v_stage = v_effective_current_stage);
			END IF;
		END IF;

		INSERT INTO public.bodyshop_stage_worklist_projection (
			repair_card_id,
			stage_no,
			is_ready,
			is_done,
			is_pending,
			reason_codes,
			rule_version,
			computed_at,
			source_hash,
			dealer_code,
			branch,
			advisor_key,
			updated_at
		) VALUES (
			v_card.id,
			v_stage,
			v_ready,
			v_done,
			v_pending,
			to_jsonb(v_reason_codes),
			v_rule_version,
			now(),
			md5(
				COALESCE(v_card.id::text, '') || ':' ||
				COALESCE(v_card.current_stage::text, '') || ':' ||
				COALESCE(v_card.survey_date::text, '') || ':' ||
				COALESCE(v_card.survey_status, '') || ':' ||
				COALESCE(v_card.bodyshop_floor, '') || ':' ||
				COALESCE(v_card.floor_status, '') || ':' ||
				COALESCE(v_card.approved_parts, '') || ':' ||
				COALESCE(v_card.additional_approval, '') || ':' ||
				COALESCE(v_card.overall_status, '') || ':' ||
				COALESCE(array_to_string(v_reason_codes, ','), '') || ':' ||
				COALESCE(v_rule_version, '')
			),
			split_part(COALESCE(v_card.sa_employee_code, ''), '_', 1),
			v_card.branch,
			COALESCE(v_card.sa_employee_code, ''),
			now()
		)
		ON CONFLICT (repair_card_id, stage_no)
		DO UPDATE SET
			is_ready = EXCLUDED.is_ready,
			is_done = EXCLUDED.is_done,
			is_pending = EXCLUDED.is_pending,
			reason_codes = EXCLUDED.reason_codes,
			rule_version = EXCLUDED.rule_version,
			computed_at = EXCLUDED.computed_at,
			source_hash = EXCLUDED.source_hash,
			dealer_code = EXCLUDED.dealer_code,
			branch = EXCLUDED.branch,
			advisor_key = EXCLUDED.advisor_key,
			updated_at = now();
	END LOOP;
END;
$$;


--
-- Name: reconcile_all_service_data_from_contact_details_chunked(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_all_service_data_from_contact_details_chunked(p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, COALESCE(p_limit, 1000));
  v_rows integer := 0;
BEGIN
  UPDATE public.all_service_data t
  SET
    contact_phones = s.phone,
    last_updated_at = now()
  FROM (
    SELECT t2.id, w.phone
    FROM (
      SELECT DISTINCT ON (upper(btrim(c.chassis_no)))
        upper(btrim(c.chassis_no)) AS chassis_norm,
        NULLIF(btrim(c.cell_phone_no), '') AS phone
      FROM public.contact_details c
      WHERE lower(btrim(COALESCE(c.contact_status, ''))) = 'customer'
        AND NULLIF(btrim(c.cell_phone_no), '') IS NOT NULL
        AND NULLIF(upper(btrim(c.chassis_no)), '') IS NOT NULL
      ORDER BY upper(btrim(c.chassis_no)), c.created_at DESC NULLS LAST, c.id DESC
    ) w
    JOIN public.all_service_data t2
      ON upper(NULLIF(btrim(t2.chassis_no), '')) = w.chassis_norm
    WHERE NULLIF(btrim(t2.contact_phones), '') IS NULL
      AND t2.contact_phones IS DISTINCT FROM w.phone
    ORDER BY t2.id
    LIMIT v_limit
  ) s
  WHERE t.id = s.id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$$;


--
-- Name: FUNCTION reconcile_all_service_data_from_contact_details_chunked(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconcile_all_service_data_from_contact_details_chunked(p_limit integer) IS 'Timeout-safe fill-null backfill: update up to N all_service_data rows whose contact_phones is NULL/blank from the latest Customer contact_details phone on the same chassis.';


--
-- Name: reconcile_all_service_data_from_job_card_closed_data_chunked(integer, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_all_service_data_from_job_card_closed_data_chunked(p_chunk_size integer DEFAULT 1000, p_max_source_id bigint DEFAULT NULL::bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
  v_chunk_size integer := greatest(1, coalesce(p_chunk_size, 1000));
  v_max_source_id bigint;
  v_processed integer := 0;
begin
  select coalesce(p_max_source_id, max(j.id))
  into v_max_source_id
  from public.job_card_closed_data j
  where j.sr_type ilike '%Service%';

  if v_max_source_id is null then
    return 0;
  end if;

  for r in
    select
      j.chassis_number,
      j.vehicle_registration_number
    from public.job_card_closed_data j
    where j.sr_type ilike '%Service%'
      and j.id <= v_max_source_id
    order by j.id desc
    limit v_chunk_size
  loop
    perform public.refresh_all_service_data_from_job_card_closed_data(
      r.chassis_number,
      r.vehicle_registration_number
    );
    v_processed := v_processed + 1;
  end loop;

  return v_processed;
end;
$$;


--
-- Name: FUNCTION reconcile_all_service_data_from_job_card_closed_data_chunked(p_chunk_size integer, p_max_source_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconcile_all_service_data_from_job_card_closed_data_chunked(p_chunk_size integer, p_max_source_id bigint) IS 'Timeout-safe chunked reconcile for job_card_closed_data winner sync. Processes most-recent eligible source keys first.';


--
-- Name: reconcile_all_service_data_from_rto_idspay_chunked(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_all_service_data_from_rto_idspay_chunked(p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_processed integer := 0;
  v_limit integer := greatest(1, coalesce(p_limit, 500));
BEGIN
  FOR r IN
    SELECT
      chassis,
      coalesce(reg_no, registration_no) AS registration_key,
      vehicle_insurance_company_name,
      vehicle_insurance_upto,
      vehicle_insurance_policy_number,
      owner_name
    FROM public.rto_idspay
    WHERE verified IS TRUE
    ORDER BY cached_at DESC NULLS LAST, updated_at DESC NULLS LAST
    LIMIT v_limit
  LOOP
    PERFORM public.refresh_all_service_data_from_rto_idspay(
      r.chassis,
      r.registration_key,
      r.vehicle_insurance_company_name,
      r.vehicle_insurance_upto,
      r.vehicle_insurance_policy_number,
      r.owner_name
    );
    v_processed := v_processed + 1;
  END LOOP;

  RETURN v_processed;
END;
$$;


--
-- Name: FUNCTION reconcile_all_service_data_from_rto_idspay_chunked(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconcile_all_service_data_from_rto_idspay_chunked(p_limit integer) IS 'Backfill helper: apply refresh_all_service_data_from_rto_idspay for up to N verified rto_idspay rows.';


--
-- Name: reconcile_all_service_data_robot_flag_freshness_for_plus2_due(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_all_service_data_robot_flag_freshness_for_plus2_due() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_rows integer := 0;
BEGIN
  UPDATE public.all_service_data AS a
  SET
    updated_by_robot = false,
    updated_by_robot_at = NULL,
    last_updated_at = now()
  WHERE a.chassis_no IS NOT NULL
    AND COALESCE(a.updated_by_robot, false) = true
    AND (
      a.updated_by_robot_at IS NULL
      OR ((a.updated_by_robot_at AT TIME ZONE 'Asia/Kolkata')::date <> (now() AT TIME ZONE 'Asia/Kolkata')::date)
    )
    AND (
      a.assumed_next_service_date = (current_date + 2)
      OR (
        a.assumed_next_service_date IS NULL
        AND lower(btrim(COALESCE(a.assumed_next_service_type, ''))) = 'first free service'
      )
    );

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$$;


--
-- Name: FUNCTION reconcile_all_service_data_robot_flag_freshness_for_plus2_due(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconcile_all_service_data_robot_flag_freshness_for_plus2_due() IS 'Reconcile helper: stale/non-today robot timestamp rows are normalized to updated_by_robot=false and updated_by_robot_at=NULL for +2 due rows and First Free Service rows with no assumed due date.';


--
-- Name: refresh_all_service_data_dynamic_full(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_all_service_data_dynamic_full() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Upsert every row that currently matches the active predicate.
  INSERT INTO public.all_service_data_dynamic (
    id,
    chassis_no,
    vehicle_registration_number,
    model,
    product_line,
    scheduled_next_service_date,
    last_service_date,
    last_service_type,
    assumed_next_service_date,
    assumed_next_service_type,
    fuel_tp,
    sold_dealer,
    priority_bucket,
    priority_score,
    vehicle_sale_date,
    updated_by_robot,
    updated_by_robot_at
  )
  SELECT
    a.id,
    a.chassis_no,
    a.vehicle_registration_number,
    a.model,
    a.product_line,
    a.scheduled_next_service_date,
    a.last_service_date,
    a.last_service_type,
    a.assumed_next_service_date,
    a.assumed_next_service_type,
    CASE
      WHEN upper(COALESCE(a.product_line, '')) LIKE '%EV%' THEN 'EV'
      ELSE 'PV'
    END AS fuel_tp,
    a.sold_dealer,
    public.calc_all_service_dynamic_priority_bucket(a.sold_dealer) AS priority_bucket,
    public.calc_all_service_dynamic_priority_score(
      a.assumed_next_service_date,
      a.assumed_next_service_type,
      a.vehicle_sale_date::text
    ) AS priority_score,
    a.vehicle_sale_date,
    a.updated_by_robot,
    a.updated_by_robot_at
  FROM public.all_service_data AS a
  WHERE public.is_all_service_dynamic_match(a)
  ON CONFLICT (id) DO UPDATE
  SET
    chassis_no = EXCLUDED.chassis_no,
    vehicle_registration_number = EXCLUDED.vehicle_registration_number,
    model = EXCLUDED.model,
    product_line = EXCLUDED.product_line,
    scheduled_next_service_date = EXCLUDED.scheduled_next_service_date,
    last_service_date = EXCLUDED.last_service_date,
    last_service_type = EXCLUDED.last_service_type,
    assumed_next_service_date = EXCLUDED.assumed_next_service_date,
    assumed_next_service_type = EXCLUDED.assumed_next_service_type,
    fuel_tp = EXCLUDED.fuel_tp,
    sold_dealer = EXCLUDED.sold_dealer,
    priority_bucket = EXCLUDED.priority_bucket,
    priority_score = EXCLUDED.priority_score,
    vehicle_sale_date = EXCLUDED.vehicle_sale_date,
    updated_by_robot = EXCLUDED.updated_by_robot,
    updated_by_robot_at = EXCLUDED.updated_by_robot_at;

  -- Remove rows that are no longer eligible after date/predicate drift.
  DELETE FROM public.all_service_data_dynamic AS d
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.all_service_data AS a
    WHERE a.id = d.id
      AND public.is_all_service_dynamic_match(a)
  );
END;
$$;


--
-- Name: FUNCTION refresh_all_service_data_dynamic_full(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_all_service_data_dynamic_full() IS 'Full reconciliation for all_service_data_dynamic. Re-evaluates active include predicate against all_service_data and repairs drift from time-dependent conditions.';


--
-- Name: refresh_all_service_data_from_contact_details(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_all_service_data_from_contact_details(p_chassis_key text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_chassis_norm text;
  v_phone text;
BEGIN
  v_chassis_norm := NULLIF(upper(btrim(COALESCE(p_chassis_key, ''))), '');
  IF v_chassis_norm IS NULL THEN
    RETURN;
  END IF;

  v_phone := public.lookup_customer_phone_from_contact_details(v_chassis_norm);
  IF v_phone IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.all_service_data t
  SET
    contact_phones = v_phone,
    last_updated_at = now()
  WHERE upper(NULLIF(btrim(t.chassis_no), '')) = v_chassis_norm
    AND NULLIF(btrim(t.contact_phones), '') IS NULL
    AND t.contact_phones IS DISTINCT FROM v_phone;
END;
$$;


--
-- Name: FUNCTION refresh_all_service_data_from_contact_details(p_chassis_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_all_service_data_from_contact_details(p_chassis_key text) IS 'Fill-null sync: write contact_details Customer phone onto matching all_service_data.contact_phones only when the target is NULL or blank.';


--
-- Name: refresh_all_service_data_from_job_card_closed_data(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_all_service_data_from_job_card_closed_data(p_chassis_key text DEFAULT NULL::text, p_vehicle_registration_key text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  with source_base as (
    select
      j.id as source_id,
      nullif(btrim(j.chassis_number), '') as chassis_number_raw,
      nullif(btrim(j.vehicle_registration_number), '') as vehicle_registration_number_raw,
      upper(nullif(btrim(j.chassis_number), '')) as chassis_norm,
      upper(nullif(btrim(j.vehicle_registration_number), '')) as vrn_norm,
      j.first_name,
      j.last_name,
      nullif(btrim(j.account_phone_number), '') as account_phone_number,
      j.parent_product_line,
      j.product_line,
      j.vehicle_sale_date,
      j.sr_type,
      j.last_service_km,
      j.closed_date_time,
      coalesce(j.closed_date_time, j.created_date_time, j.updated_at, j.created_at) as winner_ts
    from public.job_card_closed_data j
    where j.sr_type ilike '%Service%'
      and (
        (p_chassis_key is null and p_vehicle_registration_key is null)
        or (
          p_chassis_key is not null
          and upper(nullif(btrim(j.chassis_number), '')) = upper(nullif(btrim(p_chassis_key), ''))
        )
        or (
          p_vehicle_registration_key is not null
          and upper(nullif(btrim(j.vehicle_registration_number), '')) = upper(nullif(btrim(p_vehicle_registration_key), ''))
        )
      )
  ),
  winners_by_chassis as (
    select x.*
    from (
      select
        sb.*,
        row_number() over (
          partition by sb.chassis_norm
          order by sb.winner_ts desc nulls last, sb.source_id desc
        ) as rn
      from source_base sb
      where sb.chassis_norm is not null
    ) x
    where x.rn = 1
  ),
  winners_by_vrn as (
    select x.*
    from (
      select
        sb.*,
        row_number() over (
          partition by sb.vrn_norm
          order by sb.winner_ts desc nulls last, sb.source_id desc
        ) as rn
      from source_base sb
      where sb.chassis_norm is null
        and sb.vrn_norm is not null
    ) x
    where x.rn = 1
  ),
  winners as (
    select * from winners_by_chassis
    union all
    select * from winners_by_vrn
  ),
  target_match as (
    select
      w.*,
      coalesce(t_chassis.id, t_vrn.id) as matched_target_id
    from winners w
    left join lateral (
      select t.id
      from public.all_service_data t
      where w.chassis_norm is not null
        and upper(nullif(btrim(t.chassis_no), '')) = w.chassis_norm
      order by t.last_updated_at desc nulls last, t.created_at desc nulls last, t.id desc
      limit 1
    ) t_chassis on true
    left join lateral (
      select t.id
      from public.all_service_data t
      where t_chassis.id is null
        and w.vrn_norm is not null
        and upper(nullif(btrim(t.vehicle_registration_number), '')) = w.vrn_norm
      order by t.last_updated_at desc nulls last, t.created_at desc nulls last, t.id desc
      limit 1
    ) t_vrn on true
  ),
  updated_rows as (
    update public.all_service_data t
    set
      chassis_no = tm.chassis_number_raw,
      vehicle_registration_number = tm.vehicle_registration_number_raw,
      first_name = tm.first_name,
      last_name = tm.last_name,
      contact_phones = tm.account_phone_number,
      model = tm.parent_product_line,
      product_line = tm.product_line,
      vehicle_sale_date = tm.vehicle_sale_date,
      last_service_dealer = 'FIRST MOBITAL PVT. LTD.',
      last_service_type = tm.sr_type,
      last_service_km = case when tm.last_service_km is null then null else tm.last_service_km::text end,
      last_service_date = case
        when tm.closed_date_time is null then null
        else (tm.closed_date_time at time zone 'Asia/Kolkata')::date
      end,
      updated_by_closed_job = true,
      updated_by_closed_job_at = now(),
      last_updated_at = now()
    from target_match tm
    where tm.matched_target_id is not null
      and tm.closed_date_time is not null
      and (
        t.last_service_date is null
        or (tm.closed_date_time at time zone 'Asia/Kolkata')::date > t.last_service_date
        or t.last_service_dealer is null
      )
      and t.id = tm.matched_target_id
    returning t.id
  )
  insert into public.all_service_data (
    chassis_no,
    vehicle_registration_number,
    first_name,
    last_name,
    contact_phones,
    model,
    product_line,
    vehicle_sale_date,
    last_service_dealer,
    last_service_type,
    last_service_km,
    last_service_date,
    updated_by_closed_job,
    updated_by_closed_job_at,
    created_at,
    last_updated_at
  )
  select
    tm.chassis_number_raw,
    tm.vehicle_registration_number_raw,
    tm.first_name,
    tm.last_name,
    tm.account_phone_number,
    tm.parent_product_line,
    tm.product_line,
    tm.vehicle_sale_date,
    'FIRST MOBITAL PVT. LTD.',
    tm.sr_type,
    case when tm.last_service_km is null then null else tm.last_service_km::text end,
    case
      when tm.closed_date_time is null then null
      else (tm.closed_date_time at time zone 'Asia/Kolkata')::date
    end,
    true,
    now(),
    now(),
    now()
  from target_match tm
  where tm.matched_target_id is null;
end;
$$;


--
-- Name: FUNCTION refresh_all_service_data_from_job_card_closed_data(p_chassis_key text, p_vehicle_registration_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_all_service_data_from_job_card_closed_data(p_chassis_key text, p_vehicle_registration_key text) IS 'Service-only latest-winner sync from job_card_closed_data to all_service_data using closed_date_time -> last_service_date. Match by chassis first, fallback by vehicle_registration_number.';


--
-- Name: refresh_all_service_data_from_rto_idspay(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_all_service_data_from_rto_idspay(p_chassis_key text DEFAULT NULL::text, p_registration_key text DEFAULT NULL::text, p_insurance_company text DEFAULT NULL::text, p_insurance_upto text DEFAULT NULL::text, p_insurance_policy_number text DEFAULT NULL::text, p_owner_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_chassis_norm text;
  v_reg_norm text;
  v_company text;
  v_policy text;
  v_upto_text text;
  v_expiry date;
  v_owner_name text;
  v_target_id bigint;
  v_new_company text;
  v_new_policy text;
BEGIN
  v_chassis_norm := nullif(upper(btrim(coalesce(p_chassis_key, ''))), '');
  v_reg_norm := nullif(upper(btrim(coalesce(p_registration_key, ''))), '');

  IF v_chassis_norm IS NULL AND v_reg_norm IS NULL THEN
    RETURN;
  END IF;

  v_company := nullif(btrim(coalesce(p_insurance_company, '')), '');
  v_policy := nullif(btrim(coalesce(p_insurance_policy_number, '')), '');
  v_upto_text := nullif(btrim(coalesce(p_insurance_upto, '')), '');
  v_expiry := public.parse_all_service_date_text(v_upto_text);
  v_owner_name := nullif(btrim(coalesce(p_owner_name, '')), '');

  IF v_company IS NULL AND v_policy IS NULL AND v_expiry IS NULL AND v_owner_name IS NULL THEN
    RETURN;
  END IF;

  v_target_id := NULL;

  IF v_chassis_norm IS NOT NULL THEN
    SELECT t.id
    INTO v_target_id
    FROM public.all_service_data t
    WHERE upper(nullif(btrim(t.chassis_no), '')) = v_chassis_norm
    ORDER BY t.last_updated_at DESC NULLS LAST, t.created_at DESC NULLS LAST, t.id DESC
    LIMIT 1;
  END IF;

  IF v_target_id IS NULL AND v_reg_norm IS NOT NULL THEN
    SELECT t.id
    INTO v_target_id
    FROM public.all_service_data t
    WHERE upper(nullif(btrim(t.vehicle_registration_number), '')) = v_reg_norm
    ORDER BY t.last_updated_at DESC NULLS LAST, t.created_at DESC NULLS LAST, t.id DESC
    LIMIT 1;
  END IF;

  IF v_target_id IS NULL THEN
    RETURN;
  END IF;

  v_new_company := v_company;
  v_new_policy := v_policy;

  UPDATE public.all_service_data t
  SET
    last_insurance_comapny = COALESCE(v_new_company, t.last_insurance_comapny),
    last_insurance_policy_number = COALESCE(v_new_policy, t.last_insurance_policy_number),
    last_insurance_expiry_date = COALESCE(v_expiry, t.last_insurance_expiry_date),
    first_name = CASE WHEN v_owner_name IS NOT NULL THEN v_owner_name ELSE t.first_name END,
    last_name = CASE WHEN v_owner_name IS NOT NULL THEN NULL ELSE t.last_name END,
    updated_by_rtoids = CASE
      WHEN (
        (v_new_company IS NOT NULL AND t.last_insurance_comapny IS DISTINCT FROM v_new_company)
        OR (v_new_policy IS NOT NULL AND t.last_insurance_policy_number IS DISTINCT FROM v_new_policy)
        OR (v_expiry IS NOT NULL AND t.last_insurance_expiry_date IS DISTINCT FROM v_expiry)
      ) THEN true
      ELSE t.updated_by_rtoids
    END,
    updated_by_rtoids_at = CASE
      WHEN (
        (v_new_company IS NOT NULL AND t.last_insurance_comapny IS DISTINCT FROM v_new_company)
        OR (v_new_policy IS NOT NULL AND t.last_insurance_policy_number IS DISTINCT FROM v_new_policy)
        OR (v_expiry IS NOT NULL AND t.last_insurance_expiry_date IS DISTINCT FROM v_expiry)
      ) THEN now()
      ELSE t.updated_by_rtoids_at
    END,
    last_updated_at = now()
  WHERE t.id = v_target_id
    AND (
      (v_new_company IS NOT NULL AND t.last_insurance_comapny IS DISTINCT FROM v_new_company)
      OR (v_new_policy IS NOT NULL AND t.last_insurance_policy_number IS DISTINCT FROM v_new_policy)
      OR (v_expiry IS NOT NULL AND t.last_insurance_expiry_date IS DISTINCT FROM v_expiry)
      OR (
        v_owner_name IS NOT NULL
        AND (
          t.first_name IS DISTINCT FROM v_owner_name
          OR t.last_name IS NOT NULL
        )
      )
    );
END;
$$;


--
-- Name: FUNCTION refresh_all_service_data_from_rto_idspay(p_chassis_key text, p_registration_key text, p_insurance_company text, p_insurance_upto text, p_insurance_policy_number text, p_owner_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_all_service_data_from_rto_idspay(p_chassis_key text, p_registration_key text, p_insurance_company text, p_insurance_upto text, p_insurance_policy_number text, p_owner_name text) IS 'Updates all_service_data insurance and owner name from IDSPay rto_idspay row values. owner_name maps to first_name; last_name is cleared. Match target by normalized chassis_no first, then vehicle_registration_number. Skips blank IDSPay values.';


--
-- Name: refresh_all_service_data_from_service_history(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_all_service_data_from_service_history(p_chassis_key text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_key text;
begin
  v_key := nullif(upper(btrim(coalesce(p_chassis_key, ''))), '');

  if v_key is null then
    return;
  end if;

  with source_union as (
    select
      h.id,
      upper(btrim(h.chassis_no)) as chassis_key,
      h.registration_no,
      h.odometer_reading,
      h.serviced_at_dealer,
      h.sr_type,
      h.service_date_time,
      nullif(btrim(h.contact_full_name), '') as contact_full_name,
      h.created_at,
      1::int as source_rank
    from public.ev_service_history_test h
    where nullif(btrim(h.chassis_no), '') is not null
      and upper(btrim(h.chassis_no)) = v_key

    union all

    select
      h.id,
      upper(btrim(h.chassis_no)) as chassis_key,
      h.registration_no,
      h.odometer_reading,
      h.serviced_at_dealer,
      h.sr_type,
      h.service_date_time,
      nullif(btrim(h.contact_full_name), '') as contact_full_name,
      h.created_at,
      2::int as source_rank
    from public.pv_service_history_test h
    where nullif(btrim(h.chassis_no), '') is not null
      and upper(btrim(h.chassis_no)) = v_key
  ),
  ranked as (
    select
      su.*,
      case
        when lower(coalesce(su.sr_type, '')) like '%service%' then 0
        else 1
      end as service_priority,
      su.service_date_time as parsed_service_at
    from source_union su
  ),
  chosen as (
    select
      r.chassis_key,
      r.registration_no,
      r.odometer_reading,
      r.serviced_at_dealer,
      r.sr_type,
      r.parsed_service_at,
      r.contact_full_name,
      r.created_at
    from ranked r
    order by
      r.service_priority asc,
      r.parsed_service_at desc nulls last,
      r.created_at desc nulls last,
      r.source_rank asc,
      r.id desc
    limit 1
  )
  update public.all_service_data as t
  set
    vehicle_registration_number = coalesce(c.registration_no, t.vehicle_registration_number),
    updated_by_robot = true,
    updated_by_robot_at = c.created_at,
    last_updated_at = now(),
    last_service_km = coalesce(c.odometer_reading, t.last_service_km),
    last_service_dealer = coalesce(c.serviced_at_dealer, t.last_service_dealer),
    last_service_date = coalesce(c.parsed_service_at::date, t.last_service_date),
    first_name = coalesce(c.contact_full_name, t.first_name),
    last_service_type = coalesce(c.sr_type, t.last_service_type)
  from chosen c
  where upper(btrim(t.chassis_no)) = c.chassis_key
    and (
      t.vehicle_registration_number is distinct from coalesce(c.registration_no, t.vehicle_registration_number)
      or t.updated_by_robot is distinct from true
      or t.updated_by_robot_at is distinct from c.created_at
      or t.last_service_km is distinct from coalesce(c.odometer_reading, t.last_service_km)
      or t.last_service_dealer is distinct from coalesce(c.serviced_at_dealer, t.last_service_dealer)
      or t.last_service_date is distinct from coalesce(c.parsed_service_at::date, t.last_service_date)
      or t.first_name is distinct from coalesce(c.contact_full_name, t.first_name)
      or t.last_service_type is distinct from coalesce(c.sr_type, t.last_service_type)
    );
end;
$$;


--
-- Name: FUNCTION refresh_all_service_data_from_service_history(p_chassis_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_all_service_data_from_service_history(p_chassis_key text) IS 'Refreshes all_service_data from EV/PV service-history test sources (contact_full_name column).';


--
-- Name: refresh_job_card_closed_dms_revenue(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_job_card_closed_dms_revenue(p_job_card_number text, p_location text DEFAULT NULL::text, p_portal text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_updated integer := 0;
begin
  if coalesce(btrim(p_job_card_number), '') = '' then
    return 0;
  end if;

  with target as (
    select
      jc.id,
      d.final_labour_amount,
      d.total_invoice_amount
    from public.job_card_closed_data jc
    left join lateral public.latest_psf_revenue_dms_for_job_card(
      jc.job_card_number,
      jc.location,
      jc.portal
    ) d on true
    where upper(btrim(jc.job_card_number)) = upper(btrim(p_job_card_number))
      and (
        coalesce(btrim(p_location), '') = ''
        or jc.location = p_location
      )
      and (
        coalesce(btrim(p_portal), '') = ''
        or jc.portal = p_portal
      )
  )
  update public.job_card_closed_data jc
     set dms_final_labour_amount = target.final_labour_amount,
         dms_total_invoice_amount = target.total_invoice_amount
    from target
   where jc.id = target.id
     and (
       jc.dms_final_labour_amount is distinct from target.final_labour_amount
       or jc.dms_total_invoice_amount is distinct from target.total_invoice_amount
     );

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


--
-- Name: refresh_job_card_closed_dms_revenue_batch(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_job_card_closed_dms_revenue_batch(p_keys jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated integer := 0;
BEGIN
  PERFORM set_config('statement_timeout', '120s', true);

  IF p_keys IS NULL OR jsonb_typeof(p_keys) <> 'array' OR jsonb_array_length(p_keys) = 0 THEN
    RETURN 0;
  END IF;

  ALTER TABLE public.job_card_closed_data
    DISABLE TRIGGER trg_refresh_all_service_data_from_job_card_closed_data;

  WITH keys AS (
    SELECT DISTINCT
      upper(btrim(r.job_card_number)) AS job_card_number,
      nullif(btrim(r.location), '') AS location,
      nullif(btrim(r.portal), '') AS portal
    FROM jsonb_to_recordset(p_keys) AS r(
      job_card_number text,
      location text,
      portal text
    )
    WHERE coalesce(btrim(r.job_card_number), '') <> ''
      AND nullif(btrim(r.location), '') IS NOT NULL
      AND nullif(btrim(r.portal), '') IS NOT NULL
  ),
  latest_dms AS (
    SELECT DISTINCT ON (
      upper(btrim(d.job_card_number)),
      d.location,
      d.portal
    )
      upper(btrim(d.job_card_number)) AS job_card_number,
      d.location,
      d.portal,
      d.final_labour_amount,
      d.total_invoice_amount
    FROM public.psf_revenue_dms d
    INNER JOIN keys k
      ON upper(btrim(d.job_card_number)) = k.job_card_number
     AND d.location = k.location
     AND d.portal = k.portal
    ORDER BY
      upper(btrim(d.job_card_number)),
      d.location,
      d.portal,
      d.invoice_date DESC NULLS LAST,
      d.id DESC
  )
  UPDATE public.job_card_closed_data jc
     SET dms_final_labour_amount = ld.final_labour_amount,
         dms_total_invoice_amount = ld.total_invoice_amount
    FROM latest_dms ld
   WHERE upper(btrim(jc.job_card_number)) = ld.job_card_number
     AND jc.location = ld.location
     AND jc.portal = ld.portal
     AND (
       jc.dms_final_labour_amount IS DISTINCT FROM ld.final_labour_amount
       OR jc.dms_total_invoice_amount IS DISTINCT FROM ld.total_invoice_amount
     );

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  ALTER TABLE public.job_card_closed_data
    ENABLE TRIGGER trg_refresh_all_service_data_from_job_card_closed_data;

  RETURN v_updated;
EXCEPTION
  WHEN OTHERS THEN
    ALTER TABLE public.job_card_closed_data
      ENABLE TRIGGER trg_refresh_all_service_data_from_job_card_closed_data;
    RAISE;
END;
$$;


--
-- Name: FUNCTION refresh_job_card_closed_dms_revenue_batch(p_keys jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_job_card_closed_dms_revenue_batch(p_keys jsonb) IS 'Bulk mirror latest psf_revenue_dms into job_card_closed_data.dms_* columns. Skips all_service_data row trigger during update.';


--
-- Name: refresh_parts_requests_ggn_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_parts_requests_ggn_stock() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_updated integer := 0;
begin
  if not (
    public.is_admin()
    or public.has_module_modify('parts_inventory')
    or public.has_module_modify('job_cards')
    or public.has_module_modify('parts_spm')
  ) then
    raise exception 'Insufficient permissions';
  end if;

  update public.parts_requests pr
  set ggn_stock_status = public.ggn_stock_status_for_part(pr.parts_number)
  where coalesce(btrim(pr.parts_number), '') <> '';

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  return v_updated;
end;
$$;


--
-- Name: refresh_reception_updation_flags(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_reception_updation_flags() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cleared integer := 0;
  v_marked integer := 0;
BEGIN
  UPDATE public.service_reception_entries
  SET
    has_updation_available = false,
    updation_code = NULL,
    updation_name = NULL
  WHERE has_updation_available = true
     OR updation_code IS NOT NULL
     OR updation_name IS NOT NULL;
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  UPDATE public.service_reception_entries sre
  SET
    has_updation_available = true,
    updation_code = matched.updation_code,
    updation_name = matched.updation_name
  FROM (
    SELECT DISTINCT ON (sre_inner.id)
      sre_inner.id,
      v.updation_code,
      v.updation_name
    FROM public.service_reception_entries sre_inner
    INNER JOIN public.vehicle_updation_data v
      ON upper(btrim(v.vehicle_number)) = upper(btrim(sre_inner.reg_number))
     AND NULLIF(btrim(v.vehicle_number), '') IS NOT NULL
     AND (
       NULLIF(btrim(sre_inner.portal), '') IS NULL
       OR v.portal = sre_inner.portal
     )
    WHERE NULLIF(btrim(sre_inner.reg_number), '') IS NOT NULL
    ORDER BY sre_inner.id, v.imported_at DESC, v.id DESC
  ) matched
  WHERE sre.id = matched.id;

  GET DIAGNOSTICS v_marked = ROW_COUNT;

  RETURN jsonb_build_object(
    'cleared_count', v_cleared,
    'marked_count', v_marked
  );
END;
$$;


--
-- Name: FUNCTION refresh_reception_updation_flags(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_reception_updation_flags() IS 'Recompute has_updation_available for all reception rows from vehicle_updation_data.';


--
-- Name: register_staff_device_token(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_staff_device_token(p_device_token text, p_token_provider text, p_token_platform text, p_app_version text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_token text := btrim(COALESCE(p_device_token, ''));
  v_provider text := lower(btrim(COALESCE(p_token_provider, '')));
  v_platform text := lower(btrim(COALESCE(p_token_platform, '')));
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = v_uid AND u.is_active = true) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF char_length(v_token) < 10 OR char_length(v_token) > 4096 THEN
    RAISE EXCEPTION 'Invalid device token';
  END IF;
  IF v_provider NOT IN ('fcm', 'expo') OR v_platform NOT IN ('ios', 'android') THEN
    RAISE EXCEPTION 'Invalid token metadata';
  END IF;

  INSERT INTO public.device_push_tokens (
    audience, user_id, phone_10, device_token, token_provider, token_platform, app_version, is_active, last_used_at
  ) VALUES (
    'staff', v_uid, NULL, v_token, v_provider, v_platform, NULLIF(btrim(COALESCE(p_app_version, '')), ''), true, now()
  )
  ON CONFLICT (device_token) DO UPDATE SET
    audience = 'staff',
    user_id = EXCLUDED.user_id,
    phone_10 = NULL,
    token_provider = EXCLUDED.token_provider,
    token_platform = EXCLUDED.token_platform,
    app_version = EXCLUDED.app_version,
    is_active = true,
    last_used_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: reopen_complaint(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_complaint(p_token text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_complaint_id bigint;
  v_dealer_code text;
  v_status text;
  v_customer_name text;
  v_priority text;
  v_resolution_mins integer;
BEGIN
  SELECT complaint_id INTO v_complaint_id
  FROM public.complaint_access_links
  WHERE token = p_token AND status = 'consumed';

  IF v_complaint_id IS NULL THEN
    RAISE EXCEPTION 'Invalid complaint link';
  END IF;

  SELECT dealer_code, status, customer_name, priority
  INTO v_dealer_code, v_status, v_customer_name, v_priority
  FROM public.complaint_tickets
  WHERE id = v_complaint_id;

  IF v_status NOT IN ('resolved', 'closed') THEN
    RAISE EXCEPTION 'Ticket is not in a reopenable state';
  END IF;

  -- Get SLA resolution time for this priority
  SELECT resolution_mins INTO v_resolution_mins
  FROM public.complaint_sla_policies
  WHERE dealer_code = v_dealer_code AND priority = v_priority;

  -- Reopen: status → reopened, escalate, restart resolution SLA
  UPDATE public.complaint_tickets
  SET
    status = 'reopened',
    reopened_at = now(),
    is_escalated = true,
    escalated_at = now(),
    escalation_reason = p_reason,
    resolution_due_at = now() + (COALESCE(v_resolution_mins, 1440) || ' minutes')::interval
  WHERE id = v_complaint_id;

  -- Log activity
  INSERT INTO public.complaint_activity (
    dealer_code, complaint_id, event_type, actor_type, actor_name, note
  ) VALUES (
    v_dealer_code, v_complaint_id, 'reopened', 'customer', v_customer_name,
    'Reopened by customer: ' || p_reason
  );

  -- Return updated view
  RETURN public.get_complaint_by_token(p_token);
END;
$$;


--
-- Name: replace_busy_parts_source(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_busy_parts_source(p_source_type text, p_source_file_name text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_file text := nullif(btrim(p_source_file_name), '');
  v_new_invoices integer := 0;
  v_skipped_invoices integer := 0;
  v_new_parts_rows integer := 0;
  v_skipped_parts_rows integer := 0;
  v_accounts_refreshed integer := 0;
BEGIN
  IF NOT (public.is_admin() OR public.has_module_modify('busy')) THEN
    RAISE EXCEPTION 'Permission denied for BUSY Parts persist';
  END IF;

  IF p_source_type NOT IN ('PV', 'EV') THEN
    RAISE EXCEPTION 'Invalid source_type: %. Expected PV or EV.', p_source_type;
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a JSON array';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('busy_parts'), hashtext(p_source_type));

  WITH incoming AS (
    SELECT DISTINCT ON (btrim(rec.source_row_key))
      btrim(rec.job_card_no) AS job_card_no,
      btrim(rec.invoice_no) AS invoice_no,
      rec.invoice_date::date AS invoice_date,
      rec.gst_rate,
      rec.net_amount,
      btrim(rec.source_row_key) AS source_row_key,
      nullif(btrim(rec.account_name), '') AS account_name,
      CASE
        WHEN upper(regexp_replace(split_part(btrim(coalesce(rec.account_name, '')), '-', 1), '\s+', '', 'g')) ~ '^[0-9A-Z]+$'
          THEN upper(regexp_replace(split_part(btrim(coalesce(rec.account_name, '')), '-', 1), '\s+', '', 'g'))
        WHEN upper(regexp_replace(btrim(coalesce(rec.account_code, '')), '\s+', '', 'g')) ~ '^[0-9A-Z]+$'
          THEN upper(regexp_replace(btrim(coalesce(rec.account_code, '')), '\s+', '', 'g'))
        ELSE NULL
      END AS account_code
    FROM jsonb_to_recordset(p_rows) AS rec(
      job_card_no text,
      invoice_no text,
      invoice_date date,
      gst_rate numeric,
      net_amount numeric,
      source_row_key text,
      account_name text,
      account_code text
    )
    WHERE rec.job_card_no IS NOT NULL AND btrim(rec.job_card_no) <> ''
      AND rec.invoice_no IS NOT NULL AND btrim(rec.invoice_no) <> ''
      AND rec.invoice_date IS NOT NULL
      AND rec.source_row_key IS NOT NULL AND btrim(rec.source_row_key) <> ''
    ORDER BY btrim(rec.source_row_key)
  ),
  classified AS (
    SELECT
      i.*,
      EXISTS (
        SELECT 1
        FROM public.busy_parts bp
        WHERE bp.source_type = p_source_type
          AND upper(btrim(bp.invoice_no)) = upper(i.invoice_no)
          AND bp.invoice_date = i.invoice_date
      ) AS already_uploaded
    FROM incoming i
  ),
  refreshed AS (
    UPDATE public.busy_parts bp
    SET
      account_name = COALESCE(c.account_name, bp.account_name),
      account_code = c.account_code
    FROM classified c
    WHERE bp.source_type = p_source_type
      AND bp.source_row_key = c.source_row_key
      AND c.account_code IS NOT NULL
      AND (
        bp.account_name IS DISTINCT FROM COALESCE(c.account_name, bp.account_name)
        OR bp.account_code IS DISTINCT FROM c.account_code
      )
    RETURNING bp.id
  ),
  ins AS (
    INSERT INTO public.busy_parts (
      source_type,
      job_card_no,
      invoice_no,
      invoice_date,
      gst_rate,
      net_amount,
      source_row_key,
      source_file_name,
      uploaded_at,
      account_name,
      account_code
    )
    SELECT
      p_source_type,
      c.job_card_no,
      c.invoice_no,
      c.invoice_date,
      c.gst_rate,
      c.net_amount,
      c.source_row_key,
      v_file,
      now(),
      c.account_name,
      c.account_code
    FROM classified c
    WHERE NOT c.already_uploaded
    RETURNING 1
  )
  SELECT
    (
      SELECT count(*)::integer
      FROM (SELECT DISTINCT upper(invoice_no), invoice_date FROM classified WHERE NOT already_uploaded) s
    ),
    (
      SELECT count(*)::integer
      FROM (SELECT DISTINCT upper(invoice_no), invoice_date FROM classified WHERE already_uploaded) s
    ),
    (SELECT count(*)::integer FROM classified WHERE NOT already_uploaded),
    (SELECT count(*)::integer FROM classified WHERE already_uploaded),
    (SELECT count(*)::integer FROM refreshed)
  INTO
    v_new_invoices,
    v_skipped_invoices,
    v_new_parts_rows,
    v_skipped_parts_rows,
    v_accounts_refreshed
  FROM (SELECT count(*) FROM ins) AS inserted;

  RETURN jsonb_build_object(
    'deleted', 0,
    'inserted', v_new_parts_rows,
    'new_invoices', v_new_invoices,
    'new_parts_rows', v_new_parts_rows,
    'skipped_invoices', v_skipped_invoices,
    'skipped_parts_rows', v_skipped_parts_rows,
    'accounts_refreshed', v_accounts_refreshed
  );
END;
$_$;


--
-- Name: FUNCTION replace_busy_parts_source(p_source_type text, p_source_file_name text, p_rows jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replace_busy_parts_source(p_source_type text, p_source_file_name text, p_rows jsonb) IS 'Append-only busy_parts import for one source_type (PV or EV). Skips invoices already present for source_type + invoice_no + invoice_date. Inserts every line of a new invoice in the same transaction. On re-import, updates account_name/account_code only when the source_row_key already exists. Never deletes existing rows and never rewrites amounts.';


--
-- Name: replace_vehicle_updation_portal(text, uuid, text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_vehicle_updation_portal(p_portal text, p_upload_session_id uuid, p_file_name text, p_sheet_name text, p_uploaded_by_email text, p_skipped_blank_rows integer, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted_count integer := 0;
  v_inserted_count integer := 0;
  v_refresh jsonb;
BEGIN
  IF NOT (public.is_admin() OR public.has_module_modify('job_cards')) THEN
    RAISE EXCEPTION 'Permission denied for vehicle updation import';
  END IF;

  IF p_portal NOT IN ('EV', 'PV') THEN
    RAISE EXCEPTION 'Invalid portal: %. Expected EV or PV.', p_portal;
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'p_rows must be a JSON array';
  END IF;

  DELETE FROM public.vehicle_updation_data
  WHERE portal = p_portal;
  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  INSERT INTO public.vehicle_updation_uploads (
    portal,
    upload_kind,
    upload_session_id,
    uploaded_by_email,
    file_name,
    sheet_name,
    row_count,
    skipped_blank_rows
  ) VALUES (
    p_portal,
    'pending',
    p_upload_session_id,
    nullif(btrim(p_uploaded_by_email), ''),
    nullif(btrim(p_file_name), ''),
    nullif(btrim(p_sheet_name), ''),
    coalesce(jsonb_array_length(p_rows), 0),
    coalesce(p_skipped_blank_rows, 0)
  );

  IF jsonb_array_length(p_rows) > 0 THEN
    INSERT INTO public.vehicle_updation_data (
      portal,
      updation_code,
      updation_type,
      updation_name,
      chassis_no,
      model,
      vehicle_number,
      contact_number,
      selling_dealer_code,
      selling_dealer,
      city,
      region,
      zone,
      pcr_no,
      status,
      updation_dealer_code,
      code_chassis_concat,
      campaign_cost,
      fuel_type,
      source_row_number,
      source_file_name,
      upload_session_id,
      source_row_data
    )
    SELECT
      p_portal,
      coalesce(nullif(btrim(r.updation_code), ''), ''),
      nullif(btrim(r.updation_type), ''),
      nullif(btrim(r.updation_name), ''),
      upper(btrim(r.chassis_no)),
      nullif(btrim(r.model), ''),
      nullif(btrim(r.vehicle_number), ''),
      nullif(btrim(r.contact_number), ''),
      nullif(btrim(r.selling_dealer_code), ''),
      nullif(btrim(r.selling_dealer), ''),
      nullif(btrim(r.city), ''),
      nullif(btrim(r.region), ''),
      nullif(btrim(r.zone), ''),
      nullif(btrim(r.pcr_no), ''),
      nullif(btrim(r.status), ''),
      nullif(btrim(r.updation_dealer_code), ''),
      nullif(btrim(r.code_chassis_concat), ''),
      r.campaign_cost,
      nullif(btrim(r.fuel_type), ''),
      r.source_row_number,
      nullif(btrim(r.source_file_name), ''),
      p_upload_session_id,
      coalesce(r.source_row_data, '{}'::jsonb)
    FROM jsonb_to_recordset(p_rows) AS r(
      updation_code text,
      updation_type text,
      updation_name text,
      chassis_no text,
      model text,
      vehicle_number text,
      contact_number text,
      selling_dealer_code text,
      selling_dealer text,
      city text,
      region text,
      zone text,
      pcr_no text,
      status text,
      updation_dealer_code text,
      code_chassis_concat text,
      campaign_cost numeric,
      fuel_type text,
      source_row_number integer,
      source_file_name text,
      source_row_data jsonb
    )
    WHERE nullif(btrim(r.chassis_no), '') IS NOT NULL;

    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
  END IF;

  v_refresh := public.refresh_reception_updation_flags();

  RETURN jsonb_build_object(
    'portal', p_portal,
    'deleted_count', v_deleted_count,
    'inserted_count', v_inserted_count,
    'skipped_blank_rows', coalesce(p_skipped_blank_rows, 0),
    'upload_session_id', p_upload_session_id,
    'reception_flags', v_refresh
  );
END;
$$;


--
-- Name: FUNCTION replace_vehicle_updation_portal(p_portal text, p_upload_session_id uuid, p_file_name text, p_sheet_name text, p_uploaded_by_email text, p_skipped_blank_rows integer, p_rows jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replace_vehicle_updation_portal(p_portal text, p_upload_session_id uuid, p_file_name text, p_sheet_name text, p_uploaded_by_email text, p_skipped_blank_rows integer, p_rows jsonb) IS 'Atomically replace all vehicle_updation_data rows for one portal and record upload metadata.';


--
-- Name: reschedule_auto_service_reminder_cron(time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reschedule_auto_service_reminder_cron(p_send_time time without time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_existing_job_id bigint;
  v_utc_time         time;
  v_cron             text;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise notice 'pg_cron not installed — skipping reschedule for auto-service-reminder';
    return;
  end if;

  select j.jobid
  into v_existing_job_id
  from cron.job j
  where j.jobname = 'auto-service-reminder-daily-ist'
  limit 1;

  if v_existing_job_id is not null then
    perform cron.unschedule(v_existing_job_id);
  end if;

  -- Asia/Kolkata is UTC+5:30 year-round (no DST).
  v_utc_time := (p_send_time - interval '5 hours 30 minutes')::time;
  v_cron := extract(minute from v_utc_time)::int || ' ' || extract(hour from v_utc_time)::int || ' * * *';

  perform cron.schedule(
    'auto-service-reminder-daily-ist',
    v_cron,
    $job$ select public.invoke_auto_service_reminder_daily(); $job$
  );
end;
$_$;


--
-- Name: FUNCTION reschedule_auto_service_reminder_cron(p_send_time time without time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reschedule_auto_service_reminder_cron(p_send_time time without time zone) IS 'Re-registers the auto-service-reminder-daily-ist pg_cron job for the given Asia/Kolkata send time.';


