--
-- Name: run_psf_import_via_staging(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_psf_import_via_staging(p_branch_slot text, p_source_file_name text, p_rows jsonb) RETURNS TABLE(import_run_id bigint, status text, total_rows integer, staged_rows integer, valid_rows integer, inserted_rows integer, updated_rows integer, skipped_rows integer, rejected_rows integer, error_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id bigint;
  v_total_rows integer := 0;
  v_staged_rows integer := 0;
  v_valid_rows integer := 0;
  v_inserted_rows integer := 0;
  v_updated_rows integer := 0;
  v_skipped_rows integer := 0;
  v_rejected_rows integer := 0;
begin
  v_total_rows := coalesce(jsonb_array_length(coalesce(p_rows, '[]'::jsonb)), 0);

  insert into public.psf_import_runs (
    status,
    branch_slot,
    source_file_name,
    total_rows,
    started_at
  ) values (
    'running',
    p_branch_slot,
    p_source_file_name,
    v_total_rows,
    now()
  )
  returning id into v_run_id;

  if v_total_rows > 0 then
    insert into public.psf_import_staging (
      import_run_id,
      row_number,
      branch,
      branch_label,
      location,
      portal,
      invoice_date,
      job_card_number,
      sr_type,
      chassis_number,
      final_labour_amount,
      final_spares_amount,
      total_invoice_amount,
      parent_product_line,
      product_line,
      created_date_time,
      closed_date_time,
      first_name,
      last_name,
      sr_assigned_to,
      employee_code,
      vehicle_registration_number,
      vehicle_sale_date,
      account_phone_number,
      lubs_revenue,
      kms_run,
      last_service_km,
      last_service_date,
      source_row
    )
    select
      v_run_id,
      src.ordinality::integer,
      nullif(btrim(src.row ->> 'branch'), ''),
      nullif(btrim(src.row ->> 'branch_label'), ''),
      nullif(btrim(src.row ->> 'location'), ''),
      public.psf_normalize_portal(src.row ->> 'portal'),
      public.psf_try_date(src.row ->> 'invoice_date'),
      nullif(upper(btrim(src.row ->> 'job_card_number')), ''),
      nullif(btrim(src.row ->> 'sr_type'), ''),
      nullif(upper(btrim(src.row ->> 'chassis_number')), ''),
      public.psf_try_numeric(src.row ->> 'final_labour_amount'),
      public.psf_try_numeric(src.row ->> 'final_spares_amount'),
      public.psf_try_numeric(src.row ->> 'total_invoice_amount'),
      nullif(btrim(src.row ->> 'parent_product_line'), ''),
      nullif(btrim(src.row ->> 'product_line'), ''),
      public.psf_try_timestamptz(src.row ->> 'created_date_time'),
      public.psf_try_timestamptz(src.row ->> 'closed_date_time'),
      nullif(btrim(src.row ->> 'first_name'), ''),
      nullif(btrim(src.row ->> 'last_name'), ''),
      nullif(btrim(src.row ->> 'sr_assigned_to'), ''),
      nullif(upper(btrim(src.row ->> 'employee_code')), ''),
      nullif(upper(btrim(src.row ->> 'vehicle_registration_number')), ''),
      public.psf_try_date(src.row ->> 'vehicle_sale_date'),
      nullif(btrim(src.row ->> 'account_phone_number'), ''),
      public.psf_try_numeric(src.row ->> 'lubs_revenue'),
      public.psf_try_numeric(src.row ->> 'kms_run'),
      public.psf_try_numeric(src.row ->> 'last_service_km'),
      public.psf_try_date(src.row ->> 'last_service_date'),
      src.row
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) with ordinality as src(row, ordinality);
  end if;

  select count(*) into v_staged_rows
  from public.psf_import_staging s
  where s.import_run_id = v_run_id;

  with staged as (
    select
      s.*,
      nullif(btrim(em.location), '') as em_location,
      public.psf_normalize_portal(em.fuel_type) as em_portal,
      coalesce(
        nullif(btrim(em.location), ''),
        public.psf_fallback_location(s.employee_code),
        nullif(btrim(s.location), '')
      ) as resolved_location,
      coalesce(
        public.psf_normalize_portal(em.fuel_type),
        public.psf_fallback_portal(s.employee_code),
        public.psf_normalize_portal(s.portal)
      ) as resolved_portal
    from public.psf_import_staging s
    left join public.employee_master em
      on upper(btrim(coalesce(em.employee_code, ''))) = upper(btrim(coalesce(s.employee_code, '')))
    where s.import_run_id = v_run_id
  ),
  valid_dedup as (
    select distinct on (
      upper(btrim(coalesce(resolved_location, ''))),
      upper(btrim(coalesce(resolved_portal, ''))),
      upper(btrim(coalesce(job_card_number, ''))),
      invoice_date
    )
      *
    from staged
    where
      resolved_location is not null and btrim(resolved_location) <> ''
      and resolved_portal in ('PV', 'EV')
      and job_card_number is not null and btrim(job_card_number) <> ''
      and invoice_date is not null
    order by
      upper(btrim(coalesce(resolved_location, ''))),
      upper(btrim(coalesce(resolved_portal, ''))),
      upper(btrim(coalesce(job_card_number, ''))),
      invoice_date,
      row_number desc
  ),
  existing as (
    select
      v.id as staging_id,
      t.id as target_id,
      (
        t.branch is distinct from v.resolved_location
        or t.branch_label is distinct from v.resolved_location
        or t.location is distinct from v.resolved_location
        or t.portal is distinct from v.resolved_portal
        or t.sr_type is distinct from v.sr_type
        or t.chassis_number is distinct from v.chassis_number
        or t.final_labour_amount is distinct from v.final_labour_amount
        or t.final_spares_amount is distinct from v.final_spares_amount
        or t.total_invoice_amount is distinct from v.total_invoice_amount
        or t.parent_product_line is distinct from v.parent_product_line
        or t.product_line is distinct from v.product_line
        or t.created_date_time is distinct from v.created_date_time
        or t.closed_date_time is distinct from v.closed_date_time
        or t.first_name is distinct from v.first_name
        or t.last_name is distinct from v.last_name
        or t.sr_assigned_to is distinct from v.sr_assigned_to
        or t.employee_code is distinct from v.employee_code
        or t.vehicle_registration_number is distinct from v.vehicle_registration_number
        or t.vehicle_sale_date is distinct from v.vehicle_sale_date
        or t.account_phone_number is distinct from v.account_phone_number
        or t.lubs_revenue is distinct from v.lubs_revenue
        or t.kms_run is distinct from v.kms_run
        or t.last_service_km is distinct from v.last_service_km
        or t.last_service_date is distinct from v.last_service_date
      ) as needs_update
    from valid_dedup v
    join public.job_card_closed_data t
      on t.location = v.resolved_location
      and t.portal = v.resolved_portal
      and upper(btrim(t.job_card_number)) = upper(btrim(v.job_card_number))
      and t.invoice_date = v.invoice_date
  ),
  do_update as (
    update public.job_card_closed_data t
    set
      branch = v.resolved_location,
      branch_label = v.resolved_location,
      location = v.resolved_location,
      portal = v.resolved_portal,
      job_card_number = v.job_card_number,
      sr_type = v.sr_type,
      chassis_number = v.chassis_number,
      final_labour_amount = v.final_labour_amount,
      final_spares_amount = v.final_spares_amount,
      total_invoice_amount = v.total_invoice_amount,
      parent_product_line = v.parent_product_line,
      product_line = v.product_line,
      created_date_time = v.created_date_time,
      closed_date_time = v.closed_date_time,
      invoice_date = v.invoice_date,
      first_name = v.first_name,
      last_name = v.last_name,
      sr_assigned_to = v.sr_assigned_to,
      employee_code = v.employee_code,
      vehicle_registration_number = v.vehicle_registration_number,
      vehicle_sale_date = v.vehicle_sale_date,
      account_phone_number = v.account_phone_number,
      lubs_revenue = v.lubs_revenue,
      kms_run = v.kms_run,
      last_service_km = v.last_service_km,
      last_service_date = v.last_service_date
    from valid_dedup v
    join existing e
      on e.staging_id = v.id
    where
      e.target_id = t.id
      and e.needs_update
    returning t.id
  ),
  do_insert as (
    insert into public.job_card_closed_data (
      branch,
      branch_label,
      location,
      portal,
      job_card_number,
      sr_type,
      chassis_number,
      final_labour_amount,
      final_spares_amount,
      total_invoice_amount,
      parent_product_line,
      product_line,
      created_date_time,
      closed_date_time,
      invoice_date,
      first_name,
      last_name,
      sr_assigned_to,
      employee_code,
      vehicle_registration_number,
      vehicle_sale_date,
      account_phone_number,
      lubs_revenue,
      kms_run,
      last_service_km,
      last_service_date
    )
    select
      v.resolved_location,
      v.resolved_location,
      v.resolved_location,
      v.resolved_portal,
      v.job_card_number,
      v.sr_type,
      v.chassis_number,
      v.final_labour_amount,
      v.final_spares_amount,
      v.total_invoice_amount,
      v.parent_product_line,
      v.product_line,
      v.created_date_time,
      v.closed_date_time,
      v.invoice_date,
      v.first_name,
      v.last_name,
      v.sr_assigned_to,
      v.employee_code,
      v.vehicle_registration_number,
      v.vehicle_sale_date,
      v.account_phone_number,
      v.lubs_revenue,
      v.kms_run,
      v.last_service_km,
      v.last_service_date
    from valid_dedup v
    left join existing e
      on e.staging_id = v.id
    where e.staging_id is null
    returning id
  )
  select
    (select count(*) from valid_dedup),
    (select count(*) from do_insert),
    (select count(*) from do_update),
    (select count(*) from existing where not needs_update)
  into
    v_valid_rows,
    v_inserted_rows,
    v_updated_rows,
    v_skipped_rows;

  v_rejected_rows := greatest(v_staged_rows - v_valid_rows, 0);

  -- Retention policy: staging is transient execution data; keep only run-level counters.
  delete from public.psf_import_staging s
  where s.import_run_id = v_run_id;

  update public.psf_import_runs
  set
    status = 'completed',
    staged_rows = v_staged_rows,
    valid_rows = v_valid_rows,
    inserted_rows = v_inserted_rows,
    updated_rows = v_updated_rows,
    skipped_rows = v_skipped_rows,
    rejected_rows = v_rejected_rows,
    completed_at = now()
  where id = v_run_id;

  return query
  select
    v_run_id,
    'completed'::text,
    v_total_rows,
    v_staged_rows,
    v_valid_rows,
    v_inserted_rows,
    v_updated_rows,
    v_skipped_rows,
    v_rejected_rows,
    null::text;
exception
  when others then
    if v_run_id is not null then
      update public.psf_import_runs
      set
        status = 'failed',
        error_message = sqlerrm,
        completed_at = now()
      where id = v_run_id;
    end if;

    return query
    select
      coalesce(v_run_id, 0),
      'failed'::text,
      coalesce(v_total_rows, 0),
      coalesce(v_staged_rows, 0),
      coalesce(v_valid_rows, 0),
      coalesce(v_inserted_rows, 0),
      coalesce(v_updated_rows, 0),
      coalesce(v_skipped_rows, 0),
      coalesce(v_rejected_rows, 0),
      sqlerrm;
end;
$$;


--
-- Name: run_psf_revenue_dms_import_batch(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_psf_revenue_dms_import_batch(p_rows jsonb) RETURNS TABLE(processed_rows integer, inserted_rows integer, updated_rows integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM public.run_psf_revenue_dms_import_batch(p_rows, false);
$$;


--
-- Name: FUNCTION run_psf_revenue_dms_import_batch(p_rows jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_psf_revenue_dms_import_batch(p_rows jsonb) IS 'Bulk upsert psf_revenue_dms from JSON array (Import page). Disables per-row JCC DMS sync trigger during merge; bulk-refreshes affected job cards once at end.';


--
-- Name: run_psf_revenue_dms_import_batch(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_psf_revenue_dms_import_batch(p_rows jsonb, p_sync_job_cards boolean DEFAULT false) RETURNS TABLE(processed_rows integer, inserted_rows integer, updated_rows integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_processed integer := 0;
  v_inserted integer := 0;
  v_updated integer := 0;
BEGIN
  PERFORM set_config('statement_timeout', '120s', true);

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN QUERY SELECT 0, 0, 0;
    RETURN;
  END IF;

  ALTER TABLE public.psf_revenue_dms DISABLE TRIGGER trg_refresh_job_card_closed_dms_revenue;

  WITH src AS (
    SELECT
      coalesce(nullif(btrim(r.branch), ''), nullif(btrim(r.location), '')) AS branch,
      nullif(btrim(r.location), '') AS location,
      nullif(btrim(r.portal), '') AS portal,
      nullif(btrim(r.invoice_number), '') AS invoice_number,
      r.invoice_date,
      nullif(btrim(r.account), '') AS account,
      nullif(btrim(r.first_name), '') AS first_name,
      nullif(btrim(r.last_name), '') AS last_name,
      nullif(btrim(r.invoice_type), '') AS invoice_type,
      nullif(btrim(r.invoice_format), '') AS invoice_format,
      nullif(btrim(r.invoice_status), '') AS invoice_status,
      r.final_labour_amount,
      r.final_spares_amount,
      r.total_invoice_amount,
      upper(nullif(btrim(r.job_card_number), '')) AS job_card_number,
      nullif(btrim(r.sr_number), '') AS sr_number,
      upper(nullif(btrim(r.chassis_number), '')) AS chassis_number,
      nullif(btrim(r.vehicle_registration_number), '') AS vehicle_registration_number,
      nullif(btrim(r.irn), '') AS irn,
      r.irn_date,
      nullif(btrim(r.irn_status), '') AS irn_status,
      r.irn_cancellation_date,
      r.tcs_percent,
      r.tcs_assessable_amount,
      r.final_tcs_amount,
      nullif(btrim(r.cancellation_reason), '') AS cancellation_reason,
      nullif(btrim(r.arn), '') AS arn,
      nullif(btrim(r.crn), '') AS crn,
      nullif(btrim(r.contact_home_phone), '') AS contact_home_phone,
      nullif(btrim(r.account_phone_number), '') AS account_phone_number,
      nullif(btrim(r.contact_cell_phone), '') AS contact_cell_phone,
      nullif(btrim(r.contact_work_phone), '') AS contact_work_phone,
      nullif(btrim(r.jc_supervisor), '') AS jc_supervisor,
      r.delivery_date,
      nullif(btrim(r.reason_for_delay), '') AS reason_for_delay,
      nullif(btrim(r.sr_type), '') AS sr_type,
      r.kms_run,
      nullif(btrim(r.sr_assigned_to), '') AS sr_assigned_to,
      nullif(btrim(r.employee_code), '') AS employee_code,
      r.discounts_labour,
      r.other_charges_labour,
      r.service_tax,
      r.swachh_bharat_cess_amount,
      r.krishi_kalyan_cess_amount,
      r.wct,
      r.education_cess,
      r.discounts_parts,
      r.other_charges_parts,
      r.tax_parts,
      nullif(btrim(r.mode_of_payment), '') AS mode_of_payment,
      r.invoice_cancellation_date,
      nullif(btrim(r.prolife_flag), '') AS prolife_flag
    FROM jsonb_to_recordset(p_rows) AS r(
      branch text,
      location text,
      portal text,
      invoice_number text,
      invoice_date date,
      account text,
      first_name text,
      last_name text,
      invoice_type text,
      invoice_format text,
      invoice_status text,
      final_labour_amount numeric,
      final_spares_amount numeric,
      total_invoice_amount numeric,
      job_card_number text,
      sr_number text,
      chassis_number text,
      vehicle_registration_number text,
      irn text,
      irn_date date,
      irn_status text,
      irn_cancellation_date date,
      tcs_percent numeric,
      tcs_assessable_amount numeric,
      final_tcs_amount numeric,
      cancellation_reason text,
      arn text,
      crn text,
      contact_home_phone text,
      account_phone_number text,
      contact_cell_phone text,
      contact_work_phone text,
      jc_supervisor text,
      delivery_date date,
      reason_for_delay text,
      sr_type text,
      kms_run numeric,
      sr_assigned_to text,
      employee_code text,
      discounts_labour numeric,
      other_charges_labour numeric,
      service_tax numeric,
      swachh_bharat_cess_amount numeric,
      krishi_kalyan_cess_amount numeric,
      wct numeric,
      education_cess numeric,
      discounts_parts numeric,
      other_charges_parts numeric,
      tax_parts numeric,
      mode_of_payment text,
      invoice_cancellation_date date,
      prolife_flag text
    )
  ),
  eligible AS (
    SELECT *
    FROM src
    WHERE location IS NOT NULL
      AND portal IS NOT NULL
      AND job_card_number IS NOT NULL
      AND invoice_date IS NOT NULL
      AND branch IS NOT NULL
  ),
  upserted AS (
    INSERT INTO public.psf_revenue_dms AS t (
      branch,
      location,
      portal,
      invoice_number,
      invoice_date,
      account,
      first_name,
      last_name,
      invoice_type,
      invoice_format,
      invoice_status,
      final_labour_amount,
      final_spares_amount,
      total_invoice_amount,
      job_card_number,
      sr_number,
      chassis_number,
      vehicle_registration_number,
      irn,
      irn_date,
      irn_status,
      irn_cancellation_date,
      tcs_percent,
      tcs_assessable_amount,
      final_tcs_amount,
      cancellation_reason,
      arn,
      crn,
      contact_home_phone,
      account_phone_number,
      contact_cell_phone,
      contact_work_phone,
      jc_supervisor,
      delivery_date,
      reason_for_delay,
      sr_type,
      kms_run,
      sr_assigned_to,
      employee_code,
      discounts_labour,
      other_charges_labour,
      service_tax,
      swachh_bharat_cess_amount,
      krishi_kalyan_cess_amount,
      wct,
      education_cess,
      discounts_parts,
      other_charges_parts,
      tax_parts,
      mode_of_payment,
      invoice_cancellation_date,
      prolife_flag
    )
    SELECT
      branch,
      location,
      portal,
      invoice_number,
      invoice_date,
      account,
      first_name,
      last_name,
      invoice_type,
      invoice_format,
      invoice_status,
      final_labour_amount,
      final_spares_amount,
      total_invoice_amount,
      job_card_number,
      sr_number,
      chassis_number,
      vehicle_registration_number,
      irn,
      irn_date,
      irn_status,
      irn_cancellation_date,
      tcs_percent,
      tcs_assessable_amount,
      final_tcs_amount,
      cancellation_reason,
      arn,
      crn,
      contact_home_phone,
      account_phone_number,
      contact_cell_phone,
      contact_work_phone,
      jc_supervisor,
      delivery_date,
      reason_for_delay,
      sr_type,
      kms_run,
      sr_assigned_to,
      employee_code,
      discounts_labour,
      other_charges_labour,
      service_tax,
      swachh_bharat_cess_amount,
      krishi_kalyan_cess_amount,
      wct,
      education_cess,
      discounts_parts,
      other_charges_parts,
      tax_parts,
      mode_of_payment,
      invoice_cancellation_date,
      prolife_flag
    FROM eligible
    ON CONFLICT ON CONSTRAINT uq_psf_revenue_dms_location_portal_job_card_invoice_date
    DO UPDATE SET
      branch = EXCLUDED.branch,
      invoice_number = EXCLUDED.invoice_number,
      account = EXCLUDED.account,
      first_name = EXCLUDED.first_name,
      last_name = EXCLUDED.last_name,
      invoice_type = EXCLUDED.invoice_type,
      invoice_format = EXCLUDED.invoice_format,
      invoice_status = EXCLUDED.invoice_status,
      final_labour_amount = EXCLUDED.final_labour_amount,
      final_spares_amount = EXCLUDED.final_spares_amount,
      total_invoice_amount = EXCLUDED.total_invoice_amount,
      sr_number = EXCLUDED.sr_number,
      chassis_number = EXCLUDED.chassis_number,
      vehicle_registration_number = EXCLUDED.vehicle_registration_number,
      irn = EXCLUDED.irn,
      irn_date = EXCLUDED.irn_date,
      irn_status = EXCLUDED.irn_status,
      irn_cancellation_date = EXCLUDED.irn_cancellation_date,
      tcs_percent = EXCLUDED.tcs_percent,
      tcs_assessable_amount = EXCLUDED.tcs_assessable_amount,
      final_tcs_amount = EXCLUDED.final_tcs_amount,
      cancellation_reason = EXCLUDED.cancellation_reason,
      arn = EXCLUDED.arn,
      crn = EXCLUDED.crn,
      contact_home_phone = EXCLUDED.contact_home_phone,
      account_phone_number = EXCLUDED.account_phone_number,
      contact_cell_phone = EXCLUDED.contact_cell_phone,
      contact_work_phone = EXCLUDED.contact_work_phone,
      jc_supervisor = EXCLUDED.jc_supervisor,
      delivery_date = EXCLUDED.delivery_date,
      reason_for_delay = EXCLUDED.reason_for_delay,
      sr_type = EXCLUDED.sr_type,
      kms_run = EXCLUDED.kms_run,
      sr_assigned_to = EXCLUDED.sr_assigned_to,
      employee_code = EXCLUDED.employee_code,
      discounts_labour = EXCLUDED.discounts_labour,
      other_charges_labour = EXCLUDED.other_charges_labour,
      service_tax = EXCLUDED.service_tax,
      swachh_bharat_cess_amount = EXCLUDED.swachh_bharat_cess_amount,
      krishi_kalyan_cess_amount = EXCLUDED.krishi_kalyan_cess_amount,
      wct = EXCLUDED.wct,
      education_cess = EXCLUDED.education_cess,
      discounts_parts = EXCLUDED.discounts_parts,
      other_charges_parts = EXCLUDED.other_charges_parts,
      tax_parts = EXCLUDED.tax_parts,
      mode_of_payment = EXCLUDED.mode_of_payment,
      invoice_cancellation_date = EXCLUDED.invoice_cancellation_date,
      prolife_flag = EXCLUDED.prolife_flag,
      updated_at = now()
    RETURNING (xmax = 0) AS inserted_flag, job_card_number, location, portal
  )
  SELECT
    count(*)::integer,
    count(*) FILTER (WHERE inserted_flag)::integer,
    count(*) FILTER (WHERE NOT inserted_flag)::integer
  INTO v_processed, v_inserted, v_updated
  FROM upserted;

  ALTER TABLE public.psf_revenue_dms ENABLE TRIGGER trg_refresh_job_card_closed_dms_revenue;

  IF p_sync_job_cards THEN
    PERFORM public.refresh_job_card_closed_dms_revenue_batch(p_rows);
  END IF;

  RETURN QUERY SELECT v_processed, v_inserted, v_updated;
EXCEPTION
  WHEN OTHERS THEN
    ALTER TABLE public.psf_revenue_dms ENABLE TRIGGER trg_refresh_job_card_closed_dms_revenue;
    RAISE;
END;
$$;


