--
-- Name: schedule_send_chat_push(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_send_chat_push() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_job_id bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    RAISE NOTICE 'pg_cron not installed — skipping send-chat-push schedule';
    RETURN;
  END IF;

  SELECT j.jobid INTO v_job_id
  FROM cron.job j
  WHERE j.jobname = 'send-chat-push'
  LIMIT 1;

  IF v_job_id IS NOT NULL THEN
    PERFORM cron.unschedule(v_job_id);
  END IF;

  PERFORM cron.schedule(
    'send-chat-push',
    '* * * * *',
    $job$ SELECT public.invoke_send_chat_push(); $job$
  );
END;
$_$;


--
-- Name: search_reception_reg_numbers(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_reception_reg_numbers(p_prefix text, p_limit integer DEFAULT 8) RETURNS TABLE(reg_number text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prefix text;
  v_limit  integer;
BEGIN
  v_prefix := upper(btrim(coalesce(p_prefix, '')));
  v_limit := greatest(coalesce(p_limit, 8), 1);

  IF v_prefix = '' THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT DISTINCT r.reg_number
    FROM public.service_reception_entries r
   WHERE upper(r.reg_number) LIKE v_prefix || '%'
     AND public.user_can_read_service_reception_entry(
           r.dealer_code,
           r.sa_employee_code,
           r.service_type,
           r.id
         )
   ORDER BY 1
   LIMIT v_limit;
END;
$$;


--
-- Name: FUNCTION search_reception_reg_numbers(p_prefix text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_reception_reg_numbers(p_prefix text, p_limit integer) IS 'Reg-number autocomplete bypassing authenticated RLS.';


--
-- Name: service_advisor_estimates_touch_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_advisor_estimates_touch_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  new.model := btrim(regexp_replace(new.model, '\s+', ' ', 'g'));
  new.fuel := btrim(regexp_replace(new.fuel, '\s+', ' ', 'g'));
  new.make := upper(btrim(regexp_replace(coalesce(new.make, 'BS6'), '\s+', '', 'g')));
  if new.make not in ('BS4', 'BS6') then
    new.make := 'BS6';
  end if;
  new.service_type := btrim(regexp_replace(new.service_type, '\s+', ' ', 'g'));
  if new.items is null then
    new.items := '[]'::jsonb;
  end if;
  return new;
end;
$$;


--
-- Name: service_advisor_mark_invoice_done(bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_advisor_mark_invoice_done(p_reception_entry_id bigint, p_expected_invoice_amount numeric DEFAULT NULL::numeric) RETURNS SETOF public.service_reception_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sa_employee_code text;
  v_is_admin         boolean;
  v_has_sa_modify    boolean;
  v_done_by          text;
  v_service_type     text;
  v_amount           numeric;
BEGIN
  v_is_admin      := public.is_admin();
  v_has_sa_modify := public.has_module_modify('service_advisor');

  IF NOT (v_is_admin OR v_has_sa_modify) THEN
    RAISE EXCEPTION 'permission denied: requires service_advisor modify or admin'
      USING ERRCODE = '42501';
  END IF;

  SELECT sre.sa_employee_code, sre.service_type
    INTO v_sa_employee_code, v_service_type
    FROM public.service_reception_entries sre
   WHERE sre.id = p_reception_entry_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reception entry % not found', p_reception_entry_id
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_is_admin THEN
    IF v_sa_employee_code IS NULL
       OR NOT public.user_has_employee_code(v_sa_employee_code)
    THEN
      RAISE EXCEPTION 'permission denied: caller is not the SA on this reception entry'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF p_expected_invoice_amount IS NOT NULL AND p_expected_invoice_amount < 0 THEN
    RAISE EXCEPTION 'expected_invoice_amount cannot be negative'
      USING ERRCODE = '23514';
  END IF;

  IF lower(btrim(coalesce(v_service_type, ''))) IN ('accident', 'rusting') THEN
    v_amount := NULL;
  ELSE
    v_amount := CASE
      WHEN p_expected_invoice_amount IS NULL THEN NULL
      ELSE round(p_expected_invoice_amount, 2)
    END;
  END IF;

  v_done_by := coalesce(
    nullif(btrim(auth.jwt() ->> 'email'), ''),
    auth.uid()::text,
    'system'
  );

  -- Persist a typed amount in this same transaction so Mark Done cannot
  -- succeed while discarding an unsaved Invoice Amount. A NULL argument
  -- keeps the last saved expected_invoice_amount.
  UPDATE public.service_reception_entries sre
     SET invoice_done_at = now(),
         invoice_done_by = v_done_by,
         expected_invoice_amount = CASE
           WHEN p_expected_invoice_amount IS NOT NULL THEN v_amount
           ELSE sre.expected_invoice_amount
         END,
         updated_at = now()
   WHERE sre.id = p_reception_entry_id;

  PERFORM public.service_advisor_seed_mechanical_billed_amount(
    p_reception_entry_id,
    (SELECT sre.expected_invoice_amount FROM public.service_reception_entries sre WHERE sre.id = p_reception_entry_id)
  );

  RETURN QUERY
  SELECT sre.*
    FROM public.service_reception_entries sre
   WHERE sre.id = p_reception_entry_id;
END;
$$;


--
-- Name: FUNCTION service_advisor_mark_invoice_done(p_reception_entry_id bigint, p_expected_invoice_amount numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.service_advisor_mark_invoice_done(p_reception_entry_id bigint, p_expected_invoice_amount numeric) IS 'SECURITY DEFINER: mark SA invoice done and persist expected_invoice_amount in the same transaction. Seeds Accounts billed_amount when unlocked.';


--
-- Name: service_advisor_save_reception_entry(bigint, text, text, integer, text, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_advisor_save_reception_entry(p_reception_entry_id bigint, p_service_type text, p_jc_number text DEFAULT NULL::text, p_km_reading integer DEFAULT NULL::integer, p_remark text DEFAULT NULL::text, p_expected_invoice_amount numeric DEFAULT NULL::numeric, p_set_expected_invoice_amount boolean DEFAULT false) RETURNS SETOF public.service_reception_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sa_employee_code text;
  v_is_admin         boolean;
  v_has_sa_modify    boolean;
  v_service_type     text;
  v_amount           numeric;
  v_done_by          text;
  v_can_complete     boolean;
  v_jc               text;
  v_floor_completed  boolean;
  v_is_invoice_exception boolean;
BEGIN
  v_service_type := btrim(coalesce(p_service_type, ''));
  IF v_service_type = '' THEN
    RAISE EXCEPTION 'service_type is required'
      USING ERRCODE = '22023';
  END IF;

  IF p_expected_invoice_amount IS NOT NULL AND p_expected_invoice_amount < 0 THEN
    RAISE EXCEPTION 'expected_invoice_amount cannot be negative'
      USING ERRCODE = '23514';
  END IF;

  v_is_admin      := public.is_admin();
  v_has_sa_modify := public.has_module_modify('service_advisor');

  IF NOT (v_is_admin OR v_has_sa_modify) THEN
    RAISE EXCEPTION 'permission denied: requires service_advisor modify or admin'
      USING ERRCODE = '42501';
  END IF;

  SELECT sre.sa_employee_code
    INTO v_sa_employee_code
    FROM public.service_reception_entries sre
   WHERE sre.id = p_reception_entry_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reception entry % not found', p_reception_entry_id
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_is_admin THEN
    IF v_sa_employee_code IS NULL
       OR NOT public.user_has_employee_code(v_sa_employee_code)
    THEN
      RAISE EXCEPTION 'permission denied: caller is not the SA on this reception entry'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  v_is_invoice_exception := lower(v_service_type) IN ('accident', 'rusting');

  IF v_is_invoice_exception THEN
    v_amount := NULL;
  ELSE
    v_amount := CASE
      WHEN p_expected_invoice_amount IS NULL THEN NULL
      ELSE round(p_expected_invoice_amount, 2)
    END;
  END IF;

  v_jc := NULLIF(upper(btrim(coalesce(p_jc_number, ''))), '');
  IF v_jc IS NULL THEN
    SELECT NULLIF(upper(btrim(coalesce(sre.jc_number, ''))), '')
      INTO v_jc
      FROM public.service_reception_entries sre
     WHERE sre.id = p_reception_entry_id;
  END IF;

  v_floor_completed := v_jc IS NOT NULL AND EXISTS (
    SELECT 1
      FROM public.technician_assignments ta
     WHERE upper(btrim(ta.job_card_number)) = v_jc
       AND lower(btrim(coalesce(ta.work_status, ''))) = 'completed'
  );

  -- Qualifying completion: explicit persisted amount on a Floor-completed JC.
  -- 0 is valid (column CHECK >= 0). NULL / blank does not complete.
  v_can_complete := p_set_expected_invoice_amount
    AND v_amount IS NOT NULL
    AND NOT v_is_invoice_exception
    AND v_floor_completed;

  v_done_by := coalesce(
    nullif(btrim(auth.jwt() ->> 'email'), ''),
    auth.uid()::text,
    'system'
  );

  UPDATE public.service_reception_entries sre
     SET service_type = v_service_type,
         jc_number    = NULLIF(upper(btrim(coalesce(p_jc_number, ''))), ''),
         km_reading   = p_km_reading,
         remark       = NULLIF(btrim(coalesce(p_remark, '')), ''),
         expected_invoice_amount = CASE
           WHEN p_set_expected_invoice_amount AND v_is_invoice_exception THEN NULL
           WHEN p_set_expected_invoice_amount AND v_floor_completed THEN v_amount
           ELSE sre.expected_invoice_amount
         END,
         invoice_done_at = CASE
           WHEN v_can_complete AND sre.invoice_done_at IS NULL THEN now()
           ELSE sre.invoice_done_at
         END,
         invoice_done_by = CASE
           WHEN v_can_complete AND sre.invoice_done_at IS NULL THEN v_done_by
           ELSE sre.invoice_done_by
         END,
         updated_at   = now()
   WHERE sre.id = p_reception_entry_id;

  IF p_set_expected_invoice_amount AND (v_floor_completed OR v_is_invoice_exception) THEN
    PERFORM public.service_advisor_seed_mechanical_billed_amount(p_reception_entry_id, v_amount);
  END IF;

  RETURN QUERY
  SELECT sre.*
    FROM public.service_reception_entries sre
   WHERE sre.id = p_reception_entry_id;
END;
$$;


--
-- Name: FUNCTION service_advisor_save_reception_entry(p_reception_entry_id bigint, p_service_type text, p_jc_number text, p_km_reading integer, p_remark text, p_expected_invoice_amount numeric, p_set_expected_invoice_amount boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.service_advisor_save_reception_entry(p_reception_entry_id bigint, p_service_type text, p_jc_number text, p_km_reading integer, p_remark text, p_expected_invoice_amount numeric, p_set_expected_invoice_amount boolean) IS 'SECURITY DEFINER RPC: updates service_type, jc_number, km_reading, remark, and optionally expected_invoice_amount. DBL-0069: expected_invoice_amount and invoice_done_at require Floor Incharge work_status=completed on the JC. Accident/Rusting never auto-complete. Blank amount does not complete. Later amount edits do not rewrite the original timestamp. DBL-0082: seeds accounts_mechanical_invoices.billed_amount when JC exists and no payment lines exist.';


--
-- Name: service_advisor_seed_mechanical_billed_amount(bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_advisor_seed_mechanical_billed_amount(p_reception_entry_id bigint, p_amount numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_entry public.service_reception_entries%ROWTYPE;
  v_existing public.accounts_mechanical_invoices%ROWTYPE;
  v_has_lines boolean := false;
  v_actor text;
  v_billed numeric;
  v_jc text;
BEGIN
  SELECT * INTO v_entry
    FROM public.service_reception_entries
   WHERE id = p_reception_entry_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_jc := NULLIF(btrim(v_entry.jc_number), '');
  IF v_jc IS NULL THEN
    RETURN;
  END IF;
  IF NOT public.is_floor_incharge_service_type(v_entry.service_type) THEN
    RETURN;
  END IF;

  IF p_amount IS NOT NULL AND p_amount < 0 THEN
    RAISE EXCEPTION 'expected_invoice_amount cannot be negative'
      USING ERRCODE = '23514';
  END IF;

  v_billed := CASE WHEN p_amount IS NULL THEN NULL ELSE round(p_amount, 2) END;

  SELECT * INTO v_existing
    FROM public.accounts_mechanical_invoices
   WHERE reception_entry_id = p_reception_entry_id;

  IF FOUND THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.accounts_mechanical_payment_lines l
      WHERE l.reception_entry_id = p_reception_entry_id
    ) INTO v_has_lines;

    -- DBL-0082: lock only after financial activity (any payment line).
    -- invoice_number alone is Accounts capture, not a billed freeze.
    IF v_has_lines THEN
      RETURN;
    END IF;

    UPDATE public.accounts_mechanical_invoices
       SET jc_number = v_jc,
           billed_amount = v_billed,
           updated_at = now()
     WHERE reception_entry_id = p_reception_entry_id;
  ELSE
    v_actor := COALESCE(
      NULLIF(auth.jwt() ->> 'email', ''),
      NULLIF(auth.uid()::text, ''),
      'system'
    );

    INSERT INTO public.accounts_mechanical_invoices (
      reception_entry_id, jc_number, invoice_number, invoice_date, billed_amount,
      payment_status, amount_received, payment_notes, captured_by, captured_at, updated_at
    ) VALUES (
      p_reception_entry_id,
      v_jc,
      NULL,
      NULL,
      v_billed,
      'pending',
      NULL,
      NULL,
      v_actor,
      now(),
      now()
    );
  END IF;

  IF to_regprocedure('public.accounts_mechanical_recalc(bigint)') IS NOT NULL THEN
    PERFORM public.accounts_mechanical_recalc(p_reception_entry_id);
  END IF;
END;
$$;


--
-- Name: FUNCTION service_advisor_seed_mechanical_billed_amount(p_reception_entry_id bigint, p_amount numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.service_advisor_seed_mechanical_billed_amount(p_reception_entry_id bigint, p_amount numeric) IS 'DBL-0051/0082 internal: seed accounts_mechanical_invoices.billed_amount from SA expected amount. No-op without JC, non-floor types, or after financial activity (any accounts_mechanical_payment_lines row, including discount). Invoice number/date alone do not lock billed. Keep on Credit and issued gatepass are not billed locks.';


--
-- Name: service_floor_incharge_sa_in_scope(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_floor_incharge_sa_in_scope(p_sa_fuel text, p_sa_location text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.user_employee_links uel_fi
      JOIN public.employee_master fi ON fi.employee_code = uel_fi.employee_code
     WHERE uel_fi.user_id = auth.uid()
       AND uel_fi.is_active = true
       AND public.employee_has_business_role(fi.role, 'FLOOR_INCHARGE')
       AND upper(replace(btrim(coalesce(fi.department, '')), ' ', '')) = 'SERVICE'
       AND public.normalize_employee_fuel_bucket(fi.fuel_type) IS NOT NULL
       AND public.normalize_employee_fuel_bucket(fi.fuel_type)
         = public.normalize_employee_fuel_bucket(p_sa_fuel)
       AND (
         public.normalize_employee_location_key(fi.location) IS NULL
         OR public.normalize_employee_location_key(p_sa_location) IS NULL
         OR public.normalize_employee_location_key(fi.location)
            = public.normalize_employee_location_key(p_sa_location)
       )
  );
$$;


--
-- Name: FUNCTION service_floor_incharge_sa_in_scope(p_sa_fuel text, p_sa_location text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.service_floor_incharge_sa_in_scope(p_sa_fuel text, p_sa_location text) IS 'True when the current SERVICE floor incharge matches an SA by Employee Master fuel (and location when both are set). Ignores dealer-code prefixes.';


--
-- Name: service_reception_entry_in_summary_scope(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_reception_entry_in_summary_scope(p_dealer_code text, p_sa_employee_code text, p_service_type text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    (
      public.has_module_view('reception'::text)
      AND public.dealer_code_in_scope(p_dealer_code)
    )
    OR (
      (
        public.has_module_view('service_advisor'::text)
        OR public.has_module_modify('service_advisor'::text)
      )
      AND p_sa_employee_code IS NOT NULL
      AND p_sa_employee_code IN (SELECT code FROM public.my_active_employee_codes() AS code)
    )
    OR (
      public.has_module_view('service_advisor'::text)
      AND p_sa_employee_code IS NOT NULL
      AND (
        public.user_is_crm_for_dealer_sa(p_sa_employee_code)
        OR public.user_is_sm_gm_for_dealer_sa(p_sa_employee_code)
      )
    )
    OR (
      public.has_module_view('floor_incharge'::text)
      AND p_sa_employee_code IS NOT NULL
      AND public.user_has_service_floor_incharge_scope_for_sa_code(p_sa_employee_code)
    )
    OR (
      coalesce(p_service_type, ''::text) = 'Accident'::text
      AND p_sa_employee_code IS NOT NULL
      AND (
        public.has_module_view('bodyshop_floor'::text)
        OR public.has_module_modify('bodyshop_floor'::text)
      )
      AND public.user_has_bodyshop_floor_incharge_scope_for_sa_code(p_sa_employee_code)
    );
$$;


