--
-- Name: set_accounts_mechanical_keep_on_credit(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_accounts_mechanical_keep_on_credit(p_reception_entry_id bigint, p_keep_on_credit boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_actor text;
  v_reason text;
BEGIN
  IF NOT public.accounts_can_access() THEN
    RAISE EXCEPTION 'permission denied: requires accounts view'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public.accounts_mechanical_can_keep_on_credit() THEN
    RAISE EXCEPTION 'permission denied: Keep on Credit requires Admin, GM, or Accounts Keep on Credit grant'
      USING ERRCODE = '42501';
  END IF;
  IF p_keep_on_credit IS NULL THEN
    RAISE EXCEPTION 'keep_on_credit is required'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.accounts_mechanical_invoices
     WHERE reception_entry_id = p_reception_entry_id
  ) THEN
    RAISE EXCEPTION 'capture invoice number and billed amount first'
      USING ERRCODE = '23514';
  END IF;

  v_actor := public.accounts_mechanical_actor_label();

  IF p_keep_on_credit THEN
    v_reason := NULLIF(btrim(COALESCE(p_reason, '')), '');
    IF v_reason IS NULL THEN
      RAISE EXCEPTION 'reason for keeping on credit is required'
        USING ERRCODE = '23514';
    END IF;

    UPDATE public.accounts_mechanical_invoices
       SET keep_on_credit = true,
           keep_on_credit_reason = v_reason,
           keep_on_credit_approved_by = v_actor,
           keep_on_credit_approved_at = clock_timestamp(),
           keep_on_credit_revoked_by = NULL,
           keep_on_credit_revoked_at = NULL,
           updated_at = now()
     WHERE reception_entry_id = p_reception_entry_id;
  ELSE
    UPDATE public.accounts_mechanical_invoices
       SET keep_on_credit = false,
           keep_on_credit_revoked_by = v_actor,
           keep_on_credit_revoked_at = clock_timestamp(),
           updated_at = now()
     WHERE reception_entry_id = p_reception_entry_id;
  END IF;

  RETURN public.accounts_mechanical_case_json(p_reception_entry_id);
END;
$$;


--
-- Name: FUNCTION set_accounts_mechanical_keep_on_credit(p_reception_entry_id bigint, p_keep_on_credit boolean, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_accounts_mechanical_keep_on_credit(p_reception_entry_id bigint, p_keep_on_credit boolean, p_reason text) IS 'DBL-0065: Approve or revoke Mechanical Keep on Credit. Approve requires a non-empty trimmed reason and stores authenticated actor + server timestamp. Revoke keeps original reason/approved_by/approved_at and records revoked_by/revoked_at. Does not rewrite remaining or payment_status. Client cannot supply approved_by or approved_at.';


--
-- Name: set_accounts_mechanical_pending_remark(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_accounts_mechanical_pending_remark(p_reception_entry_id bigint, p_pending_remark text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_entry public.service_reception_entries%ROWTYPE;
  v_remark text;
BEGIN
  IF NOT public.accounts_can_access() THEN
    RAISE EXCEPTION 'permission denied: requires accounts view'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_entry
    FROM public.service_reception_entries
   WHERE id = p_reception_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reception entry % not found', p_reception_entry_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_entry.invoice_done_at IS NULL THEN
    RAISE EXCEPTION 'case is not Mark Done on Service Advisor'
      USING ERRCODE = '23514';
  END IF;
  IF NOT public.is_floor_incharge_service_type(v_entry.service_type) THEN
    RAISE EXCEPTION 'not a mechanical Floor Incharge service type'
      USING ERRCODE = '23514';
  END IF;
  IF NULLIF(btrim(v_entry.jc_number), '') IS NULL THEN
    RAISE EXCEPTION 'jc_number is required'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.accounts_mechanical_invoices
     WHERE reception_entry_id = p_reception_entry_id
  ) THEN
    RAISE EXCEPTION 'capture invoice number and billed amount first'
      USING ERRCODE = '23514';
  END IF;

  v_remark := NULLIF(btrim(COALESCE(p_pending_remark, '')), '');

  UPDATE public.accounts_mechanical_invoices
     SET payment_notes = v_remark,
         updated_at = now()
   WHERE reception_entry_id = p_reception_entry_id;

  RETURN public.accounts_mechanical_case_json(p_reception_entry_id);
END;
$$;


--
-- Name: FUNCTION set_accounts_mechanical_pending_remark(p_reception_entry_id bigint, p_pending_remark text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_accounts_mechanical_pending_remark(p_reception_entry_id bigint, p_pending_remark text) IS 'ACCOUNTS-001 / DBL-0075: Set Mechanical Pending Remark on accounts_mechanical_invoices.payment_notes. Trimmed blank stores NULL. Requires accounts access and an existing invoice header. Does not rewrite billed, amount_received, payment_status, payment lines, or vouchers. Does not delete the value when the case later becomes received.';


