CREATE FUNCTION public.set_registration_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.registration_no IS NULL OR TRIM(NEW.registration_no) = '' THEN
        NEW.created_at := NULL;
    ELSIF NEW.created_at IS NULL THEN
        NEW.created_at := NOW();
