--
-- Name: settings_model_options_normalize_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settings_model_options_normalize_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.dealer_code := 'GLOBAL';
  new.model_name := btrim(regexp_replace(new.model_name, '\s+', ' ', 'g'));

  if length(new.model_name) = 0 then
    raise exception 'Model name cannot be empty';
  end if;

  return new;
end;
$$;


--
-- Name: settings_service_parts_pricing_normalize_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settings_service_parts_pricing_normalize_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.dealer_code := 'GLOBAL';
  new.service_type := btrim(regexp_replace(new.service_type, '\s+', ' ', 'g'));
  new.model := btrim(regexp_replace(new.model, '\s+', ' ', 'g'));
  new.fuel := btrim(regexp_replace(new.fuel, '\s+', ' ', 'g'));
  new.make := upper(btrim(regexp_replace(coalesce(new.make, 'BS6'), '\s+', '', 'g')));
  if new.make not in ('BS4', 'BS6') then
    new.make := 'BS6';
  end if;
  new.service_name := btrim(regexp_replace(new.service_name, '\s+', ' ', 'g'));
  new.updated_at := now();
  if length(new.service_type) = 0 or length(new.model) = 0 or length(new.fuel) = 0 or length(new.make) = 0 or length(new.service_name) = 0 then
    raise exception 'Catalogue model, fuel, make, service type, and item name cannot be empty';
  end if;
  return new;
end;
$$;


