--
-- Name: submit_csat(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_csat(p_token text, p_rating integer, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_complaint_id bigint;
  v_dealer_code text;
BEGIN
  SELECT complaint_id INTO v_complaint_id
  FROM public.complaint_access_links
  WHERE token = p_token AND status = 'consumed';

  IF v_complaint_id IS NULL THEN
    RAISE EXCEPTION 'Invalid complaint link';
  END IF;

  SELECT dealer_code INTO v_dealer_code
  FROM public.complaint_tickets
  WHERE id = v_complaint_id;

  -- Update CSAT fields
  UPDATE public.complaint_tickets
  SET csat_rating = p_rating, csat_comment = p_comment, csat_at = now()
  WHERE id = v_complaint_id;

  -- Log activity
  INSERT INTO public.complaint_activity (
    dealer_code, complaint_id, event_type, to_value, actor_type, actor_name
  ) VALUES (
    v_dealer_code, v_complaint_id, 'csat',
    p_rating::text, 'customer', 'customer'
  );

  RETURN public.get_complaint_by_token(p_token);
END;
$$;


--
-- Name: sync_all_service_data_dynamic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_all_service_data_dynamic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM public.all_service_data_dynamic d
    WHERE d.id = OLD.id;
    RETURN OLD;
  END IF;

  DELETE FROM public.all_service_data_dynamic d
  WHERE d.id = NEW.id;

  IF public.is_all_service_dynamic_match(NEW) THEN
    INSERT INTO public.all_service_data_dynamic (
      id,
      chassis_no,
      vehicle_registration_number,
      model,
      product_line,
      scheduled_next_service_date,
      last_service_date,
      last_service_type,
      assumed_next_service_date,
      assumed_next_service_type,
      fuel_tp,
      sold_dealer,
      priority_bucket,
      priority_score,
      vehicle_sale_date,
      updated_by_robot,
      updated_by_robot_at
    )
    VALUES (
      NEW.id,
      NEW.chassis_no,
      NEW.vehicle_registration_number,
      NEW.model,
      NEW.product_line,
      NEW.scheduled_next_service_date,
      NEW.last_service_date,
      NEW.last_service_type,
      NEW.assumed_next_service_date,
      NEW.assumed_next_service_type,
      CASE
        WHEN upper(COALESCE(NEW.product_line, '')) LIKE '%EV%' THEN 'EV'
        ELSE 'PV'
      END,
      NEW.sold_dealer,
      public.calc_all_service_dynamic_priority_bucket(NEW.sold_dealer),
      public.calc_all_service_dynamic_priority_score(
        NEW.assumed_next_service_date,
        NEW.assumed_next_service_type,
        NEW.vehicle_sale_date::text
      ),
      NEW.vehicle_sale_date,
      NEW.updated_by_robot,
      NEW.updated_by_robot_at
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_all_service_data_dynamic(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_all_service_data_dynamic() IS 'Maintains all_service_data_dynamic in realtime, including deterministic fuel_tp, sold_dealer, priority ordering fields (exact vehicle_sale_date tertiary scoring), and source-projected vehicle_sale_date.';


--
-- Name: sync_bodyshop_invoice_account_from_dms(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_bodyshop_invoice_account_from_dms(p_job_card_nos text[] DEFAULT NULL::text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_updated integer := 0;
BEGIN
  WITH latest AS (
    SELECT DISTINCT ON (upper(btrim(p.job_card_number)))
      upper(btrim(p.job_card_number)) AS jc,
      NULLIF(btrim(p.account), '') AS account
    FROM public.psf_revenue_dms p
    WHERE COALESCE(p.invoice_status, '') <> 'Cancelled'
      AND (
        p_job_card_nos IS NULL
        OR upper(btrim(p.job_card_number)) IN (
          SELECT upper(btrim(x))
          FROM unnest(p_job_card_nos) AS u(x)
          WHERE NULLIF(btrim(x), '') IS NOT NULL
        )
      )
    ORDER BY
      upper(btrim(p.job_card_number)),
      p.invoice_date DESC NULLS LAST,
      p.updated_at DESC NULLS LAST
  ),
  upd AS (
    UPDATE public.bodyshop_settlements s
       SET invoice_account = latest.account,
           invoice_source = COALESCE(s.invoice_source, 'psf_revenue_dms'),
           updated_at = now()
      FROM latest
     WHERE upper(btrim(s.job_card_no)) = latest.jc
       AND NULLIF(btrim(s.invoice_account), '') IS NULL
       AND latest.account IS NOT NULL
    RETURNING s.id
  )
  SELECT count(*)::integer INTO v_updated FROM upd;

  RETURN v_updated;
END;
$$;


--
-- Name: FUNCTION sync_bodyshop_invoice_account_from_dms(p_job_card_nos text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_bodyshop_invoice_account_from_dms(p_job_card_nos text[]) IS 'Fill empty bodyshop_settlements.invoice_account from the latest live psf_revenue_dms.account. Does not touch insurance_company or a non-null bill-to.';


--
-- Name: sync_bodyshop_repair_card_from_reception(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_bodyshop_repair_card_from_reception() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_accident boolean;
  v_job_card_no text;
  v_sa_name text;
  v_card_job_card_no text;
BEGIN
  v_is_accident := upper(trim(coalesce(NEW.service_type, ''))) = 'ACCIDENT';
  IF NOT v_is_accident THEN
    RETURN NEW;
  END IF;

  v_job_card_no := upper(trim(coalesce(nullif(NEW.jc_number, ''), nullif(NEW.reg_number, ''))));
  IF v_job_card_no IS NULL OR v_job_card_no = '' THEN
    RETURN NEW;
  END IF;

  SELECT upper(trim(coalesce(brc.job_card_no, '')))
    INTO v_card_job_card_no
    FROM public.bodyshop_repair_cards brc
   WHERE brc.reception_entry_id = NEW.id
   ORDER BY brc.updated_at DESC NULLS LAST, brc.id DESC
   LIMIT 1;

  -- Early-exit only when synced fields are unchanged AND card already matches.
  IF TG_OP = 'UPDATE'
    AND upper(trim(coalesce(NEW.jc_number,     ''))) = upper(trim(coalesce(OLD.jc_number,     '')))
    AND upper(trim(coalesce(NEW.reg_number,    ''))) = upper(trim(coalesce(OLD.reg_number,    '')))
    AND upper(trim(coalesce(NEW.owner_name,    ''))) = upper(trim(coalesce(OLD.owner_name,    '')))
    AND upper(trim(coalesce(NEW.owner_phone,   ''))) = upper(trim(coalesce(OLD.owner_phone,   '')))
    AND upper(trim(coalesce(NEW.branch,        ''))) = upper(trim(coalesce(OLD.branch,        '')))
    AND upper(trim(coalesce(NEW.sa_employee_code, ''))) = upper(trim(coalesce(OLD.sa_employee_code, '')))
    AND upper(trim(coalesce(NEW.sa_name,       ''))) = upper(trim(coalesce(OLD.sa_name,       '')))
    AND upper(trim(coalesce(NEW.sa_display_name, ''))) = upper(trim(coalesce(OLD.sa_display_name, '')))
    AND coalesce(v_card_job_card_no, '') = v_job_card_no
  THEN
    RETURN NEW;
  END IF;

  v_sa_name := coalesce(nullif(trim(NEW.sa_display_name), ''), nullif(trim(NEW.sa_name), ''), NULL);

  UPDATE public.bodyshop_repair_cards brc
  SET
    job_card_no      = v_job_card_no,
    reg_number       = NEW.reg_number,
    customer_name    = NEW.owner_name,
    customer_phone   = NEW.owner_phone,
    branch           = NEW.branch,
    sa_employee_code = NEW.sa_employee_code,
    sa_name          = coalesce(v_sa_name, brc.sa_name),
    received_at      = coalesce(brc.received_at, NEW.created_at),
    updated_at       = now()
  WHERE brc.reception_entry_id = NEW.id;

  IF NOT FOUND THEN
    INSERT INTO public.bodyshop_repair_cards (
      reception_entry_id,
      job_card_no,
      reg_number,
      customer_name,
      customer_phone,
      branch,
      sa_employee_code,
      sa_name,
      current_stage,
      current_stage_name,
      overall_status,
      received_at,
      created_at,
      updated_at
    ) VALUES (
      NEW.id,
      v_job_card_no,
      NEW.reg_number,
      NEW.owner_name,
      NEW.owner_phone,
      NEW.branch,
      NEW.sa_employee_code,
      v_sa_name,
      1,
      'Vehicle Receiving',
      'active',
      coalesce(NEW.created_at, now()),
      now(),
      now()
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_bodyshop_repair_card_from_reception(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_bodyshop_repair_card_from_reception() IS 'Syncs accident reception entries to bodyshop_repair_cards. Guard added: on UPDATE, exits early when all synced fields are unchanged to break the mutual trigger loop with sync_reception_jc_from_bodyshop_job_card.';


--
-- Name: sync_reception_jc_from_bodyshop_job_card(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_reception_jc_from_bodyshop_job_card() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_jc text;
BEGIN
  -- Only act when row is linked to reception.
  IF NEW.reception_entry_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_new_jc := upper(trim(coalesce(NEW.job_card_no, '')));
  IF v_new_jc = '' THEN
    RETURN NEW;
  END IF;

  -- Mirror the existing app/database rule for valid JC format minimum length.
  IF length(v_new_jc) < 25 THEN
    RETURN NEW;
  END IF;

  UPDATE public.service_reception_entries sre
  SET jc_number = v_new_jc,
      updated_at = now()
  WHERE sre.id = NEW.reception_entry_id
    AND upper(trim(coalesce(sre.jc_number, ''))) IS DISTINCT FROM v_new_jc;

  RETURN NEW;
END;
$$;


--
-- Name: sync_reception_jc_to_legacy_technician_assignments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_reception_jc_to_legacy_technician_assignments() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  new_jc text;
BEGIN
  new_jc := upper(btrim(coalesce(NEW.jc_number, '')));
  IF new_jc = '' THEN
    RETURN NEW;
  END IF;

  UPDATE public.technician_assignments
     SET job_card_number = new_jc,
         updated_at = now()
   WHERE upper(btrim(job_card_number)) = ('RECEPTION-' || NEW.id::text);

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_reception_jc_to_legacy_technician_assignments(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_reception_jc_to_legacy_technician_assignments() IS 'Syncs legacy RECEPTION-{reception_id} technician_assignments rows to the real JC number when reception jc_number is set. SECURITY DEFINER: internal sync must not run under SA RLS on technician_assignments (57014 on SA save).';


--
-- Name: sync_technician_assignment_out_ts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_technician_assignment_out_ts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.work_status := lower(btrim(coalesce(NEW.work_status, 'work_inprocess')));

  IF NEW.work_status = 'completed' THEN
    IF NEW.out_ts IS NULL THEN
      NEW.out_ts := now();
    END IF;
  ELSE
    NEW.out_ts := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: telecall_get_next_assignment(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.telecall_get_next_assignment(p_campaign_id bigint, p_user_email text) RETURNS TABLE(asgn_id bigint, cust_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$ DECLARE v_assignment_id BIGINT; v_customer_id BIGINT; BEGIN SELECT ta.id, ta.customer_id INTO v_assignment_id, v_customer_id FROM telecall_assignments ta WHERE ta.campaign_id = p_campaign_id AND ta.status = 'pending' AND ta.assigned_to IS NULL ORDER BY ta.priority_score DESC NULLS LAST, ta.id ASC LIMIT 1 FOR UPDATE SKIP LOCKED; IF v_assignment_id IS NOT NULL THEN UPDATE telecall_assignments SET assigned_to = p_user_email, status = 'assigned', assigned_at = NOW(), updated_at = NOW() WHERE id = v_assignment_id; RETURN QUERY SELECT v_assignment_id, v_customer_id; END IF; END; $$;


