-- Name: trg_fill_all_service_data_contact_phones_from_contact_details(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_fill_all_service_data_contact_phones_from_contact_details() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_phone text;
BEGIN
  IF NULLIF(btrim(COALESCE(NEW.contact_phones, '')), '') IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NULLIF(btrim(COALESCE(NEW.chassis_no, '')), '') IS NULL THEN
    RETURN NEW;
  END IF;

  v_phone := public.lookup_customer_phone_from_contact_details(NEW.chassis_no);
  IF v_phone IS NOT NULL THEN
    NEW.contact_phones := v_phone;
  END IF;

  RETURN NEW;
END;
$$;


