--
-- Name: trg_insurance_renewal_campaigns_force_true_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_insurance_renewal_campaigns_force_true_counts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total integer;
  v_pending integer;
  v_in_progress integer;
  v_callback integer;
  v_quote_needed integer;
  v_policy_requested integer;
  v_quote_sent integer;
  v_renewed integer;
  v_policy_done integer;
  v_completed integer;
  v_oow integer;
BEGIN
  SELECT
    s.total_leads,
    s.pending_count,
    s.in_progress_count,
    s.callback_later_count,
    s.quote_needed_count,
    s.policy_requested_count,
    s.quote_sent_count,
    s.renewed_count,
    s.policy_done_count,
    s.completed_count,
    s.out_of_window_count
  INTO
    v_total,
    v_pending,
    v_in_progress,
    v_callback,
    v_quote_needed,
    v_policy_requested,
    v_quote_sent,
    v_renewed,
    v_policy_done,
    v_completed,
    v_oow
  FROM public.insurance_renewal_campaign_count_snapshot(NEW.id) s;

  NEW.total_leads := COALESCE(v_total, 0);
  NEW.pending_count := COALESCE(v_pending, 0);
  NEW.in_progress_count := COALESCE(v_in_progress, 0);
  NEW.callback_later_count := COALESCE(v_callback, 0);
  NEW.quote_needed_count := COALESCE(v_quote_needed, 0);
  NEW.policy_requested_count := COALESCE(v_policy_requested, 0);
  NEW.quote_sent_count := COALESCE(v_quote_sent, 0);
  NEW.renewed_count := COALESCE(v_renewed, 0);
  NEW.policy_done_count := COALESCE(v_policy_done, 0);
  NEW.completed_count := COALESCE(v_completed, 0);
  NEW.out_of_window_count := COALESCE(v_oow, 0);
  RETURN NEW;
END;
$$;


--
-- Name: trg_refresh_all_service_data_from_contact_details(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_refresh_all_service_data_from_contact_details() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.refresh_all_service_data_from_contact_details(OLD.chassis_no);
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.chassis_no IS DISTINCT FROM NEW.chassis_no THEN
    PERFORM public.refresh_all_service_data_from_contact_details(OLD.chassis_no);
  END IF;

  PERFORM public.refresh_all_service_data_from_contact_details(NEW.chassis_no);
  RETURN NEW;
END;
$$;


