-- Name: trg_refresh_job_card_closed_dms_revenue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_refresh_job_card_closed_dms_revenue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.refresh_job_card_closed_dms_revenue(
      OLD.job_card_number,
      OLD.location,
      OLD.portal
    );
    return OLD;
  end if;

  if tg_op = 'UPDATE'
     and (
       OLD.job_card_number is distinct from NEW.job_card_number
       or OLD.location is distinct from NEW.location
       or OLD.portal is distinct from NEW.portal
     ) then
    perform public.refresh_job_card_closed_dms_revenue(
      OLD.job_card_number,
      OLD.location,
      OLD.portal
    );
  end if;

  perform public.refresh_job_card_closed_dms_revenue(
    NEW.job_card_number,
    NEW.location,
    NEW.portal
  );

  return NEW;
end;
$$;


