    PERFORM public.enqueue_all_service_history_sync(OLD.chassis_no, interval '45 seconds');
  END IF;

  PERFORM public.enqueue_all_service_history_sync(NEW.chassis_no, interval '45 seconds');
  RETURN NEW;
END;
$$;


