--
-- Name: update_accounts_mechanical_payment(bigint, numeric, text, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_accounts_mechanical_payment(p_payment_line_id bigint, p_amount numeric, p_payment_mode text, p_reference text DEFAULT NULL::text, p_payment_received_date date DEFAULT NULL::date, p_remark text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_line public.accounts_mechanical_payment_lines%ROWTYPE;
  v_mode text;
  v_amount numeric;
  v_actor text;
  v_received_date date;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'permission denied: requires platform admin'
      USING ERRCODE = '42501';
  END IF;

  IF p_payment_line_id IS NULL THEN
    RAISE EXCEPTION 'payment line id is required'
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_line
    FROM public.accounts_mechanical_payment_lines
   WHERE id = p_payment_line_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'mechanical payment line % not found', p_payment_line_id
      USING ERRCODE = 'P0002';
  END IF;

  v_amount := round(COALESCE(p_amount, 0), 2);
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'receipt amount must be greater than 0'
      USING ERRCODE = '23514';
  END IF;

  v_mode := lower(btrim(COALESCE(p_payment_mode, '')));
  IF v_mode NOT IN ('cash', 'upi', 'card', 'cheque', 'bank', 'other') THEN
    RAISE EXCEPTION 'invalid payment_mode'
      USING ERRCODE = '23514';
  END IF;

  v_received_date := p_payment_received_date;
  IF v_received_date IS NULL THEN
    RAISE EXCEPTION 'payment received date is required'
      USING ERRCODE = '23514';
  END IF;

  v_actor := public.accounts_mechanical_actor_label();

  UPDATE public.accounts_mechanical_payment_lines
     SET amount = v_amount,
         payment_mode = v_mode,
         reference = NULLIF(btrim(p_reference), ''),
         payment_received_date = v_received_date,
         remark = NULLIF(btrim(p_remark), ''),
         edited_by = v_actor,
         edited_at = clock_timestamp()
   WHERE id = v_line.id;

  PERFORM public.accounts_mechanical_recalc(v_line.reception_entry_id);
  RETURN public.accounts_mechanical_case_json(v_line.reception_entry_id);
END;
$$;


--
-- Name: FUNCTION update_accounts_mechanical_payment(p_payment_line_id bigint, p_amount numeric, p_payment_mode text, p_reference text, p_payment_received_date date, p_remark text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_accounts_mechanical_payment(p_payment_line_id bigint, p_amount numeric, p_payment_mode text, p_reference text, p_payment_received_date date, p_remark text) IS 'ACCOUNTS-001 / DBL-0069: Admin/Super Admin edit of a posted Mechanical receipt. Authorizes with is_admin() only. Updates amount, payment_mode, reference, payment_received_date, remark. Preserves id, mechanical_invoice_id, reception_entry_id, posted_by, posted_at, voucher_no. Recalc via accounts_mechanical_recalc. Overpayment is stored as-is.';


