--
-- Name: update_reception_entry(bigint, text, text, text, text, text, text, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_reception_entry(p_reception_entry_id bigint, p_reg_number text, p_model text, p_service_type text, p_sa_employee_code text, p_owner_name text, p_owner_phone text, p_source text, p_km_reading integer DEFAULT NULL::integer, p_jc_number text DEFAULT NULL::text, p_branch text DEFAULT NULL::text, p_portal text DEFAULT NULL::text) RETURNS SETOF public.service_reception_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_dealer_code  text;
  v_sa_name      text;
  v_reg_number   text;
  v_service_type text;
  v_portal       text;
BEGIN
  SELECT sre.dealer_code
    INTO v_dealer_code
    FROM public.service_reception_entries sre
   WHERE sre.id = p_reception_entry_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'reception entry % not found', p_reception_entry_id
      USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
    public.is_admin()
    OR (
      public.has_module_modify('reception')
      AND public.dealer_code_in_scope(v_dealer_code)
    )
  ) THEN
    RAISE EXCEPTION 'permission denied: requires reception modify or admin'
      USING ERRCODE = '42501';
  END IF;

  v_reg_number := upper(btrim(coalesce(p_reg_number, '')));
  v_service_type := NULLIF(btrim(coalesce(p_service_type, '')), '');
  v_portal := NULLIF(upper(btrim(coalesce(p_portal, ''))), '');

  IF v_reg_number = '' THEN
    RAISE EXCEPTION 'registration number is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(coalesce(p_model, '')), '') IS NULL THEN
    RAISE EXCEPTION 'model is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(coalesce(p_sa_employee_code, '')), '') IS NULL THEN
    RAISE EXCEPTION 'sa employee code is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(coalesce(p_owner_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'owner name is required' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(coalesce(p_source, '')), '') IS NULL THEN
    RAISE EXCEPTION 'source is required' USING ERRCODE = '22023';
  END IF;
  IF p_owner_phone IS NULL OR btrim(p_owner_phone) !~ '^[0-9]{10}$' THEN
    RAISE EXCEPTION 'owner phone must be exactly 10 digits' USING ERRCODE = '22023';
  END IF;
  IF v_portal IS NOT NULL AND v_portal NOT IN ('EV', 'PV') THEN
    RAISE EXCEPTION 'portal must be EV or PV' USING ERRCODE = '22023';
  END IF;

  SELECT em.employee_name
    INTO v_sa_name
    FROM public.employee_master em
   WHERE em.employee_code = upper(btrim(p_sa_employee_code));

  IF NOT FOUND OR NULLIF(btrim(coalesce(v_sa_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'employee code % not found', p_sa_employee_code
      USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  UPDATE public.service_reception_entries sre
     SET reg_number       = v_reg_number,
         model            = NULLIF(btrim(p_model), ''),
         service_type     = v_service_type,
         sa_employee_code = upper(btrim(p_sa_employee_code)),
         sa_name          = v_sa_name,
         sa_display_name  = v_sa_name,
         owner_name       = NULLIF(btrim(p_owner_name), ''),
         owner_phone      = btrim(p_owner_phone),
         source           = NULLIF(btrim(p_source), ''),
         km_reading       = p_km_reading,
         jc_number        = NULLIF(upper(btrim(coalesce(p_jc_number, ''))), ''),
         branch           = NULLIF(btrim(coalesce(p_branch, '')), ''),
         portal           = COALESCE(v_portal, sre.portal),
         updated_at       = now()
   WHERE sre.id = p_reception_entry_id
   RETURNING sre.*;
END;
$_$;


--
-- Name: update_registration_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_registration_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.registration_no IS NULL OR TRIM(NEW.registration_no) = '' THEN
        NEW.created_at := NULL;
    ELSIF OLD.registration_no IS DISTINCT FROM NEW.registration_no THEN
        NEW.created_at := NOW();
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: upsert_accounts_mechanical_invoice(bigint, text, date, numeric, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_accounts_mechanical_invoice(p_reception_entry_id bigint, p_invoice_number text DEFAULT NULL::text, p_invoice_date date DEFAULT NULL::date, p_billed_amount numeric DEFAULT NULL::numeric, p_payment_status text DEFAULT NULL::text, p_amount_received numeric DEFAULT NULL::numeric, p_payment_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_entry public.service_reception_entries%ROWTYPE;
  v_actor text;
  v_existing public.accounts_mechanical_invoices%ROWTYPE;
  v_has_lines boolean := false;
  v_invoice_number text;
  v_invoice_date date;
  v_billed numeric;
  v_notes text;
BEGIN
  IF NOT public.accounts_can_access() THEN
    RAISE EXCEPTION 'permission denied: requires accounts view'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_entry
    FROM public.service_reception_entries
   WHERE id = p_reception_entry_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reception entry % not found', p_reception_entry_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_entry.invoice_done_at IS NULL THEN
    RAISE EXCEPTION 'case is not Mark Done on Service Advisor'
      USING ERRCODE = '23514';
  END IF;
  IF NOT public.is_floor_incharge_service_type(v_entry.service_type) THEN
    RAISE EXCEPTION 'not a mechanical Floor Incharge service type'
      USING ERRCODE = '23514';
  END IF;
  IF NULLIF(btrim(v_entry.jc_number), '') IS NULL THEN
    RAISE EXCEPTION 'jc_number is required'
      USING ERRCODE = '23514';
  END IF;
  IF p_billed_amount IS NOT NULL AND p_billed_amount < 0 THEN
    RAISE EXCEPTION 'billed_amount cannot be negative'
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_existing
    FROM public.accounts_mechanical_invoices
   WHERE reception_entry_id = p_reception_entry_id;

  IF FOUND THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.accounts_mechanical_payment_lines l
      WHERE l.reception_entry_id = p_reception_entry_id
    ) INTO v_has_lines;
  END IF;

  IF v_has_lines THEN
    v_invoice_number := COALESCE(
      NULLIF(btrim(v_existing.invoice_number), ''),
      NULLIF(btrim(p_invoice_number), '')
    );
    v_invoice_date := COALESCE(v_existing.invoice_date, p_invoice_date);
    v_billed := v_existing.billed_amount;
  ELSE
    v_invoice_number := NULLIF(btrim(p_invoice_number), '');
    v_invoice_date := p_invoice_date;
    v_billed := CASE WHEN p_billed_amount IS NULL THEN NULL ELSE round(p_billed_amount, 2) END;
  END IF;

  IF v_has_lines OR p_payment_notes IS NULL THEN
    v_notes := v_existing.payment_notes;
  ELSE
    v_notes := NULLIF(btrim(p_payment_notes), '');
  END IF;

  v_actor := COALESCE(
    NULLIF(auth.jwt() ->> 'email', ''),
    NULLIF(auth.uid()::text, ''),
    'system'
  );

  INSERT INTO public.accounts_mechanical_invoices (
    reception_entry_id, jc_number, invoice_number, invoice_date, billed_amount,
    payment_status, amount_received, payment_notes, captured_by, captured_at, updated_at
  ) VALUES (
    p_reception_entry_id,
    btrim(v_entry.jc_number),
    v_invoice_number,
    v_invoice_date,
    v_billed,
    'pending',
    NULL,
    v_notes,
    v_actor,
    now(),
    now()
  )
  ON CONFLICT (reception_entry_id) DO UPDATE SET
    jc_number = EXCLUDED.jc_number,
    invoice_number = EXCLUDED.invoice_number,
    invoice_date = EXCLUDED.invoice_date,
    billed_amount = EXCLUDED.billed_amount,
    payment_notes = EXCLUDED.payment_notes,
    updated_at = now();

  PERFORM public.accounts_mechanical_recalc(p_reception_entry_id);
  PERFORM public.accounts_mechanical_assign_eligible_null_vouchers(p_reception_entry_id, NULL);
  RETURN public.accounts_mechanical_case_json(p_reception_entry_id);
END;
$$;


--
-- Name: FUNCTION upsert_accounts_mechanical_invoice(p_reception_entry_id bigint, p_invoice_number text, p_invoice_date date, p_billed_amount numeric, p_payment_status text, p_amount_received numeric, p_payment_notes text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_accounts_mechanical_invoice(p_reception_entry_id bigint, p_invoice_number text, p_invoice_date date, p_billed_amount numeric, p_payment_status text, p_amount_received numeric, p_payment_notes text) IS 'ACCOUNTS-001 / DBL-0075: Capture mechanical invoice. After receipts, billed stays locked; NULL invoice_number/date may still be filled. Then assign eligible NULL vouchers. Does not rewrite non-null voucher_no. Omitting p_payment_notes preserves the saved Pending Remark (payment_notes).';


--
-- Name: upsert_all_service_data_from_booking_source(text, date, text, text, text, text, date, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_all_service_data_from_booking_source(p_chassis_no text, p_vehicle_sale_date date DEFAULT NULL::date, p_engine_no text DEFAULT NULL::text, p_contact_phones text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_last_insurance_comapny text DEFAULT NULL::text, p_last_insurance_expiry_date date DEFAULT NULL::date, p_model text DEFAULT NULL::text, p_product_line text DEFAULT NULL::text, p_source_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_row_id text DEFAULT NULL::text) RETURNS TABLE(action text, target_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_chassis_norm text;
  v_chassis_raw text;
  v_engine_no text;
  v_contact_phones text;
  v_first_name text;
  v_last_insurance_comapny text;
  v_model text;
  v_product_line text;
  v_target_id bigint;
begin
  v_chassis_raw := nullif(btrim(p_chassis_no), '');
  v_chassis_norm := upper(v_chassis_raw);
  v_engine_no := nullif(btrim(p_engine_no), '');
  v_contact_phones := nullif(btrim(p_contact_phones), '');
  v_first_name := nullif(btrim(p_first_name), '');
  v_last_insurance_comapny := nullif(btrim(p_last_insurance_comapny), '');
  v_model := nullif(btrim(p_model), '');
  v_product_line := nullif(btrim(p_product_line), '');

  if v_chassis_norm is null then
    return query select 'skipped_no_chassis'::text, null::bigint;
    return;
  end if;

  -- Hard gate (core fields): insert only when all core mapped values are present.
  if p_vehicle_sale_date is null
    or v_engine_no is null
    or v_contact_phones is null
    or v_first_name is null
    or v_last_insurance_comapny is null
    or p_last_insurance_expiry_date is null
    or p_source_updated_at is null
  then
    return query select 'skipped_missing_core_fields'::text, null::bigint;
    return;
  end if;

  select t.id
  into v_target_id
  from public.all_service_data t
  where upper(nullif(btrim(t.chassis_no), '')) = v_chassis_norm
  order by t.last_updated_at desc nulls last, t.id desc
  limit 1;

  if v_target_id is not null then
    return query select 'skipped_existing_chassis'::text, v_target_id;
    return;
  end if;

  insert into public.all_service_data (
    chassis_no,
    vehicle_sale_date,
    engine_no,
    contact_phones,
    first_name,
    last_insurance_comapny,
    last_insurance_expiry_date,
    model,
    product_line,
    sold_dealer,
    updated_by_sale,
    updated_by_sale_at,
    last_service_type,
    last_service_date,
    created_at,
    last_updated_at
  )
  values (
    v_chassis_raw,
    p_vehicle_sale_date,
    v_engine_no,
    v_contact_phones,
    v_first_name,
    v_last_insurance_comapny,
    p_last_insurance_expiry_date,
    v_model,
    v_product_line,
    'Techwheels',
    true,
    now(),
    'New',
    p_vehicle_sale_date,
    now(),
    now()
  )
  returning id into v_target_id;

  return query select 'inserted'::text, v_target_id;
end;
$$;


--
-- Name: FUNCTION upsert_all_service_data_from_booking_source(p_chassis_no text, p_vehicle_sale_date date, p_engine_no text, p_contact_phones text, p_first_name text, p_last_insurance_comapny text, p_last_insurance_expiry_date date, p_model text, p_product_line text, p_source_updated_at timestamp with time zone, p_source_row_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_all_service_data_from_booking_source(p_chassis_no text, p_vehicle_sale_date date, p_engine_no text, p_contact_phones text, p_first_name text, p_last_insurance_comapny text, p_last_insurance_expiry_date date, p_model text, p_product_line text, p_source_updated_at timestamp with time zone, p_source_row_id text) IS 'Wave-1 cross-project insert-only helper for booking->all_service_data. Match by normalized chassis. Existing chassis rows are skipped. Hard gate requires non-null core mapped fields; derived JSON mappings are optional. Inserts sold_dealer=Techwheels, updated_by_sale audit stamps, last_service_type=New, last_service_date from rto_date.';


--
-- Name: upsert_bodyshop_settlement_header(integer, text, text, date, numeric, numeric, numeric, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_bodyshop_settlement_header(p_repair_card_id integer, p_parts_entry_status text DEFAULT NULL::text, p_invoice_number text DEFAULT NULL::text, p_invoice_date date DEFAULT NULL::date, p_invoice_amount numeric DEFAULT NULL::numeric, p_invoice_labour_amount numeric DEFAULT NULL::numeric, p_invoice_spares_amount numeric DEFAULT NULL::numeric, p_invoice_account text DEFAULT NULL::text, p_invoice_source text DEFAULT NULL::text, p_do_amount numeric DEFAULT NULL::numeric, p_do_status text DEFAULT NULL::text, p_do_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET row_security TO 'off'
    AS $$
DECLARE
  v_id bigint;
  v_actor text;
BEGIN
  IF NOT public.bodyshop_settlement_can_modify(p_repair_card_id) THEN
    RAISE EXCEPTION 'permission denied: requires bodyshop_repair modify'
      USING ERRCODE = '42501';
  END IF;

  IF p_do_status IS NOT NULL AND lower(btrim(p_do_status)) = 'received'
     AND p_do_amount IS NULL THEN
    -- allow existing do_amount on header/card
    IF NOT EXISTS (
      SELECT 1 FROM public.bodyshop_settlements s
      WHERE s.repair_card_id = p_repair_card_id AND s.do_amount IS NOT NULL
    ) AND NOT EXISTS (
      SELECT 1 FROM public.bodyshop_repair_cards c
      WHERE c.id = p_repair_card_id AND c.do_amount IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'DO Amount is required when DO Status is Received'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  SELECT a.actor_email INTO v_actor FROM public._bodyshop_settlement_actor() a;
  v_id := public._bodyshop_ensure_settlement(p_repair_card_id);

  UPDATE public.bodyshop_settlements
     SET invoice_number = COALESCE(p_invoice_number, invoice_number),
         invoice_date = COALESCE(p_invoice_date, invoice_date),
         invoice_amount = COALESCE(p_invoice_amount, invoice_amount),
         invoice_labour_amount = COALESCE(p_invoice_labour_amount, invoice_labour_amount),
         invoice_spares_amount = COALESCE(p_invoice_spares_amount, invoice_spares_amount),
         invoice_account = COALESCE(p_invoice_account, invoice_account),
         invoice_source = COALESCE(p_invoice_source, invoice_source),
         do_amount = COALESCE(p_do_amount, do_amount),
         do_status = COALESCE(p_do_status, do_status),
         do_reference = COALESCE(p_do_reference, do_reference),
         updated_by = v_actor,
         updated_at = now()
   WHERE id = v_id;

  IF p_parts_entry_status IS NOT NULL THEN
    UPDATE public.bodyshop_repair_cards
       SET parts_entry_status = p_parts_entry_status,
           updated_at = now()
     WHERE id = p_repair_card_id;
  END IF;

  PERFORM public.recalc_bodyshop_settlement(v_id);
  RETURN public.get_bodyshop_settlement(p_repair_card_id);
END;
$$;


--
-- Name: user_can_read_service_reception_entry(text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_can_read_service_reception_entry(p_dealer_code text, p_sa_employee_code text, p_service_type text, p_reception_entry_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    public.is_admin()
    OR (public.has_module_view('reception'::text) AND public.dealer_code_in_scope(p_dealer_code))
    OR (public.has_module_view('service_advisor'::text) AND public.user_has_employee_code(p_sa_employee_code))
    OR (public.has_module_modify('service_advisor'::text) AND p_sa_employee_code IS NOT NULL AND public.user_has_employee_code(p_sa_employee_code))
    OR (
      public.has_module_view('service_advisor'::text)
      AND p_sa_employee_code IS NOT NULL
      AND (
        public.user_is_crm_for_dealer_sa(p_sa_employee_code)
        OR public.user_is_sm_gm_for_dealer_sa(p_sa_employee_code)
      )
    )
    OR (
      public.has_module_view('floor_incharge'::text)
      AND p_sa_employee_code IS NOT NULL
      AND public.user_has_service_floor_incharge_scope_for_sa_code(p_sa_employee_code)
    )
    OR (
      coalesce(p_service_type, ''::text) = 'Accident'::text
      AND p_sa_employee_code IS NOT NULL
      AND (public.has_module_view('bodyshop_floor'::text) OR public.has_module_modify('bodyshop_floor'::text))
      AND public.user_has_bodyshop_floor_incharge_scope_for_sa_code(p_sa_employee_code)
    );
$$;


--
-- Name: FUNCTION user_can_read_service_reception_entry(p_dealer_code text, p_sa_employee_code text, p_service_type text, p_reception_entry_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.user_can_read_service_reception_entry(p_dealer_code text, p_sa_employee_code text, p_service_type text, p_reception_entry_id bigint) IS 'Consolidated service_reception_entries SELECT gate for summary RPC. SECURITY DEFINER — keep in sync with reception SELECT policies.';


--
-- Name: user_has_bodyshop_floor_incharge_scope_for_sa_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_bodyshop_floor_incharge_scope_for_sa_code(p_sa_employee_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH input_codes AS (
    SELECT
      upper(btrim(coalesce(p_sa_employee_code, ''))) AS code_upper,
      upper(btrim(coalesce(split_part(p_sa_employee_code, '_', 1), ''))) AS code_part1,
      upper(btrim(coalesce(split_part(p_sa_employee_code, '_', 2), ''))) AS code_part2
  ),
  sa_location AS (
    SELECT upper(btrim(coalesce(
      sa.location,
      CASE
        WHEN c.code_upper LIKE '%500A840%' OR c.code_part1 = '500A840' OR c.code_part2 = '500A840' THEN 'Sitapura'
        WHEN c.code_upper LIKE '%3000840%' OR c.code_part1 = '3000840' OR c.code_part2 = '3000840' THEN 'Sitapura'
        WHEN c.code_upper LIKE '%3001440%' OR c.code_part1 = '3001440' OR c.code_part2 = '3001440' THEN 'Ajmer Road'
        ELSE NULL
      END
    ))) AS location_upper
    FROM input_codes c
    LEFT JOIN LATERAL (
      SELECT em.location
      FROM public.employee_master em
      WHERE upper(btrim(coalesce(em.employee_code, ''))) IN (c.code_upper, c.code_part1, c.code_part2)
      ORDER BY CASE
        WHEN upper(btrim(coalesce(em.employee_code, ''))) = c.code_upper THEN 1
        WHEN upper(btrim(coalesce(em.employee_code, ''))) = c.code_part1 THEN 2
        WHEN upper(btrim(coalesce(em.employee_code, ''))) = c.code_part2 THEN 3
        ELSE 9
      END
      LIMIT 1
    ) sa ON true
  )
  SELECT EXISTS (
    SELECT 1
    FROM public.user_employee_links uel_fi
    JOIN public.employee_master fi ON fi.employee_code = uel_fi.employee_code
    CROSS JOIN sa_location sal
    WHERE uel_fi.user_id = auth.uid()
      AND uel_fi.is_active = true
      AND public.employee_has_business_role(fi.role, 'FLOOR_INCHARGE')
      AND upper(replace(btrim(coalesce(fi.department, '')), ' ', '')) = 'BODYSHOP'
      AND nullif(upper(btrim(coalesce(fi.location, ''))), '') IS NOT NULL
      AND nullif(sal.location_upper, '') IS NOT NULL
      AND upper(btrim(coalesce(fi.location, ''))) = sal.location_upper
  );
$$;


--
-- Name: FUNCTION user_has_bodyshop_floor_incharge_scope_for_sa_code(p_sa_employee_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.user_has_bodyshop_floor_incharge_scope_for_sa_code(p_sa_employee_code text) IS 'Returns true when authenticated user is mapped as BODY SHOP floor incharge and location matches SA employee scope.';


--
-- Name: user_has_crm_dealer_scope(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_crm_dealer_scope(p_dealer_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH jwt_codes AS (
    SELECT upper(btrim(code)) AS code
    FROM unnest(public.my_effective_dealer_codes()) AS code
    WHERE btrim(coalesce(code, '')) <> ''
  ),
  target AS (
    SELECT upper(btrim(coalesce(p_dealer_code, ''))) AS code
  )
  SELECT
    btrim(coalesce(p_dealer_code, '')) <> ''
    AND EXISTS (
      SELECT 1
      FROM public.user_employee_links uel
      JOIN public.employee_master em ON em.employee_code = uel.employee_code
      WHERE uel.user_id = auth.uid()
        AND uel.is_active = true
        AND public.employee_has_business_role(em.role, 'CRM')
    )
    AND (
      (
        (SELECT count(*)::int FROM jwt_codes) > 0
        AND EXISTS (
          SELECT 1
          FROM jwt_codes dc
          CROSS JOIN target t
          WHERE dc.code = t.code
            AND dc.code <> ''
        )
      )
      OR (
        (SELECT count(*)::int FROM jwt_codes) = 0
        AND EXISTS (
          SELECT 1
          FROM public.user_employee_links uel
          JOIN public.employee_master em ON em.employee_code = uel.employee_code
          CROSS JOIN target t
          WHERE uel.user_id = auth.uid()
            AND uel.is_active = true
            AND public.employee_has_business_role(em.role, 'CRM')
            AND upper(btrim(coalesce(uel.dealer_code, ''))) = t.code
            AND t.code <> ''
        )
      )
    );
$$;


--
-- Name: FUNCTION user_has_crm_dealer_scope(p_dealer_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.user_has_crm_dealer_scope(p_dealer_code text) IS 'Returns true when authenticated user has an active CRM mapping and the dealer is in scope. JWT Additional Dealer Codes (my_effective_dealer_codes) take precedence when non-empty; otherwise falls back to CRM mapping dealer codes. SECURITY DEFINER.';


