    WHERE upper(btrim(coalesce(sa.employee_code, ''))) = upper(btrim(coalesce(p_sa_employee_code, '')))
      AND public.service_floor_incharge_sa_in_scope(sa.fuel_type, sa.location)
  );
$$;


