--
-- Name: user_is_crm_for_dealer_sa(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_is_crm_for_dealer_sa(p_sa_employee_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH sa_parts AS (
    SELECT
      upper(btrim(split_part(coalesce(p_sa_employee_code, ''), '_', 1))) AS part1,
      upper(btrim(split_part(coalesce(p_sa_employee_code, ''), '_', 2))) AS part2
  ),
  jwt_codes AS (
    SELECT upper(btrim(code)) AS code
    FROM unnest(public.my_effective_dealer_codes()) AS code
    WHERE btrim(coalesce(code, '')) <> ''
  )
  SELECT
    btrim(coalesce(p_sa_employee_code, '')) <> ''
    AND EXISTS (
      SELECT 1
      FROM public.user_employee_links uel
      JOIN public.employee_master em ON em.employee_code = uel.employee_code
      WHERE uel.user_id = auth.uid()
        AND uel.is_active = true
        AND public.employee_has_business_role(em.role, 'CRM')
    )
    AND (
      (
        (SELECT count(*)::int FROM jwt_codes) > 0
        AND EXISTS (
          SELECT 1
          FROM jwt_codes dc
          CROSS JOIN sa_parts sp
          WHERE dc.code IN (sp.part1, sp.part2)
            AND dc.code <> ''
        )
      )
      OR (
        (SELECT count(*)::int FROM jwt_codes) = 0
        AND EXISTS (
          SELECT 1
          FROM public.user_employee_links uel
          JOIN public.employee_master em ON em.employee_code = uel.employee_code
          CROSS JOIN sa_parts sp
          WHERE uel.user_id = auth.uid()
            AND uel.is_active = true
            AND public.employee_has_business_role(em.role, 'CRM')
            AND upper(btrim(coalesce(uel.dealer_code, ''))) IN (sp.part1, sp.part2)
            AND upper(btrim(coalesce(uel.dealer_code, ''))) <> ''
        )
      )
    );
$$;


--
-- Name: FUNCTION user_is_crm_for_dealer_sa(p_sa_employee_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.user_is_crm_for_dealer_sa(p_sa_employee_code text) IS 'CRM dealer-scoped SA helper. Requires an active CRM mapping. When my_effective_dealer_codes() is non-empty (JWT Additional Dealer Codes), those take precedence; otherwise falls back to CRM mapping dealer codes. Handles both SA code formats (500A840_131 and EPM_500A840). SECURITY DEFINER.';


