--
-- Name: bodyshop_settlement_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bodyshop_settlement_lines (
    id bigint NOT NULL,
    settlement_id bigint NOT NULL,
    repair_card_id integer NOT NULL,
    party text NOT NULL,
    line_type text NOT NULL,
    component text NOT NULL,
    amount numeric(14,2) NOT NULL,
    txn_date date NOT NULL,
    reference text,
    remarks text,
    reverses_line_id bigint,
    is_reversed boolean DEFAULT false NOT NULL,
    actor_id uuid,
    actor_email text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    import_row_token text,
    payment_mode text,
    voucher_no text,
    CONSTRAINT bodyshop_settlement_lines_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT bodyshop_settlement_lines_component_check CHECK ((component = ANY (ARRAY['MAIN'::text, 'GST'::text, 'TDS'::text, 'CUSTOMER'::text, 'CUSTOMER_REFUND'::text, 'WAIVER'::text]))),
    CONSTRAINT bodyshop_settlement_lines_party_check CHECK ((party = ANY (ARRAY['insurance'::text, 'customer'::text]))),
    CONSTRAINT bodyshop_settlement_lines_payment_mode_check CHECK (((payment_mode IS NULL) OR (payment_mode = ANY (ARRAY['cash'::text, 'upi'::text, 'card'::text, 'cheque'::text, 'bank'::text, 'other'::text])))),
    CONSTRAINT bodyshop_settlement_lines_type_check CHECK ((line_type = ANY (ARRAY['do_component'::text, 'receipt'::text, 'refund'::text, 'waiver'::text, 'reversal'::text]))),
    CONSTRAINT bodyshop_settlement_lines_voucher_check CHECK (((voucher_no IS NULL) OR (voucher_no ~ '^RApp/26-27/[0-9]{4}$'::text) OR (voucher_no ~ '^JApp/26-27/[0-9]{4}$'::text)))
);


--
-- Name: TABLE bodyshop_settlement_lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bodyshop_settlement_lines IS 'Append-only Stage 18 posts: Main/GST/TDS and customer receipt/refund. No updates or deletes.';


--
-- Name: COLUMN bodyshop_settlement_lines.import_row_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bodyshop_settlement_lines.import_row_token IS 'Bulk payment template row token. NULL for manual Stage 18 posts. Same token + component cannot post twice while the original line is not reversed.';


--
-- Name: COLUMN bodyshop_settlement_lines.payment_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bodyshop_settlement_lines.payment_mode IS 'Customer receipt/refund mode. Same stored values as accounts_mechanical_payment_lines.payment_mode. NULL for insurance Main/GST/TDS and historical customer rows.';


--
-- Name: COLUMN bodyshop_settlement_lines.voucher_no; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bodyshop_settlement_lines.voucher_no IS 'DBL-0080: Stable Accounts receipt voucher on customer receipts. Cash RApp/26-27/nnnn; UPI+card share JApp/26-27/nnnn via the Mechanical sequences. Null for unsupported/NULL mode, pre-cutoff, refunds, and insurance lines. Immutable once set.';


