    SEQUENCE NAME public.bodyshop_settlement_lines_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: bodyshop_settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bodyshop_settlements (
    id bigint NOT NULL,
    repair_card_id integer NOT NULL,
    job_card_no text NOT NULL,
    invoice_number text,
    invoice_date date,
    invoice_amount numeric(14,2),
    invoice_labour_amount numeric(14,2),
    invoice_spares_amount numeric(14,2),
    invoice_account text,
    do_amount numeric(14,2),
    do_status text DEFAULT 'pending'::text,
    do_reference text,
    customer_diff_amount numeric(14,2),
    customer_settlement_kind text,
    do_released_amount numeric(14,2) DEFAULT 0 NOT NULL,
    insurance_due_amount numeric(14,2),
    customer_posted_amount numeric(14,2) DEFAULT 0 NOT NULL,
    customer_remaining_amount numeric(14,2),
    outstanding_amount numeric(14,2),
    do_payment_status text DEFAULT 'pending'::text NOT NULL,
    customer_payment_status text DEFAULT 'pending'::text NOT NULL,
    derived_payment_status text DEFAULT 'pending'::text NOT NULL,
    do_not_received boolean DEFAULT false NOT NULL,
    customer_not_received boolean DEFAULT false NOT NULL,
    invoice_source text,
    needs_accounts_review boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text,
    updated_by text,
    CONSTRAINT bodyshop_settlements_cust_pay_check CHECK ((customer_payment_status = ANY (ARRAY['pending'::text, 'partial'::text, 'received'::text, 'not_received'::text]))),
