    resolved_at timestamp with time zone,
    closed_at timestamp with time zone,
    reopened_at timestamp with time zone,
    response_breached boolean DEFAULT false NOT NULL,
    resolution_breached boolean DEFAULT false NOT NULL,
    csat_rating smallint,
    csat_comment text,
    csat_at timestamp with time zone,
    channel text DEFAULT 'web_link'::text NOT NULL,
    created_by text DEFAULT COALESCE((auth.jwt() ->> 'email'::text), (auth.uid())::text, 'system'::text) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT complaint_tickets_category_check CHECK ((category = ANY (ARRAY['service_quality'::text, 'billing'::text, 'delivery_delay'::text, 'staff_behaviour'::text, 'parts_spares'::text, 'damage_during_service'::text, 'cleanliness'::text, 'other'::text]))),
    CONSTRAINT complaint_tickets_csat_rating_check CHECK (((csat_rating >= 1) AND (csat_rating <= 5))),
    CONSTRAINT complaint_tickets_customer_phone_check CHECK (((customer_phone IS NULL) OR (customer_phone ~ '^[0-9]{10}$'::text))),
    CONSTRAINT complaint_tickets_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT complaint_tickets_severity_self_check CHECK ((severity_self = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text]))),
    CONSTRAINT complaint_tickets_status_check CHECK ((status = ANY (ARRAY['new'::text, 'acknowledged'::text, 'in_progress'::text, 'resolved'::text, 'closed'::text, 'reopened'::text])))
);


