--

CREATE TABLE public.estimate_rows (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    job_card_id uuid NOT NULL,
    sr_no integer NOT NULL,
    panel_name text,
    part_number text,
    part_description text,
    defect text,
    action text,
    qty numeric(10,2) DEFAULT 1 NOT NULL,
    ndp_value numeric(12,2) DEFAULT 0 NOT NULL,
    cut_weld_charges numeric(12,2) DEFAULT 0 NOT NULL,
    paint_charges numeric(12,2) DEFAULT 0 NOT NULL,
    total_special_charges numeric(12,2) DEFAULT 0 NOT NULL,
    job_code text,
    job_code_desc text,
    no_off numeric(10,2) DEFAULT 1 NOT NULL,
    labour_charges numeric(12,2) DEFAULT 0 NOT NULL,
    row_total numeric(14,2) GENERATED ALWAYS AS ((((((qty * ndp_value) + cut_weld_charges) + paint_charges) + total_special_charges) + (no_off * labour_charges))) STORED,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT estimate_rows_cut_weld_charges_check CHECK ((cut_weld_charges >= (0)::numeric)),
    CONSTRAINT estimate_rows_labour_charges_check CHECK ((labour_charges >= (0)::numeric)),
    CONSTRAINT estimate_rows_ndp_value_check CHECK ((ndp_value >= (0)::numeric)),
    CONSTRAINT estimate_rows_no_off_check CHECK ((no_off >= (0)::numeric)),
    CONSTRAINT estimate_rows_paint_charges_check CHECK ((paint_charges >= (0)::numeric)),
    CONSTRAINT estimate_rows_qty_check CHECK ((qty >= (0)::numeric)),
    CONSTRAINT estimate_rows_sr_no_check CHECK ((sr_no > 0)),
    CONSTRAINT estimate_rows_total_special_charges_check CHECK ((total_special_charges >= (0)::numeric))
);


