--
-- Name: grn_report_data; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.grn_report_data (
    id bigint NOT NULL,
    portal text NOT NULL,
    branch text NOT NULL,
    upload_session_id uuid NOT NULL,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    sap_invoice_no text,
    order_no text,
    transaction_number text,
    part_no text,
    invoice_date text,
    status text,
    warehouse_name text,
    commit_flag text,
    recd_qty integer,
    spares_order_type text,
    condition text,
    transaction_date text,
    vendor_invoice_no text,
    discount_amount text,
    net_amount text,
    other_charges_amount text,
    total_invoice_amount text,
    vendor_name text,
    payer_code text,
    sap_order_num text,
    irn text,
    irn_date text,
    gst_invoice_no text,
    tcs_amount text,
    lr_docket_no text,
    challan_no text,
    challan_date text,
    challan_qty integer,
    purchase_order_date text,
    division_name text,
    order_type text,
    movement_type text,
    cgst text,
    igst text,
    sgst text,
    line_item_invoice_total text,
    weighted_avg text,
    source text,
    grn_status text GENERATED ALWAYS AS (
CASE
    WHEN (lower(TRIM(BOTH FROM COALESCE(status, ''::text))) = 'in transit'::text) THEN 'In Transit'::text
    WHEN ((sap_invoice_no IS NOT NULL) AND (sap_invoice_no <> ''::text)) THEN 'GRN Received'::text
    ELSE 'GRN Pending'::text
END) STORED
);


