CREATE VIEW public.insurance_renewal_leads AS
 SELECT id,
    chassis_no,
    contact_phones,
    vehicle_sale_date,
    last_insurance_expiry_date,
    COALESCE(last_insurance_expiry_date, public.insurance_next_due_date(vehicle_sale_date)) AS effective_due_date,
    (last_insurance_expiry_date IS NULL) AS due_date_is_estimated
   FROM public.all_service_data s;


