    incentive_percent numeric(8,4),
    amount numeric(12,2) NOT NULL,
    description text,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    calculation_method text DEFAULT 'percentage'::text NOT NULL,
    CONSTRAINT payroll_employee_incentives_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT payroll_employee_incentives_calculation_method_chk CHECK ((calculation_method = ANY (ARRAY['percentage'::text, 'fixed'::text]))),
    CONSTRAINT payroll_employee_incentives_incentive_percent_check CHECK ((incentive_percent >= (0)::numeric)),
    CONSTRAINT payroll_employee_incentives_incentive_type_check CHECK ((incentive_type = ANY (ARRAY['Parts'::text, 'Rusting'::text, 'VAS'::text, 'Others'::text]))),
    CONSTRAINT payroll_employee_incentives_method_amount_chk CHECK ((((calculation_method = 'percentage'::text) AND (value IS NOT NULL) AND (incentive_percent IS NOT NULL) AND (amount = round(((value * incentive_percent) / (100)::numeric), 2))) OR ((calculation_method = 'fixed'::text) AND (amount IS NOT NULL)))),
    CONSTRAINT payroll_employee_incentives_value_check CHECK ((value >= (0)::numeric))
);


