-- Name: TABLE payroll_employee_incentives; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payroll_employee_incentives IS 'DBL-0076/0077: Manual monthly employee incentive lines. Multiple rows per employee_code + payroll_month are allowed. calculation_method percentage derives amount; fixed stores amount directly. Snapshot is SUM(amount) on payroll_entries.incentive_amount.';


--
-- Name: COLUMN payroll_employee_incentives.value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_employee_incentives.value IS 'Required for percentage method. Optional/NULL for fixed method.';


--
