--
-- Name: COLUMN payroll_employee_incentives.amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_employee_incentives.amount IS 'Final line amount. Derived when calculation_method = percentage; authoritative when calculation_method = fixed.';


--
-- Name: COLUMN payroll_employee_incentives.calculation_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_employee_incentives.calculation_method IS 'DBL-0077: percentage = amount derived from value × percent / 100; fixed = amount entered directly.';


