--
-- Name: post_service_feedback_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.post_service_feedback_messages (
    id bigint NOT NULL,
    job_card_closed_data_id bigint NOT NULL,
    customer_name text,
    mobile_number text NOT NULL,
    vehicle_registration_number text,
    job_card_number text,
    closed_date date NOT NULL,
    scheduled_for_date date NOT NULL,
    sent_at timestamp with time zone,
    wa_message_id text,
    template_name text,
    status text DEFAULT 'pending'::text NOT NULL,
    failure_reason text,
    rating smallint,
    feedback_text text,
    responded_at timestamp with time zone,
    review_link_sent boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cre_status text DEFAULT 'open'::text NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by_id uuid,
    resolved_by_name text,
    next_follow_up_date date,
    cre_rating smallint,
    effective_rating smallint GENERATED ALWAYS AS (COALESCE(cre_rating, rating)) STORED,
    remarked_at timestamp with time zone,
    rating_at timestamp with time zone,
    CONSTRAINT psfm_cre_rating_check CHECK (((cre_rating IS NULL) OR ((cre_rating >= 1) AND (cre_rating <= 5)))),
    CONSTRAINT psfm_cre_status_check CHECK ((cre_status = ANY (ARRAY['open'::text, 'in_progress'::text, 'resolved'::text]))),
    CONSTRAINT psfm_rating_check CHECK (((rating IS NULL) OR ((rating >= 1) AND (rating <= 5)))),
    CONSTRAINT psfm_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'responded'::text, 'failed'::text])))
);


--
-- Name: TABLE post_service_feedback_messages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.post_service_feedback_messages IS 'Tracks automated WhatsApp post-service feedback messages sent from job_card_closed_data.closed_date_time, plus captured ratings/remarks.';


--
-- Name: COLUMN post_service_feedback_messages.rating; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_service_feedback_messages.rating IS 'Customer-submitted WhatsApp rating (1-5), or null when the customer has not responded. Source feedback. CRE workflow must not overwrite this column.';


--
-- Name: COLUMN post_service_feedback_messages.cre_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_service_feedback_messages.cre_status IS 'CRE follow-up status for low-rated feedback: open -> in_progress -> resolved.';


--
-- Name: COLUMN post_service_feedback_messages.resolved_by_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_service_feedback_messages.resolved_by_id IS 'auth.uid() of the CRE user who resolved this case (set only via psf_mark_resolved, never client-supplied).';


--
-- Name: COLUMN post_service_feedback_messages.next_follow_up_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_service_feedback_messages.next_follow_up_date IS 'Current CRE next-follow-up calendar date for this feedback case. One value per case. Null means no follow-up is scheduled. Not cleared when the case is resolved.';


--
-- Name: COLUMN post_service_feedback_messages.cre_rating; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_service_feedback_messages.cre_rating IS 'CRE-entered rating (1-5) for workflow classification. Null means no manual rating. Does not replace rating or feedback_text.';


--
-- Name: COLUMN post_service_feedback_messages.effective_rating; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_service_feedback_messages.effective_rating IS 'Authoritative rating for CRE tab classification. cre_rating when present, otherwise the customer rating. Null means no rating.';


--
-- Name: COLUMN post_service_feedback_messages.remarked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_service_feedback_messages.remarked_at IS 'Timestamp of the most recent CRE Add Remark action. Used for daily productivity tracking.';


--
-- Name: COLUMN post_service_feedback_messages.rating_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_service_feedback_messages.rating_at IS 'Timestamp of the most recent CRE Set/Change Rating action. Used for daily productivity tracking.';


--
-- Name: post_service_feedback_cre_due_today; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.post_service_feedback_cre_due_today AS
 SELECT m.id,
    m.job_card_closed_data_id,
    m.customer_name,
    m.mobile_number,
    m.vehicle_registration_number,
    m.job_card_number,
    m.closed_date,
    m.sent_at,
    m.rating,
    m.feedback_text,
    m.responded_at,
    m.cre_status,
    m.resolved_at,
    m.resolved_by_name,
    COALESCE(em.employee_name, jc.sr_assigned_to) AS service_advisor_name,
    jc.sr_type AS service_type,
    m.review_link_sent,
    jc.branch_label AS branch,
    m.next_follow_up_date,
    m.cre_rating,
    m.effective_rating
   FROM ((public.post_service_feedback_messages m
     LEFT JOIN public.job_card_closed_data jc ON ((jc.id = m.job_card_closed_data_id)))
     LEFT JOIN public.employee_master em ON ((em.employee_code = jc.employee_code)))
  WHERE ((m.next_follow_up_date = (timezone('Asia/Kolkata'::text, now()))::date) AND (m.cre_status <> 'resolved'::text) AND (((m.status = 'responded'::text) AND (m.effective_rating IS NOT NULL) AND (m.effective_rating <= 3)) OR ((m.sent_at IS NOT NULL) AND (m.effective_rating IS NULL)) OR ((m.sent_at IS NOT NULL) AND (m.cre_rating IS NOT NULL) AND (m.effective_rating <= 3))));


--
-- Name: VIEW post_service_feedback_cre_due_today; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.post_service_feedback_cre_due_today IS 'Actionable CRE cases whose next_follow_up_date is today in Asia/Kolkata. Includes effective ratings <= 3 and sent-unrated messages. Excludes resolved cases and effective ratings >= 4. Membership is not service date.';


--
-- Name: post_service_feedback_cre_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.post_service_feedback_cre_queue AS
 SELECT m.id,
    m.job_card_closed_data_id,
    m.customer_name,
    m.mobile_number,
    m.vehicle_registration_number,
    m.job_card_number,
    m.closed_date,
    m.rating,
    m.feedback_text,
    m.responded_at,
    m.cre_status,
    m.resolved_at,
    m.resolved_by_name,
    COALESCE(em.employee_name, jc.sr_assigned_to) AS service_advisor_name,
    jc.sr_type AS service_type,
    m.review_link_sent,
    jc.branch_label AS branch,
    m.next_follow_up_date,
    m.cre_rating,
    m.effective_rating
   FROM ((public.post_service_feedback_messages m
     LEFT JOIN public.job_card_closed_data jc ON ((jc.id = m.job_card_closed_data_id)))
     LEFT JOIN public.employee_master em ON ((em.employee_code = jc.employee_code)))
  WHERE ((m.effective_rating IS NOT NULL) AND (((m.status = 'responded'::text) AND (m.rating IS NOT NULL)) OR (m.cre_rating IS NOT NULL)));


--
-- Name: VIEW post_service_feedback_cre_queue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.post_service_feedback_cre_queue IS 'Responded customer ratings plus CRE-rated cases. rating is the customer score. effective_rating classifies needs follow-up (<=3) vs positive (>=4).';


--
-- Name: post_service_feedback_cre_unrated; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.post_service_feedback_cre_unrated AS
 SELECT m.id,
    m.job_card_closed_data_id,
    m.customer_name,
    m.mobile_number,
    m.vehicle_registration_number,
    m.job_card_number,
    m.closed_date,
    m.sent_at,
    m.rating,
    m.feedback_text,
    m.responded_at,
    m.cre_status,
    m.resolved_at,
    m.resolved_by_name,
    COALESCE(em.employee_name, jc.sr_assigned_to) AS service_advisor_name,
    jc.sr_type AS service_type,
    m.review_link_sent,
    jc.branch_label AS branch,
    m.next_follow_up_date,
    m.cre_rating,
    m.effective_rating
   FROM ((public.post_service_feedback_messages m
     LEFT JOIN public.job_card_closed_data jc ON ((jc.id = m.job_card_closed_data_id)))
     LEFT JOIN public.employee_master em ON ((em.employee_code = jc.employee_code)))
  WHERE ((m.sent_at IS NOT NULL) AND (m.effective_rating IS NULL));


--
-- Name: VIEW post_service_feedback_cre_unrated; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.post_service_feedback_cre_unrated IS 'Successfully sent post-service feedback with no effective rating (sent_at is not null and coalesce(cre_rating, rating) is null). Failed/unsent rows are excluded.';


