--

CREATE TABLE public.technician_assignments (
    id bigint NOT NULL,
    job_card_number text NOT NULL,
    technician_code text NOT NULL,
    technician_name text NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    bay_no text,
    work_status text DEFAULT 'work_inprocess'::text NOT NULL,
    out_ts timestamp with time zone,
    remark text,
    time_diff interval GENERATED ALWAYS AS (
CASE
    WHEN (out_ts IS NULL) THEN NULL::interval
    ELSE (out_ts - assigned_at)
END) STORED,
    CONSTRAINT technician_assignments_bay_no_format_check CHECK (((bay_no IS NULL) OR (upper(btrim(bay_no)) ~ '^(PV|EV)-(?:[1-9]|1[0-5])$'::text))),
    CONSTRAINT technician_assignments_job_card_number_nonempty CHECK ((btrim(job_card_number) <> ''::text)),
    CONSTRAINT technician_assignments_out_ts_status_check CHECK ((((lower(btrim(work_status)) = 'completed'::text) AND (out_ts IS NOT NULL)) OR ((lower(btrim(work_status)) <> 'completed'::text) AND (out_ts IS NULL)))),
    CONSTRAINT technician_assignments_work_status_check CHECK ((lower(btrim(work_status)) = ANY (ARRAY['work_inprocess'::text, 'hold'::text, 'completed'::text])))
);


