-- Name: COLUMN technician_assignments.assigned_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.technician_assignments.assigned_at IS 'IN TS for floor-incharge workflow. Automatically captured at assignment time.';


