    ew_renewal_variable_map jsonb DEFAULT '{"name": "first_name", "model": "model", "reg_no": "vehicle_registration_number", "ew_end_date": "extended_warranty_end_date"}'::jsonb NOT NULL,
    ew_renewal_send_time time without time zone DEFAULT '12:00:00'::time without time zone NOT NULL,
    ew_service_reminder_enabled boolean DEFAULT false NOT NULL,
    ew_service_reminder_template_id bigint,
    ew_service_reminder_template_lang text DEFAULT 'en'::text NOT NULL,
    ew_service_reminder_variable_map jsonb DEFAULT '{"name": "first_name", "model": "model", "reg_no": "vehicle_registration_number", "ew_end_date": "extended_warranty_end_date"}'::jsonb NOT NULL,
    ew_service_reminder_send_time time without time zone DEFAULT '13:00:00'::time without time zone NOT NULL,
