CREATE UNIQUE INDEX uq_service_invoice_conflict ON public.service_invoice_data USING btree (order_number, branch, invoice_date) WHERE ((NULLIF(TRIM(BOTH FROM COALESCE(order_number, ''::text)), ''::text) IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE(branch, ''::text)), ''::text) IS NOT NULL) AND (invoice_date IS NOT NULL));


