-- Name: advisor_chat_messages advisor_chat_messages_select_staff; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY advisor_chat_messages_select_staff ON public.advisor_chat_messages FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.advisor_chats c
  WHERE ((c.id = advisor_chat_messages.chat_id) AND (c.dealer_code = public.my_dealer_code()) AND (public.is_admin() OR public.has_module_view('chat'::text))))));


