-- =============================================================================
-- APPLICATION CUSTOMIZATION: auth schema trigger
-- Recreates the on_auth_user_created trigger that runs public.handle_new_user()
-- whenever a new Supabase auth user is created.
-- DO NOT recreate auth.users itself — that is Supabase-managed.
-- =============================================================================

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();


-- =============================================================================
-- APPLICATION CUSTOMIZATION: storage.objects RLS policies
-- These 5 policies are application-owned (autodoc bucket access control).
-- DO NOT recreate storage.objects table itself — that is Supabase-managed.
-- storage.objects RLS is ENABLED by production state (required for policies).
-- =============================================================================

ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;

CREATE POLICY "autodoc objects: own dealer delete" ON storage.objects
  FOR DELETE TO authenticated
  USING ((public.is_admin() OR ((bucket_id = 'autodoc'::text) AND (split_part(name, '/'::text, 1) = public.my_dealer_code()))));

CREATE POLICY "autodoc objects: own dealer insert" ON storage.objects
  FOR INSERT TO authenticated
  WITH CHECK ((public.is_admin() OR ((bucket_id = 'autodoc'::text) AND (split_part(name, '/'::text, 1) = public.my_dealer_code()))));

CREATE POLICY "autodoc objects: own dealer read" ON storage.objects
  FOR SELECT TO authenticated
  USING ((public.is_admin() OR ((bucket_id = 'autodoc'::text) AND (split_part(name, '/'::text, 1) = public.my_dealer_code()))));

CREATE POLICY "autodoc objects: own dealer update" ON storage.objects
  FOR UPDATE TO authenticated
  USING ((public.is_admin() OR ((bucket_id = 'autodoc'::text) AND (split_part(name, '/'::text, 1) = public.my_dealer_code()))))
  WITH CHECK ((public.is_admin() OR ((bucket_id = 'autodoc'::text) AND (split_part(name, '/'::text, 1) = public.my_dealer_code()))));

CREATE POLICY "autodoc objects: recovery read" ON storage.objects
  FOR SELECT TO authenticated
  USING (((bucket_id = 'autodoc'::text) AND (POSITION(('/service-advisor-bodyshop-docs/'::text) IN (name)) > 0) AND (public.has_module_view('bodyshop_recovery'::text) OR public.has_module_modify('bodyshop_recovery'::text))));
